insert into public.exercises
  (slug, name, description, category, skills, positions, level, levels, objective, objective_statement, duration_minutes, players_min, players_max, equipment, intensity, difficulty, instructions, instruction_steps, coaching_points, common_mistakes, common_mistakes_list, tips, progressions, regressions, solo_compatible, ball_required, physical_load, technical_load, tags)
values
  ('reception_001', 'Manchette au mur', 'Contrôle de la plateforme en autonomie, en renvoyant le ballon contre un mur à hauteur constante.', 'reception', array['manchette', 'plateforme', 'contrôle'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant'], 'reception', 'Stabiliser la plateforme de manchette sans partenaire.', 8, 1, 1, array['ballons', 'mur'], 'low', 2, 'Place-toi à deux mètres d''un mur dégagé, jambes fléchies, plateforme formée avant l''arrivée du ballon. Enchaîne des manchettes contre le mur en visant toujours la même zone, à hauteur de tête. 3 séries de 20 touches, en repartant à zéro dès que le ballon tombe.', array['Place-toi à deux mètres d''un mur dégagé, jambes fléchies, plateforme formée avant l''arrivée du ballon.', 'Enchaîne des manchettes contre le mur en visant toujours la même zone, à hauteur de tête.', '3 séries de 20 touches, en repartant à zéro dès que le ballon tombe.'], array['Bras tendus et serrés, coudes verrouillés au moment du contact.', 'Ce sont les jambes qui donnent la hauteur, pas le balancement des bras.', 'Garde les épaules devant les genoux pour rester équilibré vers l''avant.'], 'Balancer les bras vers le haut au lieu de pousser sur les jambes. Plier les coudes au contact, ce qui rend la trajectoire imprévisible.', array['Balancer les bras vers le haut au lieu de pousser sur les jambes.', 'Plier les coudes au contact, ce qui rend la trajectoire imprévisible.'], 'Bras tendus et serrés, coudes verrouillés au moment du contact. Ce sont les jambes qui donnent la hauteur, pas le balancement des bras. Garde les épaules devant les genoux pour rester équilibré vers l''avant.', array['Recule d''un mètre pour allonger la trajectoire.', 'Alterne une touche haute et une manchette sans laisser tomber le ballon.'], array['Laisse le ballon rebondir une fois au sol entre chaque manchette.'], true, true, 2, 2, array['reception', 'solo', 'maison', 'fondamentaux']),
  ('reception_002', 'Auto-manchettes sur place', 'Enchaînement de manchettes verticales à soi-même pour régler la hauteur et le point de contact.', 'reception', array['manchette', 'dosage', 'point de contact'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant'], 'reception', 'Doser la puissance de la manchette et fixer le point de contact.', 6, 1, 1, array['ballons'], 'low', 2, 'Envoie le ballon à la verticale en manchette, à environ deux mètres au-dessus de toi. Reste dans un cercle d''un mètre de diamètre pendant tout l''exercice. 3 séries de 15 touches consécutives réussies.', array['Envoie le ballon à la verticale en manchette, à environ deux mètres au-dessus de toi.', 'Reste dans un cercle d''un mètre de diamètre pendant tout l''exercice.', '3 séries de 15 touches consécutives réussies.'], array['Frappe le ballon sur la partie charnue des avant-bras, pas sur les poignets.', 'Amortis légèrement à la réception pour garder le ballon proche de toi.', 'Regarde le ballon jusqu''au contact, sans relever la tête trop tôt.'], 'Contact trop près des poignets, qui envoie le ballon n''importe où. Sortir du cercle à chaque touche faute de dosage.', array['Contact trop près des poignets, qui envoie le ballon n''importe où.', 'Sortir du cercle à chaque touche faute de dosage.'], 'Frappe le ballon sur la partie charnue des avant-bras, pas sur les poignets. Amortis légèrement à la réception pour garder le ballon proche de toi. Regarde le ballon jusqu''au contact, sans relever la tête trop tôt.', array['Réduis le cercle à cinquante centimètres.', 'Ferme les yeux une touche sur deux pour te fier aux sensations.'], array['Autorise un déplacement libre, sans contrainte de cercle.'], true, true, 1, 2, array['reception', 'solo', 'maison', 'dosage']),
  ('reception_003', 'Position d''attente et premier appui', 'Travail à vide de la posture de réception et du premier pas, sans gestion de ballon.', 'reception', array['posture', 'appuis', 'démarrage'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire'], 'reception', 'Automatiser une position d''attente qui permet de partir vite.', 6, 1, 6, '{}', 'low', 2, 'Prends la position d''attente : pieds décalés, poids sur l''avant des pieds, mains ouvertes devant. Au signal, effectue un premier appui explosif dans la direction annoncée puis reviens en position. 4 séries de 8 départs, en alternant les directions.', array['Prends la position d''attente : pieds décalés, poids sur l''avant des pieds, mains ouvertes devant.', 'Au signal, effectue un premier appui explosif dans la direction annoncée puis reviens en position.', '4 séries de 8 départs, en alternant les directions.'], array['Le poids reste sur l''avant du pied, talons décollés du sol.', 'Le premier appui part dans la direction du ballon, il ne recule jamais.', 'Garde les épaules basses et la tête stable pendant le déplacement.'], 'Se tenir debout jambes tendues, ce qui retarde tout démarrage. Faire un contre-appui vers l''arrière avant de partir.', array['Se tenir debout jambes tendues, ce qui retarde tout démarrage.', 'Faire un contre-appui vers l''arrière avant de partir.'], 'Le poids reste sur l''avant du pied, talons décollés du sol. Le premier appui part dans la direction du ballon, il ne recule jamais. Garde les épaules basses et la tête stable pendant le déplacement.', array['Ajoute un signal visuel aléatoire donné par un partenaire.'], array['Annonce la direction à l''avance pour te concentrer sur la posture.'], true, false, 2, 1, array['reception', 'sans ballon', 'appuis', 'maison']),
  ('reception_004', 'Manchettes en binôme', 'Échange contrôlé en manchette à faible distance pour installer la régularité du geste à deux.', 'reception', array['manchette', 'régularité', 'lecture de trajectoire'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant'], 'reception', 'Construire un échange régulier en manchette avec un partenaire.', 8, 2, 2, array['ballons'], 'low', 2, 'Placez-vous face à face à cinq mètres d''écart. Échangez uniquement en manchette, en cherchant à envoyer un ballon confortable au partenaire. Objectif : 30 échanges consécutifs sans faute, trois tentatives.', array['Placez-vous face à face à cinq mètres d''écart.', 'Échangez uniquement en manchette, en cherchant à envoyer un ballon confortable au partenaire.', 'Objectif : 30 échanges consécutifs sans faute, trois tentatives.'], array['Oriente tes épaules vers ton partenaire avant le contact.', 'Avance vers le ballon plutôt que de l''attendre sur place.', 'Cherche une trajectoire haute et lente, plus facile à reprendre.'], 'Rester immobile et tendre les bras vers le ballon au dernier moment. Envoyer des ballons tendus qui rendent la reprise impossible.', array['Rester immobile et tendre les bras vers le ballon au dernier moment.', 'Envoyer des ballons tendus qui rendent la reprise impossible.'], 'Oriente tes épaules vers ton partenaire avant le contact. Avance vers le ballon plutôt que de l''attendre sur place. Cherche une trajectoire haute et lente, plus facile à reprendre.', array['Augmentez la distance à huit mètres.', 'Imposez un déplacement latéral d''un pas entre chaque touche.'], array['Rapprochez-vous à trois mètres et acceptez un rebond au sol.'], false, true, 2, 2, array['reception', 'binôme', 'fondamentaux']),
  ('reception_005', 'Réception vers cible zone 3', 'Réception de ballons lancés à la main avec une cible matérialisée à l''emplacement du passeur.', 'reception', array['manchette', 'précision', 'orientation'], array['libero', 'outside_hitter'], 'debutant', array['debutant', 'intermediaire'], 'reception', 'Diriger la réception précisément vers la zone du passeur.', 10, 2, 4, array['ballons', 'plots'], 'medium', 3, 'Matérialise une cible de deux mètres sur deux à l''emplacement du passeur, en zone 3. Un partenaire lance des ballons hauts depuis le terrain adverse, le réceptionneur vise la cible. 4 séries de 10 réceptions, puis changement de rôle.', array['Matérialise une cible de deux mètres sur deux à l''emplacement du passeur, en zone 3.', 'Un partenaire lance des ballons hauts depuis le terrain adverse, le réceptionneur vise la cible.', '4 séries de 10 réceptions, puis changement de rôle.'], array['Oriente la plateforme vers la cible, pas vers le lanceur.', 'Place tes appuis avant le contact pour ne pas corriger avec les bras.', 'Vise une hauteur de trois mètres, confortable pour le passeur.'], 'Renvoyer le ballon vers le lanceur par réflexe. Compenser un mauvais placement par un mouvement de bras latéral.', array['Renvoyer le ballon vers le lanceur par réflexe.', 'Compenser un mauvais placement par un mouvement de bras latéral.'], 'Oriente la plateforme vers la cible, pas vers le lanceur. Place tes appuis avant le contact pour ne pas corriger avec les bras. Vise une hauteur de trois mètres, confortable pour le passeur.', array['Réduis la cible à un mètre sur un mètre.', 'Passe du lancer au service pour augmenter la vitesse.'], array['Élargis la cible à trois mètres et lance des ballons en cloche.'], false, true, 2, 3, array['reception', 'precision', 'cible', 'passeur']),
  ('reception_006', 'Lecture de trajectoires hautes', 'Réception de ballons envoyés très haut pour apprendre à se placer sous une trajectoire descendante.', 'reception', array['lecture de trajectoire', 'placement', 'manchette'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant'], 'reception', 'Se placer correctement sous une trajectoire haute avant de toucher.', 8, 2, 4, array['ballons'], 'low', 2, 'Un partenaire envoie des ballons en cloche très hauts, au-dessus du réceptionneur. Place-toi sous le ballon et réceptionne en manchette vers une zone annoncée. 3 séries de 10 ballons, en variant l''endroit de chute.', array['Un partenaire envoie des ballons en cloche très hauts, au-dessus du réceptionneur.', 'Place-toi sous le ballon et réceptionne en manchette vers une zone annoncée.', '3 séries de 10 ballons, en variant l''endroit de chute.'], array['Déplace-toi dès que le ballon quitte les mains du lanceur.', 'Arrive stable et arrêté avant le contact, jamais en course.', 'Laisse le ballon descendre jusqu''à hauteur de bassin avant de toucher.'], 'Attendre le ballon au lieu d''aller le chercher. Toucher le ballon trop haut, au-dessus de la poitrine.', array['Attendre le ballon au lieu d''aller le chercher.', 'Toucher le ballon trop haut, au-dessus de la poitrine.'], 'Déplace-toi dès que le ballon quitte les mains du lanceur. Arrive stable et arrêté avant le contact, jamais en course. Laisse le ballon descendre jusqu''à hauteur de bassin avant de toucher.', array['Le lanceur annonce la zone cible au dernier moment.'], array['Le lanceur envoie toujours au même endroit.'], false, true, 2, 2, array['reception', 'placement', 'debutant']),
  ('reception_007', 'Trois cibles, une plateforme', 'Réception successive vers trois zones différentes annoncées avant chaque ballon.', 'reception', array['orientation', 'plateforme', 'adaptation'], array['libero', 'outside_hitter'], 'intermediaire', array['intermediaire'], 'precision', 'Savoir rediriger une réception vers plusieurs zones au choix.', 10, 2, 4, array['ballons', 'plots'], 'medium', 3, 'Dispose trois cibles : zone 2, zone 3 et zone 4. Le lanceur annonce la cible juste avant d''envoyer le ballon. 4 séries de 9 ballons, trois vers chaque cible dans un ordre aléatoire.', array['Dispose trois cibles : zone 2, zone 3 et zone 4.', 'Le lanceur annonce la cible juste avant d''envoyer le ballon.', '4 séries de 9 ballons, trois vers chaque cible dans un ordre aléatoire.'], array['L''orientation vient des appuis et des épaules, pas d''un coup de bras.', 'Réoriente-toi pendant le déplacement, avant d''être en position.', 'Conserve la même hauteur de renvoi quelle que soit la cible.'], 'Tourner uniquement les bras vers la cible en gardant les pieds figés. Perdre la hauteur de ballon dès que la cible s''éloigne.', array['Tourner uniquement les bras vers la cible en gardant les pieds figés.', 'Perdre la hauteur de ballon dès que la cible s''éloigne.'], 'L''orientation vient des appuis et des épaules, pas d''un coup de bras. Réoriente-toi pendant le déplacement, avant d''être en position. Conserve la même hauteur de renvoi quelle que soit la cible.', array['La cible est annoncée après le départ du ballon.'], array['Travaille une seule cible par série.'], false, true, 2, 4, array['reception', 'orientation', 'precision']),
  ('reception_008', 'Réception après pas latéraux', 'Réception déclenchée après un déplacement latéral imposé, pour arriver stable sur le ballon.', 'reception', array['déplacement', 'stabilité', 'manchette'], array['libero', 'outside_hitter', 'opposite'], 'intermediaire', array['intermediaire'], 'reception', 'Arriver équilibré sur le ballon après un déplacement latéral.', 10, 2, 4, array['ballons', 'plots'], 'medium', 3, 'Pose deux plots à trois mètres d''écart, le réceptionneur démarre de l''un d''eux. Touche le plot désigné puis reçois le ballon envoyé dans la zone centrale. 4 séries de 10 réceptions, en alternant le côté de départ.', array['Pose deux plots à trois mètres d''écart, le réceptionneur démarre de l''un d''eux.', 'Touche le plot désigné puis reçois le ballon envoyé dans la zone centrale.', '4 séries de 10 réceptions, en alternant le côté de départ.'], array['Termine ton déplacement par un appui d''arrêt avant de former la plateforme.', 'Ne reçois jamais en pas chassé : stabilise-toi d''abord.', 'Garde le buste bas pendant tout le déplacement.'], 'Toucher le ballon en plein déplacement, ce qui dévie la trajectoire. Se redresser pendant le déplacement et perdre l''équilibre.', array['Toucher le ballon en plein déplacement, ce qui dévie la trajectoire.', 'Se redresser pendant le déplacement et perdre l''équilibre.'], 'Termine ton déplacement par un appui d''arrêt avant de former la plateforme. Ne reçois jamais en pas chassé : stabilise-toi d''abord. Garde le buste bas pendant tout le déplacement.', array['Réduis le délai entre le signal et l''envoi du ballon.'], array['Rapproche les plots à un mètre cinquante.'], false, true, 3, 3, array['reception', 'deplacement', 'appuis']),
  ('reception_009', 'Alternance court et profond', 'Ballons courts devant et longs derrière envoyés en alternance pour travailler la profondeur de placement.', 'reception', array['placement', 'lecture de profondeur', 'manchette'], array['libero', 'outside_hitter', 'opposite'], 'intermediaire', array['intermediaire', 'avance'], 'reception', 'Couvrir la profondeur du terrain sans perdre l''équilibre.', 10, 2, 4, array['ballons'], 'high', 4, 'Le lanceur alterne un ballon court à trois mètres et un ballon profond en fond de terrain. Le réceptionneur revient à sa position d''attente entre chaque ballon. 4 séries de 8 ballons, récupération de 45 secondes entre les séries.', array['Le lanceur alterne un ballon court à trois mètres et un ballon profond en fond de terrain.', 'Le réceptionneur revient à sa position d''attente entre chaque ballon.', '4 séries de 8 ballons, récupération de 45 secondes entre les séries.'], array['Sur le ballon court, avance en pas chassés plutôt qu''en courant.', 'Sur le ballon profond, recule en pivotant sans jamais tourner le dos au ballon.', 'Reviens systématiquement à ta position d''attente après chaque touche.'], 'Se déplacer en arrière en courant à reculons, au risque de chuter. Rester avancé après un ballon court et se faire prendre dans le dos.', array['Se déplacer en arrière en courant à reculons, au risque de chuter.', 'Rester avancé après un ballon court et se faire prendre dans le dos.'], 'Sur le ballon court, avance en pas chassés plutôt qu''en courant. Sur le ballon profond, recule en pivotant sans jamais tourner le dos au ballon. Reviens systématiquement à ta position d''attente après chaque touche.', array['Le lanceur ne respecte plus l''alternance et varie librement.'], array['Réduis l''écart entre les deux zones à deux mètres.'], false, true, 4, 3, array['reception', 'libero', 'profondeur', 'deplacement']),
  ('reception_010', 'Réception de service bas', 'Première réception de service réel, sur des services à la cuillère faciles à lire.', 'reception', array['réception de service', 'manchette', 'placement'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant'], 'reception', 'Réceptionner un service simple et le diriger vers le passeur.', 10, 2, 6, array['ballons', 'filet'], 'medium', 2, 'Un serveur envoie des services bas depuis la ligne de fond adverse. Le réceptionneur renvoie vers la zone 3 puis rattrape son ballon. 3 séries de 10 services, puis rotation des rôles.', array['Un serveur envoie des services bas depuis la ligne de fond adverse.', 'Le réceptionneur renvoie vers la zone 3 puis rattrape son ballon.', '3 séries de 10 services, puis rotation des rôles.'], array['Regarde le contact du serveur avec le ballon pour partir au bon moment.', 'Avance sur le ballon : un service bas perd de la vitesse en arrivant.', 'Reste patient, le ballon doit descendre jusqu''à hauteur de hanches.'], 'Reculer par réflexe dès que le serveur frappe. Toucher le ballon bras fléchis, trop près du corps.', array['Reculer par réflexe dès que le serveur frappe.', 'Toucher le ballon bras fléchis, trop près du corps.'], 'Regarde le contact du serveur avec le ballon pour partir au bon moment. Avance sur le ballon : un service bas perd de la vitesse en arrivant. Reste patient, le ballon doit descendre jusqu''à hauteur de hanches.', array['Le serveur se recule et sert plus fort.'], array['Le serveur sert depuis le milieu du terrain.'], false, true, 2, 2, array['reception', 'service', 'debutant']),
  ('reception_011', 'Réception de service flottant', 'Réception de services flottants dont la trajectoire se casse en fin de course.', 'reception', array['réception de service', 'lecture de trajectoire', 'stabilité'], array['libero', 'outside_hitter'], 'intermediaire', array['intermediaire', 'avance'], 'reception', 'Gérer la cassure de trajectoire propre au service flottant.', 12, 2, 6, array['ballons', 'filet'], 'medium', 4, 'Le serveur enchaîne des services flottants sans rotation de ballon. Le réceptionneur ajuste son placement tardivement et renvoie vers zone 3. 4 séries de 8 réceptions, avec changement de serveur à chaque série.', array['Le serveur enchaîne des services flottants sans rotation de ballon.', 'Le réceptionneur ajuste son placement tardivement et renvoie vers zone 3.', '4 séries de 8 réceptions, avec changement de serveur à chaque série.'], array['Ne te décide pas trop tôt : un flottant change de trajectoire en fin de course.', 'Garde la plateforme mobile et souple jusqu''au dernier instant.', 'Amortis légèrement le contact, le ballon arrive sans rotation et rebondit fort.'], 'Se figer sur la trajectoire initiale et se faire surprendre par la cassure. Frapper le ballon au lieu de l''accompagner.', array['Se figer sur la trajectoire initiale et se faire surprendre par la cassure.', 'Frapper le ballon au lieu de l''accompagner.'], 'Ne te décide pas trop tôt : un flottant change de trajectoire en fin de course. Garde la plateforme mobile et souple jusqu''au dernier instant. Amortis légèrement le contact, le ballon arrive sans rotation et rebondit fort.', array['Le serveur vise volontairement les zones de rupture entre deux joueurs.'], array['Le serveur sert flottant depuis la zone d''attaque, à mi-distance.'], false, true, 3, 4, array['reception', 'service', 'flottant', 'libero']),
  ('reception_012', 'Réception de service smashé', 'Réception de services frappés puissants, centrée sur la solidité de la plateforme.', 'reception', array['réception de service', 'absorption', 'réflexes'], array['libero', 'outside_hitter'], 'avance', array['avance'], 'reception', 'Absorber un service puissant et conserver le ballon en jeu.', 12, 2, 6, array['ballons', 'filet'], 'high', 4, 'Le serveur enchaîne des services smashés vers une zone annoncée. Le réceptionneur absorbe la puissance et cherche simplement à garder le ballon dans son camp. 5 séries de 5 réceptions, récupération complète entre les séries.', array['Le serveur enchaîne des services smashés vers une zone annoncée.', 'Le réceptionneur absorbe la puissance et cherche simplement à garder le ballon dans son camp.', '5 séries de 5 réceptions, récupération complète entre les séries.'], array['Plateforme basse et ferme, sans aucun mouvement de bras vers l''avant.', 'Recule ton bassin au contact pour absorber la vitesse du ballon.', 'Vise haut et au centre : sur un service puissant, la sécurité prime.'], 'Accompagner le ballon vers l''avant, ce qui l''envoie dans le camp adverse. Se tenir trop haut et se faire prendre à hauteur de poitrine.', array['Accompagner le ballon vers l''avant, ce qui l''envoie dans le camp adverse.', 'Se tenir trop haut et se faire prendre à hauteur de poitrine.'], 'Plateforme basse et ferme, sans aucun mouvement de bras vers l''avant. Recule ton bassin au contact pour absorber la vitesse du ballon. Vise haut et au centre : sur un service puissant, la sécurité prime.', array['Le serveur ne prévient plus de la zone visée.'], array['Le serveur réduit sa puissance à soixante pour cent.'], false, true, 4, 4, array['reception', 'service', 'puissance', 'avance']),
  ('reception_013', 'Réception de service sauté flottant', 'Réception de services sautés flottants, plus rapides et plus plongeants que le flottant classique.', 'reception', array['réception de service', 'anticipation', 'placement'], array['libero', 'outside_hitter'], 'avance', array['avance'], 'reception', 'Ajuster son placement face à un service sauté flottant.', 12, 2, 6, array['ballons', 'filet'], 'high', 4, 'Le serveur effectue des services sautés flottants depuis le fond du terrain. Le réceptionneur se place un mètre plus en avant que sur un flottant classique. 4 séries de 6 réceptions, avec analyse de la qualité après chaque série.', array['Le serveur effectue des services sautés flottants depuis le fond du terrain.', 'Le réceptionneur se place un mètre plus en avant que sur un flottant classique.', '4 séries de 6 réceptions, avec analyse de la qualité après chaque série.'], array['Avance ta position de départ : ce service plonge plus tôt qu''il n''en a l''air.', 'Lis la hauteur du lancer du serveur, elle annonce la profondeur du service.', 'Reste bas, la trajectoire descend fort en fin de course.'], 'Se placer trop profond et devoir avancer en catastrophe. Lever la plateforme trop tôt en anticipant une trajectoire haute.', array['Se placer trop profond et devoir avancer en catastrophe.', 'Lever la plateforme trop tôt en anticipant une trajectoire haute.'], 'Avance ta position de départ : ce service plonge plus tôt qu''il n''en a l''air. Lis la hauteur du lancer du serveur, elle annonce la profondeur du service. Reste bas, la trajectoire descend fort en fin de course.', array['Alterne sauté flottant et sauté smashé sans prévenir.'], array['Le serveur effectue un flottant debout, sans saut.'], false, true, 4, 4, array['reception', 'service', 'avance', 'anticipation']),
  ('reception_014', 'Lecture du serveur', 'Prise d''information sur la posture du serveur pour partir avant le contact avec le ballon.', 'reception', array['anticipation', 'lecture', 'prise d''information'], array['libero', 'outside_hitter'], 'avance', array['avance'], 'reception', 'Gagner du temps de réaction en lisant le serveur.', 10, 2, 6, array['ballons', 'filet'], 'medium', 3, 'Le réceptionneur annonce à voix haute la zone visée dès qu''il lit la position du serveur. Le serveur sert ensuite normalement, l''annonce est comparée au résultat. 4 séries de 8 services, en comptant le nombre d''annonces correctes.', array['Le réceptionneur annonce à voix haute la zone visée dès qu''il lit la position du serveur.', 'Le serveur sert ensuite normalement, l''annonce est comparée au résultat.', '4 séries de 8 services, en comptant le nombre d''annonces correctes.'], array['Observe l''orientation des épaules et des appuis du serveur avant son lancer.', 'La hauteur et la position du lancer annoncent souvent la profondeur.', 'Une lecture juste vaut mieux qu''un départ rapide au hasard.'], 'Fixer uniquement le ballon et ignorer le corps du serveur. Partir avant le contact sur une lecture non confirmée.', array['Fixer uniquement le ballon et ignorer le corps du serveur.', 'Partir avant le contact sur une lecture non confirmée.'], 'Observe l''orientation des épaules et des appuis du serveur avant son lancer. La hauteur et la position du lancer annoncent souvent la profondeur. Une lecture juste vaut mieux qu''un départ rapide au hasard.', array['Le serveur cherche volontairement à masquer son intention.'], array['Le serveur annonce lui-même sa zone une fois sur deux.'], false, true, 2, 4, array['reception', 'lecture', 'anticipation', 'libero']),
  ('reception_015', 'Réception à deux réceptionneurs', 'Répartition du terrain entre deux réceptionneurs, avec zones de responsabilité définies.', 'reception', array['répartition', 'communication', 'réception de service'], array['libero', 'outside_hitter'], 'intermediaire', array['intermediaire', 'avance'], 'reception', 'Se répartir clairement le terrain à deux réceptionneurs.', 12, 3, 6, array['ballons', 'filet', 'plots'], 'medium', 3, 'Deux réceptionneurs se partagent le terrain, la limite est matérialisée par des plots. Le serveur varie les zones, chaque réceptionneur annonce et prend les ballons de sa zone. 4 séries de 10 services, puis inversion des côtés.', array['Deux réceptionneurs se partagent le terrain, la limite est matérialisée par des plots.', 'Le serveur varie les zones, chaque réceptionneur annonce et prend les ballons de sa zone.', '4 séries de 10 services, puis inversion des côtés.'], array['Annonce dès que le ballon entre dans ta zone, avant de te déplacer.', 'Celui qui n''annonce pas s''écarte franchement pour libérer la vue.', 'Chacun reste responsable de sa zone même si le ballon est difficile.'], 'Annoncer en même temps et se gêner mutuellement. Rester passif en attendant que l''autre prenne le ballon.', array['Annoncer en même temps et se gêner mutuellement.', 'Rester passif en attendant que l''autre prenne le ballon.'], 'Annonce dès que le ballon entre dans ta zone, avant de te déplacer. Celui qui n''annonce pas s''écarte franchement pour libérer la vue. Chacun reste responsable de sa zone même si le ballon est difficile.', array['Réduis la surface couverte par chaque joueur d''un mètre.'], array['Élargis la zone neutre entre les deux réceptionneurs.'], false, true, 3, 3, array['reception', 'collectif', 'communication']),
  ('reception_016', 'Ballons sur le couloir', 'Services envoyés volontairement entre deux réceptionneurs pour traiter la zone de rupture.', 'reception', array['communication', 'décision', 'réception de service'], array['libero', 'outside_hitter'], 'avance', array['avance'], 'reception', 'Trancher rapidement les ballons de la zone de rupture.', 10, 3, 6, array['ballons', 'filet'], 'high', 4, 'Le serveur vise systématiquement l''espace entre les deux réceptionneurs. Les réceptionneurs doivent décider et annoncer très tôt qui prend le ballon. 4 séries de 8 services, en comptant les ballons laissés tomber.', array['Le serveur vise systématiquement l''espace entre les deux réceptionneurs.', 'Les réceptionneurs doivent décider et annoncer très tôt qui prend le ballon.', '4 séries de 8 services, en comptant les ballons laissés tomber.'], array['Une règle simple tranche le doute : le joueur dont le ballon vient de face prend.', 'L''annonce doit sortir avant que le ballon ne franchisse le filet.', 'Le joueur qui ne prend pas s''écarte immédiatement, il ne reste pas spectateur.'], 'Se regarder au lieu d''annoncer et laisser tomber le ballon. Partir tous les deux et se percuter.', array['Se regarder au lieu d''annoncer et laisser tomber le ballon.', 'Partir tous les deux et se percuter.'], 'Une règle simple tranche le doute : le joueur dont le ballon vient de face prend. L''annonce doit sortir avant que le ballon ne franchisse le filet. Le joueur qui ne prend pas s''écarte immédiatement, il ne reste pas spectateur.', array['Ajoute un troisième réceptionneur et deux couloirs à gérer.'], array['Désigne à l''avance un joueur prioritaire sur tous les ballons du couloir.'], false, true, 3, 4, array['reception', 'communication', 'collectif', 'libero']),
  ('reception_017', 'Réception avec annonce obligatoire', 'Réception collective où chaque ballon doit être annoncé à voix haute avant d''être touché.', 'reception', array['communication', 'réception de service', 'collectif'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire'], 'reception', 'Installer une communication systématique en réception.', 10, 3, 6, array['ballons', 'filet'], 'medium', 2, 'Trois réceptionneurs se placent en ligne de réception classique. Tout ballon touché sans annonce préalable compte comme une faute, même s''il est bien réceptionné. 4 séries de 10 services.', array['Trois réceptionneurs se placent en ligne de réception classique.', 'Tout ballon touché sans annonce préalable compte comme une faute, même s''il est bien réceptionné.', '4 séries de 10 services.'], array['Annonce fort et tôt, la voix porte l''information plus vite que le geste.', 'Les joueurs non concernés annoncent aussi lorsqu''ils laissent le ballon.', 'Garde la même intensité vocale du premier au dernier ballon.'], 'Annoncer au moment du contact, donc trop tard pour être utile. Baisser la voix au fil de la série.', array['Annoncer au moment du contact, donc trop tard pour être utile.', 'Baisser la voix au fil de la série.'], 'Annonce fort et tôt, la voix porte l''information plus vite que le geste. Les joueurs non concernés annoncent aussi lorsqu''ils laissent le ballon. Garde la même intensité vocale du premier au dernier ballon.', array['Ajoute l''annonce de la qualité du ballon juste après la réception.'], array['Autorise une annonce par geste du bras en complément de la voix.'], false, true, 2, 2, array['reception', 'communication', 'collectif']),
  ('reception_018', 'Réception en touche haute', 'Réception des services hauts à deux mains au-dessus du front plutôt qu''en manchette.', 'reception', array['touche haute', 'réception de service', 'précision'], array['libero', 'outside_hitter'], 'intermediaire', array['intermediaire', 'avance'], 'reception', 'Utiliser la touche haute sur les services au-dessus des épaules.', 10, 2, 6, array['ballons', 'filet'], 'medium', 3, 'Le serveur envoie des services flottants hauts, au-dessus des épaules du réceptionneur. Le réceptionneur les prend à deux mains au-dessus du front et dirige vers zone 3. 4 séries de 8 réceptions.', array['Le serveur envoie des services flottants hauts, au-dessus des épaules du réceptionneur.', 'Le réceptionneur les prend à deux mains au-dessus du front et dirige vers zone 3.', '4 séries de 8 réceptions.'], array['Place-toi sous le ballon, front à l''aplomb du point de contact.', 'Mains en forme de fenêtre, doigts fermes pour ne pas subir la vitesse.', 'Contact bref et sec, sans accompagnement prolongé.'], 'Prendre le ballon trop en avant du corps et perdre le contrôle. Doigts trop souples, ce qui produit une balle portée.', array['Prendre le ballon trop en avant du corps et perdre le contrôle.', 'Doigts trop souples, ce qui produit une balle portée.'], 'Place-toi sous le ballon, front à l''aplomb du point de contact. Mains en forme de fenêtre, doigts fermes pour ne pas subir la vitesse. Contact bref et sec, sans accompagnement prolongé.', array['Le serveur mélange services hauts et bas, le choix du geste revient au joueur.'], array['Le partenaire lance le ballon à la main à hauteur de front.'], false, true, 2, 4, array['reception', 'touche haute', 'moderne']),
  ('reception_019', 'Choix manchette ou touche haute', 'Prise de décision du geste de réception selon la hauteur réelle du ballon reçu.', 'reception', array['décision', 'touche haute', 'manchette'], array['libero', 'outside_hitter'], 'avance', array['avance'], 'reception', 'Choisir le bon geste de réception selon la hauteur du ballon.', 10, 2, 6, array['ballons', 'filet'], 'medium', 4, 'Le serveur alterne aléatoirement services hauts et services tendus. Le réceptionneur choisit seul entre manchette et touche haute, puis justifie son choix. 4 séries de 10 services, en notant les choix discutables.', array['Le serveur alterne aléatoirement services hauts et services tendus.', 'Le réceptionneur choisit seul entre manchette et touche haute, puis justifie son choix.', '4 séries de 10 services, en notant les choix discutables.'], array['Au-dessus des épaules, la touche haute est plus précise ; en dessous, la manchette.', 'Décide tôt : un changement de geste au dernier moment produit une faute.', 'En cas de doute réel, choisis la manchette, plus sûre.'], 'Hésiter entre les deux gestes et toucher le ballon poings fermés. Utiliser la touche haute sur un ballon puissant à hauteur de poitrine.', array['Hésiter entre les deux gestes et toucher le ballon poings fermés.', 'Utiliser la touche haute sur un ballon puissant à hauteur de poitrine.'], 'Au-dessus des épaules, la touche haute est plus précise ; en dessous, la manchette. Décide tôt : un changement de geste au dernier moment produit une faute. En cas de doute réel, choisis la manchette, plus sûre.', array['Impose une réussite de huit ballons sur dix pour valider la série.'], array['Le serveur annonce le type de service avant de servir.'], false, true, 3, 5, array['reception', 'decision', 'avance']),
  ('reception_020', 'Ballons courts devant', 'Réception de ballons déposés juste derrière le filet, avec démarrage explosif vers l''avant.', 'reception', array['démarrage', 'ballon court', 'manchette basse'], array['libero', 'outside_hitter', 'opposite'], 'intermediaire', array['intermediaire', 'avance'], 'reception', 'Couvrir vite les ballons courts déposés devant.', 10, 2, 4, array['ballons', 'filet'], 'high', 4, 'Le réceptionneur démarre en position de réception classique, en fond de terrain. Le lanceur dépose un ballon court à trois mètres du filet, le joueur avance et renvoie haut. 4 séries de 8 ballons, récupération de 45 secondes.', array['Le réceptionneur démarre en position de réception classique, en fond de terrain.', 'Le lanceur dépose un ballon court à trois mètres du filet, le joueur avance et renvoie haut.', '4 séries de 8 ballons, récupération de 45 secondes.'], array['Premier appui explosif dès la lecture, sans temps mort.', 'Descends le centre de gravité en avançant, ne te penche pas en avant.', 'Renvoie haut et au centre : la priorité est de garder le ballon en jeu.'], 'Se pencher en avant en gardant les jambes tendues. Arriver trop tard et toucher le ballon au ras du sol sans contrôle.', array['Se pencher en avant en gardant les jambes tendues.', 'Arriver trop tard et toucher le ballon au ras du sol sans contrôle.'], 'Premier appui explosif dès la lecture, sans temps mort. Descends le centre de gravité en avançant, ne te penche pas en avant. Renvoie haut et au centre : la priorité est de garder le ballon en jeu.', array['Le lanceur varie court et profond sans prévenir.'], array['Le réceptionneur démarre à mi-terrain.'], false, true, 4, 3, array['reception', 'libero', 'ballon court', 'explosivite']),
  ('reception_021', 'Ballons profonds en fond de terrain', 'Réception de ballons longs qui obligent à reculer en gardant le ballon devant soi.', 'reception', array['recul', 'ballon profond', 'placement'], array['libero', 'outside_hitter', 'opposite'], 'intermediaire', array['intermediaire', 'avance'], 'reception', 'Reculer efficacement pour traiter les ballons profonds.', 10, 2, 4, array['ballons', 'filet'], 'high', 4, 'Le réceptionneur se place à six mètres du filet. Le lanceur envoie des ballons longs près de la ligne de fond, le joueur recule et renvoie vers zone 3. 4 séries de 8 ballons.', array['Le réceptionneur se place à six mètres du filet.', 'Le lanceur envoie des ballons longs près de la ligne de fond, le joueur recule et renvoie vers zone 3.', '4 séries de 8 ballons.'], array['Pivote et recule en pas croisés, jamais à reculons face au filet.', 'Garde toujours le ballon dans ton champ de vision pendant le recul.', 'Termine en position stable, épaules orientées vers le passeur.'], 'Courir en arrière en regardant par-dessus son épaule. Toucher le ballon derrière soi, ce qui l''envoie hors du terrain.', array['Courir en arrière en regardant par-dessus son épaule.', 'Toucher le ballon derrière soi, ce qui l''envoie hors du terrain.'], 'Pivote et recule en pas croisés, jamais à reculons face au filet. Garde toujours le ballon dans ton champ de vision pendant le recul. Termine en position stable, épaules orientées vers le passeur.', array['Le lanceur envoie certains ballons volontairement hors limites, à laisser tomber.'], array['Le lanceur réduit la longueur des ballons d''un mètre.'], false, true, 4, 3, array['reception', 'libero', 'profondeur']),
  ('reception_022', 'Couverture de la ligne en zone 5', 'Réception spécifique des services le long de la ligne latérale gauche, poste de libéro.', 'reception', array['couverture de ligne', 'réception de service', 'placement'], array['libero', 'outside_hitter'], 'intermediaire', array['intermediaire', 'avance'], 'reception', 'Sécuriser la réception des services le long de la ligne.', 10, 2, 4, array['ballons', 'filet'], 'medium', 3, 'Le serveur vise exclusivement le long de la ligne, en zone 5. Le libéro couvre la ligne et renvoie vers la zone 3 sans jamais laisser le ballon sortir dans son dos. 4 séries de 8 services.', array['Le serveur vise exclusivement le long de la ligne, en zone 5.', 'Le libéro couvre la ligne et renvoie vers la zone 3 sans jamais laisser le ballon sortir dans son dos.', '4 séries de 8 services.'], array['Place-toi légèrement à l''intérieur : la ligne se couvre par un pas latéral.', 'Juge tôt si le ballon est bon ou sortant, et annonce-le.', 'Sur un ballon près de la ligne, oriente franchement la plateforme vers l''intérieur.'], 'Se coller à la ligne et laisser un trou au centre. Toucher un ballon manifestement sortant.', array['Se coller à la ligne et laisser un trou au centre.', 'Toucher un ballon manifestement sortant.'], 'Place-toi légèrement à l''intérieur : la ligne se couvre par un pas latéral. Juge tôt si le ballon est bon ou sortant, et annonce-le. Sur un ballon près de la ligne, oriente franchement la plateforme vers l''intérieur.', array['Le serveur ajoute des services au centre pour tester la couverture.'], array['Le serveur vise une cible large de deux mètres le long de la ligne.'], false, true, 3, 3, array['reception', 'libero', 'ligne']),
  ('reception_023', 'Services en diagonale longue', 'Réception de services traversant le terrain en diagonale, avec une trajectoire allongée.', 'reception', array['réception de service', 'lecture de trajectoire', 'déplacement'], array['libero', 'outside_hitter'], 'intermediaire', array['intermediaire', 'avance'], 'reception', 'Traiter une trajectoire diagonale en renvoyant vers le centre.', 10, 2, 4, array['ballons', 'filet'], 'medium', 3, 'Le serveur sert depuis la zone 1 vers la diagonale opposée, en fond de zone 5. Le réceptionneur se déplace en diagonale et renvoie vers zone 3. 4 séries de 8 services, puis on inverse le sens de la diagonale.', array['Le serveur sert depuis la zone 1 vers la diagonale opposée, en fond de zone 5.', 'Le réceptionneur se déplace en diagonale et renvoie vers zone 3.', '4 séries de 8 services, puis on inverse le sens de la diagonale.'], array['Une diagonale longue laisse plus de temps : utilise-le pour te placer parfaitement.', 'Oriente ta plateforme à contre-sens de la trajectoire pour renvoyer vers le centre.', 'Reste dans l''axe du ballon, sans lui laisser croiser ton corps.'], 'Suivre le ballon latéralement et le toucher sur le côté du corps. Renvoyer dans le prolongement de la trajectoire, donc hors du terrain.', array['Suivre le ballon latéralement et le toucher sur le côté du corps.', 'Renvoyer dans le prolongement de la trajectoire, donc hors du terrain.'], 'Une diagonale longue laisse plus de temps : utilise-le pour te placer parfaitement. Oriente ta plateforme à contre-sens de la trajectoire pour renvoyer vers le centre. Reste dans l''axe du ballon, sans lui laisser croiser ton corps.', array['Alterne diagonale longue et ligne courte sans prévenir.'], array['Le serveur sert à mi-distance pour raccourcir la trajectoire.'], false, true, 3, 3, array['reception', 'diagonale', 'libero']),
  ('reception_024', 'Ballons excentrés hors du corps', 'Réception de ballons qui arrivent nettement à côté du joueur, hors de son axe.', 'reception', array['plateforme latérale', 'extension', 'manchette'], array['libero', 'outside_hitter', 'opposite'], 'intermediaire', array['intermediaire', 'avance'], 'reception', 'Renvoyer vers le centre un ballon reçu hors de son axe.', 10, 2, 4, array['ballons'], 'high', 4, 'Le lanceur envoie volontairement des ballons à un mètre cinquante sur le côté du réceptionneur. Le joueur se déplace, et si le ballon reste hors d''atteinte, il réceptionne en plateforme inclinée. 4 séries de 10 ballons, cinq de chaque côté.', array['Le lanceur envoie volontairement des ballons à un mètre cinquante sur le côté du réceptionneur.', 'Le joueur se déplace, et si le ballon reste hors d''atteinte, il réceptionne en plateforme inclinée.', '4 séries de 10 ballons, cinq de chaque côté.'], array['Incline la plateforme vers l''intérieur du terrain, épaule extérieure plus basse.', 'Garde les deux bras joints même en extension latérale.', 'Privilégie toujours le déplacement à l''extension quand le temps le permet.'], 'Toucher le ballon d''un seul bras par facilité. Laisser la plateforme à plat, ce qui renvoie le ballon latéralement hors du terrain.', array['Toucher le ballon d''un seul bras par facilité.', 'Laisser la plateforme à plat, ce qui renvoie le ballon latéralement hors du terrain.'], 'Incline la plateforme vers l''intérieur du terrain, épaule extérieure plus basse. Garde les deux bras joints même en extension latérale. Privilégie toujours le déplacement à l''extension quand le temps le permet.', array['Augmente la distance latérale à deux mètres.'], array['Réduis la distance à un mètre et ralentis les envois.'], false, true, 4, 4, array['reception', 'laterale', 'libero']),
  ('reception_025', 'Réception en fin de série', 'Séries longues de réception pour maintenir la qualité technique malgré la fatigue.', 'reception', array['endurance', 'régularité', 'réception de service'], array['libero', 'outside_hitter'], 'avance', array['avance'], 'regularite', 'Tenir la qualité de réception malgré la fatigue.', 12, 2, 4, array['ballons', 'filet'], 'high', 4, 'Le serveur enchaîne 20 services sans pause pour un même réceptionneur. La qualité des cinq derniers ballons est notée séparément de celle des quinze premiers. 3 séries par joueur, avec deux minutes de récupération entre les séries.', array['Le serveur enchaîne 20 services sans pause pour un même réceptionneur.', 'La qualité des cinq derniers ballons est notée séparément de celle des quinze premiers.', '3 séries par joueur, avec deux minutes de récupération entre les séries.'], array['Reviens à ta position d''attente complète entre chaque ballon, même fatigué.', 'Quand la fatigue monte, simplifie : vise haut et au centre.', 'Contrôle ta respiration entre les ballons plutôt que de subir.'], 'Rester debout jambes tendues sur les derniers ballons. Chercher la précision maximale au lieu de la sécurité en fin de série.', array['Rester debout jambes tendues sur les derniers ballons.', 'Chercher la précision maximale au lieu de la sécurité en fin de série.'], 'Reviens à ta position d''attente complète entre chaque ballon, même fatigué. Quand la fatigue monte, simplifie : vise haut et au centre. Contrôle ta respiration entre les ballons plutôt que de subir.', array['Ajoute un déplacement latéral imposé entre chaque service.'], array['Réduis la série à douze services.'], false, true, 5, 3, array['reception', 'endurance', 'regularite']),
  ('reception_026', 'Réception puis attaque', 'Enchaînement complet pour réceptionneur-attaquant : recevoir, se replacer, puis attaquer.', 'reception', array['enchaînement', 'réception de service', 'transition'], array['outside_hitter', 'opposite'], 'intermediaire', array['intermediaire', 'avance'], 'reception', 'Enchaîner réception et attaque sans temps mort.', 14, 3, 6, array['ballons', 'filet'], 'high', 5, 'Le joueur réceptionne un service vers zone 3, où un passeur est en place. Il se replace immédiatement en zone 4 et attaque la passe qui suit. 4 séries de 6 enchaînements complets.', array['Le joueur réceptionne un service vers zone 3, où un passeur est en place.', 'Il se replace immédiatement en zone 4 et attaque la passe qui suit.', '4 séries de 6 enchaînements complets.'], array['Repars vers ta zone d''attaque dès que le ballon a quitté ta plateforme.', 'Une réception haute te donne le temps de te replacer : privilégie la hauteur.', 'Ne regarde pas ta réception, regarde le passeur.'], 'Admirer sa réception et démarrer son élan trop tard. Réceptionner tendu pour aller vite, ce qui casse la construction.', array['Admirer sa réception et démarrer son élan trop tard.', 'Réceptionner tendu pour aller vite, ce qui casse la construction.'], 'Repars vers ta zone d''attaque dès que le ballon a quitté ta plateforme. Une réception haute te donne le temps de te replacer : privilégie la hauteur. Ne regarde pas ta réception, regarde le passeur.', array['Ajoute un bloqueur adverse en zone 4.'], array['Le passeur envoie une passe haute fixe et prévisible.'], false, true, 5, 4, array['reception', 'enchainement', 'attaque', 'r4']),
  ('reception_027', 'Réception puis passe', 'Exercice à deux rôles alternés où chaque joueur réceptionne puis passe le ballon suivant.', 'reception', array['enchaînement', 'polyvalence', 'passe'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire'], 'reception', 'Enchaîner proprement la première et la deuxième touche.', 12, 3, 4, array['ballons', 'filet'], 'medium', 3, 'Le joueur A réceptionne un service et envoie vers le joueur B placé en zone 3. B passe le ballon en zone 4 dans un panier, puis les rôles s''inversent au ballon suivant. 4 séries de 10 ballons.', array['Le joueur A réceptionne un service et envoie vers le joueur B placé en zone 3.', 'B passe le ballon en zone 4 dans un panier, puis les rôles s''inversent au ballon suivant.', '4 séries de 10 ballons.'], array['En réception, vise systématiquement un mètre à l''intérieur du terrain.', 'En passe, sois déjà placé avant l''arrivée de la réception.', 'Communique la qualité du ballon reçu à ton partenaire.'], 'Rester spectateur du ballon après sa propre réception. Se placer en passe seulement une fois le ballon arrivé.', array['Rester spectateur du ballon après sa propre réception.', 'Se placer en passe seulement une fois le ballon arrivé.'], 'En réception, vise systématiquement un mètre à l''intérieur du terrain. En passe, sois déjà placé avant l''arrivée de la réception. Communique la qualité du ballon reçu à ton partenaire.', array['Ajoute une contrainte de deux secondes maximum entre les deux touches.'], array['Fixe les rôles pendant toute la série au lieu de les alterner.'], false, true, 3, 3, array['reception', 'passe', 'enchainement']),
  ('reception_028', 'Dix bonnes réceptions d''affilée', 'Objectif de série parfaite : dix réceptions consécutives atteignant la zone du passeur.', 'reception', array['régularité', 'concentration', 'précision'], array['libero', 'outside_hitter'], 'intermediaire', array['intermediaire', 'avance'], 'regularite', 'Produire une série de réceptions précises sans rupture.', 12, 2, 4, array['ballons', 'filet', 'plots'], 'medium', 4, 'Une cible de deux mètres sur deux est posée en zone 3. Le compteur repart à zéro dès qu''une réception manque la cible. L''exercice se termine quand le joueur atteint dix réussites consécutives, avec un maximum de 40 ballons.', array['Une cible de deux mètres sur deux est posée en zone 3.', 'Le compteur repart à zéro dès qu''une réception manque la cible.', 'L''exercice se termine quand le joueur atteint dix réussites consécutives, avec un maximum de 40 ballons.'], array['Adopte exactement la même routine avant chaque ballon.', 'Après une faute, reviens à un geste simple plutôt que de te crisper.', 'La régularité vient de la constance du placement, pas des bras.'], 'Accélérer le rythme quand le compteur monte. Changer de geste après deux échecs consécutifs.', array['Accélérer le rythme quand le compteur monte.', 'Changer de geste après deux échecs consécutifs.'], 'Adopte exactement la même routine avant chaque ballon. Après une faute, reviens à un geste simple plutôt que de te crisper. La régularité vient de la constance du placement, pas des bras.', array['Passe l''objectif à quinze réussites consécutives.'], array['Abaisse l''objectif à six réussites et élargis la cible.'], false, true, 3, 4, array['reception', 'regularite', 'objectif']),
  ('reception_029', 'Réception notée de zéro à trois', 'Évaluation chiffrée de chaque réception pour mesurer objectivement la qualité produite.', 'reception', array['évaluation', 'précision', 'réception de service'], array['libero', 'outside_hitter'], 'intermediaire', array['intermediaire', 'avance'], 'reception', 'Mesurer objectivement la qualité de sa réception.', 12, 3, 6, array['ballons', 'filet'], 'medium', 4, 'Un observateur note chaque réception : 3 si toutes les options d''attaque sont possibles, 0 si le ballon est perdu. Le réceptionneur effectue 20 ballons et calcule sa moyenne. 2 séries par joueur, avec l''objectif d''améliorer la moyenne à la seconde.', array['Un observateur note chaque réception : 3 si toutes les options d''attaque sont possibles, 0 si le ballon est perdu.', 'Le réceptionneur effectue 20 ballons et calcule sa moyenne.', '2 séries par joueur, avec l''objectif d''améliorer la moyenne à la seconde.'], array['Une réception à 3 est haute, centrée et proche du filet sans le toucher.', 'Sur ballon difficile, viser un 2 sûr vaut mieux que tenter un 3 risqué.', 'Analyse les ballons notés 1 pour identifier l''erreur qui revient.'], 'Ne viser que la perfection et multiplier les 0. Se satisfaire de ballons jouables mais systématiquement décalés.', array['Ne viser que la perfection et multiplier les 0.', 'Se satisfaire de ballons jouables mais systématiquement décalés.'], 'Une réception à 3 est haute, centrée et proche du filet sans le toucher. Sur ballon difficile, viser un 2 sûr vaut mieux que tenter un 3 risqué. Analyse les ballons notés 1 pour identifier l''erreur qui revient.', array['Le serveur augmente la difficulté à chaque série.'], array['Note simplement chaque ballon comme réussi ou manqué.'], false, true, 3, 4, array['reception', 'evaluation', 'statistiques']),
  ('reception_030', 'Cible réduite au mètre carré', 'Réception vers une cible très petite, pour pousser la précision à son maximum.', 'reception', array['précision', 'orientation', 'contrôle fin'], array['libero', 'outside_hitter'], 'avance', array['avance'], 'precision', 'Atteindre une précision de réception au mètre près.', 10, 2, 4, array['ballons', 'filet', 'plots'], 'medium', 4, 'Délimite une cible d''un mètre sur un mètre à l''emplacement exact du passeur. Le serveur sert normalement, le réceptionneur cherche à faire tomber le ballon dans la cible. 4 séries de 10 services, en comptant les réussites.', array['Délimite une cible d''un mètre sur un mètre à l''emplacement exact du passeur.', 'Le serveur sert normalement, le réceptionneur cherche à faire tomber le ballon dans la cible.', '4 séries de 10 services, en comptant les réussites.'], array['La précision se joue dans l''orientation des appuis, un degré compte.', 'Garde une hauteur constante : la profondeur se règle par la poussée des jambes.', 'Répète le même geste, ne cherche pas à corriger au dernier moment.'], 'Chercher la cible avec les bras au lieu des appuis. Baisser la hauteur de renvoi pour gagner en précision.', array['Chercher la cible avec les bras au lieu des appuis.', 'Baisser la hauteur de renvoi pour gagner en précision.'], 'La précision se joue dans l''orientation des appuis, un degré compte. Garde une hauteur constante : la profondeur se règle par la poussée des jambes. Répète le même geste, ne cherche pas à corriger au dernier moment.', array['Impose une hauteur minimale de renvoi de trois mètres.'], array['Élargis la cible à deux mètres sur deux.'], false, true, 3, 5, array['reception', 'precision', 'avance']),
  ('reception_031', 'Triangle de réception à trois', 'Rotation continue entre trois joueurs occupant successivement les rôles de serveur, réceptionneur et cible.', 'reception', array['rotation', 'réception de service', 'polyvalence'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire'], 'reception', 'Faire tourner trois joueurs sur un atelier de réception complet.', 12, 3, 3, array['ballons', 'filet'], 'medium', 3, 'Un joueur sert, un réceptionne, un troisième sert de cible en zone 3. Après chaque ballon, chacun passe au rôle suivant dans le sens du triangle. Continuez pendant douze minutes, en comptant les réceptions réussies de chacun.', array['Un joueur sert, un réceptionne, un troisième sert de cible en zone 3.', 'Après chaque ballon, chacun passe au rôle suivant dans le sens du triangle.', 'Continuez pendant douze minutes, en comptant les réceptions réussies de chacun.'], array['Chaque rôle compte : la cible doit rester immobile pour donner un vrai repère.', 'Profite du rôle de cible pour observer la technique du réceptionneur.', 'Garde un rythme constant, sans temps mort entre les rotations.'], 'Se déplacer quand on est cible, ce qui fausse le repère. Servir trop fort pour un exercice destiné à la réception.', array['Se déplacer quand on est cible, ce qui fausse le repère.', 'Servir trop fort pour un exercice destiné à la réception.'], 'Chaque rôle compte : la cible doit rester immobile pour donner un vrai repère. Profite du rôle de cible pour observer la technique du réceptionneur. Garde un rythme constant, sans temps mort entre les rotations.', array['Le serveur passe du service bas au service flottant.'], array['Remplace le service par un lancer à deux mains.'], false, true, 3, 2, array['reception', 'petit groupe', 'rotation']),
  ('reception_032', 'Services aléatoires sur trois zones', 'Réception sans information préalable, le serveur choisissant librement entre les zones 1, 5 et 6.', 'reception', array['adaptation', 'réception de service', 'déplacement'], array['libero', 'outside_hitter'], 'intermediaire', array['intermediaire', 'avance'], 'reception', 'Réceptionner sans information préalable sur la zone visée.', 12, 2, 6, array['ballons', 'filet'], 'high', 4, 'Le serveur choisit librement sa zone parmi 1, 5 et 6 à chaque service. Le réceptionneur couvre seul les trois zones et renvoie vers zone 3. 4 séries de 9 services, récupération d''une minute entre les séries.', array['Le serveur choisit librement sa zone parmi 1, 5 et 6 à chaque service.', 'Le réceptionneur couvre seul les trois zones et renvoie vers zone 3.', '4 séries de 9 services, récupération d''une minute entre les séries.'], array['Adopte une position de départ centrale qui te laisse toutes les options.', 'Ne présuppose jamais la zone : attends l''information réelle du serveur.', 'Sur les ballons éloignés, accepte un renvoi haut et sûr.'], 'Se décaler à l''avance en pariant sur une zone. Vouloir un ballon parfait sur une réception en extension.', array['Se décaler à l''avance en pariant sur une zone.', 'Vouloir un ballon parfait sur une réception en extension.'], 'Adopte une position de départ centrale qui te laisse toutes les options. Ne présuppose jamais la zone : attends l''information réelle du serveur. Sur les ballons éloignés, accepte un renvoi haut et sûr.', array['Le serveur ajoute la variation de type de service.'], array['Réduis à deux zones possibles.'], false, true, 4, 4, array['reception', 'aleatoire', 'libero']),
  ('reception_033', 'Libéro seul sur deux tiers de terrain', 'Couverture d''une très large zone par un seul réceptionneur, comme en fin de rotation difficile.', 'reception', array['couverture', 'endurance', 'réception de service'], array['libero'], 'avance', array['avance'], 'reception', 'Couvrir seul une grande surface de réception.', 12, 2, 4, array['ballons', 'filet', 'plots'], 'high', 5, 'Délimite les deux tiers du terrain que le libéro doit couvrir seul. Le serveur varie les zones à l''intérieur de cette surface. 4 séries de 8 services, avec récupération complète entre les séries.', array['Délimite les deux tiers du terrain que le libéro doit couvrir seul.', 'Le serveur varie les zones à l''intérieur de cette surface.', '4 séries de 8 services, avec récupération complète entre les séries.'], array['Positionne-toi au barycentre de la zone à couvrir, pas au milieu du terrain.', 'Sur les ballons extrêmes, la priorité absolue est de garder le ballon en jeu.', 'Reviens au centre de ta zone immédiatement après chaque touche.'], 'Rester au centre du terrain au lieu du centre de sa zone. S''épuiser en sprintant sur des ballons manifestement hors limites.', array['Rester au centre du terrain au lieu du centre de sa zone.', 'S''épuiser en sprintant sur des ballons manifestement hors limites.'], 'Positionne-toi au barycentre de la zone à couvrir, pas au milieu du terrain. Sur les ballons extrêmes, la priorité absolue est de garder le ballon en jeu. Reviens au centre de ta zone immédiatement après chaque touche.', array['Élargis la zone à la totalité du terrain.'], array['Réduis la zone à la moitié du terrain.'], false, true, 5, 4, array['reception', 'libero', 'couverture', 'avance']),
  ('reception_034', 'Réception en position basse imposée', 'Réception avec obligation de rester sous une hauteur donnée, pour renforcer le travail des jambes.', 'reception', array['posture basse', 'jambes', 'manchette'], array['libero', 'outside_hitter', 'opposite'], 'intermediaire', array['intermediaire'], 'reception', 'Réceptionner en restant réellement bas sur les appuis.', 8, 2, 4, array['ballons', 'elastique'], 'high', 3, 'Tends un élastique à un mètre vingt du sol, le joueur doit rester dessous pendant tout l''exercice. Le lanceur envoie des ballons variés, le joueur réceptionne sans se redresser. 3 séries de 10 ballons, avec une minute de récupération.', array['Tends un élastique à un mètre vingt du sol, le joueur doit rester dessous pendant tout l''exercice.', 'Le lanceur envoie des ballons variés, le joueur réceptionne sans se redresser.', '3 séries de 10 ballons, avec une minute de récupération.'], array['Le buste reste droit, c''est la flexion des jambes qui baisse la hauteur.', 'Cette position basse permet de partir plus vite dans toutes les directions.', 'Garde les talons décollés même en position basse.'], 'Se pencher en avant au lieu de fléchir les jambes. Se redresser dès que le ballon arrive.', array['Se pencher en avant au lieu de fléchir les jambes.', 'Se redresser dès que le ballon arrive.'], 'Le buste reste droit, c''est la flexion des jambes qui baisse la hauteur. Cette position basse permet de partir plus vite dans toutes les directions. Garde les talons décollés même en position basse.', array['Abaisse l''élastique à un mètre.'], array['Supprime l''élastique et utilise un simple repère visuel.'], false, true, 4, 2, array['reception', 'posture', 'jambes']),
  ('reception_035', 'Réception à genoux', 'Manchette réalisée à genoux pour isoler complètement le travail de la plateforme.', 'reception', array['plateforme', 'isolation technique', 'contrôle'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire'], 'reception', 'Isoler et corriger le geste de plateforme sans l''aide des jambes.', 6, 2, 4, array['ballons', 'tapis'], 'low', 2, 'Place-toi à genoux sur un tapis, buste droit. Un partenaire envoie des ballons doux, tu les renvoies uniquement avec la plateforme. 3 séries de 12 ballons.', array['Place-toi à genoux sur un tapis, buste droit.', 'Un partenaire envoie des ballons doux, tu les renvoies uniquement avec la plateforme.', '3 séries de 12 ballons.'], array['Sans les jambes, seule l''orientation de la plateforme dirige le ballon.', 'Garde les bras tendus et joints du début à la fin du geste.', 'L''amplitude vient des épaules, pas des coudes.'], 'Compenser l''absence de jambes par un grand mouvement de bras. Séparer les mains au moment du contact.', array['Compenser l''absence de jambes par un grand mouvement de bras.', 'Séparer les mains au moment du contact.'], 'Sans les jambes, seule l''orientation de la plateforme dirige le ballon. Garde les bras tendus et joints du début à la fin du geste. L''amplitude vient des épaules, pas des coudes.', array['Le partenaire envoie des ballons légèrement excentrés.'], array['Le partenaire envoie des ballons en cloche très lents.'], false, true, 1, 3, array['reception', 'technique', 'correction']),
  ('reception_036', 'Précision au mur avec cible', 'Travail solo de précision en visant une cible dessinée sur un mur, à distance constante.', 'reception', array['précision', 'manchette', 'autonomie'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire'], 'precision', 'Travailler seul la précision de renvoi en manchette.', 8, 1, 1, array['ballons', 'mur'], 'medium', 3, 'Repère une cible d''un mètre sur un mur, à trois mètres de hauteur. Enchaîne des manchettes en touchant la cible, en restant à trois mètres du mur. 4 séries de 10 touches, en comptant les cibles atteintes.', array['Repère une cible d''un mètre sur un mur, à trois mètres de hauteur.', 'Enchaîne des manchettes en touchant la cible, en restant à trois mètres du mur.', '4 séries de 10 touches, en comptant les cibles atteintes.'], array['Reprends ta position d''attente complète entre chaque renvoi.', 'Ajuste la profondeur avec les jambes et la direction avec les épaules.', 'Compte tes réussites : le score rend le travail solo mesurable.'], 'Se rapprocher progressivement du mur au fil de la série. Enchaîner sans se replacer entre les touches.', array['Se rapprocher progressivement du mur au fil de la série.', 'Enchaîner sans se replacer entre les touches.'], 'Reprends ta position d''attente complète entre chaque renvoi. Ajuste la profondeur avec les jambes et la direction avec les épaules. Compte tes réussites : le score rend le travail solo mesurable.', array['Réduis la cible à cinquante centimètres.'], array['Rapproche-toi à deux mètres du mur.'], true, true, 2, 3, array['reception', 'solo', 'maison', 'precision']),
  ('reception_037', 'Replacement après réception', 'Retour systématique à la position d''attente entre deux ballons rapprochés.', 'reception', array['replacement', 'appuis', 'enchaînement'], array['libero', 'outside_hitter', 'opposite'], 'intermediaire', array['intermediaire'], 'reception', 'Se replacer immédiatement après chaque réception.', 10, 2, 4, array['ballons', 'plots'], 'high', 3, 'Un plot marque la position d''attente de référence du réceptionneur. Le lanceur envoie deux ballons rapprochés : le joueur doit repasser par son plot entre les deux. 4 séries de 6 doubles ballons.', array['Un plot marque la position d''attente de référence du réceptionneur.', 'Le lanceur envoie deux ballons rapprochés : le joueur doit repasser par son plot entre les deux.', '4 séries de 6 doubles ballons.'], array['Le replacement commence dès que le ballon quitte ta plateforme.', 'Reviens en pas chassés, jamais en marchant.', 'Sois arrêté et stable sur ton plot avant le second ballon.'], 'Regarder son premier ballon au lieu de se replacer. Revenir en marchant et arriver en retard sur le second ballon.', array['Regarder son premier ballon au lieu de se replacer.', 'Revenir en marchant et arriver en retard sur le second ballon.'], 'Le replacement commence dès que le ballon quitte ta plateforme. Reviens en pas chassés, jamais en marchant. Sois arrêté et stable sur ton plot avant le second ballon.', array['Réduis le délai entre les deux ballons.'], array['Allonge le délai et rapproche la zone de chute du plot.'], false, true, 4, 2, array['reception', 'replacement', 'appuis']),
  ('reception_038', 'Réception en situation de match', 'Réception intégrée à un point réel joué jusqu''à sa conclusion.', 'reception', array['situation de jeu', 'réception de service', 'enchaînement'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire', 'avance'], 'competition', 'Réceptionner dans le contexte réel d''un point joué.', 15, 6, 12, array['ballons', 'filet'], 'high', 4, 'Chaque point démarre obligatoirement par un service réel et une réception. Le point se joue ensuite normalement jusqu''à sa conclusion. Jouez 15 points, en notant la qualité de réception à chaque entame.', array['Chaque point démarre obligatoirement par un service réel et une réception.', 'Le point se joue ensuite normalement jusqu''à sa conclusion.', 'Jouez 15 points, en notant la qualité de réception à chaque entame.'], array['La réception conditionne tout le point : elle prime sur l''envie d''attaquer.', 'Reprends ta position d''attente entre chaque point, sans relâchement.', 'Communique avant chaque service sur la répartition des zones.'], 'Anticiper son rôle offensif au détriment de la réception. Relâcher l''attention sur les points où l''on n''est pas ciblé.', array['Anticiper son rôle offensif au détriment de la réception.', 'Relâcher l''attention sur les points où l''on n''est pas ciblé.'], 'La réception conditionne tout le point : elle prime sur l''envie d''attaquer. Reprends ta position d''attente entre chaque point, sans relâchement. Communique avant chaque service sur la répartition des zones.', array['Les points où la réception est ratée comptent double pour l''adversaire.'], array['Le service de mise en jeu est remplacé par un lancer.'], false, true, 4, 4, array['reception', 'match', 'collectif']),
  ('reception_039', 'Réception sous pression au score', 'Série de réceptions avec un score à atteindre, l''échec faisant reculer le compteur.', 'reception', array['gestion de pression', 'concentration', 'réception de service'], array['libero', 'outside_hitter'], 'avance', array['avance'], 'competition', 'Maintenir sa qualité de réception sous pression de score.', 12, 3, 6, array['ballons', 'filet'], 'high', 4, 'Chaque réception réussie rapporte un point, chaque échec en retire deux. L''objectif est d''atteindre dix points avant la fin des 30 ballons. Annoncez le score à voix haute avant chaque service.', array['Chaque réception réussie rapporte un point, chaque échec en retire deux.', 'L''objectif est d''atteindre dix points avant la fin des 30 ballons.', 'Annoncez le score à voix haute avant chaque service.'], array['Traite chaque ballon indépendamment du score affiché.', 'Quand le score se tend, reviens à la solution la plus sûre.', 'Garde la même routine avant chaque ballon, quel que soit l''enjeu.'], 'Prendre plus de risques quand on est en retard au score. Se crisper sur la technique quand la pression monte.', array['Prendre plus de risques quand on est en retard au score.', 'Se crisper sur la technique quand la pression monte.'], 'Traite chaque ballon indépendamment du score affiché. Quand le score se tend, reviens à la solution la plus sûre. Garde la même routine avant chaque ballon, quel que soit l''enjeu.', array['Passe l''objectif à quinze points sur le même nombre de ballons.'], array['Un échec ne retire qu''un seul point.'], false, true, 3, 4, array['reception', 'pression', 'competition']),
  ('reception_040', 'Réception à cinq contre service ciblé', 'Ligne de réception complète soumise à un serveur qui cherche systématiquement le point faible.', 'reception', array['organisation collective', 'réception de service', 'adaptation'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'avance', array['avance'], 'competition', 'Résister collectivement à un service qui cible un joueur.', 15, 6, 12, array['ballons', 'filet'], 'high', 4, 'Cinq joueurs forment la ligne de réception, un passeur est en place en zone 3. Le serveur cible en continu le joueur qui a raté la réception précédente. 4 séries de 12 services, avec analyse collective entre les séries.', array['Cinq joueurs forment la ligne de réception, un passeur est en place en zone 3.', 'Le serveur cible en continu le joueur qui a raté la réception précédente.', '4 séries de 12 services, avec analyse collective entre les séries.'], array['Le joueur ciblé reste en confiance : le collectif resserre autour de lui.', 'Adaptez la répartition des zones si un joueur est mis en difficulté.', 'L''annonce collective devient encore plus importante sous ciblage.'], 'Laisser seul le joueur ciblé au lieu d''ajuster le dispositif. Se figer sur une organisation qui ne fonctionne plus.', array['Laisser seul le joueur ciblé au lieu d''ajuster le dispositif.', 'Se figer sur une organisation qui ne fonctionne plus.'], 'Le joueur ciblé reste en confiance : le collectif resserre autour de lui. Adaptez la répartition des zones si un joueur est mis en difficulté. L''annonce collective devient encore plus importante sous ciblage.', array['Le serveur alterne ciblage et zones libres pour créer le doute.'], array['Le serveur annonce le joueur ciblé avant de servir.'], false, true, 4, 4, array['reception', 'collectif', 'competition', 'ciblage']),
  ('defense_001', 'Position défensive de référence', 'Construction à vide de la posture basse d''attente utilisée en défense de fond de terrain.', 'defense', array['posture', 'appuis', 'équilibre'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant'], 'defense', 'Installer une posture d''attente défensive réellement basse.', 6, 1, 8, '{}', 'low', 2, 'Place-toi jambes fléchies, pieds plus larges que les épaules, poids sur l''avant des pieds. Tiens la position vingt secondes, puis effectue cinq déplacements courts avant d''y revenir. 4 séries, avec vingt secondes de récupération entre chaque.', array['Place-toi jambes fléchies, pieds plus larges que les épaules, poids sur l''avant des pieds.', 'Tiens la position vingt secondes, puis effectue cinq déplacements courts avant d''y revenir.', '4 séries, avec vingt secondes de récupération entre chaque.'], array['Les épaules restent en avant des genoux, le dos droit et non arrondi.', 'Les mains sont ouvertes devant, au-dessus du niveau des genoux.', 'Les talons ne touchent jamais complètement le sol.'], 'Fléchir le dos au lieu des jambes. Laisser les bras le long du corps et devoir les remonter en urgence.', array['Fléchir le dos au lieu des jambes.', 'Laisser les bras le long du corps et devoir les remonter en urgence.'], 'Les épaules restent en avant des genoux, le dos droit et non arrondi. Les mains sont ouvertes devant, au-dessus du niveau des genoux. Les talons ne touchent jamais complètement le sol.', array['Allonge la tenue de position à quarante secondes.'], array['Réduis la tenue à dix secondes.'], true, false, 3, 1, array['defense', 'posture', 'sans ballon', 'maison']),
  ('defense_002', 'Manchette basse en binôme', 'Renvoi de ballons frappés au ras du sol par un partenaire, sans déplacement important.', 'defense', array['manchette basse', 'absorption', 'réflexes'], array['libero', 'outside_hitter', 'opposite'], 'debutant', array['debutant', 'intermediaire'], 'defense', 'Renvoyer haut un ballon frappé à hauteur basse.', 8, 2, 2, array['ballons'], 'medium', 3, 'Un partenaire frappe des ballons tendus vers le défenseur, à cinq mètres de distance. Le défenseur renvoie haut, en restant bas sur ses appuis. 4 séries de 12 ballons, puis changement de rôle.', array['Un partenaire frappe des ballons tendus vers le défenseur, à cinq mètres de distance.', 'Le défenseur renvoie haut, en restant bas sur ses appuis.', '4 séries de 12 ballons, puis changement de rôle.'], array['Laisse le ballon venir à toi plutôt que d''aller le chercher avec les bras.', 'Renvoie très haut : en défense, la hauteur donne du temps à l''équipe.', 'Garde la plateforme sous le niveau du ballon.'], 'Renvoyer tendu et directement dans le camp adverse. Se redresser au moment du contact.', array['Renvoyer tendu et directement dans le camp adverse.', 'Se redresser au moment du contact.'], 'Laisse le ballon venir à toi plutôt que d''aller le chercher avec les bras. Renvoie très haut : en défense, la hauteur donne du temps à l''équipe. Garde la plateforme sous le niveau du ballon.', array['Le partenaire augmente la puissance de frappe.'], array['Le partenaire lance le ballon à deux mains au lieu de frapper.'], false, true, 3, 2, array['defense', 'binôme', 'fondamentaux']),
  ('defense_003', 'Réflexes contre un mur', 'Travail solo de vitesse de réaction en renvoyant des ballons rapides contre un mur proche.', 'defense', array['réflexes', 'vitesse de bras', 'contrôle'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire'], 'vitesse', 'Développer la vitesse de réaction défensive en autonomie.', 6, 1, 1, array['ballons', 'mur'], 'medium', 3, 'Place-toi à un mètre cinquante d''un mur, en position basse. Envoie le ballon contre le mur et renvoie-le sans le laisser tomber, le plus longtemps possible. 4 séries de trente secondes d''effort continu.', array['Place-toi à un mètre cinquante d''un mur, en position basse.', 'Envoie le ballon contre le mur et renvoie-le sans le laisser tomber, le plus longtemps possible.', '4 séries de trente secondes d''effort continu.'], array['Anticipe le rebond en restant bas plutôt qu''en réagissant après coup.', 'Garde les mains devant toi entre chaque touche.', 'Des gestes courts valent mieux que des grands mouvements de bras.'], 'Se relever entre chaque renvoi et perdre le rythme. Frapper trop fort et rendre le rebond ingérable.', array['Se relever entre chaque renvoi et perdre le rythme.', 'Frapper trop fort et rendre le rebond ingérable.'], 'Anticipe le rebond en restant bas plutôt qu''en réagissant après coup. Garde les mains devant toi entre chaque touche. Des gestes courts valent mieux que des grands mouvements de bras.', array['Rapproche-toi à un mètre du mur.'], array['Recule à deux mètres cinquante.'], true, true, 3, 3, array['defense', 'solo', 'maison', 'reflexes']),
  ('defense_004', 'Chute latérale sur tapis', 'Apprentissage progressif de la chute sur le côté, sans ballon, pour sécuriser les gestes au sol.', 'defense', array['chute', 'sécurité', 'technique au sol'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant'], 'defense', 'Apprendre à tomber sans se blesser avant d''ajouter le ballon.', 8, 1, 8, array['tapis'], 'medium', 3, 'Depuis une position accroupie sur un tapis, laisse-toi basculer sur le côté. Enroule l''épaule et le dos pour répartir le contact, puis reviens debout. 3 séries de 6 chutes de chaque côté.', array['Depuis une position accroupie sur un tapis, laisse-toi basculer sur le côté.', 'Enroule l''épaule et le dos pour répartir le contact, puis reviens debout.', '3 séries de 6 chutes de chaque côté.'], array['Le contact au sol commence par la hanche, jamais par le coude ou la main.', 'Enroule le dos plutôt que de le garder plat.', 'Reviens debout immédiatement, la chute n''est pas une fin en soi.'], 'Amortir avec la main ou le coude, ce qui expose le poignet et l''épaule. Rester au sol après la chute.', array['Amortir avec la main ou le coude, ce qui expose le poignet et l''épaule.', 'Rester au sol après la chute.'], 'Le contact au sol commence par la hanche, jamais par le coude ou la main. Enroule le dos plutôt que de le garder plat. Reviens debout immédiatement, la chute n''est pas une fin en soi.', array['Ajoute un départ en déplacement latéral avant la chute.'], array['Pars assis au sol et travaille uniquement l''enroulé.'], true, false, 3, 3, array['defense', 'securite', 'chute', 'debutant']),
  ('defense_005', 'Plongeon avant avec roulade', 'Technique du plongeon vers l''avant terminé par une roulade, sur tapis puis sur parquet.', 'defense', array['plongeon', 'roulade', 'engagement'], array['libero', 'outside_hitter', 'opposite'], 'intermediaire', array['intermediaire', 'avance'], 'defense', 'Maîtriser un plongeon avant sécurisé et enchaîné.', 10, 1, 6, array['tapis'], 'high', 5, 'Depuis une position basse, projette-toi vers l''avant en gardant les bras tendus devant. Touche le sol avec la poitrine et les cuisses en même temps, puis enchaîne une roulade. 4 séries de 5 plongeons, avec récupération complète entre les séries.', array['Depuis une position basse, projette-toi vers l''avant en gardant les bras tendus devant.', 'Touche le sol avec la poitrine et les cuisses en même temps, puis enchaîne une roulade.', '4 séries de 5 plongeons, avec récupération complète entre les séries.'], array['Le contact au sol se fait sur une grande surface, jamais sur les mains seules.', 'Le menton reste rentré pendant toute la roulade.', 'Reviens debout dans le même mouvement que la roulade.'], 'Réceptionner tout le poids du corps sur les bras tendus. Garder la tête relevée pendant la roulade.', array['Réceptionner tout le poids du corps sur les bras tendus.', 'Garder la tête relevée pendant la roulade.'], 'Le contact au sol se fait sur une grande surface, jamais sur les mains seules. Le menton reste rentré pendant toute la roulade. Reviens debout dans le même mouvement que la roulade.', array['Ajoute un ballon à sauver juste avant le plongeon.'], array['Reste sur tapis et pars d''une position à genoux.'], true, false, 5, 4, array['defense', 'plongeon', 'technique']),
  ('defense_006', 'Défense d''attaques annoncées', 'Premières défenses sur des attaques modérées dont la direction est annoncée à l''avance.', 'defense', array['placement', 'manchette', 'lecture'], array['libero', 'outside_hitter', 'opposite'], 'debutant', array['debutant'], 'defense', 'Se placer correctement dans la trajectoire d''une attaque connue.', 10, 2, 6, array['ballons', 'filet'], 'medium', 3, 'L''attaquant annonce la direction de sa frappe avant de sauter. Le défenseur se place dans la trajectoire et renvoie haut au centre du terrain. 4 séries de 8 attaques, en alternant les directions.', array['L''attaquant annonce la direction de sa frappe avant de sauter.', 'Le défenseur se place dans la trajectoire et renvoie haut au centre du terrain.', '4 séries de 8 attaques, en alternant les directions.'], array['Sois arrêté et stable au moment où l''attaquant frappe.', 'Place-toi dans la trajectoire annoncée, pas à côté.', 'Renvoie au centre, à cinq mètres de hauteur minimum.'], 'Se déplacer encore au moment de la frappe. Reculer au lieu d''attendre en position basse.', array['Se déplacer encore au moment de la frappe.', 'Reculer au lieu d''attendre en position basse.'], 'Sois arrêté et stable au moment où l''attaquant frappe. Place-toi dans la trajectoire annoncée, pas à côté. Renvoie au centre, à cinq mètres de hauteur minimum.', array['L''attaquant n''annonce plus qu''une fois sur deux.'], array['L''attaquant frappe depuis le sol, sans saut.'], false, true, 3, 2, array['defense', 'debutant', 'placement']),
  ('defense_007', 'Défense d''attaques puissantes', 'Défense sur frappes fortes et non annoncées, centrée sur l''absorption et la survie du ballon.', 'defense', array['absorption', 'réflexes', 'engagement'], array['libero', 'outside_hitter', 'opposite'], 'avance', array['avance'], 'defense', 'Survivre à une frappe puissante en gardant le ballon jouable.', 12, 3, 6, array['ballons', 'filet'], 'high', 4, 'L''attaquant frappe à pleine puissance depuis une passe haute, sans annoncer. Le défenseur cherche uniquement à garder le ballon en jeu, dans son camp. 5 séries de 5 attaques, récupération d''une minute entre les séries.', array['L''attaquant frappe à pleine puissance depuis une passe haute, sans annoncer.', 'Le défenseur cherche uniquement à garder le ballon en jeu, dans son camp.', '5 séries de 5 attaques, récupération d''une minute entre les séries.'], array['Plateforme ferme et immobile : sur une frappe forte, tu absorbes, tu ne frappes pas.', 'Recule légèrement les bras au contact pour casser la vitesse.', 'Vise le plafond plutôt que le terrain adverse.'], 'Accompagner le ballon vers l''avant et l''envoyer directement chez l''adversaire. Fermer les yeux au moment de l''impact.', array['Accompagner le ballon vers l''avant et l''envoyer directement chez l''adversaire.', 'Fermer les yeux au moment de l''impact.'], 'Plateforme ferme et immobile : sur une frappe forte, tu absorbes, tu ne frappes pas. Recule légèrement les bras au contact pour casser la vitesse. Vise le plafond plutôt que le terrain adverse.', array['L''attaquant varie puissance et placement sans prévenir.'], array['L''attaquant réduit sa frappe à soixante-dix pour cent.'], false, true, 4, 4, array['defense', 'puissance', 'avance']),
  ('defense_008', 'Défense de la ligne', 'Couverture spécifique de la trajectoire longeant la ligne latérale, derrière le bloc extérieur.', 'defense', array['couverture de ligne', 'placement', 'lecture'], array['libero', 'outside_hitter'], 'intermediaire', array['intermediaire', 'avance'], 'defense', 'Défendre la ligne en cohérence avec le bloc.', 10, 3, 6, array['ballons', 'filet'], 'high', 4, 'Un bloqueur ferme la diagonale, l''attaquant frappe exclusivement le long de la ligne. Le défenseur de ligne se place à un mètre de la ligne et défend toutes les frappes. 4 séries de 8 attaques.', array['Un bloqueur ferme la diagonale, l''attaquant frappe exclusivement le long de la ligne.', 'Le défenseur de ligne se place à un mètre de la ligne et défend toutes les frappes.', '4 séries de 8 attaques.'], array['Place-toi un mètre à l''intérieur de la ligne, jamais collé à elle.', 'Fais confiance au bloc pour la diagonale et reste sur ta responsabilité.', 'Sur ballon long, juge rapidement s''il est sortant.'], 'Se décaler vers le centre et laisser la ligne ouverte. Défendre un ballon manifestement hors limites.', array['Se décaler vers le centre et laisser la ligne ouverte.', 'Défendre un ballon manifestement hors limites.'], 'Place-toi un mètre à l''intérieur de la ligne, jamais collé à elle. Fais confiance au bloc pour la diagonale et reste sur ta responsabilité. Sur ballon long, juge rapidement s''il est sortant.', array['L''attaquant ajoute des amortis courts sur la ligne.'], array['L''attaquant frappe depuis une position fixe et sans saut.'], false, true, 4, 3, array['defense', 'ligne', 'libero', 'bloc']),
  ('defense_009', 'Défense de la diagonale', 'Défense des frappes croisées longues, avec un placement adapté à l''angle de l''attaquant.', 'defense', array['couverture de diagonale', 'placement', 'lecture'], array['libero', 'outside_hitter', 'opposite'], 'intermediaire', array['intermediaire', 'avance'], 'defense', 'Couvrir correctement l''angle de la frappe croisée.', 10, 3, 6, array['ballons', 'filet'], 'high', 4, 'Le bloc ferme la ligne, l''attaquant frappe uniquement en croisé. Le défenseur se positionne dans l''angle de frappe et renvoie haut au centre. 4 séries de 8 attaques.', array['Le bloc ferme la ligne, l''attaquant frappe uniquement en croisé.', 'Le défenseur se positionne dans l''angle de frappe et renvoie haut au centre.', '4 séries de 8 attaques.'], array['Ton placement dépend de l''épaule de l''attaquant, pas de la position du ballon.', 'Recule d''un mètre par rapport à une défense de ligne : la diagonale est plus longue.', 'Reste bas, la trajectoire croisée descend tard.'], 'Se placer trop près du filet et se faire passer dessus. Fixer le ballon sans lire l''orientation du corps de l''attaquant.', array['Se placer trop près du filet et se faire passer dessus.', 'Fixer le ballon sans lire l''orientation du corps de l''attaquant.'], 'Ton placement dépend de l''épaule de l''attaquant, pas de la position du ballon. Recule d''un mètre par rapport à une défense de ligne : la diagonale est plus longue. Reste bas, la trajectoire croisée descend tard.', array['L''attaquant alterne croisé long et croisé court.'], array['L''attaquant frappe à puissance réduite.'], false, true, 4, 3, array['defense', 'diagonale', 'placement']),
  ('defense_010', 'Lecture du bras armé', 'Prise d''information sur l''armé de l''attaquant pour se décider avant la frappe.', 'defense', array['lecture', 'anticipation', 'prise d''information'], array['libero', 'outside_hitter', 'opposite'], 'avance', array['avance'], 'defense', 'Anticiper la direction d''attaque à partir de l''armé.', 10, 3, 6, array['ballons', 'filet'], 'medium', 4, 'Le défenseur annonce à voix haute la direction prévue dès l''armé de l''attaquant. L''attaquant frappe ensuite librement, l''annonce est comparée au résultat. 4 séries de 8 attaques, en comptant les lectures justes.', array['Le défenseur annonce à voix haute la direction prévue dès l''armé de l''attaquant.', 'L''attaquant frappe ensuite librement, l''annonce est comparée au résultat.', '4 séries de 8 attaques, en comptant les lectures justes.'], array['L''orientation des épaules et du coude annonce la direction avant la main.', 'Un attaquant en retard sous le ballon frappe rarement en puissance.', 'Décide-toi tôt, quitte à te tromper : une lecture tardive ne sert à rien.'], 'Attendre de voir le ballon partir pour bouger. Se fier uniquement aux habitudes de l''attaquant sans regarder son armé.', array['Attendre de voir le ballon partir pour bouger.', 'Se fier uniquement aux habitudes de l''attaquant sans regarder son armé.'], 'L''orientation des épaules et du coude annonce la direction avant la main. Un attaquant en retard sous le ballon frappe rarement en puissance. Décide-toi tôt, quitte à te tromper : une lecture tardive ne sert à rien.', array['L''attaquant cherche volontairement à masquer sa direction.'], array['L''attaquant marque un temps d''arrêt visible à l''armé.'], false, true, 3, 5, array['defense', 'lecture', 'anticipation', 'libero']),
  ('defense_011', 'Récupération des amortis', 'Défense des ballons déposés juste derrière le bloc, avec démarrage explosif vers l''avant.', 'defense', array['démarrage', 'ballon court', 'engagement'], array['libero', 'outside_hitter', 'opposite'], 'intermediaire', array['intermediaire', 'avance'], 'defense', 'Récupérer les ballons courts déposés derrière le bloc.', 10, 2, 6, array['ballons', 'filet'], 'high', 4, 'Le défenseur attend en fond de terrain, l''attaquant dépose des ballons courts derrière le bloc. Le défenseur sprinte et récupère le ballon avant le second rebond, en le renvoyant haut. 4 séries de 8 ballons, récupération de 45 secondes.', array['Le défenseur attend en fond de terrain, l''attaquant dépose des ballons courts derrière le bloc.', 'Le défenseur sprinte et récupère le ballon avant le second rebond, en le renvoyant haut.', '4 séries de 8 ballons, récupération de 45 secondes.'], array['Le départ se déclenche sur le geste du poignet de l''attaquant, pas sur le ballon.', 'Reste bas en avançant : te redresser te coûte un demi-mètre.', 'Sur ballon très court, une main tendue vaut mieux qu''un geste parfait raté.'], 'Rester figé en fond de terrain en regardant tomber le ballon. Se redresser au démarrage et arriver trop tard.', array['Rester figé en fond de terrain en regardant tomber le ballon.', 'Se redresser au démarrage et arriver trop tard.'], 'Le départ se déclenche sur le geste du poignet de l''attaquant, pas sur le ballon. Reste bas en avançant : te redresser te coûte un demi-mètre. Sur ballon très court, une main tendue vaut mieux qu''un geste parfait raté.', array['L''attaquant alterne amorti et frappe puissante sans prévenir.'], array['Le défenseur démarre à mi-terrain.'], false, true, 5, 3, array['defense', 'amorti', 'explosivite', 'libero']),
  ('defense_012', 'Défense des ballons placés mi-profonds', 'Traitement des frappes travaillées qui retombent entre la zone d''attaque et le fond de court.', 'defense', array['lecture de profondeur', 'déplacement', 'manchette'], array['libero', 'outside_hitter', 'opposite'], 'intermediaire', array['intermediaire', 'avance'], 'defense', 'Défendre les ballons travaillés qui cassent la profondeur.', 10, 2, 6, array['ballons', 'filet'], 'high', 4, 'L''attaquant produit des frappes molles et brossées retombant vers six mètres. Le défenseur, placé en fond, avance et renvoie haut vers le centre. 4 séries de 8 ballons.', array['L''attaquant produit des frappes molles et brossées retombant vers six mètres.', 'Le défenseur, placé en fond, avance et renvoie haut vers le centre.', '4 séries de 8 ballons.'], array['Ce ballon tombe plus vite qu''il n''en a l''air : pars dès la lecture du geste brossé.', 'Un poignet enveloppant sur le ballon annonce une trajectoire courte.', 'Renvoie haut même si tu arrives en urgence.'], 'Lire une frappe puissante et reculer par réflexe. Arriver en courant et toucher le ballon sans être stable.', array['Lire une frappe puissante et reculer par réflexe.', 'Arriver en courant et toucher le ballon sans être stable.'], 'Ce ballon tombe plus vite qu''il n''en a l''air : pars dès la lecture du geste brossé. Un poignet enveloppant sur le ballon annonce une trajectoire courte. Renvoie haut même si tu arrives en urgence.', array['L''attaquant mélange frappes puissantes et ballons brossés.'], array['L''attaquant annonce le type de frappe avant de sauter.'], false, true, 4, 4, array['defense', 'profondeur', 'lecture']),
  ('defense_013', 'Couverture de son propre attaquant', 'Placement collectif autour de l''attaquant pour récupérer les ballons renvoyés par le bloc adverse.', 'defense', array['couverture', 'placement collectif', 'réaction'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire', 'avance'], 'defense', 'Couvrir son attaquant pour récupérer les ballons contrés.', 12, 4, 8, array['ballons', 'filet'], 'high', 4, 'Un attaquant frappe contre un bloc qui renvoie volontairement le ballon dans son camp. Les coéquipiers se placent en arc de cercle autour de lui et récupèrent le contre. 4 séries de 8 attaques, en changeant d''attaquant à chaque série.', array['Un attaquant frappe contre un bloc qui renvoie volontairement le ballon dans son camp.', 'Les coéquipiers se placent en arc de cercle autour de lui et récupèrent le contre.', '4 séries de 8 attaques, en changeant d''attaquant à chaque série.'], array['Place-toi bas et près de l''attaquant, à deux mètres maximum.', 'La couverture se met en place pendant l''élan, pas après la frappe.', 'Un ballon de couverture se renvoie très haut, sans chercher à construire.'], 'Regarder son attaquant frapper sans se placer en couverture. Se placer trop loin et laisser tomber le contre entre les joueurs.', array['Regarder son attaquant frapper sans se placer en couverture.', 'Se placer trop loin et laisser tomber le contre entre les joueurs.'], 'Place-toi bas et près de l''attaquant, à deux mètres maximum. La couverture se met en place pendant l''élan, pas après la frappe. Un ballon de couverture se renvoie très haut, sans chercher à construire.', array['Le bloc renvoie dans des directions imprévisibles.'], array['Le bloc renvoie toujours au même endroit, annoncé à l''avance.'], false, true, 4, 3, array['defense', 'couverture', 'collectif']),
  ('defense_014', 'Transition défense vers attaque', 'Enchaînement entre une action défensive et le replacement offensif qui doit suivre.', 'defense', array['transition', 'replacement', 'enchaînement'], array['outside_hitter', 'opposite', 'middle_blocker'], 'avance', array['avance'], 'defense', 'Enchaîner sans temps mort entre défense et attaque.', 14, 4, 8, array['ballons', 'filet'], 'high', 5, 'Le joueur défend une attaque adverse en fond de terrain. Dès le ballon défendu, il se replace pour attaquer la passe qui suit. 4 séries de 6 enchaînements par joueur.', array['Le joueur défend une attaque adverse en fond de terrain.', 'Dès le ballon défendu, il se replace pour attaquer la passe qui suit.', '4 séries de 6 enchaînements par joueur.'], array['Le replacement commence dès que le ballon quitte tes bras.', 'Défends haut : une défense tendue ne te laisse pas le temps de te replacer.', 'Regarde le passeur en te replaçant, pas ton propre ballon.'], 'Rester spectateur de sa propre défense. Se replacer en marchant et arriver en retard pour l''élan.', array['Rester spectateur de sa propre défense.', 'Se replacer en marchant et arriver en retard pour l''élan.'], 'Le replacement commence dès que le ballon quitte tes bras. Défends haut : une défense tendue ne te laisse pas le temps de te replacer. Regarde le passeur en te replaçant, pas ton propre ballon.', array['Ajoute un bloc adverse sur l''attaque de transition.'], array['Le passeur donne une passe haute fixe et prévisible.'], false, true, 5, 4, array['defense', 'transition', 'enchainement']),
  ('defense_015', 'Répartition défensive à deux', 'Deux défenseurs se partagent ligne et diagonale selon la position du bloc.', 'defense', array['répartition', 'communication', 'placement collectif'], array['libero', 'outside_hitter', 'opposite'], 'intermediaire', array['intermediaire', 'avance'], 'defense', 'Répartir la défense à deux en fonction du bloc.', 12, 4, 8, array['ballons', 'filet'], 'medium', 4, 'Un bloqueur ferme une direction, deux défenseurs se partagent le reste du terrain. Avant chaque attaque, ils annoncent qui prend la ligne et qui prend la diagonale. 4 séries de 10 attaques, en changeant la direction fermée par le bloc.', array['Un bloqueur ferme une direction, deux défenseurs se partagent le reste du terrain.', 'Avant chaque attaque, ils annoncent qui prend la ligne et qui prend la diagonale.', '4 séries de 10 attaques, en changeant la direction fermée par le bloc.'], array['La répartition découle de la position du bloc, elle n''est jamais fixe.', 'Annonce ta responsabilité avant que l''attaquant ne saute.', 'Chacun tient sa zone même quand le ballon semble jouable par l''autre.'], 'Se répartir le terrain sans tenir compte du bloc. Partir tous les deux sur le même ballon.', array['Se répartir le terrain sans tenir compte du bloc.', 'Partir tous les deux sur le même ballon.'], 'La répartition découle de la position du bloc, elle n''est jamais fixe. Annonce ta responsabilité avant que l''attaquant ne saute. Chacun tient sa zone même quand le ballon semble jouable par l''autre.', array['Le bloc change de direction fermée en cours de série.'], array['Le bloc reste fixe pendant toute la série.'], false, true, 3, 4, array['defense', 'collectif', 'bloc', 'communication']),
  ('defense_016', 'Défense dans l''ombre du bloc', 'Placement du défenseur central directement derrière le bloc, sur les ballons qui passent au travers.', 'defense', array['placement', 'réaction', 'coordination avec le bloc'], array['libero', 'opposite'], 'avance', array['avance'], 'defense', 'Se placer dans le prolongement du bloc pour couvrir son axe.', 10, 4, 8, array['ballons', 'filet'], 'high', 4, 'Un double bloc est en place, le défenseur se positionne dans son prolongement, en fond de terrain. L''attaquant frappe volontairement au travers ou juste à côté du bloc. 4 séries de 8 attaques.', array['Un double bloc est en place, le défenseur se positionne dans son prolongement, en fond de terrain.', 'L''attaquant frappe volontairement au travers ou juste à côté du bloc.', '4 séries de 8 attaques.'], array['Reste exactement dans l''axe du bloc, ajuste-toi quand il se déplace.', 'Les ballons qui passent le bloc arrivent très vite : reste bas et immobile.', 'Sur ballon dévié, réagis vers le haut plutôt que vers l''avant.'], 'Se décaler pour voir l''attaquant et libérer l''axe du bloc. Bouger au moment de la frappe et arriver déséquilibré.', array['Se décaler pour voir l''attaquant et libérer l''axe du bloc.', 'Bouger au moment de la frappe et arriver déséquilibré.'], 'Reste exactement dans l''axe du bloc, ajuste-toi quand il se déplace. Les ballons qui passent le bloc arrivent très vite : reste bas et immobile. Sur ballon dévié, réagis vers le haut plutôt que vers l''avant.', array['Le bloc se déplace latéralement avant chaque attaque.'], array['Le bloc reste fixe et l''attaquant frappe sans saut.'], false, true, 3, 4, array['defense', 'bloc', 'placement', 'avance']),
  ('defense_017', 'Reprise des ballons déviés', 'Récupération des trajectoires imprévisibles créées par un contact avec les mains du bloc.', 'defense', array['réaction', 'adaptation', 'geste d''urgence'], array['libero', 'outside_hitter', 'opposite'], 'avance', array['avance'], 'defense', 'Réagir à une trajectoire modifiée par le bloc.', 10, 3, 6, array['ballons', 'filet'], 'high', 4, 'Un bloqueur touche volontairement chaque ballon pour le dévier sans le contrer. Le défenseur réagit à la nouvelle trajectoire et sauve le ballon. 4 séries de 8 attaques.', array['Un bloqueur touche volontairement chaque ballon pour le dévier sans le contrer.', 'Le défenseur réagit à la nouvelle trajectoire et sauve le ballon.', '4 séries de 8 attaques.'], array['Ne te décide jamais définitivement avant le passage du ballon au filet.', 'Sur ballon dévié, tous les gestes sont permis pour le garder en jeu.', 'Garde les mains hautes et devant toi pour pouvoir réagir vite.'], 'S''engager totalement sur la trajectoire initiale. Chercher un geste propre au lieu de sauver le ballon.', array['S''engager totalement sur la trajectoire initiale.', 'Chercher un geste propre au lieu de sauver le ballon.'], 'Ne te décide jamais définitivement avant le passage du ballon au filet. Sur ballon dévié, tous les gestes sont permis pour le garder en jeu. Garde les mains hautes et devant toi pour pouvoir réagir vite.', array['Le bloqueur dévie certains ballons et en laisse passer d''autres.'], array['Le bloqueur annonce à l''avance s''il va toucher le ballon.'], false, true, 4, 4, array['defense', 'reaction', 'bloc']),
  ('defense_018', 'Réaction à courte distance', 'Défense de ballons frappés à très faible distance, pour développer le temps de réaction pur.', 'defense', array['réflexes', 'vitesse de réaction', 'mains'], array['libero', 'outside_hitter', 'opposite'], 'intermediaire', array['intermediaire', 'avance'], 'vitesse', 'Réduire son temps de réaction sur un ballon proche.', 8, 2, 4, array['ballons'], 'high', 4, 'Le lanceur se place à trois mètres du défenseur et frappe des ballons secs. Le défenseur renvoie haut, avec n''importe quelle partie des bras ou des mains. 4 séries de 10 ballons, avec une minute de récupération.', array['Le lanceur se place à trois mètres du défenseur et frappe des ballons secs.', 'Le défenseur renvoie haut, avec n''importe quelle partie des bras ou des mains.', '4 séries de 10 ballons, avec une minute de récupération.'], array['Mains hautes et devant toi en permanence, prêtes à intervenir.', 'Sur ce type de ballon, la vitesse prime sur la forme du geste.', 'Reste sur l''avant des pieds, jamais sur les talons.'], 'Garder les bras le long du corps entre les ballons. Fermer les yeux ou détourner la tête à l''impact.', array['Garder les bras le long du corps entre les ballons.', 'Fermer les yeux ou détourner la tête à l''impact.'], 'Mains hautes et devant toi en permanence, prêtes à intervenir. Sur ce type de ballon, la vitesse prime sur la forme du geste. Reste sur l''avant des pieds, jamais sur les talons.', array['Rapproche le lanceur à deux mètres.'], array['Recule le lanceur à cinq mètres et réduis la puissance.'], false, true, 4, 3, array['defense', 'reflexes', 'reaction']),
  ('defense_019', 'Série défensive continue', 'Enchaînement ininterrompu de ballons défensifs pour travailler la répétition sous fatigue.', 'defense', array['endurance', 'régularité', 'engagement'], array['libero', 'outside_hitter', 'opposite'], 'avance', array['avance'], 'defense', 'Tenir un effort défensif répété sans perdre la posture.', 12, 2, 6, array['ballons'], 'high', 4, 'Le lanceur envoie un ballon toutes les trois secondes, dans des directions variées. Le défenseur enchaîne sans pause pendant quarante-cinq secondes. 4 séries, avec deux minutes de récupération entre chacune.', array['Le lanceur envoie un ballon toutes les trois secondes, dans des directions variées.', 'Le défenseur enchaîne sans pause pendant quarante-cinq secondes.', '4 séries, avec deux minutes de récupération entre chacune.'], array['Reviens en position d''attente après chaque ballon, même en fin de série.', 'Respire entre les ballons plutôt que de retenir ton souffle.', 'Quand la fatigue monte, simplifie le geste au lieu de forcer.'], 'Rester au sol après un ballon difficile. Se relever complètement entre chaque ballon et perdre du temps.', array['Rester au sol après un ballon difficile.', 'Se relever complètement entre chaque ballon et perdre du temps.'], 'Reviens en position d''attente après chaque ballon, même en fin de série. Respire entre les ballons plutôt que de retenir ton souffle. Quand la fatigue monte, simplifie le geste au lieu de forcer.', array['Allonge la série à une minute.'], array['Réduis la série à trente secondes et ralentis la cadence.'], false, true, 5, 3, array['defense', 'endurance', 'intensite']),
  ('defense_020', 'Défense avec déplacement imposé', 'Chaque défense est précédée d''un déplacement latéral obligatoire vers un plot.', 'defense', array['déplacement', 'stabilisation', 'défense'], array['libero', 'outside_hitter', 'opposite'], 'intermediaire', array['intermediaire'], 'defense', 'Défendre après un déplacement sans perdre l''équilibre.', 10, 2, 4, array['ballons', 'plots'], 'high', 4, 'Deux plots sont posés à trois mètres d''écart en fond de terrain. Le défenseur touche le plot annoncé puis défend le ballon envoyé au centre. 4 séries de 10 ballons.', array['Deux plots sont posés à trois mètres d''écart en fond de terrain.', 'Le défenseur touche le plot annoncé puis défend le ballon envoyé au centre.', '4 séries de 10 ballons.'], array['Arrive stabilisé : un appui d''arrêt précède toujours la défense.', 'Déplace-toi en pas chassés, buste bas et orienté vers le filet.', 'Ne croise jamais les appuis sur une courte distance.'], 'Défendre en plein déplacement. Se redresser pendant le déplacement latéral.', array['Défendre en plein déplacement.', 'Se redresser pendant le déplacement latéral.'], 'Arrive stabilisé : un appui d''arrêt précède toujours la défense. Déplace-toi en pas chassés, buste bas et orienté vers le filet. Ne croise jamais les appuis sur une courte distance.', array['Le plot n''est annoncé qu''au dernier moment.'], array['Rapproche les plots à un mètre cinquante.'], false, true, 4, 3, array['defense', 'deplacement', 'appuis']),
  ('defense_021', 'Sauvetage en extension d''un bras', 'Geste d''urgence à une main sur des ballons hors de portée de la plateforme.', 'defense', array['geste d''urgence', 'extension', 'engagement'], array['libero', 'outside_hitter', 'opposite'], 'avance', array['avance'], 'defense', 'Sauver un ballon hors de portée sans se blesser.', 10, 2, 4, array['ballons', 'tapis'], 'high', 5, 'Le lanceur envoie volontairement des ballons à plus de deux mètres du défenseur. Le défenseur se projette et touche le ballon d''une seule main, poing fermé ou main ouverte. 4 séries de 6 ballons de chaque côté.', array['Le lanceur envoie volontairement des ballons à plus de deux mètres du défenseur.', 'Le défenseur se projette et touche le ballon d''une seule main, poing fermé ou main ouverte.', '4 séries de 6 ballons de chaque côté.'], array['Tends le bras au maximum et frappe le ballon vers le haut, jamais vers l''avant.', 'Termine systématiquement par une roulade ou une glissade contrôlée.', 'Ce geste est un dernier recours : privilégie toujours le déplacement.'], 'Se jeter avant d''avoir essayé de se déplacer. Réceptionner le poids du corps sur la main d''appui.', array['Se jeter avant d''avoir essayé de se déplacer.', 'Réceptionner le poids du corps sur la main d''appui.'], 'Tends le bras au maximum et frappe le ballon vers le haut, jamais vers l''avant. Termine systématiquement par une roulade ou une glissade contrôlée. Ce geste est un dernier recours : privilégie toujours le déplacement.', array['Augmente la distance latérale à deux mètres cinquante.'], array['Réduis la distance et travaille uniquement sur tapis.'], false, true, 5, 4, array['defense', 'urgence', 'avance', 'libero']),
  ('defense_022', 'Défense haute à deux mains', 'Traitement des ballons qui arrivent au-dessus des épaules en défense, à deux mains.', 'defense', array['touche haute', 'défense', 'contrôle'], array['libero', 'outside_hitter', 'opposite'], 'intermediaire', array['intermediaire', 'avance'], 'defense', 'Défendre proprement un ballon arrivant au-dessus des épaules.', 8, 2, 4, array['ballons', 'filet'], 'medium', 3, 'L''attaquant frappe volontairement haut, au-dessus des épaules du défenseur. Le défenseur les traite à deux mains au-dessus du front et renvoie au centre. 3 séries de 10 ballons.', array['L''attaquant frappe volontairement haut, au-dessus des épaules du défenseur.', 'Le défenseur les traite à deux mains au-dessus du front et renvoie au centre.', '3 séries de 10 ballons.'], array['Doigts fermes et poignets solides : le ballon arrive vite.', 'Place ton front sous le ballon avant de toucher.', 'Renvoie haut et au centre, sans chercher à construire.'], 'Reculer la tête et prendre le ballon derrière soi. Utiliser la manchette sur un ballon au-dessus des épaules.', array['Reculer la tête et prendre le ballon derrière soi.', 'Utiliser la manchette sur un ballon au-dessus des épaules.'], 'Doigts fermes et poignets solides : le ballon arrive vite. Place ton front sous le ballon avant de toucher. Renvoie haut et au centre, sans chercher à construire.', array['L''attaquant alterne ballons hauts et frappes basses.'], array['Le partenaire lance le ballon à la main.'], false, true, 2, 4, array['defense', 'touche haute', 'controle']),
  ('defense_023', 'Plongeons latéraux alternés', 'Enchaînement de plongeons vers la gauche puis la droite, avec retour en position entre chaque.', 'defense', array['plongeon', 'latéralité', 'engagement'], array['libero', 'outside_hitter', 'opposite'], 'avance', array['avance'], 'defense', 'Enchaîner des plongeons latéraux des deux côtés.', 10, 2, 4, array['ballons', 'tapis'], 'high', 5, 'Le lanceur envoie alternativement un ballon à gauche puis à droite, hors de portée en marchant. Le défenseur plonge, sauve le ballon, se relève et se replace au centre. 4 séries de 6 plongeons, avec récupération complète entre les séries.', array['Le lanceur envoie alternativement un ballon à gauche puis à droite, hors de portée en marchant.', 'Le défenseur plonge, sauve le ballon, se relève et se replace au centre.', '4 séries de 6 plongeons, avec récupération complète entre les séries.'], array['Pousse fort sur la jambe extérieure pour partir loin.', 'Contact au sol sur la hanche puis le flanc, jamais sur le coude.', 'Relève-toi dans le mouvement, sans passer par la position assise.'], 'Plonger vers le bas plutôt que vers le côté. Rester au sol et attendre le ballon suivant.', array['Plonger vers le bas plutôt que vers le côté.', 'Rester au sol et attendre le ballon suivant.'], 'Pousse fort sur la jambe extérieure pour partir loin. Contact au sol sur la hanche puis le flanc, jamais sur le coude. Relève-toi dans le mouvement, sans passer par la position assise.', array['Le lanceur n''annonce plus le côté.'], array['Travaille un seul côté par série, sur tapis.'], false, true, 5, 4, array['defense', 'plongeon', 'avance']),
  ('defense_024', 'Relance haute au centre', 'Défense orientée vers une zone de relance unique pour faciliter la construction qui suit.', 'defense', array['orientation', 'relance', 'précision'], array['libero', 'outside_hitter', 'opposite'], 'intermediaire', array['intermediaire'], 'precision', 'Relancer systématiquement haut et au centre après une défense.', 10, 3, 6, array['ballons', 'filet', 'plots'], 'medium', 3, 'Une cible de trois mètres sur trois est matérialisée au centre du terrain, à cinq mètres du filet. Chaque ballon défendu doit retomber dans cette cible, à plus de quatre mètres de hauteur. 4 séries de 10 défenses, en comptant les réussites.', array['Une cible de trois mètres sur trois est matérialisée au centre du terrain, à cinq mètres du filet.', 'Chaque ballon défendu doit retomber dans cette cible, à plus de quatre mètres de hauteur.', '4 séries de 10 défenses, en comptant les réussites.'], array['Oriente la plateforme vers le centre dès que tu te places.', 'La hauteur prime : un ballon haut au centre est toujours jouable.', 'Ne cherche jamais à relancer directement vers le passeur en défense.'], 'Relancer vers le filet et provoquer un ballon injouable. Renvoyer trop tendu par réflexe.', array['Relancer vers le filet et provoquer un ballon injouable.', 'Renvoyer trop tendu par réflexe.'], 'Oriente la plateforme vers le centre dès que tu te places. La hauteur prime : un ballon haut au centre est toujours jouable. Ne cherche jamais à relancer directement vers le passeur en défense.', array['Réduis la cible à deux mètres sur deux.'], array['Élargis la cible à la moitié du terrain.'], false, true, 3, 3, array['defense', 'relance', 'precision']),
  ('defense_025', 'Système défensif à trois arrières', 'Organisation complète de la ligne arrière face à des attaques venant de différentes zones.', 'defense', array['organisation collective', 'placement', 'communication'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'avance', array['avance'], 'defense', 'Faire fonctionner un dispositif défensif collectif cohérent.', 15, 6, 12, array['ballons', 'filet'], 'high', 5, 'Trois défenseurs occupent les zones 1, 5 et 6, avec un double bloc au filet. L''attaque adverse alterne les zones 4, 3 et 2 sans prévenir. 4 séries de 10 attaques, avec analyse du placement entre les séries.', array['Trois défenseurs occupent les zones 1, 5 et 6, avec un double bloc au filet.', 'L''attaque adverse alterne les zones 4, 3 et 2 sans prévenir.', '4 séries de 10 attaques, avec analyse du placement entre les séries.'], array['Tout le dispositif se décale en fonction de la position du bloc.', 'Le défenseur en zone 6 ajuste sa profondeur selon la hauteur de la passe adverse.', 'Chaque déplacement du bloc doit être annoncé aux arrières.'], 'Garder un dispositif figé quel que soit le bloc. Se placer trop profond et laisser un trou à sept mètres.', array['Garder un dispositif figé quel que soit le bloc.', 'Se placer trop profond et laisser un trou à sept mètres.'], 'Tout le dispositif se décale en fonction de la position du bloc. Le défenseur en zone 6 ajuste sa profondeur selon la hauteur de la passe adverse. Chaque déplacement du bloc doit être annoncé aux arrières.', array['L''adversaire ajoute des attaques de fond de court.'], array['L''attaque vient toujours de la même zone.'], false, true, 4, 5, array['defense', 'collectif', 'systeme', 'avance']),
  ('defense_026', 'Défense de l''attaque extérieure', 'Situation défensive spécifique face à un attaquant de zone 4, la configuration la plus fréquente.', 'defense', array['placement', 'lecture', 'défense'], array['libero', 'outside_hitter', 'opposite'], 'intermediaire', array['intermediaire', 'avance'], 'defense', 'Organiser la défense face à un attaquant de zone 4.', 12, 4, 8, array['ballons', 'filet'], 'high', 4, 'Un attaquant frappe systématiquement depuis la zone 4, sur passe haute. Le dispositif défensif complet se place et défend toutes les directions possibles. 4 séries de 10 attaques.', array['Un attaquant frappe systématiquement depuis la zone 4, sur passe haute.', 'Le dispositif défensif complet se place et défend toutes les directions possibles.', '4 séries de 10 attaques.'], array['L''angle disponible depuis la zone 4 est large : le défenseur de zone 5 recule.', 'Le bloc doit fermer une direction claire pour rendre la défense lisible.', 'Anticipe la frappe croisée, statistiquement la plus fréquente depuis cette zone.'], 'Se placer symétriquement sans tenir compte de l''angle réel. Attendre la frappe sans avoir lu la qualité de la passe adverse.', array['Se placer symétriquement sans tenir compte de l''angle réel.', 'Attendre la frappe sans avoir lu la qualité de la passe adverse.'], 'L''angle disponible depuis la zone 4 est large : le défenseur de zone 5 recule. Le bloc doit fermer une direction claire pour rendre la défense lisible. Anticipe la frappe croisée, statistiquement la plus fréquente depuis cette zone.', array['L''attaquant ajoute des amortis et des ballons placés.'], array['L''attaquant frappe uniquement dans une direction annoncée.'], false, true, 4, 4, array['defense', 'collectif', 'zone 4']),
  ('defense_027', 'Défense de l''attaque du pointu', 'Situation défensive face à un attaquant de zone 2, avec des angles inversés par rapport à la zone 4.', 'defense', array['placement', 'adaptation', 'défense'], array['libero', 'outside_hitter', 'opposite'], 'avance', array['avance'], 'defense', 'Adapter la défense aux angles d''une attaque de zone 2.', 12, 4, 8, array['ballons', 'filet'], 'high', 4, 'Un pointu attaque systématiquement depuis la zone 2, sur passe haute. La défense ajuste son dispositif aux angles propres à ce côté du terrain. 4 séries de 10 attaques.', array['Un pointu attaque systématiquement depuis la zone 2, sur passe haute.', 'La défense ajuste son dispositif aux angles propres à ce côté du terrain.', '4 séries de 10 attaques.'], array['Les angles sont l''image miroir de la zone 4 : c''est le défenseur de zone 1 qui recule.', 'Un pointu droitier frappe souvent long de ligne : couvre-la en priorité.', 'Le libéro adapte sa position à celle du bloc, pas à l''habitude.'], 'Reproduire à l''identique le placement utilisé face à la zone 4. Laisser la ligne ouverte en se décalant trop au centre.', array['Reproduire à l''identique le placement utilisé face à la zone 4.', 'Laisser la ligne ouverte en se décalant trop au centre.'], 'Les angles sont l''image miroir de la zone 4 : c''est le défenseur de zone 1 qui recule. Un pointu droitier frappe souvent long de ligne : couvre-la en priorité. Le libéro adapte sa position à celle du bloc, pas à l''habitude.', array['Alterne attaques de zone 2 et de zone 4 dans la même série.'], array['Le pointu attaque sans saut, depuis le sol.'], false, true, 4, 4, array['defense', 'collectif', 'pointu']),
  ('defense_028', 'Défense de la rapide centrale', 'Défense face à une attaque rapide du central, où le temps de réaction est très court.', 'defense', array['réaction', 'anticipation', 'placement'], array['libero', 'outside_hitter', 'opposite'], 'avance', array['avance'], 'defense', 'Être déjà placé face à une attaque rapide centrale.', 12, 4, 8, array['ballons', 'filet'], 'high', 5, 'Le central adverse attaque sur passe rapide et basse, au centre du filet. La défense doit être en place avant le contact, sans le moindre déplacement tardif. 4 séries de 8 attaques.', array['Le central adverse attaque sur passe rapide et basse, au centre du filet.', 'La défense doit être en place avant le contact, sans le moindre déplacement tardif.', '4 séries de 8 attaques.'], array['Sur une rapide, tu n''as pas le temps de te déplacer : place-toi avant la passe.', 'Avance légèrement : les rapides tombent souvent courtes.', 'Lis la position du passeur adverse pour anticiper la rapide.'], 'Chercher à se déplacer une fois la frappe partie. Rester en position haute sur une attaque aussi rapide.', array['Chercher à se déplacer une fois la frappe partie.', 'Rester en position haute sur une attaque aussi rapide.'], 'Sur une rapide, tu n''as pas le temps de te déplacer : place-toi avant la passe. Avance légèrement : les rapides tombent souvent courtes. Lis la position du passeur adverse pour anticiper la rapide.', array['Le passeur adverse alterne rapide et passe haute extérieure.'], array['La rapide est annoncée avant chaque ballon.'], false, true, 4, 5, array['defense', 'rapide', 'anticipation', 'avance']),
  ('defense_029', 'Défense des attaques de fond de court', 'Défense face aux attaques venues de la ligne des trois mètres, aux trajectoires plus longues.', 'defense', array['profondeur', 'placement', 'lecture'], array['libero', 'outside_hitter', 'opposite'], 'avance', array['avance'], 'defense', 'Ajuster sa profondeur face à une attaque de fond de court.', 10, 4, 8, array['ballons', 'filet'], 'high', 4, 'L''attaquant frappe depuis la zone arrière, derrière la ligne des trois mètres. Les défenseurs reculent pour couvrir des trajectoires plus longues et plus tendues. 4 séries de 8 attaques.', array['L''attaquant frappe depuis la zone arrière, derrière la ligne des trois mètres.', 'Les défenseurs reculent pour couvrir des trajectoires plus longues et plus tendues.', '4 séries de 8 attaques.'], array['Recule d''un mètre par rapport à une défense d''attaque au filet.', 'La trajectoire est plus tendue : reste bas et prêt à absorber.', 'Le bloc sert moins : la défense au sol devient prioritaire.'], 'Conserver le placement utilisé face à une attaque au filet. Se faire surprendre par la longueur de la trajectoire.', array['Conserver le placement utilisé face à une attaque au filet.', 'Se faire surprendre par la longueur de la trajectoire.'], 'Recule d''un mètre par rapport à une défense d''attaque au filet. La trajectoire est plus tendue : reste bas et prêt à absorber. Le bloc sert moins : la défense au sol devient prioritaire.', array['L''attaquant alterne attaque de fond et amorti court.'], array['L''attaquant réduit sa puissance de moitié.'], false, true, 4, 4, array['defense', 'profondeur', 'avance']),
  ('defense_030', 'Annonce du bloc vers les arrières', 'Communication systématique entre les bloqueurs et la défense sur la direction fermée.', 'defense', array['communication', 'coordination', 'placement collectif'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire', 'avance'], 'defense', 'Faire circuler l''information entre bloc et défense.', 12, 5, 10, array['ballons', 'filet'], 'medium', 3, 'Avant chaque attaque, le bloqueur annonce à voix haute la direction qu''il ferme. Les défenseurs se replacent en conséquence avant la frappe. 4 séries de 10 attaques, sans jamais sauter une annonce.', array['Avant chaque attaque, le bloqueur annonce à voix haute la direction qu''il ferme.', 'Les défenseurs se replacent en conséquence avant la frappe.', '4 séries de 10 attaques, sans jamais sauter une annonce.'], array['L''annonce se fait avant le saut, pas pendant.', 'Les arrières confirment l''information par une annonce courte.', 'Une annonce claire vaut mieux qu''une annonce exacte mais tardive.'], 'Annoncer une direction et en fermer une autre. Laisser les arrières deviner la configuration du bloc.', array['Annoncer une direction et en fermer une autre.', 'Laisser les arrières deviner la configuration du bloc.'], 'L''annonce se fait avant le saut, pas pendant. Les arrières confirment l''information par une annonce courte. Une annonce claire vaut mieux qu''une annonce exacte mais tardive.', array['Le bloc change de direction au dernier moment et doit le réannoncer.'], array['La direction fermée reste identique pendant toute la série.'], false, true, 3, 3, array['defense', 'communication', 'bloc', 'collectif']),
  ('defense_031', 'Récupération après bloc débordé', 'Défense des ballons qui passent au-dessus ou à côté d''un bloc mal positionné.', 'defense', array['adaptation', 'réaction', 'couverture'], array['libero', 'outside_hitter', 'opposite'], 'avance', array['avance'], 'defense', 'Réorganiser la défense quand le bloc ne remplit pas son rôle.', 10, 4, 8, array['ballons', 'filet'], 'high', 4, 'Le bloqueur saute volontairement en retard ou décalé sur chaque attaque. Les défenseurs doivent couvrir un terrain dont aucune direction n''est fermée. 4 séries de 8 attaques.', array['Le bloqueur saute volontairement en retard ou décalé sur chaque attaque.', 'Les défenseurs doivent couvrir un terrain dont aucune direction n''est fermée.', '4 séries de 8 attaques.'], array['Quand le bloc est débordé, chaque défenseur élargit sa zone d''un mètre.', 'Recule légèrement : sans bloc, les trajectoires sont plus longues.', 'Communique immédiatement que le bloc est hors-jeu.'], 'Conserver un placement qui suppose un bloc efficace. Attendre que le bloc corrige au lieu de s''adapter.', array['Conserver un placement qui suppose un bloc efficace.', 'Attendre que le bloc corrige au lieu de s''adapter.'], 'Quand le bloc est débordé, chaque défenseur élargit sa zone d''un mètre. Recule légèrement : sans bloc, les trajectoires sont plus longues. Communique immédiatement que le bloc est hors-jeu.', array['Le bloqueur alterne bloc efficace et bloc débordé sans prévenir.'], array['Le bloc est totalement absent et la défense s''organise sans lui.'], false, true, 4, 4, array['defense', 'adaptation', 'bloc']),
  ('defense_032', 'Traitement du ballon de renvoi', 'Gestion collective des ballons adverses renvoyés en cloche, faciles mais souvent mal exploités.', 'defense', array['organisation', 'communication', 'construction'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire'], 'defense', 'Exploiter correctement un ballon adverse facile.', 10, 4, 8, array['ballons', 'filet'], 'low', 2, 'L''adversaire renvoie des ballons hauts et faciles dans le camp. L''équipe s''organise pour construire une attaque complète en trois touches. 4 séries de 8 ballons.', array['L''adversaire renvoie des ballons hauts et faciles dans le camp.', 'L''équipe s''organise pour construire une attaque complète en trois touches.', '4 séries de 8 ballons.'], array['Annonce très tôt : sur un ballon facile, l''hésitation est la seule vraie difficulté.', 'Le passeur se replace immédiatement dès que le ballon est identifié comme facile.', 'Ne précipite pas la première touche, ce ballon donne du temps.'], 'Se précipiter et se gêner à plusieurs sur un ballon simple. Renvoyer directement au lieu de construire.', array['Se précipiter et se gêner à plusieurs sur un ballon simple.', 'Renvoyer directement au lieu de construire.'], 'Annonce très tôt : sur un ballon facile, l''hésitation est la seule vraie difficulté. Le passeur se replace immédiatement dès que le ballon est identifié comme facile. Ne précipite pas la première touche, ce ballon donne du temps.', array['Impose une attaque conclue depuis une zone annoncée à l''avance.'], array['Un joueur est désigné pour prendre tous les ballons de renvoi.'], false, true, 2, 2, array['defense', 'construction', 'collectif']),
  ('defense_033', 'Défense proche du filet', 'Traitement des ballons courts tombant dans la zone d''attaque, entre bloc et défense.', 'defense', array['ballon court', 'réaction', 'placement'], array['outside_hitter', 'opposite', 'middle_blocker'], 'intermediaire', array['intermediaire', 'avance'], 'defense', 'Couvrir la zone courte située juste derrière le bloc.', 10, 3, 6, array['ballons', 'filet'], 'high', 4, 'L''attaquant dépose des ballons dans les trois premiers mètres, derrière le bloc. Les joueurs avant retombent de leur saut et récupèrent le ballon au sol. 4 séries de 8 ballons.', array['L''attaquant dépose des ballons dans les trois premiers mètres, derrière le bloc.', 'Les joueurs avant retombent de leur saut et récupèrent le ballon au sol.', '4 séries de 8 ballons.'], array['Après ton saut de bloc, retombe équilibré et fais immédiatement demi-tour.', 'Cette zone est la responsabilité des avants, pas du libéro.', 'Une main tendue au ras du sol suffit à sauver le ballon.'], 'Rester tourné vers le filet après le bloc. Compter sur les arrières pour un ballon tombé à trois mètres.', array['Rester tourné vers le filet après le bloc.', 'Compter sur les arrières pour un ballon tombé à trois mètres.'], 'Après ton saut de bloc, retombe équilibré et fais immédiatement demi-tour. Cette zone est la responsabilité des avants, pas du libéro. Une main tendue au ras du sol suffit à sauver le ballon.', array['L''attaquant alterne amorti court et frappe puissante.'], array['Le bloc est retiré et le joueur part déjà tourné vers le terrain.'], false, true, 4, 3, array['defense', 'ballon court', 'avants']),
  ('defense_034', 'Anticipation par la passe adverse', 'Placement défensif décidé à partir de la qualité et de la direction de la passe adverse.', 'defense', array['anticipation', 'lecture de passe', 'placement'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'avance', array['avance'], 'defense', 'Se replacer en défense à partir de la lecture de la passe.', 12, 5, 10, array['ballons', 'filet'], 'medium', 4, 'Le passeur adverse distribue librement vers les zones 4, 3 ou 2. Les défenseurs doivent être replacés avant que l''attaquant ne frappe. 4 séries de 10 ballons, en notant les replacements tardifs.', array['Le passeur adverse distribue librement vers les zones 4, 3 ou 2.', 'Les défenseurs doivent être replacés avant que l''attaquant ne frappe.', '4 séries de 10 ballons, en notant les replacements tardifs.'], array['Regarde la passe, pas l''attaquant : elle donne l''information une seconde plus tôt.', 'Une passe décollée du filet annonce une attaque moins puissante : avance.', 'Une passe rapide impose d''être déjà placé, sans déplacement possible.'], 'Attendre de voir quel attaquant saute pour se replacer. Se déplacer pendant la frappe adverse.', array['Attendre de voir quel attaquant saute pour se replacer.', 'Se déplacer pendant la frappe adverse.'], 'Regarde la passe, pas l''attaquant : elle donne l''information une seconde plus tôt. Une passe décollée du filet annonce une attaque moins puissante : avance. Une passe rapide impose d''être déjà placé, sans déplacement possible.', array['Le passeur adverse utilise des feintes de passe.'], array['Le passeur annonce sa distribution avant de toucher le ballon.'], false, true, 3, 5, array['defense', 'anticipation', 'lecture', 'avance']),
  ('defense_035', 'Défense en état de fatigue', 'Séquence défensive placée volontairement après un effort physique intense.', 'defense', array['endurance', 'lucidité', 'défense'], array['libero', 'outside_hitter', 'opposite'], 'avance', array['avance'], 'defense', 'Maintenir sa qualité défensive en état de fatigue.', 12, 2, 6, array['ballons'], 'high', 4, 'Effectue trente secondes de déplacements latéraux intensifs. Enchaîne immédiatement dix ballons à défendre, sans récupération. 4 séries, avec deux minutes de récupération complète entre chacune.', array['Effectue trente secondes de déplacements latéraux intensifs.', 'Enchaîne immédiatement dix ballons à défendre, sans récupération.', '4 séries, avec deux minutes de récupération complète entre chacune.'], array['Conserve ta position basse même quand les jambes brûlent.', 'Simplifie tes choix : haut et au centre, systématiquement.', 'Utilise chaque intervalle entre deux ballons pour respirer.'], 'Défendre debout dès que la fatigue s''installe. Vouloir des gestes parfaits au lieu de garder le ballon en jeu.', array['Défendre debout dès que la fatigue s''installe.', 'Vouloir des gestes parfaits au lieu de garder le ballon en jeu.'], 'Conserve ta position basse même quand les jambes brûlent. Simplifie tes choix : haut et au centre, systématiquement. Utilise chaque intervalle entre deux ballons pour respirer.', array['Allonge l''effort préalable à quarante-cinq secondes.'], array['Réduis l''effort préalable à quinze secondes.'], false, true, 5, 3, array['defense', 'fatigue', 'physique']),
  ('defense_036', 'Défense évaluée par zone de relance', 'Notation de chaque défense selon l''endroit où le ballon retombe, pour mesurer l''utilité réelle.', 'defense', array['évaluation', 'précision', 'relance'], array['libero', 'outside_hitter', 'opposite'], 'intermediaire', array['intermediaire', 'avance'], 'defense', 'Mesurer l''utilité réelle de ses ballons défendus.', 12, 3, 6, array['ballons', 'filet', 'plots'], 'medium', 4, 'Le terrain est divisé en trois zones de relance notées 3, 2 et 1 selon leur utilité. Chaque défense est notée, le joueur calcule sa moyenne sur vingt ballons. 2 séries par joueur, avec l''objectif d''augmenter la moyenne.', array['Le terrain est divisé en trois zones de relance notées 3, 2 et 1 selon leur utilité.', 'Chaque défense est notée, le joueur calcule sa moyenne sur vingt ballons.', '2 séries par joueur, avec l''objectif d''augmenter la moyenne.'], array['Un ballon défendu mais inexploitable ne vaut presque rien : vise la zone utile.', 'La hauteur compte autant que la zone : un ballon bas ne se joue pas.', 'Analyse les ballons à 1 pour trouver l''erreur d''orientation qui revient.'], 'Se contenter de toucher le ballon sans penser à la suite. Sacrifier la hauteur pour gagner en précision.', array['Se contenter de toucher le ballon sans penser à la suite.', 'Sacrifier la hauteur pour gagner en précision.'], 'Un ballon défendu mais inexploitable ne vaut presque rien : vise la zone utile. La hauteur compte autant que la zone : un ballon bas ne se joue pas. Analyse les ballons à 1 pour trouver l''erreur d''orientation qui revient.', array['Ajoute une hauteur minimale obligatoire pour valider la note.'], array['Note simplement les ballons comme jouables ou non.'], false, true, 3, 4, array['defense', 'evaluation', 'statistiques']),
  ('defense_037', 'Double ballon en directions opposées', 'Deux ballons envoyés coup sur coup dans des directions opposées, pour forcer le replacement.', 'defense', array['replacement', 'vitesse', 'défense'], array['libero', 'outside_hitter', 'opposite'], 'avance', array['avance'], 'defense', 'Enchaîner deux interventions défensives opposées.', 10, 2, 4, array['ballons'], 'high', 5, 'Le lanceur envoie un ballon à gauche, puis immédiatement un second à droite. Le défenseur doit sauver les deux, sans temps mort entre les deux gestes. 4 séries de 6 doubles ballons.', array['Le lanceur envoie un ballon à gauche, puis immédiatement un second à droite.', 'Le défenseur doit sauver les deux, sans temps mort entre les deux gestes.', '4 séries de 6 doubles ballons.'], array['Le premier geste conditionne le second : ne t''écroule pas après le ballon initial.', 'Repousse-toi activement du sol pour repartir dans l''autre direction.', 'Renvoie court et haut sur le premier ballon pour gagner du temps.'], 'S''engager totalement sur le premier ballon et abandonner le second. Rester au sol après le premier geste.', array['S''engager totalement sur le premier ballon et abandonner le second.', 'Rester au sol après le premier geste.'], 'Le premier geste conditionne le second : ne t''écroule pas après le ballon initial. Repousse-toi activement du sol pour repartir dans l''autre direction. Renvoie court et haut sur le premier ballon pour gagner du temps.', array['Ajoute un troisième ballon dans la séquence.'], array['Allonge le délai entre les deux ballons.'], false, true, 5, 4, array['defense', 'enchainement', 'replacement']),
  ('defense_038', 'Défi des ballons sauvés', 'Objectif chiffré de ballons consécutifs gardés en jeu, avec remise à zéro en cas d''échec.', 'defense', array['régularité', 'concentration', 'engagement'], array['libero', 'outside_hitter', 'opposite'], 'intermediaire', array['intermediaire', 'avance'], 'regularite', 'Enchaîner une longue série de ballons gardés en jeu.', 10, 2, 6, array['ballons'], 'high', 4, 'Le lanceur envoie des ballons variés, chaque ballon gardé en jeu compte pour un. Le compteur revient à zéro dès qu''un ballon touche le sol. L''exercice s''arrête quand le joueur atteint douze ballons consécutifs.', array['Le lanceur envoie des ballons variés, chaque ballon gardé en jeu compte pour un.', 'Le compteur revient à zéro dès qu''un ballon touche le sol.', 'L''exercice s''arrête quand le joueur atteint douze ballons consécutifs.'], array['Garde le même engagement du premier au dernier ballon.', 'Sur les ballons difficiles, accepte un geste laid mais efficace.', 'Reviens toujours en position d''attente entre deux ballons.'], 'Se relâcher sur les ballons faciles après une belle série. Abandonner mentalement après une remise à zéro.', array['Se relâcher sur les ballons faciles après une belle série.', 'Abandonner mentalement après une remise à zéro.'], 'Garde le même engagement du premier au dernier ballon. Sur les ballons difficiles, accepte un geste laid mais efficace. Reviens toujours en position d''attente entre deux ballons.', array['Porte l''objectif à vingt ballons consécutifs.'], array['Abaisse l''objectif à huit ballons et réduis la difficulté des envois.'], false, true, 4, 3, array['defense', 'defi', 'regularite']),
  ('defense_039', 'Point joué en infériorité défensive', 'Points disputés avec un défenseur en moins, pour développer la couverture et la communication.', 'defense', array['couverture', 'communication', 'situation de jeu'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'avance', array['avance'], 'competition', 'S''organiser défensivement malgré un joueur manquant.', 15, 6, 11, array['ballons', 'filet'], 'high', 5, 'L''équipe en défense joue à cinq contre six en attaque. Les points se jouent normalement jusqu''à leur conclusion. Jouez 15 points, puis inversez les rôles.', array['L''équipe en défense joue à cinq contre six en attaque.', 'Les points se jouent normalement jusqu''à leur conclusion.', 'Jouez 15 points, puis inversez les rôles.'], array['Identifiez ensemble la zone laissée libre et décidez qui la couvre.', 'La communication devient prioritaire dès qu''il manque un joueur.', 'Acceptez de concéder une zone pour en protéger deux.'], 'Essayer de tout couvrir et ne rien couvrir correctement. Jouer en silence en situation d''infériorité.', array['Essayer de tout couvrir et ne rien couvrir correctement.', 'Jouer en silence en situation d''infériorité.'], 'Identifiez ensemble la zone laissée libre et décidez qui la couvre. La communication devient prioritaire dès qu''il manque un joueur. Acceptez de concéder une zone pour en protéger deux.', array['Retirez un second défenseur.'], array['Revenez à six contre six avec une zone neutralisée.'], false, true, 5, 4, array['defense', 'competition', 'collectif']),
  ('defense_040', 'Défense sur points à thème', 'Points de match où seuls les points gagnés par une action défensive sont comptabilisés.', 'defense', array['situation de jeu', 'engagement', 'collectif'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire', 'avance'], 'competition', 'Mettre la réussite défensive au cœur du jeu.', 15, 8, 12, array['ballons', 'filet'], 'high', 4, 'Les points ne comptent que s''ils sont conclus après au moins une défense réussie. Un point gagné directement au service ou au bloc ne rapporte rien. Jouez deux sets courts en 15 points selon cette règle.', array['Les points ne comptent que s''ils sont conclus après au moins une défense réussie.', 'Un point gagné directement au service ou au bloc ne rapporte rien.', 'Jouez deux sets courts en 15 points selon cette règle.'], array['La règle valorise la durée des échanges : joue pour prolonger le point.', 'Renvoie haut plutôt que de conclure à tout prix.', 'Félicite les défenses réussies, elles deviennent la monnaie du jeu.'], 'Chercher l''ace ou le contre alors qu''ils ne rapportent rien. Abandonner les ballons difficiles en cours d''échange.', array['Chercher l''ace ou le contre alors qu''ils ne rapportent rien.', 'Abandonner les ballons difficiles en cours d''échange.'], 'La règle valorise la durée des échanges : joue pour prolonger le point. Renvoie haut plutôt que de conclure à tout prix. Félicite les défenses réussies, elles deviennent la monnaie du jeu.', array['Exigez deux défenses réussies pour valider un point.'], array['Comptez également les points conclus sans défense, mais pour un demi-point.'], false, true, 4, 4, array['defense', 'match', 'competition']),
  ('passe_001', 'Touche haute au mur', 'Renvois répétés à deux mains contre un mur pour stabiliser la forme des mains et le contact.', 'passe', array['touche haute', 'position des mains', 'contrôle'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant'], 'precision', 'Stabiliser la forme des mains et le point de contact en autonomie.', 8, 1, 1, array['ballons', 'mur'], 'low', 2, 'Place-toi à deux mètres d''un mur, mains au-dessus du front en forme de fenêtre. Enchaîne des touches hautes contre le mur, à hauteur constante. 4 séries de 20 touches, en repartant à zéro si le ballon tombe.', array['Place-toi à deux mètres d''un mur, mains au-dessus du front en forme de fenêtre.', 'Enchaîne des touches hautes contre le mur, à hauteur constante.', '4 séries de 20 touches, en repartant à zéro si le ballon tombe.'], array['Le ballon touche les doigts, jamais les paumes.', 'Les coudes restent écartés vers l''extérieur, à hauteur d''épaules.', 'La poussée vient des jambes et se termine par l''extension des poignets.'], 'Refermer les mains et accompagner le ballon, ce qui produit une balle portée. Toucher le ballon devant le visage au lieu d''au-dessus du front.', array['Refermer les mains et accompagner le ballon, ce qui produit une balle portée.', 'Toucher le ballon devant le visage au lieu d''au-dessus du front.'], 'Le ballon touche les doigts, jamais les paumes. Les coudes restent écartés vers l''extérieur, à hauteur d''épaules. La poussée vient des jambes et se termine par l''extension des poignets.', array['Recule à trois mètres pour augmenter la poussée nécessaire.'], array['Laisse le ballon rebondir une fois au sol entre chaque touche.'], true, true, 2, 2, array['passe', 'solo', 'maison', 'fondamentaux']),
  ('passe_002', 'Auto-passes verticales', 'Enchaînement de touches hautes à la verticale au-dessus de soi, en restant dans un cercle réduit.', 'passe', array['touche haute', 'dosage', 'placement'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant'], 'precision', 'Contrôler la verticalité et le placement sous le ballon.', 6, 1, 1, array['ballons'], 'low', 2, 'Envoie le ballon à la verticale, à trois mètres au-dessus de toi. Reste dans un cercle d''un mètre pendant toute la série. 4 séries de 15 touches consécutives.', array['Envoie le ballon à la verticale, à trois mètres au-dessus de toi.', 'Reste dans un cercle d''un mètre pendant toute la série.', '4 séries de 15 touches consécutives.'], array['Replace-toi sous le ballon entre chaque touche plutôt que de tendre les bras.', 'Le front doit se trouver à l''aplomb du ballon au moment du contact.', 'Garde la même hauteur d''envoi du début à la fin.'], 'Dériver progressivement hors du cercle. Frapper le ballon vers l''avant au lieu de le pousser à la verticale.', array['Dériver progressivement hors du cercle.', 'Frapper le ballon vers l''avant au lieu de le pousser à la verticale.'], 'Replace-toi sous le ballon entre chaque touche plutôt que de tendre les bras. Le front doit se trouver à l''aplomb du ballon au moment du contact. Garde la même hauteur d''envoi du début à la fin.', array['Réduis le cercle à cinquante centimètres.'], array['Autorise un déplacement libre sans contrainte de cercle.'], true, true, 1, 3, array['passe', 'solo', 'maison', 'placement']),
  ('passe_003', 'Position des mains en fenêtre', 'Travail statique de la forme des mains et du point de contact, ballon tenu puis relâché.', 'passe', array['position des mains', 'technique', 'point de contact'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant'], 'precision', 'Corriger la forme des mains avant de travailler la passe complète.', 5, 1, 6, array['ballons'], 'low', 2, 'Tiens le ballon au-dessus du front, doigts écartés en forme de fenêtre autour de lui. Relâche le ballon, laisse-le tomber de dix centimètres et repousse-le d''une poussée sèche. 3 séries de 12 répétitions.', array['Tiens le ballon au-dessus du front, doigts écartés en forme de fenêtre autour de lui.', 'Relâche le ballon, laisse-le tomber de dix centimètres et repousse-le d''une poussée sèche.', '3 séries de 12 répétitions.'], array['Les pouces pointent vers les yeux, jamais vers l''avant.', 'Seules les deux premières phalanges touchent le ballon.', 'Le contact est bref : pousser, pas accompagner.'], 'Pouces orientés vers l''avant, ce qui expose les articulations. Contact avec les paumes des mains.', array['Pouces orientés vers l''avant, ce qui expose les articulations.', 'Contact avec les paumes des mains.'], 'Les pouces pointent vers les yeux, jamais vers l''avant. Seules les deux premières phalanges touchent le ballon. Le contact est bref : pousser, pas accompagner.', array['Augmente la hauteur de chute du ballon à cinquante centimètres.'], array['Reste sur le ballon tenu, sans le relâcher, pour sentir la position.'], true, true, 1, 2, array['passe', 'technique', 'correction', 'debutant']),
  ('passe_004', 'Passes croisées en binôme', 'Échanges en touche haute entre deux joueurs, avec obligation de renvoyer un ballon confortable.', 'passe', array['touche haute', 'régularité', 'dosage'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire'], 'precision', 'Construire un échange régulier en touche haute.', 8, 2, 2, array['ballons'], 'low', 2, 'Placez-vous face à face à cinq mètres d''écart. Échangez uniquement en touche haute, en visant le front du partenaire. Objectif : 30 échanges consécutifs, trois tentatives.', array['Placez-vous face à face à cinq mètres d''écart.', 'Échangez uniquement en touche haute, en visant le front du partenaire.', 'Objectif : 30 échanges consécutifs, trois tentatives.'], array['Vise le front de ton partenaire, pas ses mains.', 'Envoie haut : une trajectoire tendue est difficile à reprendre proprement.', 'Replace-toi sous le ballon avant chaque touche.'], 'Envoyer des ballons tendus qui obligent le partenaire à reculer. Toucher le ballon en étant encore en mouvement.', array['Envoyer des ballons tendus qui obligent le partenaire à reculer.', 'Toucher le ballon en étant encore en mouvement.'], 'Vise le front de ton partenaire, pas ses mains. Envoie haut : une trajectoire tendue est difficile à reprendre proprement. Replace-toi sous le ballon avant chaque touche.', array['Augmentez la distance à huit mètres.'], array['Rapprochez-vous à trois mètres.'], false, true, 2, 2, array['passe', 'binôme', 'fondamentaux']),
  ('passe_005', 'Passe haute vers l''aile gauche', 'Distribution classique vers la zone 4, avec une cible matérialisée le long de l''antenne.', 'passe', array['distribution', 'précision', 'hauteur'], array['setter'], 'debutant', array['debutant', 'intermediaire'], 'precision', 'Distribuer précisément vers l''aile gauche.', 10, 2, 4, array['ballons', 'filet', 'plots'], 'medium', 3, 'Une cible de deux mètres est posée en zone 4, à un mètre de l''antenne. Un partenaire envoie une réception haute, le passeur distribue vers la cible. 4 séries de 12 passes, en comptant les réussites.', array['Une cible de deux mètres est posée en zone 4, à un mètre de l''antenne.', 'Un partenaire envoie une réception haute, le passeur distribue vers la cible.', '4 séries de 12 passes, en comptant les réussites.'], array['Le ballon doit redescendre à un mètre du filet, pas dessus.', 'Vise une hauteur de trois mètres au-dessus du filet pour laisser le temps à l''attaquant.', 'Oriente tes épaules vers la cible avant le contact.'], 'Passer trop près du filet et empêcher l''attaquant de frapper. Passer trop court, à l''intérieur du terrain.', array['Passer trop près du filet et empêcher l''attaquant de frapper.', 'Passer trop court, à l''intérieur du terrain.'], 'Le ballon doit redescendre à un mètre du filet, pas dessus. Vise une hauteur de trois mètres au-dessus du filet pour laisser le temps à l''attaquant. Oriente tes épaules vers la cible avant le contact.', array['Réduis la cible à un mètre.'], array['Élargis la cible à trois mètres et reçois des ballons lancés à la main.'], false, true, 2, 3, array['passe', 'distribution', 'zone 4']),
  ('passe_006', 'Passe au pointu en zone 2', 'Distribution vers l''aile droite, qui demande une orientation différente du corps du passeur.', 'passe', array['distribution', 'orientation', 'précision'], array['setter'], 'intermediaire', array['intermediaire'], 'precision', 'Distribuer vers l''aile droite avec la même qualité qu''à gauche.', 10, 2, 4, array['ballons', 'filet', 'plots'], 'medium', 3, 'Une cible est posée en zone 2, à un mètre de l''antenne droite. Le passeur reçoit une réception haute et distribue vers cette cible sans se retourner complètement. 4 séries de 12 passes.', array['Une cible est posée en zone 2, à un mètre de l''antenne droite.', 'Le passeur reçoit une réception haute et distribue vers cette cible sans se retourner complètement.', '4 séries de 12 passes.'], array['Pivote sur tes appuis avant le contact, ne tourne pas seulement les bras.', 'Garde la même hauteur que sur une passe à gauche, pour ne pas trahir ta distribution.', 'Termine ton geste en direction de la cible.'], 'Passer en arrière au lieu de pivoter, ce qui décale la trajectoire. Réduire la hauteur par rapport à une passe vers la zone 4.', array['Passer en arrière au lieu de pivoter, ce qui décale la trajectoire.', 'Réduire la hauteur par rapport à une passe vers la zone 4.'], 'Pivote sur tes appuis avant le contact, ne tourne pas seulement les bras. Garde la même hauteur que sur une passe à gauche, pour ne pas trahir ta distribution. Termine ton geste en direction de la cible.', array['Alterne zone 4 et zone 2 sans ordre prévisible.'], array['Le passeur part déjà orienté vers la zone 2.'], false, true, 2, 3, array['passe', 'distribution', 'zone 2']),
  ('passe_007', 'Passe arrière sans rotation d''épaules', 'Envoi du ballon vers l''arrière en gardant les épaules face au filet, pour ne pas annoncer l''intention.', 'passe', array['passe arrière', 'dissimulation', 'poignets'], array['setter'], 'intermediaire', array['intermediaire', 'avance'], 'precision', 'Distribuer vers l''arrière sans trahir son intention.', 10, 2, 4, array['ballons', 'filet', 'plots'], 'medium', 4, 'Le passeur se place dos à la zone 2, épaules face au filet. Il envoie le ballon vers l''arrière, vers une cible placée derrière lui, sans tourner le buste. 4 séries de 12 passes arrière.', array['Le passeur se place dos à la zone 2, épaules face au filet.', 'Il envoie le ballon vers l''arrière, vers une cible placée derrière lui, sans tourner le buste.', '4 séries de 12 passes arrière.'], array['L''extension part du bassin et des poignets, pas d''une rotation d''épaules.', 'Le ballon est touché légèrement plus en arrière du front que sur une passe avant.', 'Regarde droit devant toi pendant tout le geste.'], 'Se cambrer excessivement et perdre l''équilibre. Tourner les épaules, ce qui annonce la passe au bloc adverse.', array['Se cambrer excessivement et perdre l''équilibre.', 'Tourner les épaules, ce qui annonce la passe au bloc adverse.'], 'L''extension part du bassin et des poignets, pas d''une rotation d''épaules. Le ballon est touché légèrement plus en arrière du front que sur une passe avant. Regarde droit devant toi pendant tout le geste.', array['Alterne passe avant et passe arrière sans prévenir l''attaquant.'], array['Autorise une légère rotation des épaules le temps d''installer le geste.'], false, true, 3, 4, array['passe', 'arriere', 'dissimulation']),
  ('passe_008', 'Passe en suspension', 'Passe réalisée en sautant, pour accélérer le jeu et réduire le temps de lecture du bloc adverse.', 'passe', array['passe en suspension', 'timing', 'gainage'], array['setter'], 'avance', array['avance'], 'precision', 'Accélérer le jeu grâce à la passe en suspension.', 10, 2, 4, array['ballons', 'filet'], 'high', 5, 'Le passeur saute légèrement et touche le ballon au sommet de son saut. La passe part vers une cible en zone 4, sans perte de précision par rapport à une passe au sol. 4 séries de 10 passes en suspension.', array['Le passeur saute légèrement et touche le ballon au sommet de son saut.', 'La passe part vers une cible en zone 4, sans perte de précision par rapport à une passe au sol.', '4 séries de 10 passes en suspension.'], array['Le saut sert la vitesse de jeu, pas la hauteur : reste discret.', 'Gaine le tronc au moment du contact pour garder la précision en l''air.', 'Touche le ballon au sommet du saut, jamais en redescendant.'], 'Sauter trop haut et perdre le contrôle de la trajectoire. Toucher le ballon pendant la phase descendante du saut.', array['Sauter trop haut et perdre le contrôle de la trajectoire.', 'Toucher le ballon pendant la phase descendante du saut.'], 'Le saut sert la vitesse de jeu, pas la hauteur : reste discret. Gaine le tronc au moment du contact pour garder la précision en l''air. Touche le ballon au sommet du saut, jamais en redescendant.', array['Ajoute un bloqueur adverse qui lit la passe.'], array['Saute à peine, sur la pointe des pieds, sans décollage complet.'], false, true, 4, 5, array['passe', 'suspension', 'avance']),
  ('passe_009', 'Passe après pas chassés', 'Passe précédée d''un déplacement latéral court, pour arriver stable sous le ballon.', 'passe', array['déplacement', 'stabilité', 'passe'], array['setter', 'opposite'], 'intermediaire', array['intermediaire'], 'precision', 'Arriver équilibré sous le ballon après un déplacement.', 10, 2, 4, array['ballons', 'filet', 'plots'], 'medium', 3, 'Le passeur démarre à deux mètres de sa position de passe. Il rejoint sa position en pas chassés puis distribue vers la zone 4. 4 séries de 10 passes, en alternant le côté de départ.', array['Le passeur démarre à deux mètres de sa position de passe.', 'Il rejoint sa position en pas chassés puis distribue vers la zone 4.', '4 séries de 10 passes, en alternant le côté de départ.'], array['Termine ton déplacement avant le contact, jamais pendant.', 'Le dernier appui te place de face au ballon, pas de côté.', 'Garde les mains déjà prêtes au-dessus du front pendant le déplacement.'], 'Passer en plein déplacement et dévier la trajectoire. Arriver les bras le long du corps et devoir les remonter en urgence.', array['Passer en plein déplacement et dévier la trajectoire.', 'Arriver les bras le long du corps et devoir les remonter en urgence.'], 'Termine ton déplacement avant le contact, jamais pendant. Le dernier appui te place de face au ballon, pas de côté. Garde les mains déjà prêtes au-dessus du front pendant le déplacement.', array['Augmente la distance de déplacement à quatre mètres.'], array['Réduis la distance à un mètre.'], false, true, 3, 3, array['passe', 'deplacement', 'appuis']),
  ('passe_010', 'Repli du passeur depuis la zone 1', 'Course de replacement depuis la position arrière droite jusqu''au poste de passe, suivie de la distribution.', 'passe', array['replacement', 'course', 'passe'], array['setter'], 'intermediaire', array['intermediaire', 'avance'], 'precision', 'Rejoindre son poste de passe et distribuer sans temps mort.', 12, 3, 6, array['ballons', 'filet'], 'high', 4, 'Le passeur part de la zone 1, en position défensive. Au signal, il court jusqu''à sa position de passe et distribue la réception qui arrive. 4 séries de 8 replis, avec une minute de récupération.', array['Le passeur part de la zone 1, en position défensive.', 'Au signal, il court jusqu''à sa position de passe et distribue la réception qui arrive.', '4 séries de 8 replis, avec une minute de récupération.'], array['Cours en regardant le ballon, jamais le sol.', 'Arrive de face au filet, épaules déjà orientées vers la zone 4.', 'Le dernier appui doit être un appui d''arrêt franc.'], 'Arriver de profil et devoir se réorienter avant de passer. Regarder ses appuis pendant la course et perdre le ballon de vue.', array['Arriver de profil et devoir se réorienter avant de passer.', 'Regarder ses appuis pendant la course et perdre le ballon de vue.'], 'Cours en regardant le ballon, jamais le sol. Arrive de face au filet, épaules déjà orientées vers la zone 4. Le dernier appui doit être un appui d''arrêt franc.', array['Le repli démarre depuis la zone 5, donc plus loin.'], array['Le passeur part déjà à mi-chemin de sa position.'], false, true, 4, 3, array['passe', 'replacement', 'passeur']),
  ('passe_011', 'Longue distribution d''un bord à l''autre', 'Passe traversant tout le filet, de la zone 2 vers la zone 4, exigeant une poussée complète.', 'passe', array['puissance de passe', 'trajectoire longue', 'précision'], array['setter'], 'intermediaire', array['intermediaire', 'avance'], 'precision', 'Envoyer une passe longue précise d''un côté à l''autre du filet.', 10, 2, 4, array['ballons', 'filet', 'plots'], 'medium', 4, 'Le passeur se place en zone 2 et distribue vers une cible en zone 4. La passe doit rester à un mètre du filet sur toute sa longueur. 4 séries de 10 passes longues.', array['Le passeur se place en zone 2 et distribue vers une cible en zone 4.', 'La passe doit rester à un mètre du filet sur toute sa longueur.', '4 séries de 10 passes longues.'], array['La distance vient des jambes, pas d''un mouvement de bras plus ample.', 'Vise un peu plus haut pour compenser la longueur de la trajectoire.', 'Garde la même forme de mains malgré la puissance nécessaire.'], 'Frapper le ballon pour gagner en distance, ce qui produit une faute. Laisser la trajectoire dériver vers l''intérieur du terrain.', array['Frapper le ballon pour gagner en distance, ce qui produit une faute.', 'Laisser la trajectoire dériver vers l''intérieur du terrain.'], 'La distance vient des jambes, pas d''un mouvement de bras plus ample. Vise un peu plus haut pour compenser la longueur de la trajectoire. Garde la même forme de mains malgré la puissance nécessaire.', array['Impose une hauteur maximale pour obliger une trajectoire tendue et précise.'], array['Rapproche la cible à la zone 3.'], false, true, 3, 4, array['passe', 'distance', 'distribution']),
  ('passe_012', 'Passe rapide au central', 'Passe courte et tendue destinée à l''attaque rapide du central, avec un timing très serré.', 'passe', array['passe rapide', 'timing', 'coordination'], array['setter'], 'avance', array['avance'], 'precision', 'Synchroniser une passe rapide avec l''appel du central.', 12, 3, 6, array['ballons', 'filet'], 'high', 4, 'Le central démarre son appel avant que le passeur ne touche le ballon. Le passeur envoie une passe courte et tendue, juste au-dessus du filet. 4 séries de 8 rapides, en analysant le timing après chaque série.', array['Le central démarre son appel avant que le passeur ne touche le ballon.', 'Le passeur envoie une passe courte et tendue, juste au-dessus du filet.', '4 séries de 8 rapides, en analysant le timing après chaque série.'], array['La passe part là où le central sera, pas là où il se trouve.', 'Un contact sec et court : la rapide ne supporte pas d''accompagnement.', 'Le ballon doit atteindre son point haut au moment où le central est au sommet du saut.'], 'Passer trop haut, ce qui annule l''intérêt de la rapide. Attendre que le central saute avant de décider de la passe.', array['Passer trop haut, ce qui annule l''intérêt de la rapide.', 'Attendre que le central saute avant de décider de la passe.'], 'La passe part là où le central sera, pas là où il se trouve. Un contact sec et court : la rapide ne supporte pas d''accompagnement. Le ballon doit atteindre son point haut au moment où le central est au sommet du saut.', array['Ajoute un bloqueur central adverse.'], array['Augmente légèrement la hauteur de la passe pour faciliter le timing.'], false, true, 3, 5, array['passe', 'rapide', 'central', 'avance']),
  ('passe_013', 'Variation de tension de passe', 'Alternance volontaire entre passes hautes, mi-hautes et tendues vers la même zone.', 'passe', array['dosage', 'adaptation', 'distribution'], array['setter'], 'avance', array['avance'], 'precision', 'Maîtriser plusieurs tensions de passe vers une même zone.', 10, 3, 6, array['ballons', 'filet'], 'medium', 4, 'Le passeur alterne trois hauteurs de passe vers la zone 4 : haute, moyenne et tendue. L''attaquant adapte son appel à la hauteur reçue. 4 séries de 9 passes, trois de chaque type.', array['Le passeur alterne trois hauteurs de passe vers la zone 4 : haute, moyenne et tendue.', 'L''attaquant adapte son appel à la hauteur reçue.', '4 séries de 9 passes, trois de chaque type.'], array['La hauteur se règle par la poussée des jambes, la forme du geste ne change pas.', 'Une passe tendue demande une précision supérieure : ne la tente pas sur ballon difficile.', 'Annonce la hauteur pendant l''apprentissage, puis supprime l''annonce.'], 'Modifier le geste des bras au lieu de la poussée des jambes. Perdre la précision dès que la passe se tend.', array['Modifier le geste des bras au lieu de la poussée des jambes.', 'Perdre la précision dès que la passe se tend.'], 'La hauteur se règle par la poussée des jambes, la forme du geste ne change pas. Une passe tendue demande une précision supérieure : ne la tente pas sur ballon difficile. Annonce la hauteur pendant l''apprentissage, puis supprime l''annonce.', array['Le passeur choisit la tension selon la qualité de la réception.'], array['Travaille une seule hauteur par série.'], false, true, 3, 4, array['passe', 'dosage', 'variation']),
  ('passe_014', 'Ballon décollé du filet', 'Distribution à partir d''une réception qui laisse le ballon loin du filet, au centre du terrain.', 'passe', array['adaptation', 'distribution', 'puissance de passe'], array['setter'], 'intermediaire', array['intermediaire', 'avance'], 'precision', 'Construire correctement depuis un ballon éloigné du filet.', 10, 3, 6, array['ballons', 'filet'], 'medium', 4, 'Le partenaire envoie volontairement des réceptions à quatre mètres du filet. Le passeur distribue malgré tout vers la zone 4, avec une trajectoire adaptée. 4 séries de 10 passes.', array['Le partenaire envoie volontairement des réceptions à quatre mètres du filet.', 'Le passeur distribue malgré tout vers la zone 4, avec une trajectoire adaptée.', '4 séries de 10 passes.'], array['Sur ballon décollé, privilégie une passe haute qui laisse à l''attaquant le temps de s''ajuster.', 'Oriente-toi franchement face au filet avant de pousser.', 'Annonce à l''attaquant que le ballon sera décollé.'], 'Vouloir une passe rapide sur un ballon éloigné du filet. Passer trop près du filet et créer une faute de filet pour l''attaquant.', array['Vouloir une passe rapide sur un ballon éloigné du filet.', 'Passer trop près du filet et créer une faute de filet pour l''attaquant.'], 'Sur ballon décollé, privilégie une passe haute qui laisse à l''attaquant le temps de s''ajuster. Oriente-toi franchement face au filet avant de pousser. Annonce à l''attaquant que le ballon sera décollé.', array['Le partenaire varie la distance au filet sans prévenir.'], array['Réduis la distance au filet à deux mètres.'], false, true, 3, 4, array['passe', 'adaptation', 'construction']),
  ('passe_015', 'Ballon collé au filet', 'Traitement des réceptions qui arrivent contre le filet, où l''espace pour passer est minimal.', 'passe', array['adaptation', 'contrôle fin', 'sécurité'], array['setter'], 'avance', array['avance'], 'precision', 'Sauver et rendre jouable un ballon collé au filet.', 10, 3, 6, array['ballons', 'filet'], 'medium', 4, 'Le partenaire envoie des ballons qui frôlent le filet. Le passeur les récupère sans toucher le filet et les redirige vers une zone jouable. 4 séries de 8 ballons.', array['Le partenaire envoie des ballons qui frôlent le filet.', 'Le passeur les récupère sans toucher le filet et les redirige vers une zone jouable.', '4 séries de 8 ballons.'], array['Recule d''un pas dès que tu lis un ballon collé, plutôt que de rester dessous.', 'Sur ballon très collé, une manchette latérale vaut mieux qu''une touche haute risquée.', 'Garde les bras près du corps pour éviter la faute de filet.'], 'Tendre les bras vers le filet et le toucher. Insister sur la touche haute quand l''espace est insuffisant.', array['Tendre les bras vers le filet et le toucher.', 'Insister sur la touche haute quand l''espace est insuffisant.'], 'Recule d''un pas dès que tu lis un ballon collé, plutôt que de rester dessous. Sur ballon très collé, une manchette latérale vaut mieux qu''une touche haute risquée. Garde les bras près du corps pour éviter la faute de filet.', array['Ajoute un bloc adverse qui exploite le ballon collé.'], array['Éloigne légèrement le ballon du filet.'], false, true, 3, 5, array['passe', 'filet', 'sauvetage', 'avance']),
  ('passe_016', 'Deuxième touche en manchette', 'Construction de la deuxième touche en manchette quand le ballon est trop bas pour une touche haute.', 'passe', array['manchette de passe', 'adaptation', 'orientation'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire'], 'precision', 'Construire proprement en manchette sur un ballon bas.', 10, 3, 6, array['ballons', 'filet'], 'medium', 3, 'Le partenaire envoie des ballons bas, sous la hauteur de la poitrine du passeur. Le passeur construit en manchette vers la zone 4, en cherchant la hauteur. 4 séries de 10 ballons.', array['Le partenaire envoie des ballons bas, sous la hauteur de la poitrine du passeur.', 'Le passeur construit en manchette vers la zone 4, en cherchant la hauteur.', '4 séries de 10 ballons.'], array['Oriente les épaules vers la cible avant le contact, la plateforme suit.', 'Cherche de la hauteur : une manchette de passe tendue est inattaquable.', 'Ne tente jamais une touche haute sur un ballon sous la poitrine.'], 'Forcer la touche haute et commettre une faute de balle portée. Envoyer une manchette tendue qui traverse le filet.', array['Forcer la touche haute et commettre une faute de balle portée.', 'Envoyer une manchette tendue qui traverse le filet.'], 'Oriente les épaules vers la cible avant le contact, la plateforme suit. Cherche de la hauteur : une manchette de passe tendue est inattaquable. Ne tente jamais une touche haute sur un ballon sous la poitrine.', array['Le partenaire alterne ballons hauts et bas sans prévenir.'], array['Le partenaire envoie des ballons bas mais toujours au même endroit.'], false, true, 3, 3, array['passe', 'manchette', 'adaptation']),
  ('passe_017', 'Passe de sécurité très haute', 'Renvoi très haut au centre du filet, solution de repli quand la construction normale est impossible.', 'passe', array['sécurité', 'hauteur', 'décision'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire'], 'precision', 'Choisir et réussir la passe de repli sur ballon difficile.', 8, 3, 6, array['ballons', 'filet'], 'low', 3, 'Le partenaire envoie des ballons difficiles, décalés ou bas. Le passeur choisit systématiquement la passe haute de sécurité au centre. 3 séries de 10 ballons.', array['Le partenaire envoie des ballons difficiles, décalés ou bas.', 'Le passeur choisit systématiquement la passe haute de sécurité au centre.', '3 séries de 10 ballons.'], array['Une passe très haute donne à l''attaquant le temps de s''ajuster, même mal placée.', 'Vise le centre du filet, à deux mètres de distance de celui-ci.', 'Annonce la passe de sécurité à voix haute pour prévenir les attaquants.'], 'Tenter une construction rapide sur un ballon impossible. Passer haut mais trop près du filet.', array['Tenter une construction rapide sur un ballon impossible.', 'Passer haut mais trop près du filet.'], 'Une passe très haute donne à l''attaquant le temps de s''ajuster, même mal placée. Vise le centre du filet, à deux mètres de distance de celui-ci. Annonce la passe de sécurité à voix haute pour prévenir les attaquants.', array['Le passeur décide seul entre construction normale et passe de sécurité.'], array['Le partenaire envoie des ballons difficiles mais prévisibles.'], false, true, 2, 3, array['passe', 'securite', 'decision']),
  ('passe_018', 'Vingt passes dans la cible', 'Série de précision où vingt passes consécutives doivent atteindre la même zone réduite.', 'passe', array['régularité', 'précision', 'concentration'], array['setter'], 'intermediaire', array['intermediaire', 'avance'], 'regularite', 'Produire une longue série de passes précises sans rupture.', 12, 2, 4, array['ballons', 'filet', 'plots'], 'medium', 3, 'Une cible d''un mètre cinquante est posée en zone 4. Le passeur enchaîne les passes, le compteur revient à zéro à chaque échec. L''exercice s''arrête à vingt réussites consécutives ou après 50 ballons.', array['Une cible d''un mètre cinquante est posée en zone 4.', 'Le passeur enchaîne les passes, le compteur revient à zéro à chaque échec.', 'L''exercice s''arrête à vingt réussites consécutives ou après 50 ballons.'], array['Garde une routine identique avant chaque ballon.', 'Après un échec, reviens à un geste simple plutôt que de corriger à l''excès.', 'La régularité vient du replacement, pas de la force des mains.'], 'Accélérer le rythme quand le compteur monte. Modifier sa technique après deux ballons manqués.', array['Accélérer le rythme quand le compteur monte.', 'Modifier sa technique après deux ballons manqués.'], 'Garde une routine identique avant chaque ballon. Après un échec, reviens à un geste simple plutôt que de corriger à l''excès. La régularité vient du replacement, pas de la force des mains.', array['Réduis la cible à un mètre.'], array['Abaisse l''objectif à dix passes consécutives.'], false, true, 2, 4, array['passe', 'regularite', 'objectif']),
  ('passe_019', 'Deux cibles annoncées', 'Distribution vers l''une ou l''autre aile, la cible étant annoncée juste avant la réception.', 'passe', array['adaptation', 'distribution', 'réactivité'], array['setter'], 'intermediaire', array['intermediaire'], 'precision', 'Distribuer vers deux zones sur information tardive.', 10, 3, 6, array['ballons', 'filet', 'plots'], 'medium', 4, 'Des cibles sont posées en zone 4 et en zone 2. Un observateur annonce la cible au moment où le ballon part vers le passeur. 4 séries de 10 passes, en ordre aléatoire.', array['Des cibles sont posées en zone 4 et en zone 2.', 'Un observateur annonce la cible au moment où le ballon part vers le passeur.', '4 séries de 10 passes, en ordre aléatoire.'], array['Adopte une position de départ neutre, qui permet les deux passes.', 'Réoriente-toi pendant le déplacement, pas au moment du contact.', 'Conserve la même hauteur quelle que soit la cible annoncée.'], 'Se préorienter vers une cible avant l''annonce. Perdre en hauteur sur la cible la moins habituelle.', array['Se préorienter vers une cible avant l''annonce.', 'Perdre en hauteur sur la cible la moins habituelle.'], 'Adopte une position de départ neutre, qui permet les deux passes. Réoriente-toi pendant le déplacement, pas au moment du contact. Conserve la même hauteur quelle que soit la cible annoncée.', array['L''annonce arrive quand le ballon est déjà à mi-hauteur.'], array['L''annonce est donnée avant l''envoi du ballon.'], false, true, 3, 4, array['passe', 'reactivite', 'distribution']),
  ('passe_020', 'Distribution sur appel d''attaquant', 'Le passeur choisit sa distribution en fonction des appels réellement effectués par ses attaquants.', 'passe', array['lecture', 'décision', 'distribution'], array['setter'], 'avance', array['avance'], 'precision', 'Décider de sa distribution à partir des appels reçus.', 12, 4, 8, array['ballons', 'filet'], 'high', 4, 'Trois attaquants appellent librement le ballon à chaque ballon reçu. Le passeur choisit vers qui distribuer selon la qualité des appels et de la réception. 4 séries de 10 ballons, avec analyse des choix entre les séries.', array['Trois attaquants appellent librement le ballon à chaque ballon reçu.', 'Le passeur choisit vers qui distribuer selon la qualité des appels et de la réception.', '4 séries de 10 ballons, avec analyse des choix entre les séries.'], array['Sur réception parfaite, privilégie l''attaquant le mieux placé face au bloc.', 'Sur réception moyenne, choisis l''attaquant le plus fiable, pas le plus rapide.', 'Un attaquant qui n''appelle pas n''est pas disponible.'], 'Distribuer toujours vers le même attaquant par habitude. Choisir une attaque rapide sur une réception décalée.', array['Distribuer toujours vers le même attaquant par habitude.', 'Choisir une attaque rapide sur une réception décalée.'], 'Sur réception parfaite, privilégie l''attaquant le mieux placé face au bloc. Sur réception moyenne, choisis l''attaquant le plus fiable, pas le plus rapide. Un attaquant qui n''appelle pas n''est pas disponible.', array['Ajoute un bloc adverse pour intégrer sa position au choix.'], array['Un seul attaquant appelle à chaque ballon.'], false, true, 3, 5, array['passe', 'decision', 'collectif', 'avance']),
  ('passe_021', 'Passe masquée', 'Travail de dissimulation de l''intention pour retarder la lecture du bloc adverse.', 'passe', array['dissimulation', 'technique', 'distribution'], array['setter'], 'avance', array['avance'], 'precision', 'Rendre sa distribution illisible pour le bloc adverse.', 10, 3, 6, array['ballons', 'filet'], 'medium', 4, 'Un observateur tente de deviner la destination de chaque passe au moment du contact. Le passeur cherche à rendre ses passes avant et arrière indiscernables. 4 séries de 10 passes, en comptant les lectures réussies de l''observateur.', array['Un observateur tente de deviner la destination de chaque passe au moment du contact.', 'Le passeur cherche à rendre ses passes avant et arrière indiscernables.', '4 séries de 10 passes, en comptant les lectures réussies de l''observateur.'], array['Adopte exactement la même position de corps quelle que soit la destination.', 'Le regard doit rester neutre : ne fixe jamais ta cible.', 'Seuls les poignets changent, tout le reste du geste est identique.'], 'Se cambrer visiblement avant une passe arrière. Regarder la zone visée juste avant le contact.', array['Se cambrer visiblement avant une passe arrière.', 'Regarder la zone visée juste avant le contact.'], 'Adopte exactement la même position de corps quelle que soit la destination. Le regard doit rester neutre : ne fixe jamais ta cible. Seuls les poignets changent, tout le reste du geste est identique.', array['L''observateur devient un vrai bloqueur qui se déplace.'], array['Travaille uniquement l''uniformité de la position de départ.'], false, true, 2, 5, array['passe', 'dissimulation', 'avance']),
  ('passe_022', 'Construction après réception décalée', 'Distribution à partir de réceptions volontairement imprécises, loin de la position idéale.', 'passe', array['adaptation', 'déplacement', 'construction'], array['setter'], 'intermediaire', array['intermediaire', 'avance'], 'precision', 'Construire correctement malgré une réception imparfaite.', 12, 3, 6, array['ballons', 'filet'], 'high', 4, 'Le partenaire envoie des réceptions décalées de deux à trois mètres de la position du passeur. Le passeur se déplace et construit la meilleure passe possible. 4 séries de 10 ballons.', array['Le partenaire envoie des réceptions décalées de deux à trois mètres de la position du passeur.', 'Le passeur se déplace et construit la meilleure passe possible.', '4 séries de 10 ballons.'], array['Pars dès que tu lis la trajectoire, pas quand le ballon arrive.', 'Adapte ton ambition à la qualité du ballon reçu.', 'Communique immédiatement aux attaquants que le ballon est décalé.'], 'Tenter la même distribution que sur une réception parfaite. Partir trop tard et passer en déséquilibre.', array['Tenter la même distribution que sur une réception parfaite.', 'Partir trop tard et passer en déséquilibre.'], 'Pars dès que tu lis la trajectoire, pas quand le ballon arrive. Adapte ton ambition à la qualité du ballon reçu. Communique immédiatement aux attaquants que le ballon est décalé.', array['Augmente le décalage à quatre mètres.'], array['Réduis le décalage à un mètre.'], false, true, 4, 4, array['passe', 'adaptation', 'construction']),
  ('passe_023', 'Relation passeur et ailier', 'Répétition du couple passeur-attaquant de zone 4 jusqu''à obtenir un timing automatique.', 'passe', array['coordination', 'timing', 'distribution'], array['setter', 'outside_hitter'], 'intermediaire', array['intermediaire', 'avance'], 'precision', 'Installer un timing fiable entre passeur et ailier.', 14, 3, 6, array['ballons', 'filet'], 'high', 4, 'Le même couple passeur-attaquant enchaîne 30 attaques sur passe haute en zone 4. Après chaque série, les deux joueurs ajustent ensemble hauteur et distance de la passe. 3 séries de 10 attaques.', array['Le même couple passeur-attaquant enchaîne 30 attaques sur passe haute en zone 4.', 'Après chaque série, les deux joueurs ajustent ensemble hauteur et distance de la passe.', '3 séries de 10 attaques.'], array['La passe idéale est celle que l''attaquant frappe sans ralentir son élan.', 'Discutez concrètement : plus haut, plus court, plus loin du filet.', 'Cherchez la répétabilité avant la variété.'], 'Ne jamais échanger sur ce qui convient à l''attaquant. Changer de hauteur à chaque ballon et empêcher tout repère.', array['Ne jamais échanger sur ce qui convient à l''attaquant.', 'Changer de hauteur à chaque ballon et empêcher tout repère.'], 'La passe idéale est celle que l''attaquant frappe sans ralentir son élan. Discutez concrètement : plus haut, plus court, plus loin du filet. Cherchez la répétabilité avant la variété.', array['Ajoutez un bloc adverse une fois le timing installé.'], array['Réduisez à quinze attaques par série.'], false, true, 4, 4, array['passe', 'coordination', 'attaque']),
  ('passe_024', 'Synchronisation avec le central', 'Travail du couple passeur-central sur des attaques rapides, où le timing est le seul facteur décisif.', 'passe', array['timing', 'coordination', 'passe rapide'], array['setter', 'middle_blocker'], 'avance', array['avance'], 'precision', 'Fixer un point de rendez-vous fiable sur l''attaque rapide.', 14, 3, 6, array['ballons', 'filet'], 'high', 5, 'Le central appelle systématiquement la rapide, le passeur la sert dès que la réception le permet. Les deux joueurs conviennent d''un point de rendez-vous précis au-dessus du filet. 4 séries de 8 rapides.', array['Le central appelle systématiquement la rapide, le passeur la sert dès que la réception le permet.', 'Les deux joueurs conviennent d''un point de rendez-vous précis au-dessus du filet.', '4 séries de 8 rapides.'], array['Le point de rendez-vous ne change pas : c''est le repère commun des deux joueurs.', 'Le central part avant la passe, le passeur sert le point convenu.', 'En cas de réception moyenne, annoncez l''annulation de la rapide.'], 'Déplacer le point de rendez-vous d''un ballon à l''autre. Servir la rapide sur une réception qui ne le permet pas.', array['Déplacer le point de rendez-vous d''un ballon à l''autre.', 'Servir la rapide sur une réception qui ne le permet pas.'], 'Le point de rendez-vous ne change pas : c''est le repère commun des deux joueurs. Le central part avant la passe, le passeur sert le point convenu. En cas de réception moyenne, annoncez l''annulation de la rapide.', array['Ajoutez un bloqueur central adverse qui lit la rapide.'], array['Ralentissez la passe pour installer le repère.'], false, true, 4, 5, array['passe', 'central', 'rapide', 'avance']),
  ('passe_025', 'Triangle de passes à trois', 'Circulation continue du ballon entre trois joueurs disposés en triangle, avec replacement obligatoire.', 'passe', array['régularité', 'déplacement', 'touche haute'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire'], 'regularite', 'Faire circuler le ballon proprement à trois joueurs.', 10, 3, 3, array['ballons'], 'medium', 3, 'Trois joueurs forment un triangle de cinq mètres de côté. Le ballon circule toujours dans le même sens, chacun se replace après sa touche. 4 séries de 30 passes sans faute, puis inversez le sens.', array['Trois joueurs forment un triangle de cinq mètres de côté.', 'Le ballon circule toujours dans le même sens, chacun se replace après sa touche.', '4 séries de 30 passes sans faute, puis inversez le sens.'], array['Oriente-toi vers ton receveur avant le contact.', 'Envoie haut pour laisser le temps au suivant de se placer.', 'Replace-toi au centre de ta position après chaque touche.'], 'Passer sans être orienté vers le receveur. Rester figé sur place après sa propre touche.', array['Passer sans être orienté vers le receveur.', 'Rester figé sur place après sa propre touche.'], 'Oriente-toi vers ton receveur avant le contact. Envoie haut pour laisser le temps au suivant de se placer. Replace-toi au centre de ta position après chaque touche.', array['Agrandissez le triangle à huit mètres de côté.'], array['Réduisez le triangle à trois mètres.'], false, true, 3, 3, array['passe', 'petit groupe', 'circulation']),
  ('passe_026', 'Navette de passes en mouvement', 'Passes enchaînées avec déplacement systématique vers la position suivante après chaque touche.', 'passe', array['déplacement', 'endurance', 'touche haute'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire'], 'regularite', 'Maintenir la qualité de passe dans un enchaînement continu.', 10, 4, 8, array['ballons', 'plots'], 'high', 4, 'Deux colonnes de joueurs se font face à six mètres d''écart. Chaque joueur passe le ballon puis court se placer au bout de la colonne opposée. 4 séries de trois minutes, avec une minute de récupération.', array['Deux colonnes de joueurs se font face à six mètres d''écart.', 'Chaque joueur passe le ballon puis court se placer au bout de la colonne opposée.', '4 séries de trois minutes, avec une minute de récupération.'], array['Passe d''abord, cours ensuite : ne pars jamais avant d''avoir touché.', 'Arrive stabilisé dans la colonne d''en face avant ton tour suivant.', 'Garde la même qualité de passe malgré l''essoufflement.'], 'Partir en courant pendant la touche et bâcler la passe. Ralentir la circulation en attendant à l''arrivée.', array['Partir en courant pendant la touche et bâcler la passe.', 'Ralentir la circulation en attendant à l''arrivée.'], 'Passe d''abord, cours ensuite : ne pars jamais avant d''avoir touché. Arrive stabilisé dans la colonne d''en face avant ton tour suivant. Garde la même qualité de passe malgré l''essoufflement.', array['Augmente la distance entre les colonnes à huit mètres.'], array['Réduis la durée des séries à deux minutes.'], false, true, 4, 3, array['passe', 'circulation', 'endurance']),
  ('passe_027', 'Passe en fin d''effort', 'Distribution exigée immédiatement après une séquence physique intense.', 'passe', array['lucidité', 'endurance', 'précision'], array['setter'], 'avance', array['avance'], 'regularite', 'Conserver une distribution précise malgré la fatigue.', 12, 2, 4, array['ballons', 'filet', 'plots'], 'high', 5, 'Effectue trente secondes de déplacements intenses entre deux plots. Enchaîne immédiatement dix passes vers une cible en zone 4. 4 séries, avec deux minutes de récupération entre chacune.', array['Effectue trente secondes de déplacements intenses entre deux plots.', 'Enchaîne immédiatement dix passes vers une cible en zone 4.', '4 séries, avec deux minutes de récupération entre chacune.'], array['La fatigue raccourcit les passes : pousse davantage avec les jambes.', 'Reprends une respiration complète entre deux ballons.', 'Simplifie ta distribution plutôt que de perdre en précision.'], 'Compenser la fatigue des jambes par un mouvement de bras. Maintenir des choix ambitieux alors que la précision baisse.', array['Compenser la fatigue des jambes par un mouvement de bras.', 'Maintenir des choix ambitieux alors que la précision baisse.'], 'La fatigue raccourcit les passes : pousse davantage avec les jambes. Reprends une respiration complète entre deux ballons. Simplifie ta distribution plutôt que de perdre en précision.', array['Allonge l''effort préalable à quarante-cinq secondes.'], array['Réduis l''effort préalable à quinze secondes.'], false, true, 5, 4, array['passe', 'fatigue', 'physique']),
  ('passe_028', 'Rythme imposé au chronomètre', 'Passes enchaînées à cadence fixe imposée par un chronomètre, sans temps mort.', 'passe', array['rythme', 'régularité', 'concentration'], array['setter'], 'intermediaire', array['intermediaire', 'avance'], 'regularite', 'Tenir une cadence de distribution soutenue et régulière.', 8, 2, 4, array['ballons', 'filet', 'chronometre'], 'high', 4, 'Le partenaire envoie un ballon toutes les quatre secondes, sans exception. Le passeur distribue vers la cible sans jamais sauter un ballon. 4 séries de 12 passes.', array['Le partenaire envoie un ballon toutes les quatre secondes, sans exception.', 'Le passeur distribue vers la cible sans jamais sauter un ballon.', '4 séries de 12 passes.'], array['Replace-toi immédiatement, le rythme ne laisse pas de temps mort.', 'Une routine plus courte mais identique vaut mieux qu''une routine bâclée.', 'Anticipe la trajectoire suivante pendant que le ballon est encore en l''air.'], 'Regarder le résultat de sa passe au lieu de se replacer. Se précipiter et sauter l''étape du placement.', array['Regarder le résultat de sa passe au lieu de se replacer.', 'Se précipiter et sauter l''étape du placement.'], 'Replace-toi immédiatement, le rythme ne laisse pas de temps mort. Une routine plus courte mais identique vaut mieux qu''une routine bâclée. Anticipe la trajectoire suivante pendant que le ballon est encore en l''air.', array['Réduis l''intervalle à trois secondes.'], array['Allonge l''intervalle à six secondes.'], false, true, 4, 4, array['passe', 'rythme', 'regularite']),
  ('passe_029', 'Précision notée du passeur', 'Évaluation chiffrée de chaque passe selon sa distance au point idéal pour l''attaquant.', 'passe', array['évaluation', 'précision', 'analyse'], array['setter'], 'intermediaire', array['intermediaire', 'avance'], 'precision', 'Mesurer objectivement la qualité de sa distribution.', 12, 3, 6, array['ballons', 'filet'], 'medium', 3, 'L''attaquant note chaque passe de 0 à 3 selon sa capacité à l''attaquer sans ajustement. Le passeur effectue 20 passes et calcule sa moyenne. 2 séries, avec l''objectif d''améliorer la moyenne à la seconde.', array['L''attaquant note chaque passe de 0 à 3 selon sa capacité à l''attaquer sans ajustement.', 'Le passeur effectue 20 passes et calcule sa moyenne.', '2 séries, avec l''objectif d''améliorer la moyenne à la seconde.'], array['C''est l''attaquant qui juge, pas le passeur : accepte son retour.', 'Analyse les passes notées 1 pour identifier l''erreur récurrente.', 'Une passe à 3 se frappe sans adaptation d''élan.'], 'Contester la note au lieu d''en tirer une correction. Se concentrer uniquement sur la hauteur en oubliant la distance au filet.', array['Contester la note au lieu d''en tirer une correction.', 'Se concentrer uniquement sur la hauteur en oubliant la distance au filet.'], 'C''est l''attaquant qui juge, pas le passeur : accepte son retour. Analyse les passes notées 1 pour identifier l''erreur récurrente. Une passe à 3 se frappe sans adaptation d''élan.', array['Ajoute un bloc adverse, qui durcit les critères de l''attaquant.'], array['Note simplement les passes comme attaquables ou non.'], false, true, 2, 4, array['passe', 'evaluation', 'statistiques']),
  ('passe_030', 'Deuxième passeur de secours', 'Construction par un joueur non passeur lorsque le passeur titulaire a touché la première balle.', 'passe', array['polyvalence', 'construction', 'décision'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire', 'avance'], 'precision', 'Assurer la construction quand le passeur est indisponible.', 12, 4, 8, array['ballons', 'filet'], 'medium', 4, 'Le passeur titulaire est contraint de défendre le premier ballon. Un autre joueur, désigné à l''avance, construit la deuxième touche. 4 séries de 8 ballons, en changeant de passeur de secours.', array['Le passeur titulaire est contraint de défendre le premier ballon.', 'Un autre joueur, désigné à l''avance, construit la deuxième touche.', '4 séries de 8 ballons, en changeant de passeur de secours.'], array['Le passeur de secours annonce dès qu''il voit le titulaire engagé.', 'Choisis la solution la plus simple : une passe haute au centre suffit.', 'Les attaquants adaptent leur appel à un passeur non spécialiste.'], 'Laisser le ballon tomber parce que personne ne prend le relais. Tenter une construction complexe en tant que passeur de secours.', array['Laisser le ballon tomber parce que personne ne prend le relais.', 'Tenter une construction complexe en tant que passeur de secours.'], 'Le passeur de secours annonce dès qu''il voit le titulaire engagé. Choisis la solution la plus simple : une passe haute au centre suffit. Les attaquants adaptent leur appel à un passeur non spécialiste.', array['Le passeur de secours n''est plus désigné à l''avance.'], array['Le passeur de secours est toujours le même joueur.'], false, true, 3, 4, array['passe', 'polyvalence', 'collectif']),
  ('passe_031', 'Distribution en situation de match', 'Passe intégrée à des points réels, avec toutes les contraintes du jeu.', 'passe', array['situation de jeu', 'décision', 'distribution'], array['setter'], 'avance', array['avance'], 'competition', 'Distribuer avec discernement dans un match réel.', 15, 8, 12, array['ballons', 'filet'], 'high', 5, 'Jouez des points complets, le passeur reçoit une consigne de variété minimale. Chaque attaquant doit être servi au moins trois fois par set. Jouez deux sets courts en 15 points.', array['Jouez des points complets, le passeur reçoit une consigne de variété minimale.', 'Chaque attaquant doit être servi au moins trois fois par set.', 'Jouez deux sets courts en 15 points.'], array['Alterne tes attaquants pour ne pas devenir prévisible.', 'Sur les points serrés, sers ton attaquant le plus fiable.', 'Rends compte après chaque set de ta répartition réelle.'], 'Servir toujours le même attaquant dans les moments importants. Chercher la variété au détriment de l''efficacité sur les points décisifs.', array['Servir toujours le même attaquant dans les moments importants.', 'Chercher la variété au détriment de l''efficacité sur les points décisifs.'], 'Alterne tes attaquants pour ne pas devenir prévisible. Sur les points serrés, sers ton attaquant le plus fiable. Rends compte après chaque set de ta répartition réelle.', array['Impose une répartition strictement équilibrée.'], array['Supprime la contrainte de variété.'], false, true, 4, 5, array['passe', 'match', 'competition']),
  ('passe_032', 'Choix contre le bloc adverse', 'Sélection de la distribution en fonction du positionnement réel du bloc en face.', 'passe', array['lecture du bloc', 'décision', 'distribution'], array['setter'], 'avance', array['avance'], 'precision', 'Choisir sa distribution en exploitant la position du bloc.', 12, 6, 10, array['ballons', 'filet'], 'high', 4, 'Un bloc adverse se décale volontairement d''un côté avant chaque ballon. Le passeur distribue vers l''attaquant laissé libre par ce décalage. 4 séries de 10 ballons, en comptant les choix pertinents.', array['Un bloc adverse se décale volontairement d''un côté avant chaque ballon.', 'Le passeur distribue vers l''attaquant laissé libre par ce décalage.', '4 séries de 10 ballons, en comptant les choix pertinents.'], array['Prends l''information sur le bloc pendant la réception, pas après.', 'Un central adverse déjà engagé d''un côté libère l''autre attaquant.', 'Si le bloc est bien placé partout, choisis ton attaquant le plus fort.'], 'Décider de sa passe avant de regarder le bloc. Chercher systématiquement à contourner le bloc, même quand c''est inutile.', array['Décider de sa passe avant de regarder le bloc.', 'Chercher systématiquement à contourner le bloc, même quand c''est inutile.'], 'Prends l''information sur le bloc pendant la réception, pas après. Un central adverse déjà engagé d''un côté libère l''autre attaquant. Si le bloc est bien placé partout, choisis ton attaquant le plus fort.', array['Le bloc adverse ajoute des feintes de déplacement.'], array['Le bloc annonce son décalage à voix haute.'], false, true, 3, 5, array['passe', 'lecture', 'bloc', 'avance']),
  ('passe_033', 'Passe sur relance défensive imprécise', 'Construction à partir de ballons issus d''une défense, donc hauts, décalés et irréguliers.', 'passe', array['adaptation', 'construction', 'déplacement'], array['setter'], 'intermediaire', array['intermediaire', 'avance'], 'precision', 'Construire depuis un ballon de défense imprévisible.', 12, 4, 8, array['ballons', 'filet'], 'high', 4, 'Un défenseur relance de vrais ballons défendus, sans consigne de précision. Le passeur court, s''ajuste et construit la meilleure attaque possible. 4 séries de 8 ballons.', array['Un défenseur relance de vrais ballons défendus, sans consigne de précision.', 'Le passeur court, s''ajuste et construit la meilleure attaque possible.', '4 séries de 8 ballons.'], array['Sur ballon de défense, la première décision est de savoir si tu peux le prendre.', 'Si le ballon est injouable pour toi, annonce-le fort et immédiatement.', 'Privilégie systématiquement une passe haute sur ce type de relance.'], 'Partir sur tous les ballons, y compris ceux hors d''atteinte. Tenter une distribution rapide sur un ballon de défense.', array['Partir sur tous les ballons, y compris ceux hors d''atteinte.', 'Tenter une distribution rapide sur un ballon de défense.'], 'Sur ballon de défense, la première décision est de savoir si tu peux le prendre. Si le ballon est injouable pour toi, annonce-le fort et immédiatement. Privilégie systématiquement une passe haute sur ce type de relance.', array['Les défenseurs enchaînent deux ballons de suite.'], array['Le défenseur relance en visant approximativement le passeur.'], false, true, 4, 4, array['passe', 'transition', 'adaptation']),
  ('passe_034', 'Extension arrière au-dessus de la tête', 'Renforcement du geste de passe arrière par des répétitions ciblées de l''extension complète.', 'passe', array['passe arrière', 'extension', 'gainage'], array['setter'], 'intermediaire', array['intermediaire', 'avance'], 'precision', 'Renforcer l''amplitude et la sûreté de la passe arrière.', 8, 2, 4, array['ballons'], 'medium', 4, 'Un partenaire lance le ballon à la verticale au-dessus du passeur. Le passeur l''envoie vers l''arrière par une extension complète du bassin et des bras. 4 séries de 12 répétitions.', array['Un partenaire lance le ballon à la verticale au-dessus du passeur.', 'Le passeur l''envoie vers l''arrière par une extension complète du bassin et des bras.', '4 séries de 12 répétitions.'], array['L''extension part des jambes et remonte jusqu''aux poignets, dans cet ordre.', 'Le tronc reste gainé : ne creuse pas le bas du dos.', 'Termine les bras complètement tendus derrière la tête.'], 'Cambrer le bas du dos au lieu d''étendre tout le corps. Arrêter le geste avant l''extension complète des bras.', array['Cambrer le bas du dos au lieu d''étendre tout le corps.', 'Arrêter le geste avant l''extension complète des bras.'], 'L''extension part des jambes et remonte jusqu''aux poignets, dans cet ordre. Le tronc reste gainé : ne creuse pas le bas du dos. Termine les bras complètement tendus derrière la tête.', array['Le partenaire varie la hauteur du lancer.'], array['Réduis la distance visée derrière le passeur.'], false, true, 3, 4, array['passe', 'arriere', 'technique']),
  ('passe_035', 'Défi d''équilibre de distribution', 'Objectif chiffré de répartition entre les trois attaquants sur une série longue.', 'passe', array['distribution', 'variété', 'décision'], array['setter'], 'avance', array['avance'], 'regularite', 'Répartir sa distribution de façon équilibrée sur la durée.', 12, 5, 8, array['ballons', 'filet'], 'medium', 4, 'Sur 30 ballons, chaque attaquant doit recevoir entre huit et douze passes. Un observateur comptabilise la répartition en direct. 2 séries, avec analyse de l''écart à l''objectif après chacune.', array['Sur 30 ballons, chaque attaquant doit recevoir entre huit et douze passes.', 'Un observateur comptabilise la répartition en direct.', '2 séries, avec analyse de l''écart à l''objectif après chacune.'], array['Garde une vision d''ensemble : compte mentalement tes distributions.', 'L''équilibre se construit tout au long de la série, pas à la fin.', 'Une distribution variée rend la défense adverse illisible.'], 'Servir massivement le meilleur attaquant puis corriger en fin de série. Oublier complètement un attaquant pendant dix ballons.', array['Servir massivement le meilleur attaquant puis corriger en fin de série.', 'Oublier complètement un attaquant pendant dix ballons.'], 'Garde une vision d''ensemble : compte mentalement tes distributions. L''équilibre se construit tout au long de la série, pas à la fin. Une distribution variée rend la défense adverse illisible.', array['Resserre la fourchette entre neuf et onze passes par attaquant.'], array['Élargis la fourchette entre six et quatorze passes.'], false, true, 3, 5, array['passe', 'variete', 'defi', 'avance']),
  ('attaque_001', 'Frappe au mur', 'Frappes répétées contre un mur pour construire le fouetté du bras et le contact main-ballon.', 'attaque', array['frappe', 'fouetté du bras', 'contact'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant'], 'attaque', 'Construire un contact de frappe propre sans partenaire.', 8, 1, 1, array['ballons', 'mur'], 'medium', 2, 'Place-toi à trois mètres d''un mur, ballon en main. Frappe le ballon au sol pour qu''il rebondisse contre le mur, puis reprends-le après son retour. 4 séries de 15 frappes.', array['Place-toi à trois mètres d''un mur, ballon en main.', 'Frappe le ballon au sol pour qu''il rebondisse contre le mur, puis reprends-le après son retour.', '4 séries de 15 frappes.'], array['Frappe avec la paume ouverte, doigts souples qui enveloppent le ballon.', 'Le poignet casse vers le bas juste après le contact.', 'Le coude passe haut, au-dessus de l''épaule, jamais sur le côté.'], 'Frapper poing fermé. Garder le poignet rigide et perdre tout effet sur le ballon.', array['Frapper poing fermé.', 'Garder le poignet rigide et perdre tout effet sur le ballon.'], 'Frappe avec la paume ouverte, doigts souples qui enveloppent le ballon. Le poignet casse vers le bas juste après le contact. Le coude passe haut, au-dessus de l''épaule, jamais sur le côté.', array['Recule à cinq mètres pour frapper plus fort.'], array['Réduis la puissance et concentre-toi uniquement sur le contact.'], true, true, 2, 2, array['attaque', 'solo', 'maison', 'fondamentaux']),
  ('attaque_002', 'Armé du bras à vide', 'Répétition à vide du mouvement d''armé pour placer correctement le coude et l''épaule.', 'attaque', array['armé', 'technique', 'épaule'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant'], 'attaque', 'Installer un armé sûr pour l''épaule et efficace.', 5, 1, 8, '{}', 'low', 2, 'Debout, monte les deux bras simultanément, puis arme le bras frappeur coude haut derrière la tête. Déroule le mouvement lentement jusqu''à la fin du fouetté, sans ballon. 3 séries de 12 répétitions.', array['Debout, monte les deux bras simultanément, puis arme le bras frappeur coude haut derrière la tête.', 'Déroule le mouvement lentement jusqu''à la fin du fouetté, sans ballon.', '3 séries de 12 répétitions.'], array['Les deux bras montent ensemble : le bras libre sert à viser et à équilibrer.', 'Le coude reste plus haut que l''épaule pendant tout l''armé.', 'Le buste se gaine et se déroule d''un bloc, pas seulement le bras.'], 'Armer coude bas, ce qui expose l''épaule et réduit la puissance. Laisser le bras libre le long du corps.', array['Armer coude bas, ce qui expose l''épaule et réduit la puissance.', 'Laisser le bras libre le long du corps.'], 'Les deux bras montent ensemble : le bras libre sert à viser et à équilibrer. Le coude reste plus haut que l''épaule pendant tout l''armé. Le buste se gaine et se déroule d''un bloc, pas seulement le bras.', array['Ajoute un élastique léger pour résister au mouvement.'], array['Fais le geste face à un miroir, très lentement.'], true, false, 1, 2, array['attaque', 'sans ballon', 'technique', 'maison']),
  ('attaque_003', 'Élan trois appuis à vide', 'Apprentissage du rythme de course d''élan en trois appuis, sans ballon ni saut complet.', 'attaque', array['élan', 'appuis', 'rythme'], array['outside_hitter', 'opposite', 'middle_blocker'], 'debutant', array['debutant'], 'attaque', 'Acquérir le rythme d''accélération de l''élan d''attaque.', 8, 1, 8, '{}', 'medium', 3, 'Pars à quatre mètres du filet et effectue l''élan : un pas d''approche, puis les deux appuis d''impulsion. Termine par une impulsion basse, sans chercher la hauteur. 4 séries de 8 élans.', array['Pars à quatre mètres du filet et effectue l''élan : un pas d''approche, puis les deux appuis d''impulsion.', 'Termine par une impulsion basse, sans chercher la hauteur.', '4 séries de 8 élans.'], array['Le rythme s''accélère : le dernier appui est le plus rapide.', 'Les deux derniers appuis se posent talon d''abord, pour freiner et convertir la vitesse.', 'Les bras partent loin derrière avant de remonter.'], 'Un élan à rythme constant, sans accélération finale. Poser les derniers appuis sur la pointe des pieds.', array['Un élan à rythme constant, sans accélération finale.', 'Poser les derniers appuis sur la pointe des pieds.'], 'Le rythme s''accélère : le dernier appui est le plus rapide. Les deux derniers appuis se posent talon d''abord, pour freiner et convertir la vitesse. Les bras partent loin derrière avant de remonter.', array['Ajoute le saut complet une fois le rythme acquis.'], array['Marche l''élan au ralenti, appui par appui.'], true, false, 3, 3, array['attaque', 'elan', 'sans ballon', 'debutant']),
  ('attaque_004', 'Élan complet avec saut', 'Élan trois appuis terminé par un saut maximal et un armé complet, sans frappe de ballon.', 'attaque', array['élan', 'impulsion', 'coordination'], array['outside_hitter', 'opposite', 'middle_blocker'], 'debutant', array['debutant', 'intermediaire'], 'attaque', 'Coordonner élan, impulsion et armé dans un geste complet.', 10, 1, 8, array['filet'], 'high', 4, 'Effectue l''élan complet et saute le plus haut possible au filet. Arme le bras au sommet du saut et simule la frappe, sans ballon. 4 séries de 6 sauts, avec une minute de récupération.', array['Effectue l''élan complet et saute le plus haut possible au filet.', 'Arme le bras au sommet du saut et simule la frappe, sans ballon.', '4 séries de 6 sauts, avec une minute de récupération.'], array['Les bras se lancent vers le haut au moment de l''impulsion.', 'Saute vers le haut, pas vers l''avant : tu ne dois pas toucher le filet.', 'Retombe sur les deux pieds, genoux fléchis pour amortir.'], 'Sauter en avant et finir dans le filet. Retomber sur un seul pied, ce qui fragilise la cheville.', array['Sauter en avant et finir dans le filet.', 'Retomber sur un seul pied, ce qui fragilise la cheville.'], 'Les bras se lancent vers le haut au moment de l''impulsion. Saute vers le haut, pas vers l''avant : tu ne dois pas toucher le filet. Retombe sur les deux pieds, genoux fléchis pour amortir.', array['Ajoute un ballon tenu en hauteur à toucher au sommet du saut.'], array['Réduis l''intensité du saut à soixante-dix pour cent.'], true, false, 4, 3, array['attaque', 'elan', 'saut']),
  ('attaque_005', 'Frappe sur ballon lancé au sol', 'Première frappe complète, pieds au sol, sur un ballon lancé haut par un partenaire.', 'attaque', array['frappe', 'timing', 'contact'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant'], 'attaque', 'Réussir une frappe complète avec un point de contact haut.', 8, 2, 4, array['ballons', 'filet'], 'medium', 3, 'Un partenaire lance le ballon à deux mètres au-dessus de ta tête. Frappe le ballon par-dessus le filet, pieds au sol, sans saut. 4 séries de 10 frappes.', array['Un partenaire lance le ballon à deux mètres au-dessus de ta tête.', 'Frappe le ballon par-dessus le filet, pieds au sol, sans saut.', '4 séries de 10 frappes.'], array['Frappe le ballon au point le plus haut que tu peux atteindre.', 'Le contact se fait devant l''épaule, pas au-dessus de la tête.', 'Casse le poignet après le contact pour faire descendre le ballon.'], 'Laisser le ballon descendre à hauteur de tête avant de frapper. Frapper le ballon derrière soi et l''envoyer en cloche.', array['Laisser le ballon descendre à hauteur de tête avant de frapper.', 'Frapper le ballon derrière soi et l''envoyer en cloche.'], 'Frappe le ballon au point le plus haut que tu peux atteindre. Le contact se fait devant l''épaule, pas au-dessus de la tête. Casse le poignet après le contact pour faire descendre le ballon.', array['Ajoute un saut sur place avant la frappe.'], array['Frappe depuis la zone d''attaque, plus près du filet.'], false, true, 2, 3, array['attaque', 'debutant', 'frappe']),
  ('attaque_006', 'Frappe en suspension sur lancer', 'Attaque complète avec saut, sur un ballon lancé à la main dans une trajectoire régulière.', 'attaque', array['frappe', 'suspension', 'timing'], array['outside_hitter', 'opposite', 'middle_blocker'], 'debutant', array['debutant', 'intermediaire'], 'attaque', 'Synchroniser l''élan, le saut et la frappe sur un ballon simple.', 10, 2, 6, array['ballons', 'filet'], 'high', 4, 'Un partenaire lance un ballon haut et régulier à un mètre du filet. L''attaquant effectue son élan complet et frappe au sommet du saut. 4 séries de 8 attaques.', array['Un partenaire lance un ballon haut et régulier à un mètre du filet.', 'L''attaquant effectue son élan complet et frappe au sommet du saut.', '4 séries de 8 attaques.'], array['Déclenche ton élan quand le ballon atteint son point haut.', 'Frappe devant toi, au point culminant de ton saut.', 'Garde les yeux sur le ballon jusqu''au contact.'], 'Partir trop tôt et attendre le ballon en l''air. Frapper le ballon en redescendant du saut.', array['Partir trop tôt et attendre le ballon en l''air.', 'Frapper le ballon en redescendant du saut.'], 'Déclenche ton élan quand le ballon atteint son point haut. Frappe devant toi, au point culminant de ton saut. Garde les yeux sur le ballon jusqu''au contact.', array['Remplace le lancer par une vraie passe de passeur.'], array['Le partenaire lance depuis une position fixe et très régulière.'], false, true, 4, 3, array['attaque', 'suspension', 'timing']),
  ('attaque_007', 'Attaque sur passe haute d''aile', 'Attaque classique en zone 4 sur passe haute, la configuration offensive la plus fréquente.', 'attaque', array['attaque d''aile', 'timing', 'frappe'], array['outside_hitter', 'opposite'], 'intermediaire', array['intermediaire'], 'attaque', 'Maîtriser l''attaque de référence en zone 4.', 12, 3, 6, array['ballons', 'filet'], 'high', 4, 'Le passeur envoie une passe haute à un mètre de l''antenne, en zone 4. L''attaquant effectue son élan et frappe dans le terrain adverse. 4 séries de 8 attaques, avec récupération d''une minute.', array['Le passeur envoie une passe haute à un mètre de l''antenne, en zone 4.', 'L''attaquant effectue son élan et frappe dans le terrain adverse.', '4 séries de 8 attaques, avec récupération d''une minute.'], array['Déclenche ton élan quand la passe atteint son point haut.', 'Attaque le ballon en avançant, jamais en reculant.', 'Vise une zone précise plutôt que le terrain en général.'], 'Démarrer l''élan trop tôt et se retrouver sous le ballon. Attaquer depuis une position statique, sans élan.', array['Démarrer l''élan trop tôt et se retrouver sous le ballon.', 'Attaquer depuis une position statique, sans élan.'], 'Déclenche ton élan quand la passe atteint son point haut. Attaque le ballon en avançant, jamais en reculant. Vise une zone précise plutôt que le terrain en général.', array['Ajoute un bloqueur adverse.'], array['Le passeur envoie une passe plus haute pour allonger le temps de lecture.'], false, true, 4, 3, array['attaque', 'zone 4', 'passe haute']),
  ('attaque_008', 'Frappe longue de ligne', 'Attaque le long de la ligne latérale, qui demande un placement du corps très précis.', 'attaque', array['attaque de ligne', 'orientation', 'précision'], array['outside_hitter', 'opposite'], 'intermediaire', array['intermediaire', 'avance'], 'attaque', 'Frapper précisément le long de la ligne.', 10, 3, 6, array['ballons', 'filet', 'plots'], 'high', 4, 'Une cible de deux mètres est posée le long de la ligne adverse. L''attaquant frappe exclusivement dans cette zone, depuis la zone 4. 4 séries de 8 attaques, en comptant les réussites.', array['Une cible de deux mètres est posée le long de la ligne adverse.', 'L''attaquant frappe exclusivement dans cette zone, depuis la zone 4.', '4 séries de 8 attaques, en comptant les réussites.'], array['Place ton épaule non frappeuse dans l''axe de la ligne avant de frapper.', 'Frappe le ballon légèrement sur son côté extérieur.', 'Reste sous le ballon : une ligne se frappe à l''aplomb, pas en extension latérale.'], 'Ouvrir les épaules vers l''intérieur et finir en croisé. Frapper trop tard et envoyer le ballon hors des limites latérales.', array['Ouvrir les épaules vers l''intérieur et finir en croisé.', 'Frapper trop tard et envoyer le ballon hors des limites latérales.'], 'Place ton épaule non frappeuse dans l''axe de la ligne avant de frapper. Frappe le ballon légèrement sur son côté extérieur. Reste sous le ballon : une ligne se frappe à l''aplomb, pas en extension latérale.', array['Ajoute un bloqueur qui ferme partiellement la ligne.'], array['Élargis la cible à quatre mètres.'], false, true, 4, 4, array['attaque', 'ligne', 'precision']),
  ('attaque_009', 'Frappe croisée longue', 'Attaque en diagonale vers le fond du terrain adverse, la trajectoire la plus utilisée en match.', 'attaque', array['attaque croisée', 'orientation', 'puissance'], array['outside_hitter', 'opposite'], 'intermediaire', array['intermediaire'], 'attaque', 'Frapper une diagonale longue et profonde.', 10, 3, 6, array['ballons', 'filet', 'plots'], 'high', 4, 'Une cible est posée dans le coin opposé du terrain adverse. L''attaquant frappe en diagonale depuis la zone 4 vers cette cible. 4 séries de 8 attaques.', array['Une cible est posée dans le coin opposé du terrain adverse.', 'L''attaquant frappe en diagonale depuis la zone 4 vers cette cible.', '4 séries de 8 attaques.'], array['Ouvre les épaules vers l''intérieur du terrain pendant l''armé.', 'Frappe le côté intérieur du ballon pour l''orienter en diagonale.', 'Cherche la profondeur : une diagonale courte est facile à défendre.'], 'Frapper trop court et offrir un ballon facile à la défense. Tourner tout le corps et devenir prévisible pour le bloc.', array['Frapper trop court et offrir un ballon facile à la défense.', 'Tourner tout le corps et devenir prévisible pour le bloc.'], 'Ouvre les épaules vers l''intérieur du terrain pendant l''armé. Frappe le côté intérieur du ballon pour l''orienter en diagonale. Cherche la profondeur : une diagonale courte est facile à défendre.', array['Alterne croisé long et croisé court dans la même série.'], array['Élargis la cible à tout le demi-terrain diagonal.'], false, true, 4, 3, array['attaque', 'diagonale', 'precision']),
  ('attaque_010', 'Ballon placé dans l''espace libre', 'Attaque sans puissance dirigée vers la zone laissée vide par la défense adverse.', 'attaque', array['placement', 'lecture de défense', 'dosage'], array['outside_hitter', 'opposite', 'middle_blocker'], 'intermediaire', array['intermediaire', 'avance'], 'attaque', 'Exploiter les espaces laissés par la défense adverse.', 10, 4, 8, array['ballons', 'filet'], 'medium', 4, 'Trois défenseurs occupent le terrain adverse en laissant volontairement une zone libre. L''attaquant identifie la zone vide et y place son ballon sans puissance. 4 séries de 8 attaques, la zone libre changeant à chaque ballon.', array['Trois défenseurs occupent le terrain adverse en laissant volontairement une zone libre.', 'L''attaquant identifie la zone vide et y place son ballon sans puissance.', '4 séries de 8 attaques, la zone libre changeant à chaque ballon.'], array['Prends l''information sur la défense pendant ton élan, pas en l''air.', 'Un ballon placé se frappe quand même avec le bras armé, pas poussé.', 'Vise loin de tout défenseur plutôt que le fond du terrain par principe.'], 'Regarder uniquement le ballon et ignorer le placement adverse. Pousser le ballon au lieu de le frapper, ce qui le rend trop lent.', array['Regarder uniquement le ballon et ignorer le placement adverse.', 'Pousser le ballon au lieu de le frapper, ce qui le rend trop lent.'], 'Prends l''information sur la défense pendant ton élan, pas en l''air. Un ballon placé se frappe quand même avec le bras armé, pas poussé. Vise loin de tout défenseur plutôt que le fond du terrain par principe.', array['La défense se replace juste avant la frappe.'], array['La zone libre est annoncée avant chaque attaque.'], false, true, 3, 4, array['attaque', 'placement', 'lecture']),
  ('attaque_011', 'Ballon brossé par-dessus le bloc', 'Frappe enveloppée qui fait retomber le ballon juste derrière le bloc adverse.', 'attaque', array['roll shot', 'effet', 'dosage'], array['outside_hitter', 'opposite', 'middle_blocker'], 'intermediaire', array['intermediaire', 'avance'], 'attaque', 'Franchir le bloc avec un ballon brossé retombant court.', 10, 3, 6, array['ballons', 'filet'], 'medium', 4, 'Un bloc est en place au filet, la cible est la zone située à six mètres derrière lui. L''attaquant enveloppe le ballon pour le faire passer haut au-dessus du bloc et retomber court. 4 séries de 8 attaques brossées.', array['Un bloc est en place au filet, la cible est la zone située à six mètres derrière lui.', 'L''attaquant enveloppe le ballon pour le faire passer haut au-dessus du bloc et retomber court.', '4 séries de 8 attaques brossées.'], array['La main passe au-dessus et derrière le ballon pour l''enrouler.', 'Le bras reste armé et rapide : un roll shot n''est pas un geste mou.', 'Vise une hauteur suffisante pour passer largement le bloc.'], 'Pousser le ballon des deux mains au lieu de le brosser. Frapper trop bas et se faire contrer.', array['Pousser le ballon des deux mains au lieu de le brosser.', 'Frapper trop bas et se faire contrer.'], 'La main passe au-dessus et derrière le ballon pour l''enrouler. Le bras reste armé et rapide : un roll shot n''est pas un geste mou. Vise une hauteur suffisante pour passer largement le bloc.', array['Alterne roll shot et frappe puissante sans prévenir.'], array['Supprime le bloc et travaille uniquement l''effet.'], false, true, 3, 4, array['attaque', 'roll shot', 'effet']),
  ('attaque_012', 'Amorti du bout des doigts', 'Dépôt du ballon juste derrière le bloc avec les doigts, sans armé complet visible.', 'attaque', array['amorti', 'dissimulation', 'toucher'], array['outside_hitter', 'opposite', 'middle_blocker'], 'intermediaire', array['intermediaire'], 'attaque', 'Déposer un ballon court sans trahir son intention.', 8, 3, 6, array['ballons', 'filet'], 'medium', 4, 'Un bloc est en place, la cible est la zone des trois mètres adverse. L''attaquant arme normalement puis dépose le ballon du bout des doigts. 4 séries de 8 amortis.', array['Un bloc est en place, la cible est la zone des trois mètres adverse.', 'L''attaquant arme normalement puis dépose le ballon du bout des doigts.', '4 séries de 8 amortis.'], array['Arme exactement comme pour une frappe : c''est l''armé qui rend l''amorti efficace.', 'Le contact se fait avec les doigts fermes, pas la paume.', 'Dirige le ballon vers un espace, pas simplement par-dessus le bloc.'], 'Ralentir visiblement l''élan et annoncer l''amorti. Pousser le ballon avec la paume, ce qui est souvent sanctionné.', array['Ralentir visiblement l''élan et annoncer l''amorti.', 'Pousser le ballon avec la paume, ce qui est souvent sanctionné.'], 'Arme exactement comme pour une frappe : c''est l''armé qui rend l''amorti efficace. Le contact se fait avec les doigts fermes, pas la paume. Dirige le ballon vers un espace, pas simplement par-dessus le bloc.', array['La défense adverse anticipe l''amorti et se rapproche.'], array['Supprime le bloc et travaille uniquement le toucher.'], false, true, 3, 4, array['attaque', 'amorti', 'finesse']),
  ('attaque_013', 'Utiliser les mains du bloc', 'Frappe volontaire dans les mains extérieures du bloc pour envoyer le ballon hors des limites.', 'attaque', array['lecture du bloc', 'précision', 'frappe'], array['outside_hitter', 'opposite'], 'avance', array['avance'], 'attaque', 'Transformer un bloc bien placé en point grâce à la déviation.', 10, 4, 8, array['ballons', 'filet'], 'high', 5, 'Un bloqueur est en place à l''antenne, sans chercher à fermer complètement. L''attaquant vise la main extérieure du bloqueur pour dévier le ballon hors du terrain. 4 séries de 8 attaques.', array['Un bloqueur est en place à l''antenne, sans chercher à fermer complètement.', 'L''attaquant vise la main extérieure du bloqueur pour dévier le ballon hors du terrain.', '4 séries de 8 attaques.'], array['Vise le bord extérieur de la main la plus proche de l''antenne.', 'Frappe vers l''extérieur, en ouvrant l''angle au maximum.', 'Cette solution s''utilise quand le bloc est bien placé, pas par défaut.'], 'Viser le centre du bloc et se faire contrer. Utiliser cette solution systématiquement au lieu de varier.', array['Viser le centre du bloc et se faire contrer.', 'Utiliser cette solution systématiquement au lieu de varier.'], 'Vise le bord extérieur de la main la plus proche de l''antenne. Frappe vers l''extérieur, en ouvrant l''angle au maximum. Cette solution s''utilise quand le bloc est bien placé, pas par défaut.', array['Le bloqueur ferme mieux et rend la fenêtre plus étroite.'], array['Le bloqueur garde les mains volontairement écartées.'], false, true, 4, 5, array['attaque', 'bloc', 'avance']),
  ('attaque_014', 'Frappe par-dessus un bloc haut', 'Attaque puissante au-dessus des mains d''un bloc bien positionné, exigeant une détente maximale.', 'attaque', array['détente', 'point de frappe haut', 'puissance'], array['outside_hitter', 'opposite', 'middle_blocker'], 'avance', array['avance'], 'attaque', 'Passer au-dessus d''un bloc grâce à la hauteur de frappe.', 12, 4, 8, array['ballons', 'filet'], 'high', 5, 'Un double bloc se forme systématiquement face à l''attaquant. L''attaquant cherche à frapper au-dessus des mains, dans le terrain. 4 séries de 6 attaques, avec récupération complète entre les séries.', array['Un double bloc se forme systématiquement face à l''attaquant.', 'L''attaquant cherche à frapper au-dessus des mains, dans le terrain.', '4 séries de 6 attaques, avec récupération complète entre les séries.'], array['Frappe au point le plus haut possible : chaque centimètre compte.', 'Casse le poignet nettement pour faire descendre le ballon derrière le bloc.', 'Reste derrière le ballon plutôt que de te jeter vers le filet.'], 'Frapper à plat et envoyer le ballon au fond hors des limites. Sauter vers l''avant et perdre de la hauteur de frappe.', array['Frapper à plat et envoyer le ballon au fond hors des limites.', 'Sauter vers l''avant et perdre de la hauteur de frappe.'], 'Frappe au point le plus haut possible : chaque centimètre compte. Casse le poignet nettement pour faire descendre le ballon derrière le bloc. Reste derrière le ballon plutôt que de te jeter vers le filet.', array['Le bloc se rapproche et monte plus haut.'], array['Le bloc ne saute qu''à moitié.'], false, true, 5, 4, array['attaque', 'bloc', 'detente', 'avance']),
  ('attaque_015', 'Enchaînement réception vers attaque', 'Séquence offensive du réceptionneur-attaquant, évaluée sur la qualité de l''attaque finale.', 'attaque', array['enchaînement', 'replacement', 'attaque d''aile'], array['outside_hitter', 'opposite'], 'intermediaire', array['intermediaire', 'avance'], 'attaque', 'Conserver une attaque de qualité après avoir réceptionné.', 14, 4, 8, array['ballons', 'filet'], 'high', 5, 'Le joueur réceptionne un service, puis sort du terrain pour prendre son élan en zone 4. Il attaque la passe qui suit, seule la qualité de l''attaque étant notée. 4 séries de 6 enchaînements.', array['Le joueur réceptionne un service, puis sort du terrain pour prendre son élan en zone 4.', 'Il attaque la passe qui suit, seule la qualité de l''attaque étant notée.', '4 séries de 6 enchaînements.'], array['Sors largement du terrain après ta réception pour disposer d''un élan complet.', 'Un élan raccourci coûte plus de puissance qu''un demi-mètre de retard.', 'Repars dès que le ballon quitte tes bras.'], 'Attaquer depuis l''intérieur du terrain sans élan complet. Rester statique après la réception.', array['Attaquer depuis l''intérieur du terrain sans élan complet.', 'Rester statique après la réception.'], 'Sors largement du terrain après ta réception pour disposer d''un élan complet. Un élan raccourci coûte plus de puissance qu''un demi-mètre de retard. Repars dès que le ballon quitte tes bras.', array['Ajoute un bloc adverse sur l''attaque finale.'], array['Le service est remplacé par un lancer facile.'], false, true, 5, 4, array['attaque', 'enchainement', 'r4']),
  ('attaque_016', 'Attaque après course longue', 'Attaque précédée d''un déplacement important, comme en transition après une action défensive.', 'attaque', array['transition', 'élan', 'endurance'], array['outside_hitter', 'opposite', 'middle_blocker'], 'avance', array['avance'], 'attaque', 'Attaquer correctement après un long déplacement.', 12, 3, 6, array['ballons', 'filet', 'plots'], 'high', 4, 'L''attaquant démarre en fond de terrain, à la ligne de fond. Au signal, il remonte, sort du terrain et attaque en zone 4. 4 séries de 6 attaques, avec une minute de récupération.', array['L''attaquant démarre en fond de terrain, à la ligne de fond.', 'Au signal, il remonte, sort du terrain et attaque en zone 4.', '4 séries de 6 attaques, avec une minute de récupération.'], array['Ta course de repli fait partie de l''élan : enchaîne sans t''arrêter.', 'Conserve un dernier appui franc malgré la distance parcourue.', 'Regarde le passeur pendant ta remontée, pas le sol.'], 'S''arrêter avant de repartir en élan, ce qui coûte tout le temps disponible. Arriver essoufflé et raccourcir l''élan à un seul appui.', array['S''arrêter avant de repartir en élan, ce qui coûte tout le temps disponible.', 'Arriver essoufflé et raccourcir l''élan à un seul appui.'], 'Ta course de repli fait partie de l''élan : enchaîne sans t''arrêter. Conserve un dernier appui franc malgré la distance parcourue. Regarde le passeur pendant ta remontée, pas le sol.', array['Ajoute une défense à effectuer avant la remontée.'], array['Réduis la distance de départ à mi-terrain.'], false, true, 5, 3, array['attaque', 'transition', 'endurance']),
  ('attaque_017', 'Attaque sur passe tendue', 'Attaque sur une passe rapide et plate, qui réduit fortement le temps de lecture.', 'attaque', array['timing rapide', 'réactivité', 'frappe'], array['outside_hitter', 'opposite'], 'avance', array['avance'], 'attaque', 'Attaquer efficacement une passe rapide et plate.', 12, 3, 6, array['ballons', 'filet'], 'high', 5, 'Le passeur envoie des passes tendues, à peine au-dessus de la hauteur du filet. L''attaquant démarre son élan avant la passe et frappe sans temps d''ajustement. 4 séries de 8 attaques.', array['Le passeur envoie des passes tendues, à peine au-dessus de la hauteur du filet.', 'L''attaquant démarre son élan avant la passe et frappe sans temps d''ajustement.', '4 séries de 8 attaques.'], array['Ton élan démarre avant que le passeur ne touche le ballon.', 'Le bras est déjà armé quand tu quittes le sol.', 'Aucun ajustement n''est possible : c''est le placement initial qui compte.'], 'Attendre de voir la passe pour démarrer. Armer en l''air et arriver systématiquement en retard.', array['Attendre de voir la passe pour démarrer.', 'Armer en l''air et arriver systématiquement en retard.'], 'Ton élan démarre avant que le passeur ne touche le ballon. Le bras est déjà armé quand tu quittes le sol. Aucun ajustement n''est possible : c''est le placement initial qui compte.', array['Le passeur tend encore davantage la trajectoire.'], array['Le passeur relève légèrement la passe.'], false, true, 4, 5, array['attaque', 'tendue', 'timing', 'avance']),
  ('attaque_018', 'Attaque sur ballon très haut', 'Attaque sur une passe lente et très haute, où le principal risque est de partir trop tôt.', 'attaque', array['patience', 'timing', 'attaque d''aile'], array['outside_hitter', 'opposite'], 'debutant', array['debutant', 'intermediaire'], 'attaque', 'Caler son départ d''élan sur une passe lente et haute.', 10, 3, 6, array['ballons', 'filet'], 'medium', 3, 'Le passeur envoie des passes très hautes, à cinq mètres au-dessus du filet. L''attaquant attend le bon moment avant de déclencher son élan. 4 séries de 8 attaques.', array['Le passeur envoie des passes très hautes, à cinq mètres au-dessus du filet.', 'L''attaquant attend le bon moment avant de déclencher son élan.', '4 séries de 8 attaques.'], array['Déclenche l''élan quand le ballon amorce sa descente, pas avant.', 'Compte mentalement pour caler ton départ de façon reproductible.', 'Une passe haute laisse le temps : place-toi parfaitement.'], 'Partir dès la passe et attendre le ballon immobile sous le filet. Sauter deux fois faute d''avoir bien évalué la descente.', array['Partir dès la passe et attendre le ballon immobile sous le filet.', 'Sauter deux fois faute d''avoir bien évalué la descente.'], 'Déclenche l''élan quand le ballon amorce sa descente, pas avant. Compte mentalement pour caler ton départ de façon reproductible. Une passe haute laisse le temps : place-toi parfaitement.', array['Le passeur varie légèrement la hauteur d''une passe à l''autre.'], array['Le passeur annonce le moment du départ à voix haute.'], false, true, 3, 3, array['attaque', 'timing', 'debutant']),
  ('attaque_019', 'Attaque sur ballon éloigné du filet', 'Attaque depuis une passe décollée, où la puissance doit céder la place au contrôle.', 'attaque', array['adaptation', 'trajectoire', 'décision'], array['outside_hitter', 'opposite', 'middle_blocker'], 'intermediaire', array['intermediaire', 'avance'], 'attaque', 'Attaquer utilement depuis un ballon éloigné du filet.', 10, 3, 6, array['ballons', 'filet'], 'high', 4, 'Le passeur envoie volontairement des passes à trois mètres du filet. L''attaquant frappe en cherchant la profondeur plutôt que la puissance maximale. 4 séries de 8 attaques.', array['Le passeur envoie volontairement des passes à trois mètres du filet.', 'L''attaquant frappe en cherchant la profondeur plutôt que la puissance maximale.', '4 séries de 8 attaques.'], array['Depuis un ballon décollé, l''angle vers le bas n''existe pas : vise long.', 'Frappe le ballon légèrement en dessous de son centre pour l''envoyer loin.', 'Accepte de ne pas conclure : garde le ballon dans le terrain.'], 'Chercher la même trajectoire descendante que près du filet et faire faute au filet. Frapper à pleine puissance et envoyer le ballon au-delà de la ligne de fond.', array['Chercher la même trajectoire descendante que près du filet et faire faute au filet.', 'Frapper à pleine puissance et envoyer le ballon au-delà de la ligne de fond.'], 'Depuis un ballon décollé, l''angle vers le bas n''existe pas : vise long. Frappe le ballon légèrement en dessous de son centre pour l''envoyer loin. Accepte de ne pas conclure : garde le ballon dans le terrain.', array['Ajoute un double bloc qui couvre le fond du terrain.'], array['Réduis la distance au filet à deux mètres.'], false, true, 4, 4, array['attaque', 'adaptation', 'decision']),
  ('attaque_020', 'Attaque rapide du central', 'Attaque courte et immédiate au centre du filet, sur une passe tendue et basse.', 'attaque', array['attaque rapide', 'timing', 'explosivité'], array['middle_blocker'], 'avance', array['avance'], 'attaque', 'Exécuter une attaque rapide synchronisée avec le passeur.', 12, 3, 6, array['ballons', 'filet'], 'high', 5, 'Le central démarre son élan avant que le passeur ne touche le ballon. Il frappe la passe rapide au sommet de son saut, juste au-dessus du filet. 4 séries de 8 rapides.', array['Le central démarre son élan avant que le passeur ne touche le ballon.', 'Il frappe la passe rapide au sommet de son saut, juste au-dessus du filet.', '4 séries de 8 rapides.'], array['Ton saut est déclenché à l''aveugle, sur la lecture de la réception.', 'Le bras doit être armé avant même de quitter le sol.', 'Frappe court et devant : la rapide se joue dans un espace réduit.'], 'Attendre de voir la passe partir avant de sauter. Armer trop tard et frapper le ballon derrière soi.', array['Attendre de voir la passe partir avant de sauter.', 'Armer trop tard et frapper le ballon derrière soi.'], 'Ton saut est déclenché à l''aveugle, sur la lecture de la réception. Le bras doit être armé avant même de quitter le sol. Frappe court et devant : la rapide se joue dans un espace réduit.', array['Ajoute un bloqueur central adverse.'], array['Le passeur relève légèrement la passe pour laisser plus de temps.'], false, true, 5, 5, array['attaque', 'rapide', 'central', 'avance']),
  ('attaque_021', 'Attaque du pointu à l''antenne droite', 'Attaque depuis la zone 2, avec des angles inversés par rapport à la zone 4.', 'attaque', array['attaque d''aile', 'orientation', 'puissance'], array['opposite'], 'intermediaire', array['intermediaire', 'avance'], 'attaque', 'Attaquer efficacement depuis l''antenne droite.', 12, 3, 6, array['ballons', 'filet'], 'high', 4, 'Le passeur distribue en zone 2, à un mètre de l''antenne droite. Le pointu attaque en alternant ligne et diagonale. 4 séries de 8 attaques.', array['Le passeur distribue en zone 2, à un mètre de l''antenne droite.', 'Le pointu attaque en alternant ligne et diagonale.', '4 séries de 8 attaques.'], array['Depuis la zone 2, un droitier ouvre naturellement vers la ligne : exploite-le.', 'Termine ton élan parallèlement au filet, pas vers lui.', 'La diagonale depuis ce côté est plus courte : vise plus profond.'], 'Aborder la zone 2 avec l''élan utilisé en zone 4. Frapper systématiquement en diagonale et devenir prévisible.', array['Aborder la zone 2 avec l''élan utilisé en zone 4.', 'Frapper systématiquement en diagonale et devenir prévisible.'], 'Depuis la zone 2, un droitier ouvre naturellement vers la ligne : exploite-le. Termine ton élan parallèlement au filet, pas vers lui. La diagonale depuis ce côté est plus courte : vise plus profond.', array['Ajoute un double bloc adverse.'], array['L''attaquant frappe uniquement dans une direction annoncée.'], false, true, 4, 4, array['attaque', 'pointu', 'zone 2']),
  ('attaque_022', 'Pipe au centre du fond de court', 'Attaque arrière depuis la zone 6, lancée derrière la ligne des trois mètres.', 'attaque', array['attaque arrière', 'impulsion', 'timing'], array['outside_hitter', 'opposite'], 'avance', array['avance'], 'attaque', 'Réussir une attaque arrière centrale depuis le fond de court.', 12, 3, 6, array['ballons', 'filet'], 'high', 5, 'L''attaquant part du fond du terrain, au centre, et prend son impulsion derrière la ligne des trois mètres. Le passeur envoie une passe tendue au centre, à hauteur d''antenne. 4 séries de 6 attaques, avec récupération complète.', array['L''attaquant part du fond du terrain, au centre, et prend son impulsion derrière la ligne des trois mètres.', 'Le passeur envoie une passe tendue au centre, à hauteur d''antenne.', '4 séries de 6 attaques, avec récupération complète.'], array['L''impulsion se prend derrière la ligne, mais la retombée peut être devant.', 'Frappe long : depuis le fond, la trajectoire descendante n''existe presque pas.', 'Conserve un élan complet malgré la distance au filet.'], 'Mordre la ligne des trois mètres à l''impulsion. Frapper vers le bas et envoyer le ballon dans le filet.', array['Mordre la ligne des trois mètres à l''impulsion.', 'Frapper vers le bas et envoyer le ballon dans le filet.'], 'L''impulsion se prend derrière la ligne, mais la retombée peut être devant. Frappe long : depuis le fond, la trajectoire descendante n''existe presque pas. Conserve un élan complet malgré la distance au filet.', array['Ajoute une rapide du central sur le même ballon pour créer le doute.'], array['Rapproche le point d''impulsion et relève la passe.'], false, true, 5, 5, array['attaque', 'arriere', 'pipe', 'avance']),
  ('attaque_023', 'Attaque arrière depuis la zone 1', 'Attaque de fond de court côté droit, solution offensive du pointu en position arrière.', 'attaque', array['attaque arrière', 'puissance', 'trajectoire longue'], array['opposite', 'outside_hitter'], 'avance', array['avance'], 'attaque', 'Ajouter une menace offensive depuis la zone arrière droite.', 12, 3, 6, array['ballons', 'filet'], 'high', 5, 'L''attaquant démarre en zone 1 et prend son impulsion derrière la ligne des trois mètres. Il attaque en diagonale vers le fond du terrain adverse. 4 séries de 6 attaques.', array['L''attaquant démarre en zone 1 et prend son impulsion derrière la ligne des trois mètres.', 'Il attaque en diagonale vers le fond du terrain adverse.', '4 séries de 6 attaques.'], array['Oriente ton élan vers l''intérieur du terrain pour ouvrir l''angle croisé.', 'Frappe le ballon au point haut et vise la profondeur.', 'Anticipe la ligne des trois mètres : repère-la avant ton dernier appui.'], 'Prendre une trajectoire d''élan parallèle à la ligne latérale, qui ferme tous les angles. Frapper trop fort vers le bas et finir dans le filet.', array['Prendre une trajectoire d''élan parallèle à la ligne latérale, qui ferme tous les angles.', 'Frapper trop fort vers le bas et finir dans le filet.'], 'Oriente ton élan vers l''intérieur du terrain pour ouvrir l''angle croisé. Frappe le ballon au point haut et vise la profondeur. Anticipe la ligne des trois mètres : repère-la avant ton dernier appui.', array['Ajoute un bloc adverse à deux joueurs.'], array['Autorise une impulsion depuis la ligne des trois mètres.'], false, true, 5, 4, array['attaque', 'arriere', 'pointu', 'avance']),
  ('attaque_024', 'Lecture du bloc pendant l''élan', 'Prise d''information sur la position du bloc adverse au cours de la course d''élan.', 'attaque', array['lecture du bloc', 'prise d''information', 'décision'], array['outside_hitter', 'opposite', 'middle_blocker'], 'avance', array['avance'], 'attaque', 'Prendre l''information sur le bloc sans perdre le ballon de vue.', 10, 4, 8, array['ballons', 'filet'], 'high', 5, 'Le bloc se positionne différemment à chaque ballon : un bloqueur, deux, ou aucun. L''attaquant annonce après sa frappe ce qu''il a vu, pour vérifier sa prise d''information. 4 séries de 8 attaques.', array['Le bloc se positionne différemment à chaque ballon : un bloqueur, deux, ou aucun.', 'L''attaquant annonce après sa frappe ce qu''il a vu, pour vérifier sa prise d''information.', '4 séries de 8 attaques.'], array['Regarde le bloc pendant tes deux premiers appuis, puis le ballon.', 'Une seule information suffit : combien de bloqueurs et de quel côté.', 'Décide avant de sauter, pas en l''air.'], 'Fixer le ballon du début à la fin de l''élan. Chercher à regarder le bloc au moment de la frappe.', array['Fixer le ballon du début à la fin de l''élan.', 'Chercher à regarder le bloc au moment de la frappe.'], 'Regarde le bloc pendant tes deux premiers appuis, puis le ballon. Une seule information suffit : combien de bloqueurs et de quel côté. Décide avant de sauter, pas en l''air.', array['Le bloc change de configuration pendant l''élan.'], array['Le bloc garde la même configuration sur toute une série.'], false, true, 4, 5, array['attaque', 'lecture', 'bloc', 'avance']),
  ('attaque_025', 'Choix de direction selon le contre', 'Décision de frappe prise en fonction de la direction réellement fermée par le bloc.', 'attaque', array['décision', 'adaptation', 'précision'], array['outside_hitter', 'opposite'], 'avance', array['avance'], 'attaque', 'Adapter sa direction de frappe au bloc rencontré.', 12, 4, 8, array['ballons', 'filet'], 'high', 5, 'Le bloqueur ferme aléatoirement la ligne ou la diagonale avant chaque attaque. L''attaquant frappe obligatoirement dans la direction laissée libre. 4 séries de 8 attaques, en comptant les bons choix.', array['Le bloqueur ferme aléatoirement la ligne ou la diagonale avant chaque attaque.', 'L''attaquant frappe obligatoirement dans la direction laissée libre.', '4 séries de 8 attaques, en comptant les bons choix.'], array['La décision se prend pendant l''élan, jamais au sommet du saut.', 'Si le bloc est bien fermé partout, choisis la déviation extérieure.', 'Ne reste jamais sur une direction décidée avant d''avoir vu le bloc.'], 'Décider de sa direction avant même que la passe ne parte. Frapper dans le bloc faute d''avoir choisi à temps.', array['Décider de sa direction avant même que la passe ne parte.', 'Frapper dans le bloc faute d''avoir choisi à temps.'], 'La décision se prend pendant l''élan, jamais au sommet du saut. Si le bloc est bien fermé partout, choisis la déviation extérieure. Ne reste jamais sur une direction décidée avant d''avoir vu le bloc.', array['Le bloqueur change de direction fermée au dernier moment.'], array['Le bloqueur annonce la direction qu''il ferme.'], false, true, 4, 5, array['attaque', 'decision', 'bloc']),
  ('attaque_026', 'Feinte d''appel offensif', 'Simulation d''un appel d''attaque sans frapper, pour fixer le bloc adverse.', 'attaque', array['feinte', 'coordination', 'jeu collectif'], array['outside_hitter', 'opposite', 'middle_blocker'], 'avance', array['avance'], 'attaque', 'Fixer le bloc adverse par un appel crédible.', 10, 5, 8, array['ballons', 'filet'], 'high', 5, 'Le central effectue un appel de rapide complet sans recevoir le ballon. Le passeur distribue vers l''aile pendant que le bloc central est fixé. 4 séries de 8 combinaisons.', array['Le central effectue un appel de rapide complet sans recevoir le ballon.', 'Le passeur distribue vers l''aile pendant que le bloc central est fixé.', '4 séries de 8 combinaisons.'], array['L''appel doit être totalement crédible : même vitesse, même saut.', 'Le central regarde le passeur, comme s''il allait recevoir le ballon.', 'L''efficacité se mesure au bloc central, pas au ballon marqué.'], 'Faire un appel mou qui ne trompe personne. Regarder l''ailier pendant sa propre feinte.', array['Faire un appel mou qui ne trompe personne.', 'Regarder l''ailier pendant sa propre feinte.'], 'L''appel doit être totalement crédible : même vitesse, même saut. Le central regarde le passeur, comme s''il allait recevoir le ballon. L''efficacité se mesure au bloc central, pas au ballon marqué.', array['Le passeur sert parfois réellement le central pour entretenir le doute.'], array['Travaille d''abord l''appel seul, sans distribution.'], false, true, 5, 4, array['attaque', 'combinaison', 'collectif', 'avance']),
  ('attaque_027', 'Variation du point de frappe', 'Alternance volontaire entre frappe haute, frappe à plat et frappe enveloppée sur la même passe.', 'attaque', array['variété', 'toucher', 'adaptation'], array['outside_hitter', 'opposite', 'middle_blocker'], 'avance', array['avance'], 'attaque', 'Disposer de plusieurs trajectoires depuis une même situation.', 10, 3, 6, array['ballons', 'filet'], 'high', 5, 'Sur une passe identique, l''attaquant produit successivement trois frappes différentes. Un observateur vérifie que les trois trajectoires sont réellement distinctes. 4 séries de 9 attaques, trois de chaque type.', array['Sur une passe identique, l''attaquant produit successivement trois frappes différentes.', 'Un observateur vérifie que les trois trajectoires sont réellement distinctes.', '4 séries de 9 attaques, trois de chaque type.'], array['Seul le contact de la main change, l''élan reste identique.', 'Frapper au-dessus du ballon le fait descendre, derrière il part long.', 'Garde la même vitesse de bras quelle que soit la trajectoire visée.'], 'Ralentir le bras sur les frappes travaillées. Modifier l''élan et annoncer le type de frappe.', array['Ralentir le bras sur les frappes travaillées.', 'Modifier l''élan et annoncer le type de frappe.'], 'Seul le contact de la main change, l''élan reste identique. Frapper au-dessus du ballon le fait descendre, derrière il part long. Garde la même vitesse de bras quelle que soit la trajectoire visée.', array['L''attaquant choisit librement, un observateur note la variété obtenue.'], array['Travaille une seule variante par série.'], false, true, 4, 5, array['attaque', 'variete', 'toucher']),
  ('attaque_028', 'Conclusion par le passeur', 'Attaque réalisée par le passeur sur la deuxième touche, quand le bloc ne l''attend pas.', 'attaque', array['surprise', 'attaque', 'décision'], array['setter'], 'avance', array['avance'], 'attaque', 'Ajouter la menace d''une conclusion sur deuxième touche.', 10, 4, 8, array['ballons', 'filet'], 'medium', 4, 'Le passeur reçoit une réception haute et proche du filet. Il choisit entre distribuer normalement et conclure lui-même sur la deuxième touche. 4 séries de 10 ballons, avec au maximum trois conclusions personnelles par série.', array['Le passeur reçoit une réception haute et proche du filet.', 'Il choisit entre distribuer normalement et conclure lui-même sur la deuxième touche.', '4 séries de 10 ballons, avec au maximum trois conclusions personnelles par série.'], array['Adopte la même posture que pour une passe jusqu''au dernier instant.', 'Place le ballon dans un espace vide plutôt que de chercher la puissance.', 'N''utilise cette solution que sur ballon parfait et bloc mal placé.'], 'Annoncer son intention par une posture d''attaque dès la réception. Abuser de la solution et la rendre prévisible.', array['Annoncer son intention par une posture d''attaque dès la réception.', 'Abuser de la solution et la rendre prévisible.'], 'Adopte la même posture que pour une passe jusqu''au dernier instant. Place le ballon dans un espace vide plutôt que de chercher la puissance. N''utilise cette solution que sur ballon parfait et bloc mal placé.', array['Le bloc adverse surveille activement le passeur.'], array['Le passeur annonce à l''avance les ballons qu''il conclura.'], false, true, 3, 5, array['attaque', 'passeur', 'surprise', 'avance']),
  ('attaque_029', 'Parcours de cibles au sol', 'Série d''attaques dirigées successivement vers six zones matérialisées dans le terrain adverse.', 'attaque', array['précision', 'contrôle', 'variété'], array['outside_hitter', 'opposite', 'middle_blocker'], 'intermediaire', array['intermediaire', 'avance'], 'precision', 'Diriger précisément ses attaques dans tout le terrain.', 12, 3, 6, array['ballons', 'filet', 'plots'], 'high', 5, 'Six cibles sont réparties dans le terrain adverse, numérotées de 1 à 6. L''attaquant doit les toucher dans l''ordre, en reprenant à la première en cas d''échec. L''exercice s''arrête au parcours complet ou après 30 attaques.', array['Six cibles sont réparties dans le terrain adverse, numérotées de 1 à 6.', 'L''attaquant doit les toucher dans l''ordre, en reprenant à la première en cas d''échec.', 'L''exercice s''arrête au parcours complet ou après 30 attaques.'], array['Vise la cible, pas la zone générale : la précision se travaille par intention.', 'Adapte ton orientation de corps à chaque cible avant de sauter.', 'Conserve une vraie vitesse de bras même sur les cibles courtes.'], 'Réduire la puissance dès qu''une cible est difficile. Frapper au hasard en espérant toucher une cible.', array['Réduire la puissance dès qu''une cible est difficile.', 'Frapper au hasard en espérant toucher une cible.'], 'Vise la cible, pas la zone générale : la précision se travaille par intention. Adapte ton orientation de corps à chaque cible avant de sauter. Conserve une vraie vitesse de bras même sur les cibles courtes.', array['Réduis la taille des cibles à un mètre.'], array['Réduis le parcours à trois cibles.'], false, true, 4, 5, array['attaque', 'precision', 'cibles']),
  ('attaque_030', 'Attaque en état de fatigue', 'Attaques exigées après un effort physique, pour maintenir la qualité de geste en fin de set.', 'attaque', array['endurance', 'lucidité', 'frappe'], array['outside_hitter', 'opposite', 'middle_blocker'], 'avance', array['avance'], 'attaque', 'Conserver une attaque fiable en état de fatigue.', 12, 3, 6, array['ballons', 'filet'], 'high', 5, 'Effectue cinq sauts de bloc consécutifs au filet. Enchaîne immédiatement trois attaques complètes en zone 4. 4 séries, avec deux minutes de récupération entre chacune.', array['Effectue cinq sauts de bloc consécutifs au filet.', 'Enchaîne immédiatement trois attaques complètes en zone 4.', '4 séries, avec deux minutes de récupération entre chacune.'], array['Conserve un élan complet même fatigué : le raccourcir coûte plus cher.', 'Vise la sécurité plutôt que la puissance maximale en fin de série.', 'Contrôle ta respiration entre les répétitions.'], 'Réduire l''élan à un seul appui par fatigue. Frapper à pleine puissance sans contrôle et sortir le ballon.', array['Réduire l''élan à un seul appui par fatigue.', 'Frapper à pleine puissance sans contrôle et sortir le ballon.'], 'Conserve un élan complet même fatigué : le raccourcir coûte plus cher. Vise la sécurité plutôt que la puissance maximale en fin de série. Contrôle ta respiration entre les répétitions.', array['Passe à huit sauts de bloc avant les attaques.'], array['Réduis à trois sauts de bloc.'], false, true, 5, 4, array['attaque', 'fatigue', 'physique']),
  ('attaque_031', 'Série continue d''attaques', 'Répétition rapprochée d''attaques sans temps de récupération entre les ballons.', 'attaque', array['répétition', 'endurance', 'régularité'], array['outside_hitter', 'opposite', 'middle_blocker'], 'intermediaire', array['intermediaire', 'avance'], 'regularite', 'Répéter des attaques de qualité à cadence soutenue.', 10, 3, 6, array['ballons', 'filet'], 'high', 4, 'Le passeur envoie une passe toutes les cinq secondes. L''attaquant enchaîne dix attaques sans sortir du terrain. 4 séries, avec deux minutes de récupération.', array['Le passeur envoie une passe toutes les cinq secondes.', 'L''attaquant enchaîne dix attaques sans sortir du terrain.', '4 séries, avec deux minutes de récupération.'], array['Reviens à ton point de départ d''élan immédiatement après la retombée.', 'Amortis chaque retombée sur les deux pieds pour protéger les genoux.', 'Garde la même intention de frappe du premier au dernier ballon.'], 'Sauter à pieds joints sans élan pour aller plus vite. Négliger l''amorti des retombées quand la fatigue arrive.', array['Sauter à pieds joints sans élan pour aller plus vite.', 'Négliger l''amorti des retombées quand la fatigue arrive.'], 'Reviens à ton point de départ d''élan immédiatement après la retombée. Amortis chaque retombée sur les deux pieds pour protéger les genoux. Garde la même intention de frappe du premier au dernier ballon.', array['Réduis l''intervalle à quatre secondes.'], array['Allonge l''intervalle à huit secondes et réduis la série à six attaques.'], false, true, 5, 3, array['attaque', 'repetition', 'endurance']),
  ('attaque_032', 'Attaque face à un double contre', 'Situation offensive contre deux bloqueurs bien organisés, qui ferme les angles principaux.', 'attaque', array['décision', 'variété', 'lecture du bloc'], array['outside_hitter', 'opposite'], 'avance', array['avance'], 'attaque', 'Trouver des solutions offensives contre un double bloc.', 12, 5, 8, array['ballons', 'filet'], 'high', 5, 'Deux bloqueurs se coordonnent pour fermer la diagonale sur chaque attaque. L''attaquant doit trouver une solution : ligne, déviation ou ballon travaillé. 4 séries de 8 attaques, avec bilan des solutions efficaces.', array['Deux bloqueurs se coordonnent pour fermer la diagonale sur chaque attaque.', 'L''attaquant doit trouver une solution : ligne, déviation ou ballon travaillé.', '4 séries de 8 attaques, avec bilan des solutions efficaces.'], array['Contre un double bloc, la puissance seule ne suffit presque jamais.', 'Alterne trois solutions pour rester imprévisible.', 'Cherche l''espace entre le bloc et l''antenne, souvent mal fermé.'], 'Frapper systématiquement dans le bloc en espérant passer en force. Se rabattre uniquement sur l''amorti et devenir prévisible.', array['Frapper systématiquement dans le bloc en espérant passer en force.', 'Se rabattre uniquement sur l''amorti et devenir prévisible.'], 'Contre un double bloc, la puissance seule ne suffit presque jamais. Alterne trois solutions pour rester imprévisible. Cherche l''espace entre le bloc et l''antenne, souvent mal fermé.', array['Ajoute une défense complète derrière le bloc.'], array['Passe à un seul bloqueur.'], false, true, 5, 5, array['attaque', 'bloc', 'decision', 'avance']),
  ('attaque_033', 'Exploitation d''un ballon contre le filet', 'Gestion offensive des passes qui collent au filet, où l''espace de frappe est très réduit.', 'attaque', array['adaptation', 'toucher', 'sécurité'], array['outside_hitter', 'opposite', 'middle_blocker'], 'avance', array['avance'], 'attaque', 'Jouer un ballon collé au filet sans commettre de faute.', 10, 3, 6, array['ballons', 'filet'], 'high', 5, 'Le passeur envoie volontairement des passes très proches du filet. L''attaquant cherche une solution sans commettre de faute de filet. 4 séries de 8 ballons.', array['Le passeur envoie volontairement des passes très proches du filet.', 'L''attaquant cherche une solution sans commettre de faute de filet.', '4 séries de 8 ballons.'], array['Saute légèrement en retrait plutôt que sous le ballon.', 'Sur ballon très collé, une déviation dans le bloc est la meilleure option.', 'Garde ton bras libre près du corps pour éviter la faute de filet.'], 'Frapper en avançant et toucher le filet. Laisser passer le ballon dans le camp adverse sans le jouer.', array['Frapper en avançant et toucher le filet.', 'Laisser passer le ballon dans le camp adverse sans le jouer.'], 'Saute légèrement en retrait plutôt que sous le ballon. Sur ballon très collé, une déviation dans le bloc est la meilleure option. Garde ton bras libre près du corps pour éviter la faute de filet.', array['Ajoute un bloc adverse qui exploite la position du ballon.'], array['Éloigne légèrement la passe du filet.'], false, true, 4, 5, array['attaque', 'filet', 'adaptation', 'avance']),
  ('attaque_034', 'Puissance contrôlée en cible profonde', 'Frappes à intensité maximale mais contraintes de retomber dans les trois derniers mètres.', 'attaque', array['puissance', 'contrôle', 'précision'], array['outside_hitter', 'opposite', 'middle_blocker'], 'avance', array['avance'], 'attaque', 'Frapper fort tout en gardant le ballon dans une zone précise.', 10, 3, 6, array['ballons', 'filet', 'plots'], 'high', 5, 'Une zone de trois mètres est délimitée au fond du terrain adverse. L''attaquant frappe à pleine puissance en visant exclusivement cette zone. 4 séries de 8 attaques, en comptant les réussites.', array['Une zone de trois mètres est délimitée au fond du terrain adverse.', 'L''attaquant frappe à pleine puissance en visant exclusivement cette zone.', '4 séries de 8 attaques, en comptant les réussites.'], array['La puissance vient du gainage et du fouetté, pas de la force du bras seul.', 'Frappe légèrement plus haut sur le ballon pour l''allonger sans le sortir.', 'Une attaque puissante mais hors limites vaut zéro : le contrôle prime.'], 'Sacrifier la précision dès que la puissance augmente. Réduire la vitesse de bras pour sécuriser la zone.', array['Sacrifier la précision dès que la puissance augmente.', 'Réduire la vitesse de bras pour sécuriser la zone.'], 'La puissance vient du gainage et du fouetté, pas de la force du bras seul. Frappe légèrement plus haut sur le ballon pour l''allonger sans le sortir. Une attaque puissante mais hors limites vaut zéro : le contrôle prime.', array['Réduis la zone cible à deux mètres.'], array['Élargis la zone à toute la moitié arrière du terrain.'], false, true, 5, 4, array['attaque', 'puissance', 'precision']),
  ('attaque_035', 'Attaque en situation de match', 'Attaques intégrées à des points complets, avec bloc et défense adverses réels.', 'attaque', array['situation de jeu', 'décision', 'efficacité'], array['outside_hitter', 'opposite', 'middle_blocker'], 'avance', array['avance'], 'competition', 'Attaquer avec discernement dans un match réel.', 15, 8, 12, array['ballons', 'filet'], 'high', 5, 'Jouez des points complets, chaque attaque étant classée en point, poursuite ou faute. Chaque attaquant comptabilise son efficacité sur l''ensemble de la séance. Jouez deux sets courts en 15 points.', array['Jouez des points complets, chaque attaque étant classée en point, poursuite ou faute.', 'Chaque attaquant comptabilise son efficacité sur l''ensemble de la séance.', 'Jouez deux sets courts en 15 points.'], array['En match, une attaque qui prolonge l''échange vaut mieux qu''une faute.', 'Adapte ton choix à la qualité de la passe, pas à ton envie.', 'Analyse tes fautes : viennent-elles du choix ou de l''exécution ?'], 'Chercher le point à tout prix sur des ballons difficiles. Répéter le même choix offensif tout au long du set.', array['Chercher le point à tout prix sur des ballons difficiles.', 'Répéter le même choix offensif tout au long du set.'], 'En match, une attaque qui prolonge l''échange vaut mieux qu''une faute. Adapte ton choix à la qualité de la passe, pas à ton envie. Analyse tes fautes : viennent-elles du choix ou de l''exécution ?', array['Les fautes d''attaque comptent double pour l''adversaire.'], array['Supprimez le bloc adverse.'], false, true, 5, 5, array['attaque', 'match', 'competition']),
  ('attaque_036', 'Points comptés à l''efficacité', 'Jeu où seule l''efficacité offensive mesurée est prise en compte, fautes lourdement pénalisées.', 'attaque', array['gestion du risque', 'décision', 'efficacité'], array['outside_hitter', 'opposite', 'middle_blocker'], 'avance', array['avance'], 'competition', 'Apprendre à doser le risque offensif.', 15, 6, 12, array['ballons', 'filet'], 'high', 5, 'Une attaque conclue rapporte deux points, une attaque défendue zéro, une faute retire deux points. L''équipe atteignant vingt points remporte la confrontation. Jouez deux manches selon ce barème.', array['Une attaque conclue rapporte deux points, une attaque défendue zéro, une faute retire deux points.', 'L''équipe atteignant vingt points remporte la confrontation.', 'Jouez deux manches selon ce barème.'], array['Le barème récompense la lucidité : ne tente pas l''impossible.', 'Sur ballon difficile, une attaque sûre défendue vaut mieux qu''une faute.', 'Choisis ton moment pour prendre un vrai risque.'], 'Jouer en force sur tous les ballons malgré le barème. Devenir trop prudent et ne plus jamais conclure.', array['Jouer en force sur tous les ballons malgré le barème.', 'Devenir trop prudent et ne plus jamais conclure.'], 'Le barème récompense la lucidité : ne tente pas l''impossible. Sur ballon difficile, une attaque sûre défendue vaut mieux qu''une faute. Choisis ton moment pour prendre un vrai risque.', array['Une faute retire trois points.'], array['Une faute ne retire qu''un seul point.'], false, true, 4, 5, array['attaque', 'risque', 'competition']),
  ('attaque_037', 'Enchaînement attaque et couverture', 'Séquence où l''attaquant doit immédiatement couvrir son propre ballon après avoir frappé.', 'attaque', array['couverture', 'enchaînement', 'réaction'], array['outside_hitter', 'opposite', 'middle_blocker'], 'intermediaire', array['intermediaire', 'avance'], 'attaque', 'Enchaîner sa propre couverture après avoir attaqué.', 12, 4, 8, array['ballons', 'filet'], 'high', 4, 'L''attaquant frappe contre un bloc qui renvoie systématiquement le ballon. Il retombe, se retourne et récupère son propre ballon contré. 4 séries de 6 enchaînements.', array['L''attaquant frappe contre un bloc qui renvoie systématiquement le ballon.', 'Il retombe, se retourne et récupère son propre ballon contré.', '4 séries de 6 enchaînements.'], array['Retombe équilibré sur les deux pieds, prêt à repartir.', 'Fais demi-tour immédiatement, sans regarder le résultat de ta frappe.', 'Reste bas après ta retombée pour pouvoir plonger si nécessaire.'], 'Rester tourné vers le filet après la frappe. Se relever complètement avant de chercher le ballon contré.', array['Rester tourné vers le filet après la frappe.', 'Se relever complètement avant de chercher le ballon contré.'], 'Retombe équilibré sur les deux pieds, prêt à repartir. Fais demi-tour immédiatement, sans regarder le résultat de ta frappe. Reste bas après ta retombée pour pouvoir plonger si nécessaire.', array['Le bloc renvoie dans une direction imprévisible.'], array['Le bloc renvoie toujours au même endroit.'], false, true, 5, 3, array['attaque', 'couverture', 'enchainement']),
  ('attaque_038', 'Transition du bloc vers l''attaque', 'Décollage du filet après un saut de bloc pour reprendre un élan d''attaque complet.', 'attaque', array['transition', 'élan', 'coordination'], array['outside_hitter', 'opposite', 'middle_blocker'], 'avance', array['avance'], 'attaque', 'Repasser du bloc à l''attaque sans perdre son élan.', 12, 4, 8, array['ballons', 'filet'], 'high', 5, 'L''attaquant effectue d''abord un saut de bloc au filet. Il recule immédiatement hors du terrain et attaque la passe qui suit. 4 séries de 6 transitions, avec une minute de récupération.', array['L''attaquant effectue d''abord un saut de bloc au filet.', 'Il recule immédiatement hors du terrain et attaque la passe qui suit.', '4 séries de 6 transitions, avec une minute de récupération.'], array['Recule en pas croisés dès la retombée du bloc, sans temps mort.', 'Sors suffisamment loin pour disposer d''un élan complet.', 'Garde le passeur dans ton champ de vision pendant ton repli.'], 'Rester collé au filet et attaquer sans élan. Reculer en marchant et arriver en retard sur la passe.', array['Rester collé au filet et attaquer sans élan.', 'Reculer en marchant et arriver en retard sur la passe.'], 'Recule en pas croisés dès la retombée du bloc, sans temps mort. Sors suffisamment loin pour disposer d''un élan complet. Garde le passeur dans ton champ de vision pendant ton repli.', array['Ajoute un bloc adverse sur l''attaque de transition.'], array['Supprime le saut de bloc initial.'], false, true, 5, 4, array['attaque', 'transition', 'bloc']),
  ('attaque_039', 'Alternance des deux ailes', 'Attaques alternées en zone 4 puis en zone 2 pour développer la polyvalence offensive.', 'attaque', array['polyvalence', 'adaptation', 'élan'], array['outside_hitter', 'opposite'], 'avance', array['avance'], 'attaque', 'Attaquer efficacement depuis les deux ailes.', 12, 3, 6, array['ballons', 'filet'], 'high', 5, 'L''attaquant frappe une attaque en zone 4, puis traverse pour attaquer en zone 2. Il enchaîne sans pause entre les deux côtés. 4 séries de 6 doublons, avec récupération complète.', array['L''attaquant frappe une attaque en zone 4, puis traverse pour attaquer en zone 2.', 'Il enchaîne sans pause entre les deux côtés.', '4 séries de 6 doublons, avec récupération complète.'], array['Adapte l''orientation de ton élan à chaque côté du filet.', 'Les angles disponibles changent complètement d''une aile à l''autre.', 'Traverse derrière la ligne des trois mètres pour garder de l''espace d''élan.'], 'Utiliser le même élan des deux côtés. Traverser trop près du filet et manquer d''espace pour l''élan.', array['Utiliser le même élan des deux côtés.', 'Traverser trop près du filet et manquer d''espace pour l''élan.'], 'Adapte l''orientation de ton élan à chaque côté du filet. Les angles disponibles changent complètement d''une aile à l''autre. Traverse derrière la ligne des trois mètres pour garder de l''espace d''élan.', array['Ajoute une attaque arrière au centre entre les deux ailes.'], array['Travaille un seul côté par série.'], false, true, 5, 4, array['attaque', 'polyvalence', 'avance']),
  ('attaque_040', 'Défi de réussite offensive', 'Objectif chiffré d''attaques réussies consécutives, avec remise à zéro en cas de faute.', 'attaque', array['régularité', 'concentration', 'gestion du risque'], array['outside_hitter', 'opposite', 'middle_blocker'], 'intermediaire', array['intermediaire', 'avance'], 'regularite', 'Enchaîner des attaques réussies sans faute.', 12, 3, 6, array['ballons', 'filet'], 'high', 4, 'Chaque attaque qui retombe dans le terrain compte pour un point. Le compteur revient à zéro à la première faute, quelle qu''elle soit. L''exercice s''arrête à dix attaques consécutives réussies ou après 40 ballons.', array['Chaque attaque qui retombe dans le terrain compte pour un point.', 'Le compteur revient à zéro à la première faute, quelle qu''elle soit.', 'L''exercice s''arrête à dix attaques consécutives réussies ou après 40 ballons.'], array['Choisis une trajectoire sûre quand le compteur monte, sans ralentir le bras.', 'Conserve la même routine d''élan sur chaque ballon.', 'Après une remise à zéro, reviens à un choix simple.'], 'Frapper de plus en plus fort à mesure que le compteur monte. Se relâcher techniquement après une faute.', array['Frapper de plus en plus fort à mesure que le compteur monte.', 'Se relâcher techniquement après une faute.'], 'Choisis une trajectoire sûre quand le compteur monte, sans ralentir le bras. Conserve la même routine d''élan sur chaque ballon. Après une remise à zéro, reviens à un choix simple.', array['Porte l''objectif à quinze attaques consécutives.'], array['Abaisse l''objectif à six attaques.'], false, true, 4, 4, array['attaque', 'defi', 'regularite']),
  ('service_001', 'Service bas à la cuillère', 'Premier service, frappé sous la ligne d''épaule, pour franchir le filet de façon fiable.', 'service', array['service bas', 'contact', 'régularité'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant'], 'service', 'Réussir un service régulier qui franchit le filet.', 8, 1, 6, array['ballons', 'filet'], 'low', 2, 'Tiens le ballon dans la main opposée, bras tendu devant toi, à hauteur de hanche. Frappe le ballon avec le talon de la main en balançant le bras d''arrière en avant. 4 séries de 10 services, en comptant ceux qui passent le filet.', array['Tiens le ballon dans la main opposée, bras tendu devant toi, à hauteur de hanche.', 'Frappe le ballon avec le talon de la main en balançant le bras d''arrière en avant.', '4 séries de 10 services, en comptant ceux qui passent le filet.'], array['Ne lance pas le ballon : garde-le en main jusqu''au contact.', 'Avance le pied opposé au bras frappeur au moment de la frappe.', 'Le bras accompagne le ballon vers le haut après le contact.'], 'Lancer le ballon en l''air, ce qui rend le contact aléatoire. Frapper avec les doigts au lieu du talon de la main.', array['Lancer le ballon en l''air, ce qui rend le contact aléatoire.', 'Frapper avec les doigts au lieu du talon de la main.'], 'Ne lance pas le ballon : garde-le en main jusqu''au contact. Avance le pied opposé au bras frappeur au moment de la frappe. Le bras accompagne le ballon vers le haut après le contact.', array['Recule progressivement jusqu''à la ligne de fond.'], array['Sers depuis la ligne des trois mètres.'], true, true, 1, 2, array['service', 'debutant', 'fondamentaux']),
  ('service_002', 'Régularité du lancer de balle', 'Travail isolé du lancer, sans frappe, pour fiabiliser le point de départ de tout service haut.', 'service', array['lancer de balle', 'régularité', 'technique'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire'], 'service', 'Rendre le lancer de balle parfaitement reproductible.', 6, 1, 8, array['ballons'], 'low', 2, 'Lance le ballon comme pour servir, puis laisse-le retomber au sol sans le frapper. Le ballon doit retomber systématiquement au même endroit, devant ton pied avant. 3 séries de 15 lancers.', array['Lance le ballon comme pour servir, puis laisse-le retomber au sol sans le frapper.', 'Le ballon doit retomber systématiquement au même endroit, devant ton pied avant.', '3 séries de 15 lancers.'], array['Lance avec le bras tendu, sans mouvement de poignet.', 'Vise une hauteur d''un mètre cinquante au-dessus de ta main.', 'Repère un point au sol et vérifie que le ballon y retombe à chaque fois.'], 'Lancer le ballon derrière la tête, ce qui oblige à se cambrer. Donner un effet de rotation au ballon en le lançant.', array['Lancer le ballon derrière la tête, ce qui oblige à se cambrer.', 'Donner un effet de rotation au ballon en le lançant.'], 'Lance avec le bras tendu, sans mouvement de poignet. Vise une hauteur d''un mètre cinquante au-dessus de ta main. Repère un point au sol et vérifie que le ballon y retombe à chaque fois.', array['Ajoute la frappe une fois dix lancers consécutifs réguliers obtenus.'], array['Réduis la hauteur du lancer à un mètre.'], true, true, 1, 3, array['service', 'technique', 'solo', 'maison']),
  ('service_003', 'Service tennis debout', 'Service frappé au-dessus de l''épaule, pieds au sol, première forme de service haut.', 'service', array['service haut', 'frappe', 'coordination'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire'], 'service', 'Construire un service haut fiable, pieds au sol.', 10, 1, 6, array['ballons', 'filet'], 'medium', 3, 'Lance le ballon devant ton épaule frappeuse, à un mètre cinquante de hauteur. Frappe le ballon bras tendu, au point le plus haut, avec la paume ouverte. 4 séries de 10 services.', array['Lance le ballon devant ton épaule frappeuse, à un mètre cinquante de hauteur.', 'Frappe le ballon bras tendu, au point le plus haut, avec la paume ouverte.', '4 séries de 10 services.'], array['Le contact se fait devant toi, pas au-dessus de la tête.', 'Transfère ton poids de la jambe arrière vers la jambe avant pendant la frappe.', 'Garde le bras tendu au moment du contact.'], 'Frapper le ballon derrière la tête et l''envoyer dans le plafond. Plier le coude au contact et perdre toute puissance.', array['Frapper le ballon derrière la tête et l''envoyer dans le plafond.', 'Plier le coude au contact et perdre toute puissance.'], 'Le contact se fait devant toi, pas au-dessus de la tête. Transfère ton poids de la jambe arrière vers la jambe avant pendant la frappe. Garde le bras tendu au moment du contact.', array['Cherche à viser une moitié de terrain.'], array['Sers depuis la ligne des trois mètres.'], true, true, 2, 3, array['service', 'fondamentaux', 'frappe']),
  ('service_004', 'Service flottant debout', 'Service sans rotation du ballon, dont la trajectoire devient imprévisible en fin de course.', 'service', array['service flottant', 'contact sec', 'précision'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire'], 'service', 'Produire un service flottant sans rotation.', 10, 1, 6, array['ballons', 'filet'], 'medium', 3, 'Lance le ballon sans lui donner d''effet, à un mètre de hauteur seulement. Frappe sèchement le centre du ballon avec la paume, et arrête ton geste juste après. 4 séries de 10 services flottants.', array['Lance le ballon sans lui donner d''effet, à un mètre de hauteur seulement.', 'Frappe sèchement le centre du ballon avec la paume, et arrête ton geste juste après.', '4 séries de 10 services flottants.'], array['Coupe net ton geste après le contact : aucun accompagnement.', 'Frappe exactement le centre du ballon, une frappe décentrée crée de la rotation.', 'Un lancer bas facilite un contact précis.'], 'Accompagner le ballon et lui donner une rotation. Lancer trop haut, ce qui rend le contact au centre difficile.', array['Accompagner le ballon et lui donner une rotation.', 'Lancer trop haut, ce qui rend le contact au centre difficile.'], 'Coupe net ton geste après le contact : aucun accompagnement. Frappe exactement le centre du ballon, une frappe décentrée crée de la rotation. Un lancer bas facilite un contact précis.', array['Vise une zone précise du terrain adverse.'], array['Sers depuis la ligne des trois mètres.'], true, true, 2, 4, array['service', 'flottant', 'technique']),
  ('service_005', 'Service flottant sauté', 'Service flottant frappé en suspension, plus rapide et plus plongeant que sa version debout.', 'service', array['service flottant', 'suspension', 'timing'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'avance', array['avance'], 'service', 'Maîtriser le service flottant en suspension.', 12, 1, 6, array['ballons', 'filet'], 'high', 5, 'Lance le ballon devant toi puis effectue deux ou trois appuis d''élan. Frappe le ballon sèchement au sommet du saut, sans accompagnement. 4 séries de 8 services.', array['Lance le ballon devant toi puis effectue deux ou trois appuis d''élan.', 'Frappe le ballon sèchement au sommet du saut, sans accompagnement.', '4 séries de 8 services.'], array['Le lancer doit être suffisamment en avant pour frapper en montant.', 'Le saut sert la vitesse, pas la hauteur : reste efficace plutôt que spectaculaire.', 'Le contact reste sec, exactement comme en flottant debout.'], 'Lancer trop haut et devoir attendre le ballon en l''air. Accompagner le ballon et perdre l''effet flottant.', array['Lancer trop haut et devoir attendre le ballon en l''air.', 'Accompagner le ballon et perdre l''effet flottant.'], 'Le lancer doit être suffisamment en avant pour frapper en montant. Le saut sert la vitesse, pas la hauteur : reste efficace plutôt que spectaculaire. Le contact reste sec, exactement comme en flottant debout.', array['Ajoute une contrainte de zone visée.'], array['Reviens au flottant debout pour retrouver le contact sec.'], true, true, 4, 5, array['service', 'flottant', 'saute', 'avance']),
  ('service_006', 'Service smashé sauté', 'Service le plus puissant, frappé avec rotation après un véritable élan d''attaque.', 'service', array['service smashé', 'élan', 'puissance'], array['outside_hitter', 'opposite', 'middle_blocker'], 'avance', array['avance'], 'service', 'Développer un service smashé puissant et dans le terrain.', 12, 1, 6, array['ballons', 'filet'], 'high', 5, 'Lance le ballon haut et loin devant toi, puis effectue un élan d''attaque complet. Frappe le ballon en le brossant vers le haut pour lui donner une rotation avant. 4 séries de 6 services, avec récupération complète entre les séries.', array['Lance le ballon haut et loin devant toi, puis effectue un élan d''attaque complet.', 'Frappe le ballon en le brossant vers le haut pour lui donner une rotation avant.', '4 séries de 6 services, avec récupération complète entre les séries.'], array['Le lancer conditionne tout : il doit être identique à chaque service.', 'Brosse le dessus du ballon pour le faire retomber dans le terrain.', 'Frappe en avançant, le corps en mouvement vers le filet.'], 'Frapper le ballon à plat, ce qui l''envoie systématiquement trop long. Lancer le ballon trop près de soi et frapper en se cambrant.', array['Frapper le ballon à plat, ce qui l''envoie systématiquement trop long.', 'Lancer le ballon trop près de soi et frapper en se cambrant.'], 'Le lancer conditionne tout : il doit être identique à chaque service. Brosse le dessus du ballon pour le faire retomber dans le terrain. Frappe en avançant, le corps en mouvement vers le filet.', array['Ajoute une contrainte de zone après avoir fiabilisé le geste.'], array['Réduis la puissance à soixante-dix pour cent pour installer la trajectoire.'], true, true, 5, 5, array['service', 'smashe', 'puissance', 'avance']),
  ('service_007', 'Ciblage du coin arrière droit', 'Services dirigés vers le coin le plus éloigné, à droite du terrain adverse.', 'service', array['précision', 'orientation', 'service'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire'], 'precision', 'Servir précisément dans le coin arrière droit.', 10, 1, 6, array['ballons', 'filet', 'plots'], 'medium', 3, 'Une cible de deux mètres sur deux est posée dans le coin arrière droit adverse. Effectue 10 services en visant exclusivement cette zone. 4 séries, en comptant les réussites.', array['Une cible de deux mètres sur deux est posée dans le coin arrière droit adverse.', 'Effectue 10 services en visant exclusivement cette zone.', '4 séries, en comptant les réussites.'], array['Oriente tes appuis vers la cible avant de lancer le ballon.', 'Vise une trajectoire longue : ce coin est le point le plus éloigné du terrain.', 'Garde la même puissance, seule la direction change.'], 'Corriger la direction avec le bras au lieu des appuis. Réduire la puissance pour gagner en précision.', array['Corriger la direction avec le bras au lieu des appuis.', 'Réduire la puissance pour gagner en précision.'], 'Oriente tes appuis vers la cible avant de lancer le ballon. Vise une trajectoire longue : ce coin est le point le plus éloigné du terrain. Garde la même puissance, seule la direction change.', array['Réduis la cible à un mètre.'], array['Élargis la cible à tout le quart arrière du terrain.'], true, true, 2, 4, array['service', 'precision', 'ciblage']),
  ('service_008', 'Service long sur la ligne gauche', 'Services longeant la ligne latérale gauche, zone difficile à couvrir pour la réception.', 'service', array['précision', 'trajectoire longue', 'service'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire', 'avance'], 'precision', 'Servir le long de la ligne sans sortir du terrain.', 10, 1, 6, array['ballons', 'filet', 'plots'], 'medium', 3, 'Une bande d''un mètre le long de la ligne latérale gauche sert de cible. Effectue 10 services dans cette bande, sur toute sa longueur. 4 séries, en comptant les réussites.', array['Une bande d''un mètre le long de la ligne latérale gauche sert de cible.', 'Effectue 10 services dans cette bande, sur toute sa longueur.', '4 séries, en comptant les réussites.'], array['Une cible étroite impose une marge : vise un mètre à l''intérieur de la ligne.', 'La trajectoire doit rester tendue pour ne pas dériver hors du terrain.', 'Répète exactement le même lancer sur chaque service.'], 'Viser la ligne elle-même et sortir un service sur deux. Servir trop haut, ce qui laisse la trajectoire dériver.', array['Viser la ligne elle-même et sortir un service sur deux.', 'Servir trop haut, ce qui laisse la trajectoire dériver.'], 'Une cible étroite impose une marge : vise un mètre à l''intérieur de la ligne. La trajectoire doit rester tendue pour ne pas dériver hors du terrain. Répète exactement le même lancer sur chaque service.', array['Réduis la bande à cinquante centimètres.'], array['Élargis la bande à deux mètres.'], true, true, 2, 4, array['service', 'precision', 'ligne']),
  ('service_009', 'Service au centre du fond de court', 'Services dirigés au centre en profondeur, zone de partage entre plusieurs réceptionneurs.', 'service', array['précision', 'profondeur', 'service'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire'], 'precision', 'Servir profond au centre pour créer le doute en réception.', 10, 1, 6, array['ballons', 'filet', 'plots'], 'medium', 3, 'Une cible est posée au centre du terrain adverse, à un mètre de la ligne de fond. Effectue 10 services dans cette zone. 4 séries, en comptant les réussites.', array['Une cible est posée au centre du terrain adverse, à un mètre de la ligne de fond.', 'Effectue 10 services dans cette zone.', '4 séries, en comptant les réussites.'], array['Cette zone met en difficulté la répartition entre réceptionneurs : elle est payante.', 'Vise profond : un service central trop court est facile à réceptionner.', 'Garde la même hauteur de trajectoire d''un service à l''autre.'], 'Servir court au centre et offrir une réception facile. Viser le milieu du terrain en profondeur sans repère précis.', array['Servir court au centre et offrir une réception facile.', 'Viser le milieu du terrain en profondeur sans repère précis.'], 'Cette zone met en difficulté la répartition entre réceptionneurs : elle est payante. Vise profond : un service central trop court est facile à réceptionner. Garde la même hauteur de trajectoire d''un service à l''autre.', array['Réduis la cible à un mètre et ajoute une contrainte de puissance.'], array['Élargis la cible à trois mètres.'], true, true, 2, 3, array['service', 'precision', 'profondeur']),
  ('service_010', 'Service court devant la ligne des trois mètres', 'Services déposés juste derrière le filet, pour prendre à contre-pied une réception reculée.', 'service', array['dosage', 'précision', 'surprise'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire', 'avance'], 'service', 'Déposer un service court derrière le filet.', 10, 1, 6, array['ballons', 'filet', 'plots'], 'medium', 3, 'La cible est la zone comprise entre le filet et la ligne des trois mètres. Effectue 10 services courts, en gardant une trajectoire tendue au-dessus du filet. 4 séries, en comptant les réussites.', array['La cible est la zone comprise entre le filet et la ligne des trois mètres.', 'Effectue 10 services courts, en gardant une trajectoire tendue au-dessus du filet.', '4 séries, en comptant les réussites.'], array['Réduis la puissance sans changer la vitesse du bras : le contact est plus léger.', 'Garde la trajectoire basse, un service court en cloche est trop lisible.', 'Adopte la même posture de départ que sur un service long.'], 'Annoncer le service court par une attitude différente. Envoyer le ballon dans le filet en cherchant trop court.', array['Annoncer le service court par une attitude différente.', 'Envoyer le ballon dans le filet en cherchant trop court.'], 'Réduis la puissance sans changer la vitesse du bras : le contact est plus léger. Garde la trajectoire basse, un service court en cloche est trop lisible. Adopte la même posture de départ que sur un service long.', array['Alterne service court et service long sans prévenir.'], array['Élargis la cible jusqu''à quatre mètres du filet.'], true, true, 2, 4, array['service', 'court', 'surprise']),
  ('service_011', 'Service profond près de la ligne de fond', 'Services longs qui obligent les réceptionneurs à reculer jusqu''aux limites du terrain.', 'service', array['profondeur', 'puissance', 'précision'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire', 'avance'], 'precision', 'Repousser la réception adverse vers le fond du terrain.', 10, 1, 6, array['ballons', 'filet', 'plots'], 'medium', 3, 'La cible est la bande de deux mètres située devant la ligne de fond adverse. Effectue 10 services dans cette bande, sans mordre la ligne. 4 séries, en comptant les réussites.', array['La cible est la bande de deux mètres située devant la ligne de fond adverse.', 'Effectue 10 services dans cette bande, sans mordre la ligne.', '4 séries, en comptant les réussites.'], array['Sers légèrement plus haut au-dessus du filet pour gagner en longueur.', 'Une trajectoire descendante tardive est bien plus difficile à réceptionner.', 'Ne cherche pas la ligne exacte : garde un mètre de marge.'], 'Viser la ligne et multiplier les services hors limites. Forcer la puissance sans gagner en longueur utile.', array['Viser la ligne et multiplier les services hors limites.', 'Forcer la puissance sans gagner en longueur utile.'], 'Sers légèrement plus haut au-dessus du filet pour gagner en longueur. Une trajectoire descendante tardive est bien plus difficile à réceptionner. Ne cherche pas la ligne exacte : garde un mètre de marge.', array['Réduis la bande cible à un mètre.'], array['Élargis la bande à quatre mètres.'], true, true, 3, 3, array['service', 'profondeur', 'precision']),
  ('service_012', 'Service entre deux réceptionneurs', 'Services dirigés sur la zone de partage entre deux joueurs, pour provoquer l''hésitation.', 'service', array['tactique', 'précision', 'service'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'avance', array['avance'], 'service', 'Exploiter les zones de partage de la réception adverse.', 10, 3, 8, array['ballons', 'filet'], 'medium', 4, 'Deux réceptionneurs se placent en ligne de réception normale. Le serveur vise systématiquement l''espace situé entre eux. 4 séries de 8 services, en comptant les hésitations provoquées.', array['Deux réceptionneurs se placent en ligne de réception normale.', 'Le serveur vise systématiquement l''espace situé entre eux.', '4 séries de 8 services, en comptant les hésitations provoquées.'], array['Cette zone n''est pas au milieu du terrain : elle dépend du placement adverse.', 'Observe la ligne de réception avant de lancer ton ballon.', 'Un service flottant est particulièrement efficace sur cette zone.'], 'Viser le milieu du terrain sans regarder le placement réel. Servir trop fort, ce qui laisse moins de temps au doute de s''installer.', array['Viser le milieu du terrain sans regarder le placement réel.', 'Servir trop fort, ce qui laisse moins de temps au doute de s''installer.'], 'Cette zone n''est pas au milieu du terrain : elle dépend du placement adverse. Observe la ligne de réception avant de lancer ton ballon. Un service flottant est particulièrement efficace sur cette zone.', array['Les réceptionneurs changent de placement entre chaque service.'], array['Les réceptionneurs s''écartent volontairement pour élargir la zone.'], false, true, 2, 5, array['service', 'tactique', 'avance']),
  ('service_013', 'Service sur le passeur adverse', 'Services dirigés vers le passeur pour l''obliger à toucher la première balle.', 'service', array['tactique', 'ciblage', 'service'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'avance', array['avance'], 'service', 'Perturber l''organisation adverse en ciblant le passeur.', 10, 4, 8, array['ballons', 'filet'], 'medium', 4, 'Le passeur adverse se place dans sa zone de départ habituelle. Le serveur vise systématiquement la zone du passeur. 4 séries de 8 services.', array['Le passeur adverse se place dans sa zone de départ habituelle.', 'Le serveur vise systématiquement la zone du passeur.', '4 séries de 8 services.'], array['Repère la position de départ du passeur avant chaque service.', 'Un service court vers le passeur est souvent plus gênant qu''un service long.', 'L''objectif est de le contraindre à toucher la balle, pas forcément l''ace.'], 'Servir vers la zone de passe plutôt que vers le passeur lui-même. Chercher l''ace au lieu de simplement gêner l''organisation adverse.', array['Servir vers la zone de passe plutôt que vers le passeur lui-même.', 'Chercher l''ace au lieu de simplement gêner l''organisation adverse.'], 'Repère la position de départ du passeur avant chaque service. Un service court vers le passeur est souvent plus gênant qu''un service long. L''objectif est de le contraindre à toucher la balle, pas forcément l''ace.', array['Le passeur change de position de départ à chaque rotation.'], array['Le passeur reste immobile à une position fixe.'], false, true, 2, 5, array['service', 'tactique', 'passeur', 'avance']),
  ('service_014', 'Ciblage du meilleur attaquant', 'Services dirigés sur l''attaquant principal adverse pour réduire sa disponibilité offensive.', 'service', array['tactique', 'ciblage', 'service'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'avance', array['avance'], 'service', 'Réduire la menace offensive adverse par le service.', 10, 4, 8, array['ballons', 'filet'], 'medium', 4, 'Un attaquant est désigné comme cible prioritaire à chaque rotation. Le serveur l''oblige à réceptionner avant de pouvoir attaquer. 4 séries de 8 services, en observant l''effet sur ses attaques.', array['Un attaquant est désigné comme cible prioritaire à chaque rotation.', 'Le serveur l''oblige à réceptionner avant de pouvoir attaquer.', '4 séries de 8 services, en observant l''effet sur ses attaques.'], array['Sers loin de lui pour l''obliger à se déplacer, pas directement sur lui.', 'Un attaquant qui réceptionne loin de sa zone d''élan perd en efficacité.', 'Répète le ciblage : l''effet se construit sur la durée.'], 'Cibler un joueur une fois puis passer à autre chose. Servir sur le joueur sans le faire se déplacer.', array['Cibler un joueur une fois puis passer à autre chose.', 'Servir sur le joueur sans le faire se déplacer.'], 'Sers loin de lui pour l''obliger à se déplacer, pas directement sur lui. Un attaquant qui réceptionne loin de sa zone d''élan perd en efficacité. Répète le ciblage : l''effet se construit sur la durée.', array['Ajoute une contrainte de zone en plus du ciblage.'], array['Le joueur ciblé reste à une position fixe.'], false, true, 2, 5, array['service', 'tactique', 'ciblage', 'avance']),
  ('service_015', 'Routine avant le service', 'Construction d''un rituel identique avant chaque service, pour stabiliser le geste sous pression.', 'service', array['routine', 'concentration', 'régularité'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire', 'avance'], 'service', 'Installer un rituel de service stable et reproductible.', 8, 1, 8, array['ballons', 'filet'], 'low', 2, 'Définis une routine précise : nombre de rebonds, respiration, point visé. Exécute exactement la même routine avant chacun de tes 20 services. Un observateur vérifie qu''aucune étape n''est sautée.', array['Définis une routine précise : nombre de rebonds, respiration, point visé.', 'Exécute exactement la même routine avant chacun de tes 20 services.', 'Un observateur vérifie qu''aucune étape n''est sautée.'], array['La routine doit être courte, reproductible et identique en toutes circonstances.', 'Elle se termine toujours par la visualisation de la zone visée.', 'C''est sous pression qu''elle sert : entraîne-la quand tout va bien.'], 'Accélérer ou raccourcir la routine quand le rythme du jeu s''accélère. Changer de routine d''une séance à l''autre.', array['Accélérer ou raccourcir la routine quand le rythme du jeu s''accélère.', 'Changer de routine d''une séance à l''autre.'], 'La routine doit être courte, reproductible et identique en toutes circonstances. Elle se termine toujours par la visualisation de la zone visée. C''est sous pression qu''elle sert : entraîne-la quand tout va bien.', array['Exécute la routine dans un environnement bruyant.'], array['Réduis la routine à deux étapes simples.'], true, true, 1, 3, array['service', 'routine', 'mental']),
  ('service_016', 'Dix services consécutifs dans le terrain', 'Série de fiabilité où toute faute remet le compteur à zéro.', 'service', array['régularité', 'concentration', 'gestion du risque'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire'], 'regularite', 'Atteindre une fiabilité complète au service.', 10, 1, 6, array['ballons', 'filet'], 'medium', 3, 'Chaque service réussi compte pour un, toute faute remet le compteur à zéro. L''objectif est d''atteindre dix services consécutifs. L''exercice s''arrête à l''objectif atteint ou après 40 tentatives.', array['Chaque service réussi compte pour un, toute faute remet le compteur à zéro.', 'L''objectif est d''atteindre dix services consécutifs.', 'L''exercice s''arrête à l''objectif atteint ou après 40 tentatives.'], array['Choisis une zone sûre : la régularité prime sur l''agressivité ici.', 'Garde la même routine, surtout quand le compteur monte.', 'Après une faute, reviens au geste le plus simple.'], 'Augmenter la prise de risque à mesure que le compteur monte. Se crisper sur la technique après deux fautes.', array['Augmenter la prise de risque à mesure que le compteur monte.', 'Se crisper sur la technique après deux fautes.'], 'Choisis une zone sûre : la régularité prime sur l''agressivité ici. Garde la même routine, surtout quand le compteur monte. Après une faute, reviens au geste le plus simple.', array['Porte l''objectif à vingt services consécutifs.'], array['Abaisse l''objectif à cinq services.'], true, true, 2, 3, array['service', 'regularite', 'objectif']),
  ('service_017', 'Service sur balle de set', 'Services effectués en situation simulée de point décisif, avec conséquence en cas de faute.', 'service', array['gestion de pression', 'décision', 'service'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'avance', array['avance'], 'competition', 'Servir avec lucidité sur un point décisif.', 10, 2, 8, array['ballons', 'filet'], 'medium', 4, 'Annonce à voix haute un score de 24 à 24 avant chaque service. Une faute de service coûte dix pompes ou un sprint, une réussite fait gagner le point. Effectue 15 services dans ces conditions.', array['Annonce à voix haute un score de 24 à 24 avant chaque service.', 'Une faute de service coûte dix pompes ou un sprint, une réussite fait gagner le point.', 'Effectue 15 services dans ces conditions.'], array['Sous pression, réduis l''ambition d''un cran : vise une zone plus large.', 'Respire complètement avant de lancer le ballon.', 'Garde exactement la même routine qu''à l''entraînement.'], 'Servir beaucoup plus mou par peur de la faute. Au contraire, forcer davantage sous l''effet du stress.', array['Servir beaucoup plus mou par peur de la faute.', 'Au contraire, forcer davantage sous l''effet du stress.'], 'Sous pression, réduis l''ambition d''un cran : vise une zone plus large. Respire complètement avant de lancer le ballon. Garde exactement la même routine qu''à l''entraînement.', array['Ajoute un public ou des coéquipiers qui commentent.'], array['Supprime la conséquence physique en cas de faute.'], false, true, 3, 4, array['service', 'pression', 'competition']),
  ('service_018', 'Service après course intense', 'Services exécutés immédiatement après un effort, comme en fin de long échange.', 'service', array['lucidité', 'endurance', 'service'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire', 'avance'], 'service', 'Servir avec fiabilité malgré l''essoufflement.', 10, 1, 6, array['ballons', 'filet', 'plots'], 'high', 4, 'Effectue trente secondes de navettes entre deux plots. Enchaîne immédiatement cinq services vers une zone définie. 4 séries, avec deux minutes de récupération entre chacune.', array['Effectue trente secondes de navettes entre deux plots.', 'Enchaîne immédiatement cinq services vers une zone définie.', '4 séries, avec deux minutes de récupération entre chacune.'], array['Prends le temps de respirer avant de lancer, même si tu es essoufflé.', 'La fatigue raccourcit le geste : pense à finir ton mouvement.', 'Reviens à une zone sûre plutôt qu''à un ciblage difficile.'], 'Servir immédiatement sans reprendre son souffle. Garder le même niveau de risque qu''à froid.', array['Servir immédiatement sans reprendre son souffle.', 'Garder le même niveau de risque qu''à froid.'], 'Prends le temps de respirer avant de lancer, même si tu es essoufflé. La fatigue raccourcit le geste : pense à finir ton mouvement. Reviens à une zone sûre plutôt qu''à un ciblage difficile.', array['Allonge l''effort préalable à quarante-cinq secondes.'], array['Réduis l''effort préalable à quinze secondes.'], true, true, 4, 3, array['service', 'fatigue', 'physique']),
  ('service_019', 'Trois puissances sur une même zone', 'Services successifs vers la même cible en variant volontairement la puissance.', 'service', array['dosage', 'contrôle', 'variété'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'avance', array['avance'], 'service', 'Contrôler sa zone quelle que soit la puissance employée.', 10, 1, 6, array['ballons', 'filet', 'plots'], 'medium', 4, 'Vise une cible unique et sers successivement à cinquante, soixante-quinze puis cent pour cent. Les trois services doivent atteindre la même zone. 4 séries de 9 services, trois de chaque intensité.', array['Vise une cible unique et sers successivement à cinquante, soixante-quinze puis cent pour cent.', 'Les trois services doivent atteindre la même zone.', '4 séries de 9 services, trois de chaque intensité.'], array['La trajectoire change avec la puissance : ajuste la hauteur de passage au filet.', 'Conserve exactement le même lancer quelle que soit l''intensité.', 'Un service lent bien placé reste dangereux.'], 'Modifier le lancer en même temps que la puissance. Perdre la zone dès que l''intensité augmente.', array['Modifier le lancer en même temps que la puissance.', 'Perdre la zone dès que l''intensité augmente.'], 'La trajectoire change avec la puissance : ajuste la hauteur de passage au filet. Conserve exactement le même lancer quelle que soit l''intensité. Un service lent bien placé reste dangereux.', array['Un observateur annonce l''intensité au dernier moment.'], array['Travaille deux intensités seulement.'], true, true, 3, 4, array['service', 'dosage', 'variete']),
  ('service_020', 'Alternance de hauteur de passage', 'Services variant la hauteur de passage au-dessus du filet, tendue puis cloche.', 'service', array['trajectoire', 'variété', 'contrôle'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire', 'avance'], 'service', 'Varier la hauteur de passage au filet à volonté.', 10, 1, 6, array['ballons', 'filet', 'elastique'], 'medium', 3, 'Tends un élastique à un mètre au-dessus du filet. Alterne un service passant sous l''élastique et un service passant au-dessus. 4 séries de 10 services, cinq de chaque type.', array['Tends un élastique à un mètre au-dessus du filet.', 'Alterne un service passant sous l''élastique et un service passant au-dessus.', '4 séries de 10 services, cinq de chaque type.'], array['La hauteur se règle par l''angle de frappe, pas par la puissance.', 'Un service tendu arrive plus vite, un service haut plonge plus tard.', 'Les deux doivent rester dans le terrain : c''est la contrainte réelle.'], 'Ralentir le bras pour faire passer le ballon haut. Servir systématiquement à la même hauteur sans s''en rendre compte.', array['Ralentir le bras pour faire passer le ballon haut.', 'Servir systématiquement à la même hauteur sans s''en rendre compte.'], 'La hauteur se règle par l''angle de frappe, pas par la puissance. Un service tendu arrive plus vite, un service haut plonge plus tard. Les deux doivent rester dans le terrain : c''est la contrainte réelle.', array['Ajoute une contrainte de zone en plus de la hauteur.'], array['Supprime l''élastique et utilise un repère visuel.'], true, true, 2, 4, array['service', 'trajectoire', 'variete']),
  ('service_021', 'Frappe de service contre un mur', 'Travail solo du geste de service en frappant contre un mur, sans terrain nécessaire.', 'service', array['frappe', 'technique', 'autonomie'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire'], 'service', 'Travailler son service seul, sans terrain ni partenaire.', 8, 1, 1, array['ballons', 'mur'], 'medium', 3, 'Place-toi à cinq mètres d''un mur et repère une cible à trois mètres de hauteur. Effectue le geste complet de service en visant cette cible. 4 séries de 10 services, en comptant les cibles touchées.', array['Place-toi à cinq mètres d''un mur et repère une cible à trois mètres de hauteur.', 'Effectue le geste complet de service en visant cette cible.', '4 séries de 10 services, en comptant les cibles touchées.'], array['Concentre-toi sur la régularité du lancer, c''est le point clé du service.', 'La cible haute reproduit la trajectoire de passage au-dessus du filet.', 'Récupère ton ballon et reprends ta routine complète à chaque fois.'], 'Enchaîner sans routine pour aller plus vite. Se rapprocher du mur au fil de la série.', array['Enchaîner sans routine pour aller plus vite.', 'Se rapprocher du mur au fil de la série.'], 'Concentre-toi sur la régularité du lancer, c''est le point clé du service. La cible haute reproduit la trajectoire de passage au-dessus du filet. Récupère ton ballon et reprends ta routine complète à chaque fois.', array['Réduis la taille de la cible sur le mur.'], array['Rapproche-toi à trois mètres du mur.'], true, true, 2, 3, array['service', 'solo', 'maison']),
  ('service_022', 'Passage sous contrainte de hauteur', 'Services devant passer dans une fenêtre étroite au-dessus du filet, matérialisée par un élastique.', 'service', array['précision', 'trajectoire', 'contrôle'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'avance', array['avance'], 'service', 'Produire un service tendu qui reste dans le terrain.', 10, 2, 6, array['ballons', 'filet', 'elastique'], 'medium', 4, 'Tends un élastique à cinquante centimètres au-dessus du filet. Chaque service doit passer entre le filet et l''élastique, et rester dans le terrain. 4 séries de 10 services.', array['Tends un élastique à cinquante centimètres au-dessus du filet.', 'Chaque service doit passer entre le filet et l''élastique, et rester dans le terrain.', '4 séries de 10 services.'], array['Une trajectoire tendue arrive plus vite sur le réceptionneur.', 'Frappe un peu plus haut sur le ballon pour aplatir la trajectoire.', 'Accepte quelques fautes : la marge est volontairement étroite.'], 'Réduire la puissance pour passer sous l''élastique et perdre tout danger. Frapper dans le filet en cherchant une trajectoire trop basse.', array['Réduire la puissance pour passer sous l''élastique et perdre tout danger.', 'Frapper dans le filet en cherchant une trajectoire trop basse.'], 'Une trajectoire tendue arrive plus vite sur le réceptionneur. Frappe un peu plus haut sur le ballon pour aplatir la trajectoire. Accepte quelques fautes : la marge est volontairement étroite.', array['Abaisse l''élastique à trente centimètres.'], array['Monte l''élastique à un mètre.'], false, true, 3, 5, array['service', 'trajectoire', 'avance']),
  ('service_023', 'Variation de l''angle de départ', 'Services effectués depuis différents points de la ligne de fond, modifiant les angles disponibles.', 'service', array['angles', 'adaptation', 'tactique'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire', 'avance'], 'service', 'Exploiter les angles offerts par la position de service.', 10, 1, 6, array['ballons', 'filet', 'plots'], 'medium', 3, 'Trois positions de service sont marquées : à gauche, au centre et à droite de la zone. Effectue trois services depuis chaque position, en visant la même zone adverse. 4 séries de 9 services.', array['Trois positions de service sont marquées : à gauche, au centre et à droite de la zone.', 'Effectue trois services depuis chaque position, en visant la même zone adverse.', '4 séries de 9 services.'], array['Changer de point de départ modifie tout l''angle de trajectoire.', 'Un départ latéral ouvre des zones inaccessibles depuis le centre.', 'Réoriente tout ton corps, pas seulement le bras.'], 'Garder la même orientation de corps quelle que soit la position de départ. Servir toujours depuis le même endroit en match par habitude.', array['Garder la même orientation de corps quelle que soit la position de départ.', 'Servir toujours depuis le même endroit en match par habitude.'], 'Changer de point de départ modifie tout l''angle de trajectoire. Un départ latéral ouvre des zones inaccessibles depuis le centre. Réoriente tout ton corps, pas seulement le bras.', array['Change de position de départ à chaque service.'], array['Utilise deux positions de départ seulement.'], true, true, 2, 4, array['service', 'angles', 'tactique']),
  ('service_024', 'Duel entre serveur et réceptionneur', 'Opposition directe où le serveur marque des points selon la qualité de réception obtenue.', 'service', array['opposition', 'tactique', 'service'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire', 'avance'], 'service', 'Développer une intention tactique au service.', 12, 2, 6, array['ballons', 'filet'], 'medium', 4, 'Le serveur marque deux points sur un ace, un point sur une réception ratée, zéro sinon. Le réceptionneur marque un point par réception parfaite. Jouez en dix points, puis inversez les rôles.', array['Le serveur marque deux points sur un ace, un point sur une réception ratée, zéro sinon.', 'Le réceptionneur marque un point par réception parfaite.', 'Jouez en dix points, puis inversez les rôles.'], array['Observe les faiblesses du réceptionneur et exploite-les avec insistance.', 'Un service moyen bien placé rapporte plus qu''un service fort mal placé.', 'Adapte ta stratégie en cours de duel selon ce qui fonctionne.'], 'Servir toujours de la même façon quel que soit le résultat. Prendre trop de risques et multiplier les fautes.', array['Servir toujours de la même façon quel que soit le résultat.', 'Prendre trop de risques et multiplier les fautes.'], 'Observe les faiblesses du réceptionneur et exploite-les avec insistance. Un service moyen bien placé rapporte plus qu''un service fort mal placé. Adapte ta stratégie en cours de duel selon ce qui fonctionne.', array['Ajoutez une faute de service qui donne deux points au réceptionneur.'], array['Supprimez le barème et comptez simplement les réussites.'], false, true, 3, 4, array['service', 'opposition', 'tactique']),
  ('service_025', 'Service dans le temps réglementaire', 'Services exécutés dans les huit secondes réglementaires, pour intégrer la contrainte de match.', 'service', array['routine', 'gestion du temps', 'concentration'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire', 'avance'], 'service', 'Adapter sa routine à la contrainte de temps du match.', 8, 2, 6, array['ballons', 'filet', 'chronometre'], 'low', 2, 'Un partenaire déclenche le chronomètre au moment où tu reçois le ballon. Tu dois avoir servi avant huit secondes, routine complète comprise. 4 séries de 10 services.', array['Un partenaire déclenche le chronomètre au moment où tu reçois le ballon.', 'Tu dois avoir servi avant huit secondes, routine complète comprise.', '4 séries de 10 services.'], array['Une routine trop longue devient un risque en match : calibre-la.', 'Commence ta routine dès que tu as le ballon, sans temps mort.', 'Le temps disponible est largement suffisant si la routine est nette.'], 'Perdre du temps avant de commencer la routine. Précipiter le service en croyant manquer de temps.', array['Perdre du temps avant de commencer la routine.', 'Précipiter le service en croyant manquer de temps.'], 'Une routine trop longue devient un risque en match : calibre-la. Commence ta routine dès que tu as le ballon, sans temps mort. Le temps disponible est largement suffisant si la routine est nette.', array['Réduis le délai autorisé à six secondes.'], array['Allonge le délai à douze secondes.'], false, true, 1, 3, array['service', 'routine', 'reglement']),
  ('service_026', 'Zone annoncée au dernier moment', 'Le serveur découvre la zone à viser juste avant de lancer son ballon.', 'service', array['adaptation', 'précision', 'réactivité'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'avance', array['avance'], 'precision', 'Viser n''importe quelle zone sur information tardive.', 10, 2, 6, array['ballons', 'filet', 'plots'], 'medium', 4, 'Six zones sont numérotées dans le terrain adverse. Un partenaire annonce un numéro au moment où le serveur prend son ballon. 4 séries de 10 services, en comptant les zones atteintes.', array['Six zones sont numérotées dans le terrain adverse.', 'Un partenaire annonce un numéro au moment où le serveur prend son ballon.', '4 séries de 10 services, en comptant les zones atteintes.'], array['Réoriente tes appuis pendant ta routine, avant le lancer.', 'Ne modifie jamais ta trajectoire en cours de geste.', 'Garde la même routine malgré l''annonce tardive.'], 'Corriger la direction avec le bras au dernier moment. Perdre sa routine à cause de l''information tardive.', array['Corriger la direction avec le bras au dernier moment.', 'Perdre sa routine à cause de l''information tardive.'], 'Réoriente tes appuis pendant ta routine, avant le lancer. Ne modifie jamais ta trajectoire en cours de geste. Garde la même routine malgré l''annonce tardive.', array['L''annonce arrive après le lancer du ballon.'], array['L''annonce est donnée dix secondes avant le service.'], false, true, 2, 5, array['service', 'reactivite', 'precision']),
  ('service_027', 'Comptage des services gagnants', 'Suivi chiffré de l''efficacité du service sur une longue série, aces et réceptions ratées confondus.', 'service', array['évaluation', 'efficacité', 'service'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire', 'avance'], 'service', 'Mesurer objectivement l''efficacité de son service.', 12, 3, 8, array['ballons', 'filet'], 'medium', 4, 'Effectue 30 services face à une réception complète. Comptabilise aces, réceptions dégradées, réceptions parfaites et fautes. Compare tes chiffres d''une séance à l''autre.', array['Effectue 30 services face à une réception complète.', 'Comptabilise aces, réceptions dégradées, réceptions parfaites et fautes.', 'Compare tes chiffres d''une séance à l''autre.'], array['Un taux de fautes supérieur à vingt pour cent annule tout gain d''agressivité.', 'Les réceptions dégradées comptent : elles font gagner des points indirectement.', 'Cherche le meilleur rapport entre agressivité et fiabilité, pas l''ace à tout prix.'], 'Ne juger son service que sur le nombre d''aces. Ignorer son taux de fautes réel.', array['Ne juger son service que sur le nombre d''aces.', 'Ignorer son taux de fautes réel.'], 'Un taux de fautes supérieur à vingt pour cent annule tout gain d''agressivité. Les réceptions dégradées comptent : elles font gagner des points indirectement. Cherche le meilleur rapport entre agressivité et fiabilité, pas l''ace à tout prix.', array['Fixe-toi un objectif chiffré à battre à la séance suivante.'], array['Réduis la série à quinze services.'], false, true, 3, 4, array['service', 'evaluation', 'statistiques']),
  ('service_028', 'Service de sécurité assumé', 'Travail volontaire du service à risque réduit, à utiliser dans les moments de tension.', 'service', array['fiabilité', 'décision', 'gestion du risque'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire'], 'regularite', 'Disposer d''un service fiable pour les moments de tension.', 8, 1, 6, array['ballons', 'filet'], 'low', 2, 'Choisis une zone large et une puissance à soixante pour cent de ton maximum. Effectue 20 services dans ces conditions en visant zéro faute. Répète la série jusqu''à obtenir vingt réussites sur vingt.', array['Choisis une zone large et une puissance à soixante pour cent de ton maximum.', 'Effectue 20 services dans ces conditions en visant zéro faute.', 'Répète la série jusqu''à obtenir vingt réussites sur vingt.'], array['Un service de sécurité doit rester haut au-dessus du filet, avec une vraie marge.', 'Garde une trajectoire longue : un service mou et court est une invitation.', 'Ce service se travaille pour être disponible sous pression.'], 'Servir tellement mou que le ballon devient un cadeau pour l''adversaire. Mépriser cet exercice et le bâcler.', array['Servir tellement mou que le ballon devient un cadeau pour l''adversaire.', 'Mépriser cet exercice et le bâcler.'], 'Un service de sécurité doit rester haut au-dessus du filet, avec une vraie marge. Garde une trajectoire longue : un service mou et court est une invitation. Ce service se travaille pour être disponible sous pression.', array['Ajoute une contrainte de profondeur minimale.'], array['Réduis la série à dix services.'], true, true, 1, 3, array['service', 'securite', 'regularite']),
  ('service_029', 'Enchaînement service puis défense', 'Repli défensif immédiat après le service, comme l''exige une vraie situation de jeu.', 'service', array['enchaînement', 'replacement', 'service'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire', 'avance'], 'service', 'Enchaîner service et prise de position défensive.', 12, 4, 8, array['ballons', 'filet'], 'high', 4, 'Le joueur sert puis entre immédiatement sur le terrain pour prendre sa position défensive. Un ballon lui est envoyé trois secondes après son service. 4 séries de 8 enchaînements.', array['Le joueur sert puis entre immédiatement sur le terrain pour prendre sa position défensive.', 'Un ballon lui est envoyé trois secondes après son service.', '4 séries de 8 enchaînements.'], array['Entre sur le terrain dès que le ballon a quitté ta main.', 'Ne regarde pas ton service : ta position défensive compte davantage.', 'Arrive en position basse, prêt à défendre.'], 'Rester derrière la ligne à admirer son service. Entrer sur le terrain en marchant.', array['Rester derrière la ligne à admirer son service.', 'Entrer sur le terrain en marchant.'], 'Entre sur le terrain dès que le ballon a quitté ta main. Ne regarde pas ton service : ta position défensive compte davantage. Arrive en position basse, prêt à défendre.', array['Réduis le délai à deux secondes.'], array['Allonge le délai à cinq secondes.'], false, true, 4, 3, array['service', 'enchainement', 'defense']),
  ('service_030', 'Série de smashés à pleine intensité', 'Répétition de services smashés à intensité maximale pour développer la puissance spécifique.', 'service', array['puissance', 'service smashé', 'endurance'], array['outside_hitter', 'opposite', 'middle_blocker'], 'avance', array['avance'], 'service', 'Développer la puissance de service sans abîmer l''épaule.', 12, 1, 6, array['ballons', 'filet'], 'high', 5, 'Effectue cinq services smashés consécutifs à pleine intensité. Récupère deux minutes complètes entre chaque série. 4 séries au total, en arrêtant si la technique se dégrade.', array['Effectue cinq services smashés consécutifs à pleine intensité.', 'Récupère deux minutes complètes entre chaque série.', '4 séries au total, en arrêtant si la technique se dégrade.'], array['Arrête la série dès que ton élan ou ton armé se déforment.', 'Le volume reste faible volontairement : l''épaule est sollicitée fortement.', 'Échauffe complètement l''épaule avant de commencer.'], 'Enchaîner sans récupération et dégrader le geste. Multiplier les séries au-delà du raisonnable pour l''épaule.', array['Enchaîner sans récupération et dégrader le geste.', 'Multiplier les séries au-delà du raisonnable pour l''épaule.'], 'Arrête la série dès que ton élan ou ton armé se déforment. Le volume reste faible volontairement : l''épaule est sollicitée fortement. Échauffe complètement l''épaule avant de commencer.', array['Ajoute une contrainte de zone sur les deux derniers services de chaque série.'], array['Réduis à trois services par série.'], true, true, 5, 4, array['service', 'puissance', 'avance']),
  ('service_031', 'Alternance flottant et smashé', 'Changement de type de service à chaque ballon, pour empêcher la réception de prendre ses repères.', 'service', array['variété', 'adaptation', 'service'], array['outside_hitter', 'opposite', 'middle_blocker'], 'avance', array['avance'], 'service', 'Varier le type de service sans perdre en précision.', 10, 1, 6, array['ballons', 'filet'], 'high', 5, 'Alterne strictement un service flottant puis un service smashé. Les deux doivent atteindre la même zone du terrain adverse. 4 séries de 10 services.', array['Alterne strictement un service flottant puis un service smashé.', 'Les deux doivent atteindre la même zone du terrain adverse.', '4 séries de 10 services.'], array['Adopte la même position de départ pour les deux types de service.', 'Seuls le lancer et le contact changent réellement.', 'Cette alternance empêche le réceptionneur de se caler sur un rythme.'], 'Annoncer le type de service par une posture différente. Perdre la zone dès que le type de service change.', array['Annoncer le type de service par une posture différente.', 'Perdre la zone dès que le type de service change.'], 'Adopte la même position de départ pour les deux types de service. Seuls le lancer et le contact changent réellement. Cette alternance empêche le réceptionneur de se caler sur un rythme.', array['Choisis librement le type de service, sans alternance imposée.'], array['Travaille chaque type de service sur une série séparée.'], true, true, 4, 5, array['service', 'variete', 'avance']),
  ('service_032', 'Auto-observation du geste de service', 'Analyse de son propre service filmé ou observé par un partenaire, suivie d''une correction ciblée.', 'service', array['analyse', 'correction', 'technique'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire', 'avance'], 'service', 'Corriger méthodiquement un défaut de service.', 10, 2, 4, array['ballons', 'filet'], 'low', 3, 'Effectue dix services pendant qu''un partenaire observe uniquement ton lancer de balle. Identifie ensemble un seul défaut, puis effectue dix nouveaux services en le corrigeant. 3 cycles d''observation et de correction.', array['Effectue dix services pendant qu''un partenaire observe uniquement ton lancer de balle.', 'Identifie ensemble un seul défaut, puis effectue dix nouveaux services en le corrigeant.', '3 cycles d''observation et de correction.'], array['Ne corrige qu''un seul point à la fois : deux corrections simultanées ne fonctionnent pas.', 'Le lancer explique la majorité des irrégularités de service.', 'Vérifie le résultat sur dix services avant de changer d''objet de travail.'], 'Vouloir corriger le lancer, l''armé et la frappe en même temps. Juger la correction sur deux ou trois services seulement.', array['Vouloir corriger le lancer, l''armé et la frappe en même temps.', 'Juger la correction sur deux ou trois services seulement.'], 'Ne corrige qu''un seul point à la fois : deux corrections simultanées ne fonctionnent pas. Le lancer explique la majorité des irrégularités de service. Vérifie le résultat sur dix services avant de changer d''objet de travail.', array['Filme le geste pour une analyse plus précise.'], array['Limite l''observation au seul point de chute du lancer.'], false, true, 1, 4, array['service', 'analyse', 'correction']),
  ('service_033', 'Service en situation de match', 'Services intégrés à des points complets, avec toutes les contraintes de rythme et d''enjeu.', 'service', array['situation de jeu', 'décision', 'service'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire', 'avance'], 'competition', 'Servir avec intention dans un vrai contexte de match.', 15, 8, 12, array['ballons', 'filet'], 'high', 4, 'Jouez des sets courts en 15 points, chaque serveur annonçant sa zone visée avant de servir. Un observateur note si la zone annoncée a été atteinte. Jouez deux sets selon ces règles.', array['Jouez des sets courts en 15 points, chaque serveur annonçant sa zone visée avant de servir.', 'Un observateur note si la zone annoncée a été atteinte.', 'Jouez deux sets selon ces règles.'], array['Servir avec intention change tout : choisis ta zone avant chaque service.', 'Adapte ton agressivité au score et à la rotation adverse.', 'Une série de services sans faute fait basculer un set.'], 'Servir sans aucune intention tactique en match. Prendre les mêmes risques à 5-5 qu''à 24-20.', array['Servir sans aucune intention tactique en match.', 'Prendre les mêmes risques à 5-5 qu''à 24-20.'], 'Servir avec intention change tout : choisis ta zone avant chaque service. Adapte ton agressivité au score et à la rotation adverse. Une série de services sans faute fait basculer un set.', array['Supprimez l''annonce et demandez un bilan après le set.'], array['Autorisez une zone large plutôt qu''une cible précise.'], false, true, 4, 4, array['service', 'match', 'competition']),
  ('service_034', 'Six services, six zones', 'Parcours obligeant à toucher successivement les six zones du terrain adverse.', 'service', array['précision', 'variété', 'contrôle'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'avance', array['avance'], 'precision', 'Savoir servir précisément dans toutes les zones du terrain.', 12, 1, 6, array['ballons', 'filet', 'plots'], 'medium', 4, 'Les six zones du terrain adverse sont matérialisées et numérotées. Touche-les dans l''ordre, en reprenant à la zone 1 à chaque échec. L''exercice s''arrête au parcours complet ou après 40 services.', array['Les six zones du terrain adverse sont matérialisées et numérotées.', 'Touche-les dans l''ordre, en reprenant à la zone 1 à chaque échec.', 'L''exercice s''arrête au parcours complet ou après 40 services.'], array['Chaque zone demande une orientation de corps différente.', 'Prends le temps de te réorienter complètement entre deux services.', 'Les zones courtes sont souvent les plus difficiles : ne les néglige pas.'], 'Enchaîner sans se réorienter entre les zones. Bâcler les zones jugées faciles.', array['Enchaîner sans se réorienter entre les zones.', 'Bâcler les zones jugées faciles.'], 'Chaque zone demande une orientation de corps différente. Prends le temps de te réorienter complètement entre deux services. Les zones courtes sont souvent les plus difficiles : ne les néglige pas.', array['Effectue le parcours en sens inverse dans la foulée.'], array['Réduis le parcours à trois zones.'], true, true, 3, 5, array['service', 'precision', 'parcours']),
  ('service_035', 'Défi de séries gagnantes', 'Objectif collectif d''enchaîner des services agressifs sans faute sur une rotation complète.', 'service', array['régularité', 'agressivité', 'collectif'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'avance', array['avance'], 'competition', 'Tenir une exigence de service à l''échelle du collectif.', 12, 4, 8, array['ballons', 'filet'], 'medium', 4, 'Chaque joueur sert trois fois de suite, en visant une zone imposée. L''équipe compte le nombre total de services réussis sur la rotation complète. 3 tours complets, avec un objectif d''équipe à améliorer.', array['Chaque joueur sert trois fois de suite, en visant une zone imposée.', 'L''équipe compte le nombre total de services réussis sur la rotation complète.', '3 tours complets, avec un objectif d''équipe à améliorer.'], array['Le collectif pousse chacun à maintenir sa fiabilité.', 'Adapte ton niveau de risque à ta fiabilité réelle, pas à celle des autres.', 'Encouragez le joueur qui sert : la pression collective doit rester positive.'], 'Prendre des risques excessifs pour impressionner le groupe. Servir trop mou pour ne pas faire perdre l''équipe.', array['Prendre des risques excessifs pour impressionner le groupe.', 'Servir trop mou pour ne pas faire perdre l''équipe.'], 'Le collectif pousse chacun à maintenir sa fiabilité. Adapte ton niveau de risque à ta fiabilité réelle, pas à celle des autres. Encouragez le joueur qui sert : la pression collective doit rester positive.', array['Une faute annule tous les points de la rotation en cours.'], array['Chaque joueur ne sert que deux fois de suite.'], false, true, 3, 4, array['service', 'collectif', 'defi']),
  ('bloc_001', 'Position d''attente au filet', 'Construction de la posture de départ du bloqueur, mains hautes et appuis prêts.', 'bloc', array['posture', 'placement', 'disponibilité'], array['middle_blocker', 'outside_hitter', 'opposite'], 'debutant', array['debutant'], 'bloc', 'Adopter une position de bloc immédiatement disponible.', 6, 1, 8, array['filet'], 'low', 2, 'Place-toi à un bras du filet, pieds parallèles écartés à la largeur des épaules. Mains ouvertes à hauteur d''épaules, coudes fléchis devant la poitrine. Tiens la position vingt secondes puis effectue cinq sauts, 4 séries.', array['Place-toi à un bras du filet, pieds parallèles écartés à la largeur des épaules.', 'Mains ouvertes à hauteur d''épaules, coudes fléchis devant la poitrine.', 'Tiens la position vingt secondes puis effectue cinq sauts, 4 séries.'], array['Les mains restent hautes en permanence : les remonter coûte un temps décisif.', 'Reste à une distance d''un bras du filet pour pouvoir sauter sans le toucher.', 'Regarde par-dessus le filet, jamais le sol.'], 'Attendre les bras le long du corps. Se coller au filet et se retrouver gêné au saut.', array['Attendre les bras le long du corps.', 'Se coller au filet et se retrouver gêné au saut.'], 'Les mains restent hautes en permanence : les remonter coûte un temps décisif. Reste à une distance d''un bras du filet pour pouvoir sauter sans le toucher. Regarde par-dessus le filet, jamais le sol.', array['Ajoute des déplacements courts entre les tenues de position.'], array['Réduis la tenue à dix secondes.'], true, false, 2, 1, array['bloc', 'posture', 'debutant']),
  ('bloc_002', 'Placement des mains au-dessus du filet', 'Travail statique de l''orientation des mains et des doigts au moment du contact avec le ballon.', 'bloc', array['placement des mains', 'technique', 'orientation'], array['middle_blocker', 'outside_hitter', 'opposite'], 'debutant', array['debutant', 'intermediaire'], 'bloc', 'Orienter correctement mains et poignets au contact.', 6, 2, 6, array['ballons', 'filet'], 'low', 3, 'Un partenaire tient un ballon au-dessus du filet, côté adverse. Saute et place tes mains autour du ballon, doigts écartés et poignets orientés vers le bas. 3 séries de 10 répétitions.', array['Un partenaire tient un ballon au-dessus du filet, côté adverse.', 'Saute et place tes mains autour du ballon, doigts écartés et poignets orientés vers le bas.', '3 séries de 10 répétitions.'], array['Doigts écartés et fermes, pouces vers le haut.', 'Les poignets cassent vers le bas pour renvoyer le ballon dans le terrain adverse.', 'Les mains forment un toit au-dessus du ballon, pas un mur devant lui.'], 'Doigts serrés et mous, le ballon traverse le bloc. Poignets orientés vers le haut, ce qui renvoie le ballon au plafond.', array['Doigts serrés et mous, le ballon traverse le bloc.', 'Poignets orientés vers le haut, ce qui renvoie le ballon au plafond.'], 'Doigts écartés et fermes, pouces vers le haut. Les poignets cassent vers le bas pour renvoyer le ballon dans le terrain adverse. Les mains forment un toit au-dessus du ballon, pas un mur devant lui.', array['Le partenaire déplace le ballon juste avant le saut.'], array['Travaille le placement des mains debout, sans saut.'], false, true, 3, 3, array['bloc', 'technique', 'mains']),
  ('bloc_003', 'Saut de bloc sur place', 'Répétition du saut vertical de bloc avec pénétration des bras au-dessus du filet.', 'bloc', array['saut', 'pénétration', 'gainage'], array['middle_blocker', 'outside_hitter', 'opposite'], 'debutant', array['debutant', 'intermediaire'], 'bloc', 'Sauter haut et pénétrer le plan du filet en sécurité.', 8, 1, 8, array['filet'], 'high', 4, 'Depuis la position d''attente, fléchis les jambes et saute verticalement. Pousse les bras et les épaules au-delà du plan du filet, sans le toucher. 4 séries de 8 sauts, avec une minute de récupération.', array['Depuis la position d''attente, fléchis les jambes et saute verticalement.', 'Pousse les bras et les épaules au-delà du plan du filet, sans le toucher.', '4 séries de 8 sauts, avec une minute de récupération.'], array['Saute strictement vers le haut, jamais vers le filet.', 'Les épaules montent plus haut que le filet : c''est ce qui fait pénétrer les mains.', 'Retombe sur les deux pieds au même endroit que ton départ.'], 'Se déporter vers le filet en sautant et commettre une faute. Monter les bras sans engager les épaules.', array['Se déporter vers le filet en sautant et commettre une faute.', 'Monter les bras sans engager les épaules.'], 'Saute strictement vers le haut, jamais vers le filet. Les épaules montent plus haut que le filet : c''est ce qui fait pénétrer les mains. Retombe sur les deux pieds au même endroit que ton départ.', array['Enchaîne deux sauts consécutifs sans temps mort.'], array['Saute à soixante-dix pour cent d''intensité.'], true, false, 4, 3, array['bloc', 'saut', 'technique']),
  ('bloc_004', 'Timing sur l''attaquant', 'Réglage du moment du saut pour que les mains arrivent juste après celles de l''attaquant.', 'bloc', array['timing', 'lecture', 'saut'], array['middle_blocker', 'outside_hitter', 'opposite'], 'intermediaire', array['intermediaire'], 'bloc', 'Régler son saut sur celui de l''attaquant.', 10, 3, 6, array['ballons', 'filet'], 'high', 4, 'Un attaquant frappe sur passe haute en zone 4. Le bloqueur saute légèrement après lui, de façon à être au sommet au moment de la frappe. 4 séries de 8 blocs.', array['Un attaquant frappe sur passe haute en zone 4.', 'Le bloqueur saute légèrement après lui, de façon à être au sommet au moment de la frappe.', '4 séries de 8 blocs.'], array['Sur passe haute, attends que l''attaquant quitte le sol avant de sauter.', 'Tes mains doivent franchir le filet juste après les siennes.', 'Mieux vaut sauter un peu tard qu''un peu tôt.'], 'Sauter en même temps que l''attaquant et redescendre avant la frappe. Sauter dès que la passe part.', array['Sauter en même temps que l''attaquant et redescendre avant la frappe.', 'Sauter dès que la passe part.'], 'Sur passe haute, attends que l''attaquant quitte le sol avant de sauter. Tes mains doivent franchir le filet juste après les siennes. Mieux vaut sauter un peu tard qu''un peu tôt.', array['L''attaquant varie la hauteur de passe et donc le timing.'], array['L''attaquant annonce le moment de sa frappe à voix haute.'], false, true, 4, 4, array['bloc', 'timing', 'lecture']),
  ('bloc_005', 'Déplacement en pas chassés', 'Déplacement latéral court le long du filet, en conservant les épaules parallèles à celui-ci.', 'bloc', array['déplacement latéral', 'appuis', 'équilibre'], array['middle_blocker', 'outside_hitter', 'opposite'], 'debutant', array['debutant', 'intermediaire'], 'bloc', 'Se déplacer latéralement sans perdre l''orientation au filet.', 8, 1, 8, array['filet', 'plots'], 'medium', 4, 'Deux plots sont posés à deux mètres d''écart le long du filet. Déplace-toi d''un plot à l''autre en pas chassés puis effectue un saut de bloc. 4 séries de 8 allers-retours.', array['Deux plots sont posés à deux mètres d''écart le long du filet.', 'Déplace-toi d''un plot à l''autre en pas chassés puis effectue un saut de bloc.', '4 séries de 8 allers-retours.'], array['Les épaules restent parallèles au filet pendant tout le déplacement.', 'Les pieds ne se croisent jamais sur cette distance courte.', 'Termine par un appui d''arrêt franc avant de sauter.'], 'Tourner les épaules et perdre le filet de vue. Sauter en plein déplacement latéral, ce qui dévie le bloc.', array['Tourner les épaules et perdre le filet de vue.', 'Sauter en plein déplacement latéral, ce qui dévie le bloc.'], 'Les épaules restent parallèles au filet pendant tout le déplacement. Les pieds ne se croisent jamais sur cette distance courte. Termine par un appui d''arrêt franc avant de sauter.', array['Réduis le temps disponible pour rejoindre le plot.'], array['Rapproche les plots à un mètre.'], true, false, 4, 3, array['bloc', 'deplacement', 'appuis']),
  ('bloc_006', 'Déplacement en pas croisés', 'Traversée rapide du filet en pas croisés, technique du central pour rejoindre une aile.', 'bloc', array['déplacement', 'vitesse', 'coordination'], array['middle_blocker'], 'intermediaire', array['intermediaire', 'avance'], 'bloc', 'Rejoindre rapidement l''antenne et sauter face au filet.', 10, 1, 6, array['filet', 'plots'], 'high', 5, 'Pars du centre du filet et rejoins l''antenne en trois appuis : ouverture, croisé, appui d''arrêt. Termine par un saut de bloc face au filet. 4 séries de 6 déplacements de chaque côté.', array['Pars du centre du filet et rejoins l''antenne en trois appuis : ouverture, croisé, appui d''arrêt.', 'Termine par un saut de bloc face au filet.', '4 séries de 6 déplacements de chaque côté.'], array['Le premier appui ouvre le bassin dans la direction visée.', 'Le pas croisé couvre la distance, le dernier appui te remet face au filet.', 'Reviens face au filet avant de sauter, jamais de profil.'], 'Sauter encore de profil, ce qui laisse une ouverture dans le bloc. Utiliser des pas chassés sur une distance trop longue et arriver en retard.', array['Sauter encore de profil, ce qui laisse une ouverture dans le bloc.', 'Utiliser des pas chassés sur une distance trop longue et arriver en retard.'], 'Le premier appui ouvre le bassin dans la direction visée. Le pas croisé couvre la distance, le dernier appui te remet face au filet. Reviens face au filet avant de sauter, jamais de profil.', array['Ajoute un ballon réellement attaqué à l''antenne.'], array['Réduis la distance à parcourir de moitié.'], true, false, 5, 4, array['bloc', 'central', 'deplacement']),
  ('bloc_007', 'Bloc individuel sur attaque annoncée', 'Premier bloc réel face à un attaquant qui annonce sa direction avant de frapper.', 'bloc', array['bloc individuel', 'placement', 'timing'], array['middle_blocker', 'outside_hitter', 'opposite'], 'debutant', array['debutant'], 'bloc', 'Réussir un bloc placé sur une direction connue.', 10, 2, 6, array['ballons', 'filet'], 'medium', 3, 'L''attaquant annonce la direction de sa frappe avant de sauter. Le bloqueur se place dans cette direction et saute au bon moment. 4 séries de 8 blocs.', array['L''attaquant annonce la direction de sa frappe avant de sauter.', 'Le bloqueur se place dans cette direction et saute au bon moment.', '4 séries de 8 blocs.'], array['Place-toi face au ballon, pas face à l''attaquant.', 'Un bloc bien placé n''a pas besoin d''être haut pour être efficace.', 'Garde les mains fermes au contact, ne les relâche pas.'], 'Se placer au centre du filet par défaut, sans tenir compte de l''annonce. Reculer au moment du contact par appréhension.', array['Se placer au centre du filet par défaut, sans tenir compte de l''annonce.', 'Reculer au moment du contact par appréhension.'], 'Place-toi face au ballon, pas face à l''attaquant. Un bloc bien placé n''a pas besoin d''être haut pour être efficace. Garde les mains fermes au contact, ne les relâche pas.', array['L''attaquant n''annonce plus qu''une fois sur deux.'], array['L''attaquant frappe sans saut, depuis le sol.'], false, true, 3, 3, array['bloc', 'debutant', 'individuel']),
  ('bloc_008', 'Fermeture de la ligne', 'Positionnement du bloc extérieur pour supprimer la frappe le long de la ligne.', 'bloc', array['bloc individuel', 'placement', 'coordination défensive'], array['outside_hitter', 'opposite'], 'intermediaire', array['intermediaire'], 'bloc', 'Fermer la ligne de façon fiable et lisible pour la défense.', 10, 3, 8, array['ballons', 'filet'], 'high', 4, 'Le bloqueur extérieur se place de manière à couvrir totalement la ligne. L''attaquant tente la ligne à chaque ballon, puis la diagonale une fois sur trois. 4 séries de 9 attaques.', array['Le bloqueur extérieur se place de manière à couvrir totalement la ligne.', 'L''attaquant tente la ligne à chaque ballon, puis la diagonale une fois sur trois.', '4 séries de 9 attaques.'], array['Ta main extérieure doit se trouver dans le prolongement de la ligne latérale.', 'Ferme la ligne et laisse la diagonale à la défense : c''est le contrat.', 'Ne dérive jamais vers l''intérieur, même si l''attaquant croise.'], 'Se décaler vers le centre et rouvrir la ligne. Vouloir tout bloquer et ne rien fermer réellement.', array['Se décaler vers le centre et rouvrir la ligne.', 'Vouloir tout bloquer et ne rien fermer réellement.'], 'Ta main extérieure doit se trouver dans le prolongement de la ligne latérale. Ferme la ligne et laisse la diagonale à la défense : c''est le contrat. Ne dérive jamais vers l''intérieur, même si l''attaquant croise.', array['Ajoute un second bloqueur pour former un double bloc.'], array['L''attaquant ne frappe que dans la ligne.'], false, true, 4, 4, array['bloc', 'ligne', 'collectif']),
  ('bloc_009', 'Fermeture de la diagonale', 'Positionnement du bloc pour supprimer l''angle croisé, l''attaque statistiquement la plus fréquente.', 'bloc', array['bloc individuel', 'placement', 'lecture'], array['middle_blocker', 'outside_hitter', 'opposite'], 'intermediaire', array['intermediaire', 'avance'], 'bloc', 'Supprimer l''angle croisé de façon cohérente avec la défense.', 10, 3, 8, array['ballons', 'filet'], 'high', 4, 'Le bloqueur se décale vers l''intérieur pour couvrir l''angle croisé. L''attaquant frappe librement, la défense couvre la ligne laissée ouverte. 4 séries de 9 attaques.', array['Le bloqueur se décale vers l''intérieur pour couvrir l''angle croisé.', 'L''attaquant frappe librement, la défense couvre la ligne laissée ouverte.', '4 séries de 9 attaques.'], array['Positionne-toi sur l''épaule frappeuse de l''attaquant pour couvrir le croisé.', 'Annonce clairement à la défense que tu fermes la diagonale.', 'Conserve ta position même si l''attaquant feinte vers la ligne.'], 'Suivre le ballon et changer de direction fermée en plein vol. Fermer la diagonale sans prévenir les défenseurs.', array['Suivre le ballon et changer de direction fermée en plein vol.', 'Fermer la diagonale sans prévenir les défenseurs.'], 'Positionne-toi sur l''épaule frappeuse de l''attaquant pour couvrir le croisé. Annonce clairement à la défense que tu fermes la diagonale. Conserve ta position même si l''attaquant feinte vers la ligne.', array['Le bloc change de consigne d''une attaque à l''autre.'], array['L''attaquant ne frappe qu''en diagonale.'], false, true, 4, 4, array['bloc', 'diagonale', 'collectif']),
  ('bloc_010', 'Double bloc coordonné', 'Formation d''un mur à deux bloqueurs, sans espace entre les mains.', 'bloc', array['coordination', 'bloc collectif', 'timing'], array['middle_blocker', 'outside_hitter', 'opposite'], 'intermediaire', array['intermediaire', 'avance'], 'bloc', 'Former un double bloc sans espace exploitable.', 12, 4, 8, array['ballons', 'filet'], 'high', 4, 'Le bloqueur extérieur fixe la position, le central vient le rejoindre. Les quatre mains doivent former une surface continue, sans trou au milieu. 4 séries de 8 attaques bloquées à deux.', array['Le bloqueur extérieur fixe la position, le central vient le rejoindre.', 'Les quatre mains doivent former une surface continue, sans trou au milieu.', '4 séries de 8 attaques bloquées à deux.'], array['Le bloqueur extérieur ne bouge pas : c''est le central qui s''ajuste à lui.', 'Les mains intérieures des deux bloqueurs se touchent presque.', 'Sautez ensemble : un décalage crée un trou immédiatement exploitable.'], 'Laisser un espace entre les deux bloqueurs. Le bloqueur extérieur qui se déplace vers le central au lieu de l''inverse.', array['Laisser un espace entre les deux bloqueurs.', 'Le bloqueur extérieur qui se déplace vers le central au lieu de l''inverse.'], 'Le bloqueur extérieur ne bouge pas : c''est le central qui s''ajuste à lui. Les mains intérieures des deux bloqueurs se touchent presque. Sautez ensemble : un décalage crée un trou immédiatement exploitable.', array['Le passeur adverse varie la zone d''attaque sans prévenir.'], array['Les deux bloqueurs partent déjà côte à côte.'], false, true, 4, 4, array['bloc', 'collectif', 'coordination']),
  ('bloc_011', 'Triple bloc sur attaque centrale', 'Regroupement des trois bloqueurs face à une attaque au centre du filet.', 'bloc', array['bloc collectif', 'coordination', 'déplacement'], array['middle_blocker', 'outside_hitter', 'opposite'], 'avance', array['avance'], 'bloc', 'Constituer un triple bloc sur une attaque centrale.', 12, 5, 10, array['ballons', 'filet'], 'high', 5, 'Les deux ailiers rejoignent le central sur une attaque en zone 3. Les trois bloqueurs sautent ensemble en formant un mur continu. 4 séries de 6 triples blocs.', array['Les deux ailiers rejoignent le central sur une attaque en zone 3.', 'Les trois bloqueurs sautent ensemble en formant un mur continu.', '4 séries de 6 triples blocs.'], array['Le central est le repère fixe : les ailiers viennent à lui.', 'Le déplacement des ailiers se fait en pas croisés pour gagner du temps.', 'Si un ailier ne peut pas arriver à temps, il reste en place plutôt que de sauter en retard.'], 'Un ailier qui saute en retard et ouvre un trou dans le mur. Les trois bloqueurs qui arrivent décalés en hauteur.', array['Un ailier qui saute en retard et ouvre un trou dans le mur.', 'Les trois bloqueurs qui arrivent décalés en hauteur.'], 'Le central est le repère fixe : les ailiers viennent à lui. Le déplacement des ailiers se fait en pas croisés pour gagner du temps. Si un ailier ne peut pas arriver à temps, il reste en place plutôt que de sauter en retard.', array['Le passeur adverse feinte la rapide avant de distribuer à l''aile.'], array['Deux bloqueurs seulement se regroupent.'], false, true, 5, 4, array['bloc', 'collectif', 'avance']),
  ('bloc_012', 'Lecture du passeur adverse', 'Anticipation de la zone d''attaque à partir de la position et du geste du passeur adverse.', 'bloc', array['lecture', 'anticipation', 'prise d''information'], array['middle_blocker'], 'avance', array['avance'], 'bloc', 'Partir au bloc sur la lecture du passeur adverse.', 12, 5, 10, array['ballons', 'filet'], 'medium', 5, 'Le central annonce à voix haute la destination de la passe dès qu''il la lit. Le passeur adverse distribue librement entre les trois zones. 4 séries de 10 ballons, en comptant les lectures justes.', array['Le central annonce à voix haute la destination de la passe dès qu''il la lit.', 'Le passeur adverse distribue librement entre les trois zones.', '4 séries de 10 ballons, en comptant les lectures justes.'], array['Un passeur légèrement cambré prépare le plus souvent une passe arrière.', 'La position du ballon par rapport au front annonce la direction.', 'Regarde le passeur, pas l''attaquant : c''est lui qui décide.'], 'Suivre le ballon des yeux au lieu d''observer le passeur. Attendre de voir la passe partir pour se déplacer.', array['Suivre le ballon des yeux au lieu d''observer le passeur.', 'Attendre de voir la passe partir pour se déplacer.'], 'Un passeur légèrement cambré prépare le plus souvent une passe arrière. La position du ballon par rapport au front annonce la direction. Regarde le passeur, pas l''attaquant : c''est lui qui décide.', array['Le passeur adverse travaille volontairement la dissimulation.'], array['Le passeur annonce sa destination avant de toucher le ballon.'], false, true, 4, 5, array['bloc', 'lecture', 'central', 'avance']),
  ('bloc_013', 'Lecture de l''armé adverse', 'Ajustement du bloc en fonction de l''orientation du bras et des épaules de l''attaquant.', 'bloc', array['lecture', 'ajustement', 'réaction'], array['middle_blocker', 'outside_hitter', 'opposite'], 'avance', array['avance'], 'bloc', 'Ajuster son bloc à la lecture de l''armé adverse.', 10, 3, 8, array['ballons', 'filet'], 'high', 5, 'L''attaquant choisit librement sa direction sans l''annoncer. Le bloqueur ajuste la position de ses mains en l''air selon ce qu''il lit à l''armé. 4 séries de 8 attaques.', array['L''attaquant choisit librement sa direction sans l''annoncer.', 'Le bloqueur ajuste la position de ses mains en l''air selon ce qu''il lit à l''armé.', '4 séries de 8 attaques.'], array['L''épaule non frappeuse pointe presque toujours vers la direction visée.', 'L''ajustement en l''air se fait avec les mains, jamais avec tout le corps.', 'Un attaquant en retard sous le ballon frappe rarement fort : garde les mains hautes.'], 'Sauter avec les mains figées dans une position décidée à l''avance. Tourner tout le corps en l''air et perdre l''équilibre.', array['Sauter avec les mains figées dans une position décidée à l''avance.', 'Tourner tout le corps en l''air et perdre l''équilibre.'], 'L''épaule non frappeuse pointe presque toujours vers la direction visée. L''ajustement en l''air se fait avec les mains, jamais avec tout le corps. Un attaquant en retard sous le ballon frappe rarement fort : garde les mains hautes.', array['L''attaquant ajoute des feintes d''orientation.'], array['L''attaquant marque un temps d''arrêt visible à l''armé.'], false, true, 4, 5, array['bloc', 'lecture', 'avance']),
  ('bloc_014', 'Bloc sur attaque rapide', 'Bloc individuel du central face à une attaque rapide, où le temps de réaction est minimal.', 'bloc', array['réaction', 'timing rapide', 'bloc individuel'], array['middle_blocker'], 'avance', array['avance'], 'bloc', 'Bloquer une attaque rapide malgré le temps très court.', 12, 4, 8, array['ballons', 'filet'], 'high', 5, 'Le central adverse attaque uniquement en rapide au centre du filet. Le bloqueur central saute presque en même temps que lui. 4 séries de 8 blocs.', array['Le central adverse attaque uniquement en rapide au centre du filet.', 'Le bloqueur central saute presque en même temps que lui.', '4 séries de 8 blocs.'], array['Sur une rapide, tu sautes avec l''attaquant, pas après lui.', 'Reste face au ballon, il n''y a pas le temps de se déplacer.', 'Garde les mains déjà hautes : les monter coûterait le ballon.'], 'Appliquer le timing d''une passe haute et sauter trop tard. Quitter la rapide des yeux pour regarder les ailes.', array['Appliquer le timing d''une passe haute et sauter trop tard.', 'Quitter la rapide des yeux pour regarder les ailes.'], 'Sur une rapide, tu sautes avec l''attaquant, pas après lui. Reste face au ballon, il n''y a pas le temps de se déplacer. Garde les mains déjà hautes : les monter coûterait le ballon.', array['Le passeur alterne rapide et passe extérieure sans prévenir.'], array['La rapide est annoncée avant chaque ballon.'], false, true, 5, 5, array['bloc', 'rapide', 'central', 'avance']),
  ('bloc_015', 'Bloc sur attaque arrière', 'Bloc face à une attaque venue du fond de court, avec un timing plus tardif et une trajectoire longue.', 'bloc', array['timing', 'adaptation', 'bloc collectif'], array['middle_blocker', 'outside_hitter', 'opposite'], 'avance', array['avance'], 'bloc', 'Adapter le timing du bloc à une attaque de fond de court.', 10, 4, 8, array['ballons', 'filet'], 'high', 4, 'L''attaquant adverse frappe depuis la zone arrière, derrière la ligne des trois mètres. Le bloc ajuste son timing, plus tardif que sur une attaque au filet. 4 séries de 8 blocs.', array['L''attaquant adverse frappe depuis la zone arrière, derrière la ligne des trois mètres.', 'Le bloc ajuste son timing, plus tardif que sur une attaque au filet.', '4 séries de 8 blocs.'], array['Une attaque arrière arrive plus tard : retarde ton saut en conséquence.', 'La trajectoire est plus tendue : le bloc sert surtout à orienter vers la défense.', 'Ne cherche pas le contre direct, cherche à réduire l''angle.'], 'Sauter au même moment que sur une attaque au filet et redescendre trop tôt. Chercher le contre gagnant sur un ballon venu de loin.', array['Sauter au même moment que sur une attaque au filet et redescendre trop tôt.', 'Chercher le contre gagnant sur un ballon venu de loin.'], 'Une attaque arrière arrive plus tard : retarde ton saut en conséquence. La trajectoire est plus tendue : le bloc sert surtout à orienter vers la défense. Ne cherche pas le contre direct, cherche à réduire l''angle.', array['L''adversaire alterne attaque arrière et attaque au filet.'], array['L''attaquant arrière annonce sa frappe.'], false, true, 4, 4, array['bloc', 'arriere', 'timing']),
  ('bloc_016', 'Renoncer au saut sur ballon travaillé', 'Apprentissage de la décision de ne pas sauter quand l''attaque n''est pas une frappe puissante.', 'bloc', array['décision', 'lecture', 'couverture'], array['middle_blocker', 'outside_hitter', 'opposite'], 'intermediaire', array['intermediaire', 'avance'], 'bloc', 'Choisir de sauter ou non selon le type d''attaque.', 10, 3, 8, array['ballons', 'filet'], 'medium', 4, 'L''attaquant alterne frappe puissante et ballon déposé derrière le bloc. Le bloqueur saute uniquement sur les vraies frappes et reste au sol sur les ballons travaillés. 4 séries de 10 attaques.', array['L''attaquant alterne frappe puissante et ballon déposé derrière le bloc.', 'Le bloqueur saute uniquement sur les vraies frappes et reste au sol sur les ballons travaillés.', '4 séries de 10 attaques.'], array['Un attaquant qui ralentit son bras prépare presque toujours un ballon placé.', 'Rester au sol te permet de couvrir la zone courte derrière toi.', 'Décide avant de quitter le sol : en l''air, il est trop tard.'], 'Sauter systématiquement par réflexe. Rester au sol sur une vraie frappe par excès de prudence.', array['Sauter systématiquement par réflexe.', 'Rester au sol sur une vraie frappe par excès de prudence.'], 'Un attaquant qui ralentit son bras prépare presque toujours un ballon placé. Rester au sol te permet de couvrir la zone courte derrière toi. Décide avant de quitter le sol : en l''air, il est trop tard.', array['L''attaquant masque mieux son intention.'], array['L''attaquant annonce le type d''attaque avant de sauter.'], false, true, 3, 5, array['bloc', 'decision', 'lecture']),
  ('bloc_017', 'Retombée équilibrée après le contre', 'Travail de la réception au sol après un saut de bloc, pour protéger les articulations et repartir vite.', 'bloc', array['réception au sol', 'équilibre', 'prévention'], array['middle_blocker', 'outside_hitter', 'opposite'], 'debutant', array['debutant', 'intermediaire'], 'bloc', 'Sécuriser la retombée du bloc et repartir immédiatement.', 8, 1, 8, array['filet'], 'medium', 3, 'Effectue un saut de bloc et concentre-toi uniquement sur ta retombée. Retombe sur les deux pieds, genoux fléchis, et enchaîne immédiatement un pas vers l''arrière. 4 séries de 8 sauts.', array['Effectue un saut de bloc et concentre-toi uniquement sur ta retombée.', 'Retombe sur les deux pieds, genoux fléchis, et enchaîne immédiatement un pas vers l''arrière.', '4 séries de 8 sauts.'], array['Retombe sur l''avant des pieds puis déroule vers le talon.', 'Genoux fléchis et alignés avec les pieds à l''amorti.', 'Ta retombée est le début de ton action suivante, pas la fin du bloc.'], 'Retomber jambes tendues, ce qui expose genoux et chevilles. Retomber sur un seul pied ou en déséquilibre vers le filet.', array['Retomber jambes tendues, ce qui expose genoux et chevilles.', 'Retomber sur un seul pied ou en déséquilibre vers le filet.'], 'Retombe sur l''avant des pieds puis déroule vers le talon. Genoux fléchis et alignés avec les pieds à l''amorti. Ta retombée est le début de ton action suivante, pas la fin du bloc.', array['Enchaîne un déplacement défensif immédiat après la retombée.'], array['Réduis la hauteur du saut à soixante-dix pour cent.'], true, false, 3, 3, array['bloc', 'prevention', 'technique']),
  ('bloc_018', 'Enchaînement de sauts au filet', 'Répétition de sauts de bloc rapprochés, pour tenir l''intensité sur un échange long.', 'bloc', array['endurance', 'détente répétée', 'gainage'], array['middle_blocker', 'outside_hitter', 'opposite'], 'intermediaire', array['intermediaire', 'avance'], 'detente', 'Tenir une série de sauts de bloc sans perdre en qualité.', 10, 1, 8, array['filet'], 'high', 4, 'Effectue cinq sauts de bloc consécutifs, sans pause entre chacun. Conserve la même hauteur et la même qualité de pénétration sur les cinq. 4 séries, avec deux minutes de récupération complète.', array['Effectue cinq sauts de bloc consécutifs, sans pause entre chacun.', 'Conserve la même hauteur et la même qualité de pénétration sur les cinq.', '4 séries, avec deux minutes de récupération complète.'], array['Amortis chaque retombée : c''est elle qui prépare le saut suivant.', 'Si la hauteur chute nettement, arrête la série.', 'Garde les mains hautes entre les sauts plutôt que de les baisser.'], 'Réduire l''amplitude dès le troisième saut. Enchaîner sans amortir et fatiguer inutilement les genoux.', array['Réduire l''amplitude dès le troisième saut.', 'Enchaîner sans amortir et fatiguer inutilement les genoux.'], 'Amortis chaque retombée : c''est elle qui prépare le saut suivant. Si la hauteur chute nettement, arrête la série. Garde les mains hautes entre les sauts plutôt que de les baisser.', array['Passe à sept sauts consécutifs.'], array['Réduis à trois sauts par série.'], true, false, 5, 2, array['bloc', 'endurance', 'detente']),
  ('bloc_019', 'Bloc face à un attaquant gaucher', 'Adaptation du placement face à un gaucher, dont les angles sont inversés.', 'bloc', array['adaptation', 'placement', 'lecture'], array['middle_blocker', 'outside_hitter', 'opposite'], 'avance', array['avance'], 'bloc', 'Adapter son bloc au profil d''un attaquant gaucher.', 10, 3, 8, array['ballons', 'filet'], 'high', 5, 'Un attaquant gaucher frappe depuis la zone 2 et la zone 4. Le bloqueur ajuste son placement aux angles inversés de ce profil. 4 séries de 8 attaques.', array['Un attaquant gaucher frappe depuis la zone 2 et la zone 4.', 'Le bloqueur ajuste son placement aux angles inversés de ce profil.', '4 séries de 8 attaques.'], array['Un gaucher en zone 4 ouvre naturellement la ligne, contrairement à un droitier.', 'Positionne-toi par rapport à son épaule frappeuse, pas par habitude.', 'Annonce à l''équipe que l''attaquant est gaucher avant le point.'], 'Reproduire le placement utilisé contre un droitier. Oublier l''information en cours de set.', array['Reproduire le placement utilisé contre un droitier.', 'Oublier l''information en cours de set.'], 'Un gaucher en zone 4 ouvre naturellement la ligne, contrairement à un droitier. Positionne-toi par rapport à son épaule frappeuse, pas par habitude. Annonce à l''équipe que l''attaquant est gaucher avant le point.', array['Alternez attaquants droitier et gaucher dans la même série.'], array['L''attaquant gaucher ne frappe que d''une seule zone.'], false, true, 4, 5, array['bloc', 'adaptation', 'avance']),
  ('bloc_020', 'Bloc sans toucher le filet', 'Série de blocs avec sanction immédiate à la moindre faute de filet.', 'bloc', array['contrôle', 'discipline technique', 'saut'], array['middle_blocker', 'outside_hitter', 'opposite'], 'intermediaire', array['intermediaire'], 'bloc', 'Bloquer efficacement sans jamais toucher le filet.', 10, 2, 8, array['ballons', 'filet'], 'high', 4, 'Un observateur surveille uniquement les contacts avec le filet. Toute faute de filet annule la série en cours, qui doit être reprise. Objectif : 12 blocs consécutifs sans aucun contact.', array['Un observateur surveille uniquement les contacts avec le filet.', 'Toute faute de filet annule la série en cours, qui doit être reprise.', 'Objectif : 12 blocs consécutifs sans aucun contact.'], array['Saute strictement à la verticale, la faute vient presque toujours d''un saut vers l''avant.', 'Redescends les bras le long du filet, sans les ramener vers toi trop vite.', 'Garde une distance d''un bras avant de sauter.'], 'Sauter vers le filet pour gagner en pénétration. Redescendre les bras en les rabattant contre le filet.', array['Sauter vers le filet pour gagner en pénétration.', 'Redescendre les bras en les rabattant contre le filet.'], 'Saute strictement à la verticale, la faute vient presque toujours d''un saut vers l''avant. Redescends les bras le long du filet, sans les ramener vers toi trop vite. Garde une distance d''un bras avant de sauter.', array['Porte l''objectif à vingt blocs consécutifs.'], array['Abaisse l''objectif à six blocs.'], false, true, 4, 4, array['bloc', 'reglement', 'technique']),
  ('bloc_021', 'Transition entre bloc et défense', 'Repli défensif immédiat lorsque le bloc ne touche pas le ballon.', 'bloc', array['transition', 'réaction', 'couverture'], array['middle_blocker', 'outside_hitter', 'opposite'], 'intermediaire', array['intermediaire', 'avance'], 'bloc', 'Enchaîner bloc et intervention défensive sans temps mort.', 10, 3, 8, array['ballons', 'filet'], 'high', 4, 'Le bloqueur saute, l''attaquant frappe volontairement à côté du bloc. Le bloqueur retombe, fait demi-tour et récupère le ballon suivant déposé derrière lui. 4 séries de 8 enchaînements.', array['Le bloqueur saute, l''attaquant frappe volontairement à côté du bloc.', 'Le bloqueur retombe, fait demi-tour et récupère le ballon suivant déposé derrière lui.', '4 séries de 8 enchaînements.'], array['Fais demi-tour dès la retombée, sans regarder le résultat de ton bloc.', 'Reste bas après la retombée pour pouvoir intervenir vite.', 'La zone courte derrière le bloc est ta responsabilité.'], 'Rester tourné vers le filet après le saut. Se redresser complètement avant de chercher le ballon.', array['Rester tourné vers le filet après le saut.', 'Se redresser complètement avant de chercher le ballon.'], 'Fais demi-tour dès la retombée, sans regarder le résultat de ton bloc. Reste bas après la retombée pour pouvoir intervenir vite. La zone courte derrière le bloc est ta responsabilité.', array['Le ballon suivant est envoyé dans une direction imprévisible.'], array['Allonge le délai avant l''envoi du second ballon.'], false, true, 5, 3, array['bloc', 'transition', 'defense']),
  ('bloc_022', 'Bloc contre combinaison adverse', 'Bloc face à une attaque construite avec feinte du central, exigeant de ne pas se laisser fixer.', 'bloc', array['lecture', 'sang-froid', 'bloc collectif'], array['middle_blocker', 'outside_hitter', 'opposite'], 'avance', array['avance'], 'bloc', 'Ne pas se faire fixer par une feinte offensive.', 12, 6, 10, array['ballons', 'filet'], 'high', 5, 'L''équipe adverse utilise systématiquement une feinte d''appel du central. Le bloc doit rester disponible pour l''attaque réellement servie. 4 séries de 8 combinaisons.', array['L''équipe adverse utilise systématiquement une feinte d''appel du central.', 'Le bloc doit rester disponible pour l''attaque réellement servie.', '4 séries de 8 combinaisons.'], array['Suis le ballon, pas l''appel : seule la passe dit la vérité.', 'Le central bloqueur reste disponible plutôt que de sauter sur la feinte.', 'Accepte de bloquer à un seul joueur plutôt que de sauter à contretemps.'], 'Sauter sur l''appel du central et laisser l''aile totalement libre. Rester immobile par peur de la feinte et arriver en retard partout.', array['Sauter sur l''appel du central et laisser l''aile totalement libre.', 'Rester immobile par peur de la feinte et arriver en retard partout.'], 'Suis le ballon, pas l''appel : seule la passe dit la vérité. Le central bloqueur reste disponible plutôt que de sauter sur la feinte. Accepte de bloquer à un seul joueur plutôt que de sauter à contretemps.', array['L''adversaire sert réellement le central une fois sur trois.'], array['L''adversaire n''utilise la feinte qu''une fois sur quatre.'], false, true, 5, 5, array['bloc', 'lecture', 'collectif', 'avance']),
  ('bloc_023', 'Bloc en situation de match', 'Bloc intégré à des points complets, avec toutes les rotations et les contraintes réelles.', 'bloc', array['situation de jeu', 'collectif', 'lecture'], array['middle_blocker', 'outside_hitter', 'opposite'], 'avance', array['avance'], 'competition', 'Bloquer de façon organisée dans un match réel.', 15, 8, 12, array['ballons', 'filet'], 'high', 5, 'Jouez des points complets, chaque bloqueur annonçant sa direction fermée avant l''attaque. Un observateur note la cohérence entre l''annonce et la position réelle du bloc. Jouez deux sets courts en 15 points.', array['Jouez des points complets, chaque bloqueur annonçant sa direction fermée avant l''attaque.', 'Un observateur note la cohérence entre l''annonce et la position réelle du bloc.', 'Jouez deux sets courts en 15 points.'], array['En match, la cohérence bloc-défense compte plus que le contre gagnant.', 'Annonce systématiquement, même quand l''échange s''accélère.', 'Adapte ta direction fermée à l''attaquant que tu as en face.'], 'Cesser d''annoncer dès que le rythme monte. Chercher le contre spectaculaire au détriment de l''organisation.', array['Cesser d''annoncer dès que le rythme monte.', 'Chercher le contre spectaculaire au détriment de l''organisation.'], 'En match, la cohérence bloc-défense compte plus que le contre gagnant. Annonce systématiquement, même quand l''échange s''accélère. Adapte ta direction fermée à l''attaquant que tu as en face.', array['Les points gagnés au bloc comptent double.'], array['Supprimez l''obligation d''annonce.'], false, true, 5, 5, array['bloc', 'match', 'competition']),
  ('bloc_024', 'Comptage de l''efficacité au contre', 'Suivi chiffré des interventions de bloc : contres gagnants, ballons ralentis et fautes.', 'bloc', array['évaluation', 'analyse', 'bloc'], array['middle_blocker', 'outside_hitter', 'opposite'], 'intermediaire', array['intermediaire', 'avance'], 'bloc', 'Mesurer objectivement l''utilité réelle de son bloc.', 12, 4, 10, array['ballons', 'filet'], 'medium', 4, 'Sur 30 attaques adverses, comptabilise contres gagnants, ballons ralentis, blocs traversés et fautes. Calcule la part d''interventions utiles. Compare tes chiffres d''une séance à l''autre.', array['Sur 30 attaques adverses, comptabilise contres gagnants, ballons ralentis, blocs traversés et fautes.', 'Calcule la part d''interventions utiles.', 'Compare tes chiffres d''une séance à l''autre.'], array['Un ballon ralenti et défendu vaut presque autant qu''un contre gagnant.', 'Un taux de fautes de filet élevé annule tout le bénéfice du bloc.', 'Analyse tes blocs traversés : problème de placement ou de timing ?'], 'Ne compter que les contres gagnants. Négliger le décompte des fautes de filet.', array['Ne compter que les contres gagnants.', 'Négliger le décompte des fautes de filet.'], 'Un ballon ralenti et défendu vaut presque autant qu''un contre gagnant. Un taux de fautes de filet élevé annule tout le bénéfice du bloc. Analyse tes blocs traversés : problème de placement ou de timing ?', array['Fixe-toi un objectif chiffré pour la séance suivante.'], array['Réduis l''observation à quinze attaques.'], false, true, 4, 4, array['bloc', 'evaluation', 'statistiques']),
  ('bloc_025', 'Défi de contres consécutifs', 'Objectif chiffré d''interventions de bloc utiles enchaînées sans faute.', 'bloc', array['régularité', 'concentration', 'bloc'], array['middle_blocker', 'outside_hitter', 'opposite'], 'avance', array['avance'], 'regularite', 'Enchaîner des interventions de bloc utiles sans faute.', 10, 3, 8, array['ballons', 'filet'], 'high', 5, 'Chaque bloc qui touche le ballon ou ferme correctement sa direction compte pour un point. Une faute de filet ou un bloc hors sujet remet le compteur à zéro. L''exercice s''arrête à huit interventions consécutives ou après 30 attaques.', array['Chaque bloc qui touche le ballon ou ferme correctement sa direction compte pour un point.', 'Une faute de filet ou un bloc hors sujet remet le compteur à zéro.', 'L''exercice s''arrête à huit interventions consécutives ou après 30 attaques.'], array['La constance du placement compte plus que la hauteur du saut.', 'Après une remise à zéro, reviens au plus simple : place-toi bien et saute juste.', 'Conserve la même énergie sur chaque saut.'], 'Forcer le saut vers l''avant quand le compteur monte. Se relâcher après une remise à zéro.', array['Forcer le saut vers l''avant quand le compteur monte.', 'Se relâcher après une remise à zéro.'], 'La constance du placement compte plus que la hauteur du saut. Après une remise à zéro, reviens au plus simple : place-toi bien et saute juste. Conserve la même énergie sur chaque saut.', array['Porte l''objectif à douze interventions consécutives.'], array['Abaisse l''objectif à cinq interventions.'], false, true, 5, 4, array['bloc', 'defi', 'regularite']),
  ('deplacements_001', 'Position d''attente universelle', 'Posture de base utilisée avant chaque action, avec un poids de corps toujours prêt à partir.', 'deplacements', array['posture', 'disponibilité', 'équilibre'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant'], 'vitesse', 'Installer une posture qui permet de partir instantanément.', 5, 1, 12, '{}', 'low', 2, 'Pieds légèrement décalés, écartés à la largeur des épaules, poids sur l''avant des pieds. Tiens la position quinze secondes, puis effectue trois départs courts avant d''y revenir. 4 séries, avec vingt secondes de récupération.', array['Pieds légèrement décalés, écartés à la largeur des épaules, poids sur l''avant des pieds.', 'Tiens la position quinze secondes, puis effectue trois départs courts avant d''y revenir.', '4 séries, avec vingt secondes de récupération.'], array['Les talons restent décollés du sol, prêts à libérer un appui.', 'Le buste penche légèrement vers l''avant, le dos reste droit.', 'Les mains sont devant, jamais le long du corps.'], 'Se tenir jambes tendues, ce qui retarde chaque démarrage. Mettre le poids sur les talons.', array['Se tenir jambes tendues, ce qui retarde chaque démarrage.', 'Mettre le poids sur les talons.'], 'Les talons restent décollés du sol, prêts à libérer un appui. Le buste penche légèrement vers l''avant, le dos reste droit. Les mains sont devant, jamais le long du corps.', array['Allonge la tenue de position à trente secondes.'], array['Réduis la tenue à huit secondes.'], true, false, 2, 1, array['deplacements', 'posture', 'maison', 'debutant']),
  ('deplacements_002', 'Pas chassés sur courte distance', 'Déplacement latéral sans croisement d''appuis, technique de base sur les courtes distances.', 'deplacements', array['pas chassés', 'latéralité', 'équilibre'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant'], 'vitesse', 'Se déplacer latéralement en restant équilibré et bas.', 8, 1, 12, array['plots'], 'medium', 3, 'Pose deux plots à deux mètres d''écart. Déplace-toi de l''un à l''autre en pas chassés, sans jamais croiser les pieds. 4 séries de 8 allers-retours, avec 30 secondes de récupération.', array['Pose deux plots à deux mètres d''écart.', 'Déplace-toi de l''un à l''autre en pas chassés, sans jamais croiser les pieds.', '4 séries de 8 allers-retours, avec 30 secondes de récupération.'], array['Les épaules restent orientées vers le filet pendant tout le déplacement.', 'Le buste reste bas : ne te redresse pas en te déplaçant.', 'Le pied d''arrivée ne rejoint jamais complètement le pied de départ.'], 'Croiser les pieds sur une distance courte et perdre l''équilibre. Se redresser au premier appui.', array['Croiser les pieds sur une distance courte et perdre l''équilibre.', 'Se redresser au premier appui.'], 'Les épaules restent orientées vers le filet pendant tout le déplacement. Le buste reste bas : ne te redresse pas en te déplaçant. Le pied d''arrivée ne rejoint jamais complètement le pied de départ.', array['Ajoute un geste technique à chaque extrémité.'], array['Rapproche les plots à un mètre.'], true, false, 3, 2, array['deplacements', 'lateral', 'fondamentaux']),
  ('deplacements_003', 'Pas croisés sur longue distance', 'Déplacement latéral rapide sur plusieurs mètres, où le croisement d''appuis devient indispensable.', 'deplacements', array['pas croisés', 'vitesse', 'coordination'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire'], 'vitesse', 'Couvrir rapidement une distance latérale importante.', 8, 1, 12, array['plots'], 'high', 4, 'Pose deux plots à cinq mètres d''écart. Rejoins le plot opposé en trois appuis : ouverture, croisé, appui d''arrêt. 4 séries de 6 allers-retours.', array['Pose deux plots à cinq mètres d''écart.', 'Rejoins le plot opposé en trois appuis : ouverture, croisé, appui d''arrêt.', '4 séries de 6 allers-retours.'], array['Le premier appui ouvre le bassin dans la direction visée.', 'Le dernier appui te remet face à ta zone de jeu.', 'Au-delà de trois mètres, le pas croisé est toujours plus rapide.'], 'Rester en pas chassés sur une longue distance et arriver en retard. Terminer de profil au lieu de se remettre face au jeu.', array['Rester en pas chassés sur une longue distance et arriver en retard.', 'Terminer de profil au lieu de se remettre face au jeu.'], 'Le premier appui ouvre le bassin dans la direction visée. Le dernier appui te remet face à ta zone de jeu. Au-delà de trois mètres, le pas croisé est toujours plus rapide.', array['Ajoute un geste technique à l''arrivée.'], array['Réduis la distance à trois mètres.'], true, false, 4, 3, array['deplacements', 'lateral', 'vitesse']),
  ('deplacements_004', 'Avancées et reculs alternés', 'Déplacements dans l''axe avant-arrière, en gardant le regard orienté vers le filet.', 'deplacements', array['profondeur', 'pivot', 'équilibre'], array['libero', 'outside_hitter', 'opposite'], 'debutant', array['debutant', 'intermediaire'], 'vitesse', 'Gérer la profondeur sans jamais perdre le jeu de vue.', 8, 1, 12, array['plots'], 'medium', 3, 'Deux plots sont posés à quatre mètres, l''un devant l''autre. Avance au plot avant puis recule au plot arrière, sans jamais tourner le dos au filet. 4 séries de 8 allers-retours.', array['Deux plots sont posés à quatre mètres, l''un devant l''autre.', 'Avance au plot avant puis recule au plot arrière, sans jamais tourner le dos au filet.', '4 séries de 8 allers-retours.'], array['Pour reculer, pivote le bassin et utilise des pas croisés, jamais la marche arrière.', 'Garde le filet dans ton champ de vision en permanence.', 'Termine chaque déplacement par un appui d''arrêt stable.'], 'Courir à reculons, au risque de trébucher. Se retourner complètement et perdre le jeu de vue.', array['Courir à reculons, au risque de trébucher.', 'Se retourner complètement et perdre le jeu de vue.'], 'Pour reculer, pivote le bassin et utilise des pas croisés, jamais la marche arrière. Garde le filet dans ton champ de vision en permanence. Termine chaque déplacement par un appui d''arrêt stable.', array['Un partenaire annonce la direction au dernier moment.'], array['Réduis la distance à deux mètres.'], true, false, 3, 3, array['deplacements', 'profondeur', 'libero']),
  ('deplacements_005', 'Navette courte chronométrée', 'Allers-retours rapides sur six mètres, avec un temps de référence à améliorer.', 'deplacements', array['vitesse', 'freinage', 'endurance'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire', 'avance'], 'vitesse', 'Améliorer sa vitesse sur les déplacements courts répétés.', 10, 1, 12, array['plots', 'chronometre'], 'high', 4, 'Deux plots sont posés à six mètres d''écart. Effectue six allers-retours le plus vite possible, en touchant chaque plot de la main. 5 séries, avec 45 secondes de récupération, en notant les temps.', array['Deux plots sont posés à six mètres d''écart.', 'Effectue six allers-retours le plus vite possible, en touchant chaque plot de la main.', '5 séries, avec 45 secondes de récupération, en notant les temps.'], array['Le temps se gagne dans les freinages, pas dans la vitesse de pointe.', 'Baisse ton centre de gravité avant chaque demi-tour.', 'Fais des appuis courts et rapprochés dans les deux derniers mètres.'], 'Arriver debout sur le plot et devoir freiner sur plusieurs pas. Faire de grandes foulées jusqu''au dernier moment.', array['Arriver debout sur le plot et devoir freiner sur plusieurs pas.', 'Faire de grandes foulées jusqu''au dernier moment.'], 'Le temps se gagne dans les freinages, pas dans la vitesse de pointe. Baisse ton centre de gravité avant chaque demi-tour. Fais des appuis courts et rapprochés dans les deux derniers mètres.', array['Passe à huit allers-retours par série.'], array['Réduis à quatre allers-retours.'], true, false, 5, 2, array['deplacements', 'vitesse', 'chronometre']),
  ('deplacements_006', 'Parcours en étoile à cinq branches', 'Départs depuis un point central vers cinq directions, avec retour systématique au centre.', 'deplacements', array['multidirectionnel', 'replacement', 'vitesse'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire', 'avance'], 'vitesse', 'Couvrir toutes les directions depuis une position d''attente.', 10, 1, 8, array['plots'], 'high', 4, 'Cinq plots sont disposés en étoile à trois mètres d''un point central. Pars du centre, touche un plot annoncé, puis reviens au centre avant le suivant. 4 séries de 10 départs, avec une minute de récupération.', array['Cinq plots sont disposés en étoile à trois mètres d''un point central.', 'Pars du centre, touche un plot annoncé, puis reviens au centre avant le suivant.', '4 séries de 10 départs, avec une minute de récupération.'], array['Choisis le type d''appui selon la direction : chassé sur les côtés, croisé en diagonale.', 'Le retour au centre compte autant que l''aller : reviens en position d''attente.', 'Reste bas sur l''ensemble du parcours.'], 'Utiliser le même déplacement quelle que soit la direction. Revenir au centre en marchant.', array['Utiliser le même déplacement quelle que soit la direction.', 'Revenir au centre en marchant.'], 'Choisis le type d''appui selon la direction : chassé sur les côtés, croisé en diagonale. Le retour au centre compte autant que l''aller : reviens en position d''attente. Reste bas sur l''ensemble du parcours.', array['L''annonce arrive pendant le retour au centre.'], array['Réduis le rayon à deux mètres.'], false, false, 5, 3, array['deplacements', 'multidirectionnel', 'reaction']),
  ('deplacements_007', 'Fréquence d''appuis au sol', 'Appuis très rapides sur place pour développer la fréquence gestuelle des jambes.', 'deplacements', array['fréquence', 'coordination', 'vitesse'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire'], 'vitesse', 'Augmenter la fréquence et la légèreté des appuis.', 6, 1, 12, '{}', 'high', 3, 'Effectue des appuis alternés très rapides sur place, sur l''avant des pieds. Tiens quinze secondes à fréquence maximale, puis reste en position d''attente cinq secondes. 6 séries, avec 30 secondes de récupération.', array['Effectue des appuis alternés très rapides sur place, sur l''avant des pieds.', 'Tiens quinze secondes à fréquence maximale, puis reste en position d''attente cinq secondes.', '6 séries, avec 30 secondes de récupération.'], array['Le contact au sol doit être le plus court possible.', 'Reste sur l''avant des pieds, les talons ne touchent jamais.', 'Les bras accompagnent le rythme, ils ne restent pas inertes.'], 'Lever les genoux haut au détriment de la fréquence. Poser les talons et alourdir les appuis.', array['Lever les genoux haut au détriment de la fréquence.', 'Poser les talons et alourdir les appuis.'], 'Le contact au sol doit être le plus court possible. Reste sur l''avant des pieds, les talons ne touchent jamais. Les bras accompagnent le rythme, ils ne restent pas inertes.', array['Ajoute un départ en sprint au signal en fin de série.'], array['Réduis la durée à dix secondes.'], true, false, 4, 2, array['deplacements', 'frequence', 'maison']),
  ('deplacements_008', 'Freinage et relance', 'Travail spécifique de l''arrêt brutal suivi d''un redémarrage dans la direction opposée.', 'deplacements', array['freinage', 'changement de direction', 'force excentrique'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire', 'avance'], 'vitesse', 'Freiner et repartir sans perdre de temps ni se blesser.', 10, 1, 8, array['plots'], 'high', 4, 'Sprinte sur quatre mètres, arrête-toi net sur un plot, puis repars immédiatement en sens inverse. Effectue six changements de direction par série. 4 séries, avec une minute de récupération.', array['Sprinte sur quatre mètres, arrête-toi net sur un plot, puis repars immédiatement en sens inverse.', 'Effectue six changements de direction par série.', '4 séries, avec une minute de récupération.'], array['Le freinage se fait en trois appuis raccourcis, pas d''un seul coup.', 'Fléchis les genoux et abaisse le bassin pour absorber la décélération.', 'Les genoux restent alignés avec les pieds pendant tout le freinage.'], 'Freiner d''un seul appui, ce qui expose fortement le genou. Rester haut sur les jambes pendant la décélération.', array['Freiner d''un seul appui, ce qui expose fortement le genou.', 'Rester haut sur les jambes pendant la décélération.'], 'Le freinage se fait en trois appuis raccourcis, pas d''un seul coup. Fléchis les genoux et abaisse le bassin pour absorber la décélération. Les genoux restent alignés avec les pieds pendant tout le freinage.', array['Augmente la distance de sprint à six mètres.'], array['Réduis la vitesse d''approche à soixante-dix pour cent.'], true, false, 5, 3, array['deplacements', 'freinage', 'prevention']),
  ('deplacements_009', 'Départ explosif depuis position basse', 'Premier pas maximal depuis la posture de défense, sur trois mètres.', 'deplacements', array['démarrage', 'explosivité', 'premier appui'], array['libero', 'outside_hitter', 'opposite'], 'intermediaire', array['intermediaire'], 'vitesse', 'Gagner du temps sur le premier pas défensif.', 8, 1, 8, array['plots'], 'high', 3, 'Pars en position de défense basse, mains devant. Au signal, sprinte trois mètres jusqu''à un plot, puis reviens en marchant. 5 séries de 6 départs, avec une minute de récupération.', array['Pars en position de défense basse, mains devant.', 'Au signal, sprinte trois mètres jusqu''à un plot, puis reviens en marchant.', '5 séries de 6 départs, avec une minute de récupération.'], array['Le premier appui pousse vers la cible, il ne recule jamais.', 'Reste bas sur les deux premiers appuis : te redresser coûte du temps.', 'Les bras participent activement au démarrage.'], 'Faire un contre-appui vers l''arrière avant de partir. Se redresser dès le premier pas.', array['Faire un contre-appui vers l''arrière avant de partir.', 'Se redresser dès le premier pas.'], 'Le premier appui pousse vers la cible, il ne recule jamais. Reste bas sur les deux premiers appuis : te redresser coûte du temps. Les bras participent activement au démarrage.', array['Le signal devient visuel et aléatoire.'], array['Pars d''une position debout classique.'], true, false, 4, 2, array['deplacements', 'demarrage', 'explosivite']),
  ('deplacements_010', 'Arrivée stabilisée sur cible', 'Déplacement terminé par un arrêt parfaitement équilibré, condition de tout geste technique.', 'deplacements', array['stabilisation', 'appui d''arrêt', 'équilibre'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire'], 'vitesse', 'Terminer chaque déplacement en position stable.', 8, 1, 8, array['plots'], 'medium', 3, 'Déplace-toi sur trois mètres vers un plot et arrête-toi exactement dessus. Tiens la position d''attente deux secondes sans bouger avant de repartir. 4 séries de 8 déplacements.', array['Déplace-toi sur trois mètres vers un plot et arrête-toi exactement dessus.', 'Tiens la position d''attente deux secondes sans bouger avant de repartir.', '4 séries de 8 déplacements.'], array['Anticipe ton freinage un mètre avant la cible.', 'L''arrêt doit être total : aucun pas de rattrapage autorisé.', 'Reviens immédiatement en position d''attente complète.'], 'Dépasser la cible et corriger par un pas supplémentaire. Arriver en déséquilibre vers l''avant.', array['Dépasser la cible et corriger par un pas supplémentaire.', 'Arriver en déséquilibre vers l''avant.'], 'Anticipe ton freinage un mètre avant la cible. L''arrêt doit être total : aucun pas de rattrapage autorisé. Reviens immédiatement en position d''attente complète.', array['Ajoute un geste technique après l''arrêt.'], array['Réduis la distance à deux mètres.'], true, false, 3, 3, array['deplacements', 'stabilite', 'appuis']),
  ('deplacements_011', 'Appuis de bloqueur le long du filet', 'Déplacements spécifiques au bloc, en restant à distance constante du filet.', 'deplacements', array['déplacement au filet', 'orientation', 'appuis'], array['middle_blocker', 'outside_hitter', 'opposite'], 'intermediaire', array['intermediaire'], 'vitesse', 'Se déplacer au filet sans perdre sa distance de bloc.', 10, 1, 8, array['filet', 'plots'], 'high', 4, 'Trois plots sont posés le long du filet : antenne gauche, centre, antenne droite. Enchaîne les déplacements entre ces trois points en gardant la même distance au filet. 4 séries de 6 parcours complets.', array['Trois plots sont posés le long du filet : antenne gauche, centre, antenne droite.', 'Enchaîne les déplacements entre ces trois points en gardant la même distance au filet.', '4 séries de 6 parcours complets.'], array['Conserve toujours une distance d''un bras avec le filet.', 'Pas chassés vers le plot voisin, pas croisés pour traverser tout le filet.', 'Termine chaque déplacement face au filet, jamais de profil.'], 'Dériver vers le filet au fil du parcours. S''éloigner du filet et ne plus pouvoir bloquer efficacement.', array['Dériver vers le filet au fil du parcours.', 'S''éloigner du filet et ne plus pouvoir bloquer efficacement.'], 'Conserve toujours une distance d''un bras avec le filet. Pas chassés vers le plot voisin, pas croisés pour traverser tout le filet. Termine chaque déplacement face au filet, jamais de profil.', array['Ajoute un saut de bloc à chaque arrivée.'], array['Travaille uniquement entre deux plots voisins.'], true, false, 4, 3, array['deplacements', 'bloc', 'filet']),
  ('deplacements_012', 'Départ sur signal visuel', 'Démarrage déclenché par un signal imprévisible, pour travailler le temps de réaction.', 'deplacements', array['réaction', 'démarrage', 'attention'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire'], 'vitesse', 'Réduire son temps de réaction au départ.', 8, 2, 8, array['plots'], 'high', 3, 'Un partenaire pointe une direction du bras à un moment imprévisible. Pars immédiatement dans cette direction sur trois mètres. 4 séries de 8 départs, avec une minute de récupération.', array['Un partenaire pointe une direction du bras à un moment imprévisible.', 'Pars immédiatement dans cette direction sur trois mètres.', '4 séries de 8 départs, avec une minute de récupération.'], array['Reste en position d''attente active pendant l''attente du signal.', 'Ne devine pas : attends l''information réelle.', 'Le partenaire varie volontairement le délai avant le signal.'], 'Anticiper le signal et fausser le travail de réaction. Se relâcher pendant l''attente.', array['Anticiper le signal et fausser le travail de réaction.', 'Se relâcher pendant l''attente.'], 'Reste en position d''attente active pendant l''attente du signal. Ne devine pas : attends l''information réelle. Le partenaire varie volontairement le délai avant le signal.', array['Ajoute une direction supplémentaire à couvrir.'], array['Réduis à deux directions possibles.'], false, false, 4, 2, array['deplacements', 'reaction', 'signal']),
  ('deplacements_013', 'Slalom entre plots', 'Parcours sinueux entre des plots rapprochés, pour la vivacité et le placement des appuis.', 'deplacements', array['agilité', 'appuis', 'coordination'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire'], 'vitesse', 'Développer la vivacité des appuis sur trajectoire sinueuse.', 8, 1, 8, array['plots'], 'high', 3, 'Dispose six plots en ligne, espacés d''un mètre. Slalome entre eux le plus vite possible, puis reviens en courant droit. 4 séries de 5 parcours, avec 45 secondes de récupération.', array['Dispose six plots en ligne, espacés d''un mètre.', 'Slalome entre eux le plus vite possible, puis reviens en courant droit.', '4 séries de 5 parcours, avec 45 secondes de récupération.'], array['Fais des appuis courts et nombreux plutôt que de grandes foulées.', 'Le buste reste bas et stable, seuls les appuis changent de direction.', 'Passe au plus près des plots pour raccourcir la trajectoire.'], 'Contourner largement les plots et allonger le parcours. Se redresser complètement entre chaque plot.', array['Contourner largement les plots et allonger le parcours.', 'Se redresser complètement entre chaque plot.'], 'Fais des appuis courts et nombreux plutôt que de grandes foulées. Le buste reste bas et stable, seuls les appuis changent de direction. Passe au plus près des plots pour raccourcir la trajectoire.', array['Réduis l''espacement des plots à soixante-dix centimètres.'], array['Espace les plots d''un mètre cinquante.'], true, false, 4, 2, array['deplacements', 'agilite', 'plots']),
  ('deplacements_014', 'Recul en pivot vers le fond', 'Technique de recul rapide vers la ligne de fond, sans jamais courir à reculons.', 'deplacements', array['recul', 'pivot', 'orientation'], array['libero', 'outside_hitter', 'opposite'], 'intermediaire', array['intermediaire', 'avance'], 'vitesse', 'Reculer vite tout en gardant le jeu dans son champ de vision.', 8, 1, 8, array['plots'], 'high', 4, 'Pars à trois mètres du filet et recule jusqu''à la ligne de fond. Pivote le bassin, recule en pas croisés, et reviens face au filet à l''arrivée. 4 séries de 6 reculs.', array['Pars à trois mètres du filet et recule jusqu''à la ligne de fond.', 'Pivote le bassin, recule en pas croisés, et reviens face au filet à l''arrivée.', '4 séries de 6 reculs.'], array['Le pivot du bassin précède le premier appui de recul.', 'Garde la tête tournée vers le filet pendant toute la course.', 'Le dernier appui te replace de face, prêt à jouer.'], 'Courir en marche arrière et perdre en vitesse. Tourner complètement le dos au filet.', array['Courir en marche arrière et perdre en vitesse.', 'Tourner complètement le dos au filet.'], 'Le pivot du bassin précède le premier appui de recul. Garde la tête tournée vers le filet pendant toute la course. Le dernier appui te replace de face, prêt à jouer.', array['Ajoute un ballon à jouer à l''arrivée.'], array['Réduis la distance de recul à trois mètres.'], true, false, 4, 3, array['deplacements', 'recul', 'libero']),
  ('deplacements_015', 'Déplacement sous contrainte de hauteur', 'Parcours entier réalisé sous un élastique, pour obliger à rester en position basse.', 'deplacements', array['posture basse', 'jambes', 'endurance'], array['libero', 'outside_hitter', 'opposite'], 'intermediaire', array['intermediaire'], 'vitesse', 'Tenir réellement une position basse en déplacement.', 8, 1, 6, array['elastique', 'plots'], 'high', 4, 'Tends un élastique à un mètre vingt du sol, sur quatre mètres de longueur. Effectue des allers-retours latéraux sous l''élastique sans jamais le toucher. 4 séries de 30 secondes, avec une minute de récupération.', array['Tends un élastique à un mètre vingt du sol, sur quatre mètres de longueur.', 'Effectue des allers-retours latéraux sous l''élastique sans jamais le toucher.', '4 séries de 30 secondes, avec une minute de récupération.'], array['La hauteur se gagne par la flexion des jambes, pas en penchant le buste.', 'Garde le dos droit malgré la contrainte de hauteur.', 'Cette position basse est celle qui permet de partir le plus vite.'], 'Se pencher en avant au lieu de fléchir les jambes. Se redresser dès que la fatigue arrive.', array['Se pencher en avant au lieu de fléchir les jambes.', 'Se redresser dès que la fatigue arrive.'], 'La hauteur se gagne par la flexion des jambes, pas en penchant le buste. Garde le dos droit malgré la contrainte de hauteur. Cette position basse est celle qui permet de partir le plus vite.', array['Abaisse l''élastique à un mètre.'], array['Monte l''élastique à un mètre quarante.'], true, false, 5, 2, array['deplacements', 'posture', 'jambes']),
  ('deplacements_016', 'Déplacement puis geste technique', 'Enchaînement systématique entre un déplacement et une touche de balle, comme en match.', 'deplacements', array['enchaînement', 'stabilisation', 'appuis'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire'], 'vitesse', 'Relier déplacement et geste technique sans rupture.', 10, 2, 6, array['ballons', 'plots'], 'high', 4, 'Déplace-toi de trois mètres vers un plot, puis réceptionne un ballon envoyé à cet endroit. Reviens ensuite à ta position de départ avant le ballon suivant. 4 séries de 8 enchaînements.', array['Déplace-toi de trois mètres vers un plot, puis réceptionne un ballon envoyé à cet endroit.', 'Reviens ensuite à ta position de départ avant le ballon suivant.', '4 séries de 8 enchaînements.'], array['Sois arrêté avant la touche : un geste en déplacement est toujours imprécis.', 'Le déplacement n''est réussi que s''il permet un geste propre.', 'Reviens à ta position de départ sans temps mort.'], 'Toucher le ballon encore en mouvement. Se replacer en marchant.', array['Toucher le ballon encore en mouvement.', 'Se replacer en marchant.'], 'Sois arrêté avant la touche : un geste en déplacement est toujours imprécis. Le déplacement n''est réussi que s''il permet un geste propre. Reviens à ta position de départ sans temps mort.', array['Réduis le délai entre deux ballons.'], array['Réduis la distance de déplacement à deux mètres.'], false, true, 4, 3, array['deplacements', 'enchainement', 'technique']),
  ('deplacements_017', 'Rythme de la course d''élan', 'Travail isolé des appuis de l''élan d''attaque, sans ballon ni frappe.', 'deplacements', array['élan', 'rythme', 'impulsion'], array['middle_blocker', 'outside_hitter', 'opposite'], 'debutant', array['debutant', 'intermediaire'], 'vitesse', 'Installer le rythme d''accélération propre à l''élan d''attaque.', 8, 1, 8, '{}', 'medium', 3, 'Effectue la course d''élan complète en marquant nettement l''accélération finale. Termine par une impulsion sans saut maximal, uniquement pour sentir le rythme. 4 séries de 8 élans.', array['Effectue la course d''élan complète en marquant nettement l''accélération finale.', 'Termine par une impulsion sans saut maximal, uniquement pour sentir le rythme.', '4 séries de 8 élans.'], array['Le rythme s''accélère progressivement : lent, plus rapide, très rapide.', 'Les deux derniers appuis se posent talon en premier, pour convertir la vitesse.', 'Les bras partent loin derrière avant de se lancer vers le haut.'], 'Un élan à vitesse constante, sans accélération. Des derniers appuis posés sur la pointe des pieds.', array['Un élan à vitesse constante, sans accélération.', 'Des derniers appuis posés sur la pointe des pieds.'], 'Le rythme s''accélère progressivement : lent, plus rapide, très rapide. Les deux derniers appuis se posent talon en premier, pour convertir la vitesse. Les bras partent loin derrière avant de se lancer vers le haut.', array['Ajoute le saut maximal une fois le rythme installé.'], array['Décompose l''élan appui par appui, au ralenti.'], true, false, 3, 3, array['deplacements', 'elan', 'attaque']),
  ('deplacements_018', 'Replacement systématique après action', 'Retour à sa position de référence après chaque intervention, automatisme souvent négligé.', 'deplacements', array['replacement', 'discipline', 'endurance'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire'], 'vitesse', 'Automatiser le retour à sa position de référence.', 10, 2, 8, array['ballons', 'plots'], 'high', 3, 'Un plot marque ta position de référence sur le terrain. Après chaque ballon joué, reviens obligatoirement sur ce plot avant le suivant. 4 séries de 10 ballons.', array['Un plot marque ta position de référence sur le terrain.', 'Après chaque ballon joué, reviens obligatoirement sur ce plot avant le suivant.', '4 séries de 10 ballons.'], array['Le replacement commence dès que le ballon quitte tes mains.', 'Reviens en pas chassés ou croisés, jamais en marchant.', 'Sois arrêté sur ton plot avant l''envoi suivant.'], 'Regarder le résultat de son action au lieu de se replacer. Se replacer approximativement, à un mètre de sa position réelle.', array['Regarder le résultat de son action au lieu de se replacer.', 'Se replacer approximativement, à un mètre de sa position réelle.'], 'Le replacement commence dès que le ballon quitte tes mains. Reviens en pas chassés ou croisés, jamais en marchant. Sois arrêté sur ton plot avant l''envoi suivant.', array['Réduis le délai entre les ballons.'], array['Allonge le délai entre les ballons.'], false, true, 4, 2, array['deplacements', 'replacement', 'discipline']),
  ('deplacements_019', 'Coordination bras et jambes', 'Exercices de coordination associant un mouvement de bras à un déplacement des appuis.', 'deplacements', array['coordination', 'dissociation', 'rythme'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant'], 'vitesse', 'Dissocier le travail des bras et des appuis.', 6, 1, 12, '{}', 'medium', 3, 'Enchaîne des pas chassés latéraux tout en effectuant des cercles de bras vers l''avant. Change de sens de rotation des bras à chaque changement de direction. 3 séries de 30 secondes, avec 30 secondes de récupération.', array['Enchaîne des pas chassés latéraux tout en effectuant des cercles de bras vers l''avant.', 'Change de sens de rotation des bras à chaque changement de direction.', '3 séries de 30 secondes, avec 30 secondes de récupération.'], array['Les bras et les jambes travaillent indépendamment : c''est le but de l''exercice.', 'Garde un rythme de déplacement régulier malgré le travail des bras.', 'Reste bas sur tes appuis pendant tout l''exercice.'], 'Ralentir les jambes dès que les bras se compliquent. Se redresser pour mieux gérer la coordination.', array['Ralentir les jambes dès que les bras se compliquent.', 'Se redresser pour mieux gérer la coordination.'], 'Les bras et les jambes travaillent indépendamment : c''est le but de l''exercice. Garde un rythme de déplacement régulier malgré le travail des bras. Reste bas sur tes appuis pendant tout l''exercice.', array['Ajoute un changement de direction sur signal.'], array['Ralentis le rythme de déplacement.'], true, false, 3, 3, array['deplacements', 'coordination', 'maison']),
  ('deplacements_020', 'Appuis courus en fond de terrain', 'Course de couverture sur de grandes distances en fond de court, typique du libéro.', 'deplacements', array['course', 'couverture', 'endurance'], array['libero', 'outside_hitter', 'opposite'], 'intermediaire', array['intermediaire', 'avance'], 'vitesse', 'Couvrir efficacement toute la largeur du fond de terrain.', 10, 1, 8, array['plots'], 'high', 4, 'Trois plots sont posés en fond de terrain, aux zones 1, 6 et 5. Enchaîne les déplacements entre ces trois zones en couvrant toute la largeur. 4 séries de 6 parcours complets, avec une minute de récupération.', array['Trois plots sont posés en fond de terrain, aux zones 1, 6 et 5.', 'Enchaîne les déplacements entre ces trois zones en couvrant toute la largeur.', '4 séries de 6 parcours complets, avec une minute de récupération.'], array['Sur ces distances, la course reste plus rapide que les pas chassés.', 'Reviens systématiquement en position basse à chaque plot.', 'Anticipe la fin de course pour arriver stabilisé.'], 'Utiliser des pas chassés sur toute la largeur et arriver en retard. Arriver debout et non en position de défense.', array['Utiliser des pas chassés sur toute la largeur et arriver en retard.', 'Arriver debout et non en position de défense.'], 'Sur ces distances, la course reste plus rapide que les pas chassés. Reviens systématiquement en position basse à chaque plot. Anticipe la fin de course pour arriver stabilisé.', array['Ajoute un ballon à défendre à chaque plot.'], array['Réduis à deux plots.'], true, false, 5, 2, array['deplacements', 'libero', 'couverture']),
  ('deplacements_021', 'Déplacement en miroir', 'Reproduction en temps réel des déplacements d''un partenaire placé en face.', 'deplacements', array['réaction', 'adaptation', 'agilité'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire'], 'vitesse', 'Réagir instantanément à un déplacement imprévisible.', 8, 2, 8, '{}', 'high', 3, 'Deux joueurs se font face à deux mètres, l''un mène, l''autre reproduit ses déplacements. Le meneur varie librement direction et rythme pendant 30 secondes. 4 séries, en inversant les rôles à chaque fois.', array['Deux joueurs se font face à deux mètres, l''un mène, l''autre reproduit ses déplacements.', 'Le meneur varie librement direction et rythme pendant 30 secondes.', '4 séries, en inversant les rôles à chaque fois.'], array['Le suiveur regarde le bassin du meneur, pas ses pieds.', 'Reste en position basse pour pouvoir changer de direction instantanément.', 'Le meneur doit varier réellement, sans rythme prévisible.'], 'Regarder les pieds du partenaire et réagir avec un temps de retard. Prendre un rythme régulier qui annule l''intérêt de l''exercice.', array['Regarder les pieds du partenaire et réagir avec un temps de retard.', 'Prendre un rythme régulier qui annule l''intérêt de l''exercice.'], 'Le suiveur regarde le bassin du meneur, pas ses pieds. Reste en position basse pour pouvoir changer de direction instantanément. Le meneur doit varier réellement, sans rythme prévisible.', array['Rapprochez-vous à un mètre pour accélérer les réactions.'], array['Le meneur ralentit et annonce ses directions.'], false, false, 4, 2, array['deplacements', 'reaction', 'binôme']),
  ('deplacements_022', 'Appuis en état de fatigue', 'Maintien de la qualité des appuis après un effort intense, comme en fin de set.', 'deplacements', array['endurance', 'discipline technique', 'appuis'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'avance', array['avance'], 'vitesse', 'Conserver des appuis corrects malgré la fatigue.', 10, 1, 8, array['plots'], 'high', 4, 'Effectue quarante-cinq secondes de navettes intenses. Enchaîne immédiatement dix déplacements techniques en pas chassés, sans dégrader la forme. 4 séries, avec deux minutes de récupération complète.', array['Effectue quarante-cinq secondes de navettes intenses.', 'Enchaîne immédiatement dix déplacements techniques en pas chassés, sans dégrader la forme.', '4 séries, avec deux minutes de récupération complète.'], array['La fatigue fait remonter le buste : garde consciemment ta position basse.', 'Les appuis s''allongent quand on fatigue : raccourcis-les volontairement.', 'Respire amplement pendant les déplacements techniques.'], 'Laisser les appuis devenir des pas croisés approximatifs. Se redresser complètement dès la fin de l''effort intense.', array['Laisser les appuis devenir des pas croisés approximatifs.', 'Se redresser complètement dès la fin de l''effort intense.'], 'La fatigue fait remonter le buste : garde consciemment ta position basse. Les appuis s''allongent quand on fatigue : raccourcis-les volontairement. Respire amplement pendant les déplacements techniques.', array['Allonge la phase intense à une minute.'], array['Réduis la phase intense à trente secondes.'], true, false, 5, 3, array['deplacements', 'fatigue', 'endurance']),
  ('deplacements_023', 'Double contrainte directionnelle', 'Deux déplacements enchaînés dans des directions opposées, sans retour au centre.', 'deplacements', array['changement de direction', 'réaction', 'équilibre'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'avance', array['avance'], 'vitesse', 'Enchaîner deux déplacements opposés sans temps mort.', 8, 2, 8, array['plots'], 'high', 4, 'Un partenaire annonce deux directions successives, très rapprochées dans le temps. Enchaîne les deux déplacements sans repasser par ta position de départ. 4 séries de 6 doubles déplacements.', array['Un partenaire annonce deux directions successives, très rapprochées dans le temps.', 'Enchaîne les deux déplacements sans repasser par ta position de départ.', '4 séries de 6 doubles déplacements.'], array['Le premier déplacement doit rester contrôlé pour pouvoir enchaîner.', 'Ne t''engage jamais totalement sur la première direction.', 'Le changement de direction se prépare dès le premier appui.'], 'S''engager complètement et ne plus pouvoir changer de direction. Marquer un arrêt complet entre les deux déplacements.', array['S''engager complètement et ne plus pouvoir changer de direction.', 'Marquer un arrêt complet entre les deux déplacements.'], 'Le premier déplacement doit rester contrôlé pour pouvoir enchaîner. Ne t''engage jamais totalement sur la première direction. Le changement de direction se prépare dès le premier appui.', array['Ajoute une troisième direction dans la séquence.'], array['Allonge le délai entre les deux annonces.'], false, false, 5, 3, array['deplacements', 'reaction', 'avance']),
  ('deplacements_024', 'Mesure des temps de déplacement', 'Chronométrage de plusieurs types de déplacements pour objectiver ses progrès.', 'deplacements', array['évaluation', 'vitesse', 'analyse'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire', 'avance'], 'vitesse', 'Objectiver ses progrès en vitesse de déplacement.', 10, 2, 8, array['plots', 'chronometre'], 'high', 3, 'Chronomètre trois déplacements types : trois mètres latéraux, six mètres en navette, parcours en étoile. Note tes temps et compare-les d''une séance à l''autre. 2 essais par déplacement, en gardant le meilleur temps.', array['Chronomètre trois déplacements types : trois mètres latéraux, six mètres en navette, parcours en étoile.', 'Note tes temps et compare-les d''une séance à l''autre.', '2 essais par déplacement, en gardant le meilleur temps.'], array['Échauffe-toi complètement avant de chronométrer.', 'Répète le protocole à l''identique pour que la comparaison ait un sens.', 'Un progrès réel se mesure sur plusieurs semaines, pas d''une séance à l''autre.'], 'Comparer des temps mesurés dans des conditions différentes. Se décourager d''une variation de quelques dixièmes.', array['Comparer des temps mesurés dans des conditions différentes.', 'Se décourager d''une variation de quelques dixièmes.'], 'Échauffe-toi complètement avant de chronométrer. Répète le protocole à l''identique pour que la comparaison ait un sens. Un progrès réel se mesure sur plusieurs semaines, pas d''une séance à l''autre.', array['Ajoute un déplacement avec ballon à la fin du parcours.'], array['Chronomètre un seul type de déplacement.'], false, false, 4, 2, array['deplacements', 'evaluation', 'chronometre']),
  ('deplacements_025', 'Circuit complet d''appuis', 'Enchaînement de toutes les formes de déplacement du volley en un seul parcours continu.', 'deplacements', array['polyvalence', 'endurance', 'appuis'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire', 'avance'], 'vitesse', 'Enchaîner toutes les formes de déplacement du volley.', 12, 1, 8, array['plots'], 'high', 4, 'Enchaîne sans pause : trois mètres en pas chassés, cinq mètres en pas croisés, un recul en pivot, un sprint de trois mètres. Termine par une position d''attente tenue deux secondes. 4 séries de 3 parcours, avec une minute et demie de récupération.', array['Enchaîne sans pause : trois mètres en pas chassés, cinq mètres en pas croisés, un recul en pivot, un sprint de trois mètres.', 'Termine par une position d''attente tenue deux secondes.', '4 séries de 3 parcours, avec une minute et demie de récupération.'], array['Chaque portion a sa technique propre : ne les mélange pas.', 'Les transitions entre les types d''appuis sont le vrai enjeu du circuit.', 'Termine chaque parcours en position d''attente complète.'], 'Utiliser le même type d''appui sur tout le parcours. Négliger la position finale par fatigue.', array['Utiliser le même type d''appui sur tout le parcours.', 'Négliger la position finale par fatigue.'], 'Chaque portion a sa technique propre : ne les mélange pas. Les transitions entre les types d''appuis sont le vrai enjeu du circuit. Termine chaque parcours en position d''attente complète.', array['Ajoute un ballon à jouer en fin de parcours.'], array['Réduis le circuit à deux portions.'], true, false, 5, 3, array['deplacements', 'circuit', 'polyvalence']),
  ('detente_001', 'Squats sautés', 'Renforcement explosif des jambes par un saut vertical enchaîné depuis une flexion complète.', 'detente', array['explosivité', 'force des jambes', 'réception'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire'], 'detente', 'Développer la force explosive des jambes en sécurité.', 10, 1, 12, '{}', 'high', 3, 'Pieds à largeur d''épaules, descends en squat jusqu''à ce que les cuisses soient proches de l''horizontale. Explose vers le haut en tendant complètement les jambes, puis amortis la réception en repassant en squat. 4 séries de 8 répétitions, avec 90 secondes de récupération.', array['Pieds à largeur d''épaules, descends en squat jusqu''à ce que les cuisses soient proches de l''horizontale.', 'Explose vers le haut en tendant complètement les jambes, puis amortis la réception en repassant en squat.', '4 séries de 8 répétitions, avec 90 secondes de récupération.'], array['Les genoux restent alignés avec les pieds, ils ne rentrent jamais vers l''intérieur.', 'Réceptionne sur l''avant du pied puis déroule vers le talon.', 'Le dos reste droit et le regard devant pendant tout le mouvement.'], 'Genoux qui rentrent vers l''intérieur à la réception. Réception jambes tendues, qui envoie tout l''impact dans les articulations.', array['Genoux qui rentrent vers l''intérieur à la réception.', 'Réception jambes tendues, qui envoie tout l''impact dans les articulations.'], 'Les genoux restent alignés avec les pieds, ils ne rentrent jamais vers l''intérieur. Réceptionne sur l''avant du pied puis déroule vers le talon. Le dos reste droit et le regard devant pendant tout le mouvement.', array['Enchaîne les répétitions sans marquer d''arrêt en bas.'], array['Supprime le saut et reste sur des squats classiques.'], true, false, 4, 2, array['detente', 'maison', 'renforcement', 'sans materiel']),
  ('detente_002', 'Technique du saut vertical', 'Construction du saut maximal avec utilisation complète des bras et de l''extension du corps.', 'detente', array['technique de saut', 'coordination', 'extension'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant'], 'detente', 'Utiliser correctement les bras et l''extension pour sauter plus haut.', 8, 1, 12, '{}', 'medium', 3, 'Lance les bras loin derrière toi pendant la flexion, puis vers le haut pendant l''extension. Saute à la verticale en cherchant l''extension complète du corps. 4 séries de 6 sauts, avec une minute de récupération.', array['Lance les bras loin derrière toi pendant la flexion, puis vers le haut pendant l''extension.', 'Saute à la verticale en cherchant l''extension complète du corps.', '4 séries de 6 sauts, avec une minute de récupération.'], array['Les bras apportent plusieurs centimètres : ils doivent partir loin en arrière.', 'Le corps se déroule de bas en haut : jambes, bassin, tronc, bras.', 'Cherche l''extension complète, doigts pointés vers le plafond.'], 'Garder les bras devant soi pendant la flexion. Se plier en avant pendant le saut au lieu de s''étendre.', array['Garder les bras devant soi pendant la flexion.', 'Se plier en avant pendant le saut au lieu de s''étendre.'], 'Les bras apportent plusieurs centimètres : ils doivent partir loin en arrière. Le corps se déroule de bas en haut : jambes, bassin, tronc, bras. Cherche l''extension complète, doigts pointés vers le plafond.', array['Ajoute une cible à toucher, légèrement au-dessus de ta portée.'], array['Travaille d''abord le mouvement des bras sans saut.'], true, false, 3, 3, array['detente', 'technique', 'maison']),
  ('detente_003', 'Bondissements horizontaux', 'Sauts vers l''avant enchaînés, complémentaires du travail vertical pour la puissance de poussée.', 'detente', array['puissance horizontale', 'réception', 'enchaînement'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire'], 'detente', 'Développer la puissance de poussée dans le plan horizontal.', 10, 1, 12, '{}', 'high', 3, 'Effectue des bonds vers l''avant à pieds joints, en cherchant la distance. Stabilise-toi complètement après chaque bond avant d''enchaîner. 4 séries de 6 bonds, avec 90 secondes de récupération.', array['Effectue des bonds vers l''avant à pieds joints, en cherchant la distance.', 'Stabilise-toi complètement après chaque bond avant d''enchaîner.', '4 séries de 6 bonds, avec 90 secondes de récupération.'], array['Pousse vers l''avant et vers le haut, pas uniquement vers l''avant.', 'Amortis la réception en fléchissant les jambes et en gardant le buste droit.', 'Stabilise-toi vraiment entre deux bonds au début.'], 'Se déséquilibrer vers l''avant à la réception. Enchaîner trop vite et perdre la qualité d''amorti.', array['Se déséquilibrer vers l''avant à la réception.', 'Enchaîner trop vite et perdre la qualité d''amorti.'], 'Pousse vers l''avant et vers le haut, pas uniquement vers l''avant. Amortis la réception en fléchissant les jambes et en gardant le buste droit. Stabilise-toi vraiment entre deux bonds au début.', array['Enchaîne les bonds sans stabilisation intermédiaire.'], array['Réduis la distance recherchée et marque un temps d''arrêt de deux secondes.'], true, false, 4, 2, array['detente', 'bondissements', 'maison']),
  ('detente_004', 'Sauts en contrebas', 'Pliométrie intense : descente depuis une hauteur suivie d''un rebond immédiat le plus haut possible.', 'detente', array['pliométrie', 'puissance réactive', 'temps de contact'], array['middle_blocker', 'outside_hitter', 'opposite'], 'avance', array['avance'], 'detente', 'Développer la puissance réactive des jambes.', 12, 1, 6, array['plyobox'], 'high', 5, 'Descends d''une caisse de quarante centimètres, sans sauter vers le bas. Dès le contact au sol, rebondis immédiatement le plus haut possible. 4 séries de 5 répétitions, avec deux minutes de récupération complète.', array['Descends d''une caisse de quarante centimètres, sans sauter vers le bas.', 'Dès le contact au sol, rebondis immédiatement le plus haut possible.', '4 séries de 5 répétitions, avec deux minutes de récupération complète.'], array['Pense sol brûlant : le temps de contact au sol doit être minimal.', 'Ne verrouille jamais les genoux à la réception.', 'Cet exercice est exigeant pour les tendons : maximum deux séances par semaine, à 48 h d''intervalle.'], 'Temps de contact au sol trop long, qui annule l''effet pliométrique. Réception genoux tendus, très traumatisante pour les articulations.', array['Temps de contact au sol trop long, qui annule l''effet pliométrique.', 'Réception genoux tendus, très traumatisante pour les articulations.'], 'Pense sol brûlant : le temps de contact au sol doit être minimal. Ne verrouille jamais les genoux à la réception. Cet exercice est exigeant pour les tendons : maximum deux séances par semaine, à 48 h d''intervalle.', array['Augmente la hauteur de la caisse à cinquante centimètres.'], array['Descends d''une caisse de vingt centimètres, ou remplace par des squats sautés.'], true, false, 5, 4, array['detente', 'pliometrie', 'avance']),
  ('detente_005', 'Montée explosive sur caisse', 'Saut vers le haut sur une caisse, avec une réception amortie et sans impact au sol.', 'detente', array['explosivité', 'coordination', 'réception'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire'], 'detente', 'Développer l''explosivité avec un impact articulaire réduit.', 10, 1, 8, array['plyobox'], 'high', 3, 'Place-toi face à une caisse de quarante centimètres. Saute dessus à pieds joints et réceptionne en douceur, genoux fléchis, puis redescends en marchant. 4 séries de 8 montées, avec 90 secondes de récupération.', array['Place-toi face à une caisse de quarante centimètres.', 'Saute dessus à pieds joints et réceptionne en douceur, genoux fléchis, puis redescends en marchant.', '4 séries de 8 montées, avec 90 secondes de récupération.'], array['Redescends toujours en marchant : sauter de la caisse ajoute un impact inutile.', 'Réceptionne silencieusement, c''est le signe d''un bon amorti.', 'Utilise pleinement le lancer de bras pour monter.'], 'Redescendre en sautant et accumuler des impacts. Réceptionner bruyamment, jambes tendues.', array['Redescendre en sautant et accumuler des impacts.', 'Réceptionner bruyamment, jambes tendues.'], 'Redescends toujours en marchant : sauter de la caisse ajoute un impact inutile. Réceptionne silencieusement, c''est le signe d''un bon amorti. Utilise pleinement le lancer de bras pour monter.', array['Augmente la hauteur de la caisse de dix centimètres.'], array['Réduis la hauteur à vingt centimètres.'], true, false, 4, 2, array['detente', 'caisse', 'securite']),
  ('detente_006', 'Impulsion sur une seule jambe', 'Sauts unilatéraux pour corriger les déséquilibres entre les deux jambes.', 'detente', array['équilibre', 'force unilatérale', 'stabilité'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire'], 'detente', 'Corriger les déséquilibres de force entre les jambes.', 10, 1, 12, '{}', 'high', 4, 'Sur une jambe, fléchis légèrement puis saute à la verticale et réceptionne sur la même jambe. Stabilise-toi deux secondes avant la répétition suivante. 3 séries de 6 sauts par jambe, avec une minute de récupération.', array['Sur une jambe, fléchis légèrement puis saute à la verticale et réceptionne sur la même jambe.', 'Stabilise-toi deux secondes avant la répétition suivante.', '3 séries de 6 sauts par jambe, avec une minute de récupération.'], array['Le genou reste aligné avec le pied à la réception, sans partir vers l''intérieur.', 'Compare les deux jambes : un écart important mérite un travail spécifique.', 'La stabilisation compte autant que la hauteur du saut.'], 'Genou qui s''effondre vers l''intérieur à la réception. Enchaîner sans stabiliser et perdre tout le bénéfice de l''exercice.', array['Genou qui s''effondre vers l''intérieur à la réception.', 'Enchaîner sans stabiliser et perdre tout le bénéfice de l''exercice.'], 'Le genou reste aligné avec le pied à la réception, sans partir vers l''intérieur. Compare les deux jambes : un écart important mérite un travail spécifique. La stabilisation compte autant que la hauteur du saut.', array['Enchaîne trois sauts avant de stabiliser.'], array['Effectue de simples montées sur pointe à une jambe, sans saut.'], true, false, 4, 3, array['detente', 'unilateral', 'prevention']),
  ('detente_007', 'Corde à sauter rythmée', 'Sauts à la corde pour développer la raideur de cheville et l''endurance de saut.', 'detente', array['raideur de cheville', 'endurance', 'coordination'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire'], 'detente', 'Renforcer les chevilles et l''endurance de saut.', 10, 1, 12, array['corde'], 'medium', 3, 'Saute à la corde sur l''avant des pieds, genoux très légèrement fléchis. Effectue 6 séries de 45 secondes, avec 30 secondes de récupération. Alterne appuis joints et appuis alternés d''une série à l''autre.', array['Saute à la corde sur l''avant des pieds, genoux très légèrement fléchis.', 'Effectue 6 séries de 45 secondes, avec 30 secondes de récupération.', 'Alterne appuis joints et appuis alternés d''une série à l''autre.'], array['Les sauts restent bas : la corde passe, ce n''est pas un concours de hauteur.', 'Le travail vient de la cheville, les genoux bougent très peu.', 'Reste silencieux : un bruit lourd signale un mauvais amorti.'], 'Sauter trop haut et fatiguer inutilement. Retomber sur les talons.', array['Sauter trop haut et fatiguer inutilement.', 'Retomber sur les talons.'], 'Les sauts restent bas : la corde passe, ce n''est pas un concours de hauteur. Le travail vient de la cheville, les genoux bougent très peu. Reste silencieux : un bruit lourd signale un mauvais amorti.', array['Ajoute des séries d''appuis alternés rapides.'], array['Réduis les séries à 30 secondes.'], true, false, 3, 2, array['detente', 'corde', 'maison', 'chevilles']),
  ('detente_008', 'Fentes sautées alternées', 'Changement de jambe en l''air depuis une position de fente, pour la puissance unilatérale.', 'detente', array['puissance unilatérale', 'coordination', 'équilibre'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire'], 'detente', 'Développer la puissance de chaque jambe séparément.', 8, 1, 12, '{}', 'high', 4, 'Pars en position de fente, genou arrière proche du sol. Saute et change de jambe en l''air, en réceptionnant en fente inversée. 4 séries de 10 répétitions, avec 90 secondes de récupération.', array['Pars en position de fente, genou arrière proche du sol.', 'Saute et change de jambe en l''air, en réceptionnant en fente inversée.', '4 séries de 10 répétitions, avec 90 secondes de récupération.'], array['Le buste reste droit, ne te penche pas en avant.', 'Le genou avant ne dépasse pas la pointe du pied.', 'Amortis la réception avant de repartir.'], 'Pencher le buste vers l''avant pour compenser un manque de force. Réceptionner brutalement sans amortir.', array['Pencher le buste vers l''avant pour compenser un manque de force.', 'Réceptionner brutalement sans amortir.'], 'Le buste reste droit, ne te penche pas en avant. Le genou avant ne dépasse pas la pointe du pied. Amortis la réception avant de repartir.', array['Augmente à 14 répétitions par série.'], array['Effectue des fentes marchées sans saut.'], true, false, 4, 3, array['detente', 'fentes', 'maison']),
  ('detente_009', 'Saut avec contre-mouvement', 'Saut vertical précédé d''une flexion rapide, la forme la plus proche du saut de volley.', 'detente', array['explosivité', 'cycle étirement-détente', 'technique'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire', 'avance'], 'detente', 'Exploiter l''élasticité musculaire pour sauter plus haut.', 8, 1, 12, '{}', 'high', 4, 'Debout, fléchis rapidement les jambes puis saute immédiatement, sans marquer de pause en bas. Cherche la hauteur maximale sur chaque répétition. 4 séries de 6 sauts, avec 90 secondes de récupération.', array['Debout, fléchis rapidement les jambes puis saute immédiatement, sans marquer de pause en bas.', 'Cherche la hauteur maximale sur chaque répétition.', '4 séries de 6 sauts, avec 90 secondes de récupération.'], array['La descente doit être rapide : c''est elle qui crée l''élasticité musculaire.', 'Aucun temps d''arrêt en position basse.', 'Arrête la série dès que la hauteur baisse nettement.'], 'Marquer une pause en position basse et perdre l''effet élastique. Descendre trop bas, ce qui ralentit la remontée.', array['Marquer une pause en position basse et perdre l''effet élastique.', 'Descendre trop bas, ce qui ralentit la remontée.'], 'La descente doit être rapide : c''est elle qui crée l''élasticité musculaire. Aucun temps d''arrêt en position basse. Arrête la série dès que la hauteur baisse nettement.', array['Ajoute une cible à toucher en hauteur.'], array['Effectue le saut depuis une position statique, sans contre-mouvement.'], true, false, 4, 3, array['detente', 'explosivite', 'maison']),
  ('detente_010', 'Saut départ arrêté', 'Saut depuis une position basse maintenue, sans élasticité, pour isoler la force pure.', 'detente', array['force concentrique', 'explosivité', 'gainage'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire'], 'detente', 'Développer la force explosive sans aide élastique.', 8, 1, 12, '{}', 'high', 3, 'Descends en position de squat et tiens-la trois secondes, immobile. Saute ensuite le plus haut possible, sans rebond préalable. 4 séries de 6 sauts, avec 90 secondes de récupération.', array['Descends en position de squat et tiens-la trois secondes, immobile.', 'Saute ensuite le plus haut possible, sans rebond préalable.', '4 séries de 6 sauts, avec 90 secondes de récupération.'], array['Aucun mouvement vers le bas avant le saut : c''est tout l''intérêt de l''exercice.', 'Le gainage du tronc empêche de perdre la force dans le buste.', 'Compare cette hauteur à celle du saut avec contre-mouvement pour situer ton élasticité.'], 'Faire un petit rebond avant de sauter. Relâcher le tronc pendant la tenue de position.', array['Faire un petit rebond avant de sauter.', 'Relâcher le tronc pendant la tenue de position.'], 'Aucun mouvement vers le bas avant le saut : c''est tout l''intérêt de l''exercice. Le gainage du tronc empêche de perdre la force dans le buste. Compare cette hauteur à celle du saut avec contre-mouvement pour situer ton élasticité.', array['Allonge la tenue à cinq secondes.'], array['Réduis la tenue à une seconde.'], true, false, 4, 2, array['detente', 'force', 'maison']),
  ('detente_011', 'Sauts latéraux par-dessus une ligne', 'Bonds latéraux rapides pour la raideur des chevilles et la stabilité des appuis.', 'detente', array['raideur', 'latéralité', 'stabilité'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire'], 'detente', 'Développer la raideur et la vivacité des chevilles.', 8, 1, 12, '{}', 'high', 3, 'Place-toi à côté d''une ligne au sol, pieds joints. Franchis la ligne par des bonds latéraux rapides, sans t''arrêter. 5 séries de 20 secondes, avec 40 secondes de récupération.', array['Place-toi à côté d''une ligne au sol, pieds joints.', 'Franchis la ligne par des bonds latéraux rapides, sans t''arrêter.', '5 séries de 20 secondes, avec 40 secondes de récupération.'], array['Reste sur l''avant des pieds, le contact au sol doit être bref.', 'Les sauts restent bas et rapides, la fréquence prime sur la hauteur.', 'Le buste reste stable, seules les jambes travaillent.'], 'Sauter haut au détriment de la fréquence. Laisser le buste basculer d''un côté à l''autre.', array['Sauter haut au détriment de la fréquence.', 'Laisser le buste basculer d''un côté à l''autre.'], 'Reste sur l''avant des pieds, le contact au sol doit être bref. Les sauts restent bas et rapides, la fréquence prime sur la hauteur. Le buste reste stable, seules les jambes travaillent.', array['Allonge les séries à 30 secondes.'], array['Effectue les franchissements en pas chassés, sans saut.'], true, false, 4, 2, array['detente', 'chevilles', 'maison']),
  ('detente_012', 'Amorti de réception au sol', 'Travail spécifique de la retombée de saut, geste décisif pour la prévention des blessures.', 'detente', array['amorti', 'prévention', 'alignement'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant'], 'detente', 'Sécuriser la retombée de tous les sauts du volley.', 8, 1, 12, '{}', 'medium', 3, 'Effectue un saut vertical modéré et concentre-toi uniquement sur la réception. Retombe sur l''avant des pieds, déroule vers le talon et fléchis les genoux. 4 séries de 8 sauts, en cherchant une réception parfaitement silencieuse.', array['Effectue un saut vertical modéré et concentre-toi uniquement sur la réception.', 'Retombe sur l''avant des pieds, déroule vers le talon et fléchis les genoux.', '4 séries de 8 sauts, en cherchant une réception parfaitement silencieuse.'], array['Une réception silencieuse est une réception bien amortie.', 'Les genoux restent alignés avec les pointes de pieds.', 'La flexion doit être progressive, pas un effondrement.'], 'Retomber jambes tendues, ce qui envoie tout l''impact dans les genoux. Laisser les genoux rentrer vers l''intérieur à la réception.', array['Retomber jambes tendues, ce qui envoie tout l''impact dans les genoux.', 'Laisser les genoux rentrer vers l''intérieur à la réception.'], 'Une réception silencieuse est une réception bien amortie. Les genoux restent alignés avec les pointes de pieds. La flexion doit être progressive, pas un effondrement.', array['Réceptionne sur une seule jambe.'], array['Travaille depuis un simple saut sur place, sans amplitude.'], true, false, 3, 3, array['detente', 'prevention', 'amorti', 'maison']),
  ('detente_013', 'Saut maximal après élan complet', 'Détente mesurée dans les conditions réelles du volley, après une course d''élan trois appuis.', 'detente', array['détente spécifique', 'élan', 'coordination'], array['middle_blocker', 'outside_hitter', 'opposite'], 'intermediaire', array['intermediaire', 'avance'], 'detente', 'Développer la détente dans les conditions réelles du jeu.', 10, 1, 8, array['filet'], 'high', 4, 'Effectue l''élan trois appuis complet puis saute au maximum au filet. Marque ton point de contact le plus haut pour mesurer ta progression. 4 séries de 5 sauts, avec deux minutes de récupération.', array['Effectue l''élan trois appuis complet puis saute au maximum au filet.', 'Marque ton point de contact le plus haut pour mesurer ta progression.', '4 séries de 5 sauts, avec deux minutes de récupération.'], array['C''est la mesure la plus utile : elle correspond à ton saut réel en match.', 'L''accélération de l''élan apporte autant que la force des jambes.', 'Arrête la série dès que la hauteur baisse.'], 'Raccourcir l''élan pour enchaîner plus vite. Sauter vers l''avant plutôt que vers le haut.', array['Raccourcir l''élan pour enchaîner plus vite.', 'Sauter vers l''avant plutôt que vers le haut.'], 'C''est la mesure la plus utile : elle correspond à ton saut réel en match. L''accélération de l''élan apporte autant que la force des jambes. Arrête la série dès que la hauteur baisse.', array['Mesure ta hauteur et fixe un objectif de progression mensuel.'], array['Réduis l''élan à deux appuis.'], true, false, 5, 3, array['detente', 'elan', 'specifique']),
  ('detente_014', 'Montées de marches explosives', 'Poussées puissantes en montée d''escalier, pour la force des jambes sans impact de réception.', 'detente', array['force des jambes', 'puissance', 'endurance'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire'], 'detente', 'Renforcer les jambes avec très peu d''impact articulaire.', 10, 1, 8, '{}', 'high', 3, 'Monte un escalier deux marches à la fois, en poussant fort sur chaque appui. Redescends en marchant tranquillement pour récupérer. 5 séries de 10 poussées, avec une récupération complète entre les séries.', array['Monte un escalier deux marches à la fois, en poussant fort sur chaque appui.', 'Redescends en marchant tranquillement pour récupérer.', '5 séries de 10 poussées, avec une récupération complète entre les séries.'], array['Pousse complètement sur la jambe d''appui, jusqu''à l''extension totale.', 'Les bras accompagnent activement le mouvement.', 'Redescends toujours en marchant : la descente en courant est traumatisante.'], 'Monter en s''appuyant sur la rampe. Redescendre en courant et multiplier les impacts.', array['Monter en s''appuyant sur la rampe.', 'Redescendre en courant et multiplier les impacts.'], 'Pousse complètement sur la jambe d''appui, jusqu''à l''extension totale. Les bras accompagnent activement le mouvement. Redescends toujours en marchant : la descente en courant est traumatisante.', array['Monte trois marches à la fois si l''escalier le permet.'], array['Monte marche par marche, à rythme soutenu.'], true, false, 4, 1, array['detente', 'maison', 'exterieur', 'force']),
  ('detente_015', 'Saut avec résistance élastique', 'Sauts effectués contre la résistance d''un élastique, pour augmenter la demande de force.', 'detente', array['force', 'explosivité', 'gainage'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'avance', array['avance'], 'detente', 'Augmenter la demande de force sur le geste de saut.', 10, 1, 6, array['elastique'], 'high', 4, 'Place un élastique de résistance modérée au-dessus des épaules, ancré au sol sous tes pieds. Effectue des sauts verticaux contre cette résistance. 4 séries de 6 sauts, avec deux minutes de récupération.', array['Place un élastique de résistance modérée au-dessus des épaules, ancré au sol sous tes pieds.', 'Effectue des sauts verticaux contre cette résistance.', '4 séries de 6 sauts, avec deux minutes de récupération.'], array['Choisis une résistance qui n''altère pas ta technique de saut.', 'Le gainage du tronc devient essentiel avec la résistance.', 'Contrôle la descente, l''élastique accélère la réception.'], 'Utiliser un élastique trop résistant et déformer complètement le geste. Se laisser tirer vers le bas sans contrôler la réception.', array['Utiliser un élastique trop résistant et déformer complètement le geste.', 'Se laisser tirer vers le bas sans contrôler la réception.'], 'Choisis une résistance qui n''altère pas ta technique de saut. Le gainage du tronc devient essentiel avec la résistance. Contrôle la descente, l''élastique accélère la réception.', array['Augmente légèrement la résistance de l''élastique.'], array['Supprime l''élastique et reviens au saut libre.'], true, false, 5, 3, array['detente', 'elastique', 'avance']),
  ('detente_016', 'Mesure de la détente verticale', 'Protocole de mesure simple pour suivre l''évolution de sa hauteur de saut dans le temps.', 'detente', array['évaluation', 'suivi', 'détente'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire', 'avance'], 'detente', 'Suivre objectivement l''évolution de sa détente.', 8, 2, 8, '{}', 'medium', 3, 'Mesure d''abord ta portée bras tendu debout, contre un mur. Effectue trois sauts maximaux et relève le point le plus haut atteint. La différence entre les deux mesures donne ta détente ; note-la à chaque cycle.', array['Mesure d''abord ta portée bras tendu debout, contre un mur.', 'Effectue trois sauts maximaux et relève le point le plus haut atteint.', 'La différence entre les deux mesures donne ta détente ; note-la à chaque cycle.'], array['Échauffe-toi complètement avant de mesurer, sinon le chiffre ne veut rien dire.', 'Reproduis exactement le même protocole à chaque mesure.', 'Mesure une fois par mois, pas à chaque séance.'], 'Mesurer à froid et se décourager d''un résultat faussé. Changer de protocole entre deux mesures.', array['Mesurer à froid et se décourager d''un résultat faussé.', 'Changer de protocole entre deux mesures.'], 'Échauffe-toi complètement avant de mesurer, sinon le chiffre ne veut rien dire. Reproduis exactement le même protocole à chaque mesure. Mesure une fois par mois, pas à chaque séance.', array['Mesure également la détente après élan complet.'], array['Mesure simplement la hauteur atteinte, sans calculer l''écart.'], false, false, 3, 2, array['detente', 'evaluation', 'suivi']),
  ('detente_017', 'Série de sauts maximaux répétés', 'Capacité à répéter des sauts de haute qualité, comme sur un long échange.', 'detente', array['endurance de saut', 'répétition', 'récupération'], array['middle_blocker', 'outside_hitter', 'opposite'], 'avance', array['avance'], 'detente', 'Tenir une hauteur de saut élevée sur une série.', 12, 1, 8, array['filet'], 'high', 4, 'Effectue six sauts maximaux consécutifs, avec cinq secondes entre chacun. Note si la hauteur du dernier saut reste proche de celle du premier. 4 séries, avec trois minutes de récupération complète entre elles.', array['Effectue six sauts maximaux consécutifs, avec cinq secondes entre chacun.', 'Note si la hauteur du dernier saut reste proche de celle du premier.', '4 séries, avec trois minutes de récupération complète entre elles.'], array['L''objectif est de limiter la chute de hauteur, pas d''accumuler des sauts.', 'Amortis chaque réception : elle prépare le saut suivant.', 'Arrête la série si la hauteur chute de plus de vingt pour cent.'], 'Enchaîner mécaniquement sans chercher la hauteur maximale. Poursuivre la série alors que la qualité s''est effondrée.', array['Enchaîner mécaniquement sans chercher la hauteur maximale.', 'Poursuivre la série alors que la qualité s''est effondrée.'], 'L''objectif est de limiter la chute de hauteur, pas d''accumuler des sauts. Amortis chaque réception : elle prépare le saut suivant. Arrête la série si la hauteur chute de plus de vingt pour cent.', array['Passe à huit sauts par série.'], array['Réduis à quatre sauts par série.'], true, false, 5, 2, array['detente', 'endurance', 'avance']),
  ('detente_018', 'Gainage puis saut immédiat', 'Transfert de la stabilité du tronc vers le saut, en enchaînant les deux sans pause.', 'detente', array['gainage', 'transfert', 'explosivité'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire'], 'detente', 'Relier la stabilité du tronc à la performance de saut.', 10, 1, 12, array['tapis'], 'high', 3, 'Tiens une planche gainée pendant vingt secondes. Relève-toi immédiatement et effectue cinq sauts verticaux maximaux. 4 séries, avec 90 secondes de récupération.', array['Tiens une planche gainée pendant vingt secondes.', 'Relève-toi immédiatement et effectue cinq sauts verticaux maximaux.', '4 séries, avec 90 secondes de récupération.'], array['Un tronc stable transmet mieux la force des jambes vers le haut.', 'Garde le gainage actif pendant les sauts, ventre engagé.', 'Ne creuse pas le bas du dos pendant la planche.'], 'Relâcher complètement le tronc au moment des sauts. Laisser le bassin s''affaisser pendant la planche.', array['Relâcher complètement le tronc au moment des sauts.', 'Laisser le bassin s''affaisser pendant la planche.'], 'Un tronc stable transmet mieux la force des jambes vers le haut. Garde le gainage actif pendant les sauts, ventre engagé. Ne creuse pas le bas du dos pendant la planche.', array['Allonge la planche à trente secondes.'], array['Réduis la planche à dix secondes et les sauts à trois.'], true, false, 4, 2, array['detente', 'gainage', 'maison']),
  ('detente_019', 'Contrainte de temps de contact au sol', 'Sauts enchaînés avec l''objectif explicite de minimiser la durée d''appui au sol.', 'detente', array['raideur', 'puissance réactive', 'technique'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire', 'avance'], 'detente', 'Améliorer la raideur et la réactivité des appuis.', 8, 1, 8, '{}', 'high', 4, 'Effectue des sauts verticaux enchaînés en réduisant au maximum le temps passé au sol. La hauteur importe moins que la brièveté du contact. 5 séries de 8 sauts, avec 90 secondes de récupération.', array['Effectue des sauts verticaux enchaînés en réduisant au maximum le temps passé au sol.', 'La hauteur importe moins que la brièveté du contact.', '5 séries de 8 sauts, avec 90 secondes de récupération.'], array['Reste sur l''avant des pieds, les talons ne touchent jamais le sol.', 'Les jambes restent raides, sans flexion profonde.', 'Cherche le rebond, pas la flexion.'], 'Fléchir profondément entre deux sauts et perdre la raideur. Chercher la hauteur maximale et allonger le temps de contact.', array['Fléchir profondément entre deux sauts et perdre la raideur.', 'Chercher la hauteur maximale et allonger le temps de contact.'], 'Reste sur l''avant des pieds, les talons ne touchent jamais le sol. Les jambes restent raides, sans flexion profonde. Cherche le rebond, pas la flexion.', array['Enchaîne douze sauts par série.'], array['Réduis à cinq sauts et autorise une flexion plus marquée.'], true, false, 4, 3, array['detente', 'raideur', 'maison']),
  ('detente_020', 'Circuit complet de détente', 'Séance structurée combinant force, bondissements et sauts spécifiques dans un ordre progressif.', 'detente', array['polyvalence', 'progressivité', 'explosivité'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire', 'avance'], 'detente', 'Structurer une séance de détente complète et progressive.', 20, 1, 12, array['tapis'], 'high', 4, 'Enchaîne dans cet ordre : 10 squats sautés, 6 bondissements horizontaux, 5 sauts avec élan. Récupère deux minutes complètes entre chaque tour. 3 tours au total, en arrêtant si la qualité de réception se dégrade.', array['Enchaîne dans cet ordre : 10 squats sautés, 6 bondissements horizontaux, 5 sauts avec élan.', 'Récupère deux minutes complètes entre chaque tour.', '3 tours au total, en arrêtant si la qualité de réception se dégrade.'], array['L''ordre compte : force d''abord, puis bondissements, puis sauts spécifiques.', 'Une réception mal amortie signale qu''il faut arrêter la séance.', 'Laisse 48 h avant une nouvelle séance de ce type.'], 'Inverser l''ordre et commencer par les sauts les plus intenses. Enchaîner les tours sans récupération suffisante.', array['Inverser l''ordre et commencer par les sauts les plus intenses.', 'Enchaîner les tours sans récupération suffisante.'], 'L''ordre compte : force d''abord, puis bondissements, puis sauts spécifiques. Une réception mal amortie signale qu''il faut arrêter la séance. Laisse 48 h avant une nouvelle séance de ce type.', array['Ajoute un quatrième tour une fois les trois premiers maîtrisés.'], array['Réduis à deux tours et supprime les sauts avec élan.'], true, false, 5, 3, array['detente', 'circuit', 'seance']),
  ('renforcement_001', 'Gainage dynamique', 'Renforcement du tronc en planche avec mouvements contrôlés, pour la stabilité en vol et en défense.', 'renforcement', array['gainage', 'stabilité du tronc', 'endurance'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire'], 'global', 'Renforcer le tronc pour gagner en stabilité de jeu.', 8, 1, 12, array['tapis'], 'medium', 3, 'En position de planche sur les avant-bras, corps parfaitement aligné. Lève alternativement un bras puis une jambe, trois secondes chacun, sans bouger le bassin. 3 séries de 30 secondes, avec 30 secondes de récupération.', array['En position de planche sur les avant-bras, corps parfaitement aligné.', 'Lève alternativement un bras puis une jambe, trois secondes chacun, sans bouger le bassin.', '3 séries de 30 secondes, avec 30 secondes de récupération.'], array['Le bassin ne doit ni s''affaisser ni remonter pendant les levés.', 'Respire normalement, ne bloque jamais ta respiration.', 'Serre les fessiers pour protéger le bas du dos.'], 'Bassin qui s''affaisse dès que la fatigue arrive. Respiration bloquée pendant tout l''exercice.', array['Bassin qui s''affaisse dès que la fatigue arrive.', 'Respiration bloquée pendant tout l''exercice.'], 'Le bassin ne doit ni s''affaisser ni remonter pendant les levés. Respire normalement, ne bloque jamais ta respiration. Serre les fessiers pour protéger le bas du dos.', array['Allonge les séries à 45 secondes.'], array['Tiens une planche statique, sans levé de membre.'], true, false, 3, 2, array['renforcement', 'gainage', 'maison']),
  ('renforcement_002', 'Gainage latéral', 'Travail des muscles latéraux du tronc, sollicités dans toutes les frappes et défenses en extension.', 'renforcement', array['gainage latéral', 'obliques', 'stabilité'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire'], 'global', 'Renforcer les muscles latéraux du tronc.', 8, 1, 12, array['tapis'], 'medium', 3, 'Sur le côté, en appui sur un avant-bras, corps aligné de la tête aux pieds. Tiens la position, puis monte et descends lentement le bassin. 3 séries de 20 secondes par côté, avec 30 secondes de récupération.', array['Sur le côté, en appui sur un avant-bras, corps aligné de la tête aux pieds.', 'Tiens la position, puis monte et descends lentement le bassin.', '3 séries de 20 secondes par côté, avec 30 secondes de récupération.'], array['Le coude est placé exactement sous l''épaule.', 'Le corps forme une ligne droite vue de face comme de profil.', 'Travaille les deux côtés de façon strictement équivalente.'], 'Bassin qui recule, ce qui allège complètement l''exercice. Travailler davantage son côté fort.', array['Bassin qui recule, ce qui allège complètement l''exercice.', 'Travailler davantage son côté fort.'], 'Le coude est placé exactement sous l''épaule. Le corps forme une ligne droite vue de face comme de profil. Travaille les deux côtés de façon strictement équivalente.', array['Allonge à 30 secondes par côté.'], array['Pose les genoux au sol pour réduire le bras de levier.'], true, false, 3, 2, array['renforcement', 'gainage', 'maison']),
  ('renforcement_003', 'Renforcement de la chaîne postérieure', 'Travail des fessiers et ischio-jambiers, moteurs principaux du saut et du freinage.', 'renforcement', array['chaîne postérieure', 'fessiers', 'prévention'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire'], 'global', 'Renforcer les muscles moteurs du saut et du freinage.', 10, 1, 12, array['tapis'], 'medium', 3, 'Allongé sur le dos, pieds au sol, monte le bassin jusqu''à aligner genoux, bassin et épaules. Tiens deux secondes en haut puis redescends lentement sans poser complètement le bassin. 4 séries de 12 répétitions, avec une minute de récupération.', array['Allongé sur le dos, pieds au sol, monte le bassin jusqu''à aligner genoux, bassin et épaules.', 'Tiens deux secondes en haut puis redescends lentement sans poser complètement le bassin.', '4 séries de 12 répétitions, avec une minute de récupération.'], array['La poussée vient des talons et des fessiers, pas du bas du dos.', 'Ne creuse pas le bas du dos en haut du mouvement.', 'La descente doit être lente et contrôlée.'], 'Cambrer le bas du dos pour monter plus haut. Redescendre en se laissant tomber.', array['Cambrer le bas du dos pour monter plus haut.', 'Redescendre en se laissant tomber.'], 'La poussée vient des talons et des fessiers, pas du bas du dos. Ne creuse pas le bas du dos en haut du mouvement. La descente doit être lente et contrôlée.', array['Effectue le mouvement sur une seule jambe.'], array['Réduis l''amplitude et le nombre de répétitions.'], true, false, 3, 2, array['renforcement', 'fessiers', 'maison', 'prevention']),
  ('renforcement_004', 'Rotateurs de l''épaule à l''élastique', 'Renforcement des petits muscles stabilisateurs de l''épaule, essentiels pour les frappeurs.', 'renforcement', array['coiffe des rotateurs', 'prévention', 'stabilité de l''épaule'], array['outside_hitter', 'opposite', 'middle_blocker'], 'debutant', array['debutant', 'intermediaire', 'avance'], 'global', 'Protéger l''épaule des frappeurs par un renforcement ciblé.', 8, 1, 12, array['elastique'], 'low', 3, 'Coude collé au corps et fléchi à angle droit, tiens un élastique léger. Effectue des rotations externes lentes vers l''extérieur, puis reviens en contrôlant. 3 séries de 15 répétitions par bras, avec 45 secondes de récupération.', array['Coude collé au corps et fléchi à angle droit, tiens un élastique léger.', 'Effectue des rotations externes lentes vers l''extérieur, puis reviens en contrôlant.', '3 séries de 15 répétitions par bras, avec 45 secondes de récupération.'], array['Utilise un élastique léger : ces muscles sont petits et se fatiguent vite.', 'Le coude reste collé au corps pendant tout le mouvement.', 'Le retour se contrôle, il ne se subit pas.'], 'Prendre un élastique trop résistant et compenser avec tout le corps. Décoller le coude du corps.', array['Prendre un élastique trop résistant et compenser avec tout le corps.', 'Décoller le coude du corps.'], 'Utilise un élastique léger : ces muscles sont petits et se fatiguent vite. Le coude reste collé au corps pendant tout le mouvement. Le retour se contrôle, il ne se subit pas.', array['Ajoute une série de rotations internes.'], array['Effectue le mouvement sans élastique, à vide.'], true, false, 2, 3, array['renforcement', 'epaule', 'prevention', 'maison']),
  ('renforcement_005', 'Pompes contrôlées', 'Renforcement des pectoraux, épaules et triceps, utile au bloc et à la frappe.', 'renforcement', array['poussée', 'haut du corps', 'gainage'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire'], 'global', 'Renforcer le haut du corps pour le bloc et la frappe.', 8, 1, 12, array['tapis'], 'medium', 3, 'En appui sur les mains, corps gainé et aligné, descends jusqu''à ce que la poitrine frôle le sol. Remonte en poussant fort, sans casser l''alignement du corps. 4 séries de 10 répétitions, avec une minute de récupération.', array['En appui sur les mains, corps gainé et aligné, descends jusqu''à ce que la poitrine frôle le sol.', 'Remonte en poussant fort, sans casser l''alignement du corps.', '4 séries de 10 répétitions, avec une minute de récupération.'], array['Le corps reste rigide comme une planche du début à la fin.', 'Les coudes partent légèrement vers l''arrière, pas complètement sur les côtés.', 'La descente est aussi importante que la poussée.'], 'Bassin qui s''affaisse ou remonte pendant le mouvement. Descente partielle pour faire plus de répétitions.', array['Bassin qui s''affaisse ou remonte pendant le mouvement.', 'Descente partielle pour faire plus de répétitions.'], 'Le corps reste rigide comme une planche du début à la fin. Les coudes partent légèrement vers l''arrière, pas complètement sur les côtés. La descente est aussi importante que la poussée.', array['Ralentis la descente à trois secondes.'], array['Effectue les pompes genoux au sol ou mains surélevées.'], true, false, 3, 2, array['renforcement', 'haut du corps', 'maison']),
  ('renforcement_006', 'Flexions excentriques des ischio-jambiers', 'Travail excentrique des ischio-jambiers, reconnu pour la prévention des lésions musculaires.', 'renforcement', array['excentrique', 'ischio-jambiers', 'prévention'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire', 'avance'], 'global', 'Prévenir les lésions des ischio-jambiers.', 8, 2, 12, array['tapis'], 'high', 4, 'À genoux, un partenaire bloque fermement tes chevilles. Descends le buste vers l''avant le plus lentement possible, corps gainé, puis rattrape-toi avec les mains. 3 séries de 5 répétitions, avec deux minutes de récupération.', array['À genoux, un partenaire bloque fermement tes chevilles.', 'Descends le buste vers l''avant le plus lentement possible, corps gainé, puis rattrape-toi avec les mains.', '3 séries de 5 répétitions, avec deux minutes de récupération.'], array['La lenteur de la descente fait tout le travail : ne te laisse pas tomber.', 'Le corps reste aligné des genoux aux épaules, sans plier au niveau des hanches.', 'Cet exercice provoque souvent des courbatures : commence avec très peu de volume.'], 'Plier au niveau des hanches pour tricher. Se laisser tomber sans contrôler la descente.', array['Plier au niveau des hanches pour tricher.', 'Se laisser tomber sans contrôler la descente.'], 'La lenteur de la descente fait tout le travail : ne te laisse pas tomber. Le corps reste aligné des genoux aux épaules, sans plier au niveau des hanches. Cet exercice provoque souvent des courbatures : commence avec très peu de volume.', array['Allonge la durée de descente à cinq secondes.'], array['Réduis l''amplitude de descente de moitié.'], false, false, 5, 3, array['renforcement', 'prevention', 'excentrique']),
  ('renforcement_007', 'Squats au poids du corps', 'Renforcement fondamental des jambes, base de tout travail de détente ultérieur.', 'renforcement', array['force des jambes', 'technique de squat', 'alignement'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant'], 'global', 'Construire la force de base des jambes avec une technique sûre.', 8, 1, 12, '{}', 'medium', 3, 'Pieds à largeur d''épaules, pointes légèrement ouvertes vers l''extérieur. Descends jusqu''à ce que les cuisses soient parallèles au sol, puis remonte en poussant dans les talons. 4 séries de 15 répétitions, avec une minute de récupération.', array['Pieds à largeur d''épaules, pointes légèrement ouvertes vers l''extérieur.', 'Descends jusqu''à ce que les cuisses soient parallèles au sol, puis remonte en poussant dans les talons.', '4 séries de 15 répétitions, avec une minute de récupération.'], array['Les genoux suivent la direction des pointes de pieds.', 'Le dos reste droit, le regard devant, la poitrine ouverte.', 'Le poids reste réparti sur tout le pied, pas seulement sur l''avant.'], 'Genoux qui rentrent vers l''intérieur pendant la descente. Dos arrondi en bas du mouvement.', array['Genoux qui rentrent vers l''intérieur pendant la descente.', 'Dos arrondi en bas du mouvement.'], 'Les genoux suivent la direction des pointes de pieds. Le dos reste droit, le regard devant, la poitrine ouverte. Le poids reste réparti sur tout le pied, pas seulement sur l''avant.', array['Ralentis la descente à trois secondes par répétition.'], array['Réduis l''amplitude en t''asseyant sur une chaise.'], true, false, 3, 2, array['renforcement', 'jambes', 'maison', 'debutant']),
  ('renforcement_008', 'Fentes marchées', 'Renforcement unilatéral des jambes en déplacement, proche des appuis réels du volley.', 'renforcement', array['force unilatérale', 'équilibre', 'coordination'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire'], 'global', 'Renforcer chaque jambe séparément en situation de déplacement.', 8, 1, 12, '{}', 'medium', 3, 'Avance d''un grand pas et descends jusqu''à ce que le genou arrière frôle le sol. Pousse sur la jambe avant pour enchaîner directement le pas suivant. 4 séries de 10 fentes par jambe, avec une minute de récupération.', array['Avance d''un grand pas et descends jusqu''à ce que le genou arrière frôle le sol.', 'Pousse sur la jambe avant pour enchaîner directement le pas suivant.', '4 séries de 10 fentes par jambe, avec une minute de récupération.'], array['Le buste reste vertical, ne te penche pas vers l''avant.', 'Le genou avant ne dépasse pas la pointe du pied.', 'Contrôle la descente : le genou arrière effleure le sol sans le heurter.'], 'Pencher le buste pour compenser un manque de force. Poser brutalement le genou arrière au sol.', array['Pencher le buste pour compenser un manque de force.', 'Poser brutalement le genou arrière au sol.'], 'Le buste reste vertical, ne te penche pas vers l''avant. Le genou avant ne dépasse pas la pointe du pied. Contrôle la descente : le genou arrière effleure le sol sans le heurter.', array['Ajoute une pause de deux secondes en position basse.'], array['Effectue des fentes sur place, sans déplacement.'], true, false, 3, 2, array['renforcement', 'jambes', 'maison']),
  ('renforcement_009', 'Montées sur pointes', 'Renforcement des mollets et du tendon d''Achille, très sollicités par les sauts répétés.', 'renforcement', array['mollets', 'tendon d''Achille', 'prévention'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire'], 'global', 'Protéger et renforcer les mollets face aux sauts répétés.', 6, 1, 12, '{}', 'low', 2, 'Debout, monte lentement sur la pointe des pieds puis redescends encore plus lentement. Effectue 4 séries de 20 répétitions, avec 45 secondes de récupération. Passe progressivement à une jambe quand l''exercice devient facile.', array['Debout, monte lentement sur la pointe des pieds puis redescends encore plus lentement.', 'Effectue 4 séries de 20 répétitions, avec 45 secondes de récupération.', 'Passe progressivement à une jambe quand l''exercice devient facile.'], array['La descente doit être deux fois plus lente que la montée.', 'Monte le plus haut possible sur la pointe à chaque répétition.', 'Garde le corps gainé, sans balancement.'], 'Redescendre en se laissant tomber. Faire des répétitions incomplètes pour aller plus vite.', array['Redescendre en se laissant tomber.', 'Faire des répétitions incomplètes pour aller plus vite.'], 'La descente doit être deux fois plus lente que la montée. Monte le plus haut possible sur la pointe à chaque répétition. Garde le corps gainé, sans balancement.', array['Effectue les montées sur une seule jambe, depuis une marche.'], array['Appuie-toi légèrement à un mur pour l''équilibre.'], true, false, 2, 1, array['renforcement', 'mollets', 'prevention', 'maison']),
  ('renforcement_010', 'Renforcement des poignets et avant-bras', 'Travail des avant-bras et des poignets, sollicités à chaque passe et chaque frappe.', 'renforcement', array['poignets', 'avant-bras', 'prévention'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire'], 'global', 'Renforcer les poignets pour la passe et la frappe.', 6, 1, 12, array['elastique'], 'low', 2, 'Avant-bras posé sur une cuisse, paume vers le haut, tiens un élastique léger. Effectue des flexions de poignet lentes, puis retourne la main et recommence. 3 séries de 15 répétitions dans chaque position, par bras.', array['Avant-bras posé sur une cuisse, paume vers le haut, tiens un élastique léger.', 'Effectue des flexions de poignet lentes, puis retourne la main et recommence.', '3 séries de 15 répétitions dans chaque position, par bras.'], array['Seul le poignet bouge, l''avant-bras reste immobile.', 'Amplitude complète sur chaque répétition.', 'Des poignets solides améliorent la précision de la touche haute.'], 'Bouger tout l''avant-bras au lieu d''isoler le poignet. Utiliser une résistance trop forte.', array['Bouger tout l''avant-bras au lieu d''isoler le poignet.', 'Utiliser une résistance trop forte.'], 'Seul le poignet bouge, l''avant-bras reste immobile. Amplitude complète sur chaque répétition. Des poignets solides améliorent la précision de la touche haute.', array['Augmente légèrement la résistance de l''élastique.'], array['Effectue le mouvement à vide, sans résistance.'], true, false, 2, 2, array['renforcement', 'poignets', 'prevention', 'maison']),
  ('renforcement_011', 'Rotations du tronc en résistance', 'Renforcement des rotateurs du tronc, qui transmettent la force des jambes vers le bras frappeur.', 'renforcement', array['rotation du tronc', 'transfert de force', 'gainage'], array['outside_hitter', 'opposite', 'middle_blocker'], 'intermediaire', array['intermediaire'], 'global', 'Améliorer le transfert de force des jambes vers le bras.', 8, 1, 8, array['elastique'], 'medium', 3, 'Fixe un élastique à hauteur de poitrine sur un point fixe, place-toi de profil. Bras tendus devant toi, effectue une rotation lente du tronc à l''opposé de l''ancrage. 3 séries de 12 répétitions par côté, avec une minute de récupération.', array['Fixe un élastique à hauteur de poitrine sur un point fixe, place-toi de profil.', 'Bras tendus devant toi, effectue une rotation lente du tronc à l''opposé de l''ancrage.', '3 séries de 12 répétitions par côté, avec une minute de récupération.'], array['La rotation part du tronc, pas des bras.', 'Le bassin reste face à l''avant, seul le haut du corps tourne.', 'Contrôle le retour, ne laisse pas l''élastique te ramener.'], 'Tourner tout le corps, bassin compris. Laisser l''élastique dicter le retour.', array['Tourner tout le corps, bassin compris.', 'Laisser l''élastique dicter le retour.'], 'La rotation part du tronc, pas des bras. Le bassin reste face à l''avant, seul le haut du corps tourne. Contrôle le retour, ne laisse pas l''élastique te ramener.', array['Effectue le mouvement en position de fente.'], array['Réduis la résistance ou l''amplitude de rotation.'], true, false, 3, 3, array['renforcement', 'tronc', 'transfert']),
  ('renforcement_012', 'Tenue isométrique en chaise', 'Renforcement isométrique des cuisses, utile pour tenir les positions basses de défense.', 'renforcement', array['isométrie', 'quadriceps', 'endurance'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire'], 'global', 'Renforcer les cuisses pour tenir les positions basses.', 6, 1, 12, '{}', 'medium', 2, 'Dos contre un mur, descends jusqu''à ce que les cuisses soient parallèles au sol. Tiens la position sans bouger, pieds bien à plat. 4 séries de 30 secondes, avec 45 secondes de récupération.', array['Dos contre un mur, descends jusqu''à ce que les cuisses soient parallèles au sol.', 'Tiens la position sans bouger, pieds bien à plat.', '4 séries de 30 secondes, avec 45 secondes de récupération.'], array['Les genoux forment un angle droit, pas plus fermé.', 'Le dos reste entièrement plaqué contre le mur.', 'Respire régulièrement, ne bloque pas ta respiration.'], 'Descendre trop bas et surcharger les genoux. Décoller le bas du dos du mur.', array['Descendre trop bas et surcharger les genoux.', 'Décoller le bas du dos du mur.'], 'Les genoux forment un angle droit, pas plus fermé. Le dos reste entièrement plaqué contre le mur. Respire régulièrement, ne bloque pas ta respiration.', array['Allonge la tenue à 45 secondes.'], array['Remonte légèrement pour ouvrir l''angle des genoux.'], true, false, 3, 1, array['renforcement', 'isometrie', 'maison']),
  ('renforcement_013', 'Abducteurs de hanche à l''élastique', 'Renforcement des muscles latéraux de la hanche, qui stabilisent le genou à la réception.', 'renforcement', array['hanches', 'stabilité du genou', 'prévention'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire'], 'global', 'Stabiliser le genou par le renforcement des hanches.', 6, 1, 12, array['elastique'], 'low', 2, 'Place un élastique autour des cuisses, juste au-dessus des genoux. En position de demi-squat, effectue des pas latéraux en maintenant la tension. 3 séries de 12 pas dans chaque direction, avec 45 secondes de récupération.', array['Place un élastique autour des cuisses, juste au-dessus des genoux.', 'En position de demi-squat, effectue des pas latéraux en maintenant la tension.', '3 séries de 12 pas dans chaque direction, avec 45 secondes de récupération.'], array['Les genoux poussent vers l''extérieur en permanence contre l''élastique.', 'Reste en position basse pendant tous les pas.', 'Ces muscles empêchent le genou de s''effondrer vers l''intérieur à la réception.'], 'Se redresser entre les pas et relâcher la tension. Laisser les genoux rentrer vers l''intérieur.', array['Se redresser entre les pas et relâcher la tension.', 'Laisser les genoux rentrer vers l''intérieur.'], 'Les genoux poussent vers l''extérieur en permanence contre l''élastique. Reste en position basse pendant tous les pas. Ces muscles empêchent le genou de s''effondrer vers l''intérieur à la réception.', array['Augmente la résistance de l''élastique.'], array['Effectue les pas latéraux sans élastique.'], true, false, 2, 2, array['renforcement', 'hanches', 'prevention', 'maison']),
  ('renforcement_014', 'Circuit de renforcement complet', 'Enchaînement de six exercices au poids du corps couvrant l''ensemble des besoins du volleyeur.', 'renforcement', array['polyvalence', 'endurance musculaire', 'circuit'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire'], 'global', 'Entretenir un renforcement complet sans matériel.', 20, 1, 12, array['tapis'], 'high', 3, 'Enchaîne : 15 squats, 10 pompes, 30 secondes de gainage, 10 fentes par jambe, 15 montées sur pointes, 20 secondes de gainage latéral par côté. Récupère 60 secondes entre chaque tour complet. 4 tours, en arrêtant si la qualité d''exécution se dégrade nettement.', array['Enchaîne : 15 squats, 10 pompes, 30 secondes de gainage, 10 fentes par jambe, 15 montées sur pointes, 20 secondes de gainage latéral par côté.', 'Récupère 60 secondes entre chaque tour complet.', '4 tours, en arrêtant si la qualité d''exécution se dégrade nettement.'], array['La qualité d''exécution prime sur la vitesse d''enchaînement.', 'Respecte les temps de récupération, ils font partie du travail.', 'Réduis le nombre de répétitions plutôt que de bâcler la technique.'], 'Supprimer les récupérations pour finir plus vite. Dégrader la forme d''exécution au troisième tour.', array['Supprimer les récupérations pour finir plus vite.', 'Dégrader la forme d''exécution au troisième tour.'], 'La qualité d''exécution prime sur la vitesse d''enchaînement. Respecte les temps de récupération, ils font partie du travail. Réduis le nombre de répétitions plutôt que de bâcler la technique.', array['Ajoute un cinquième tour.'], array['Réduis à deux tours et diminue les répétitions d''un tiers.'], true, false, 4, 2, array['renforcement', 'circuit', 'maison']),
  ('renforcement_015', 'Descente excentrique sur une jambe', 'Travail excentrique des quadriceps, reconnu pour prévenir les tendinopathies du genou.', 'renforcement', array['excentrique', 'quadriceps', 'prévention du genou'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire', 'avance'], 'global', 'Prévenir les tendinopathies du genou chez le sauteur.', 8, 1, 8, array['banc'], 'medium', 3, 'Debout sur une jambe sur un banc bas, descends lentement en pliant le genou d''appui. Remonte en t''aidant des deux jambes, puis recommence la descente sur une seule. 3 séries de 8 descentes par jambe, avec 90 secondes de récupération.', array['Debout sur une jambe sur un banc bas, descends lentement en pliant le genou d''appui.', 'Remonte en t''aidant des deux jambes, puis recommence la descente sur une seule.', '3 séries de 8 descentes par jambe, avec 90 secondes de récupération.'], array['La descente doit durer au moins trois secondes : c''est là que tout se joue.', 'Le genou reste aligné avec la pointe du pied.', 'Une légère gêne est normale, une douleur vive impose d''arrêter et de consulter.'], 'Descendre trop vite et perdre l''effet excentrique. Laisser le genou partir vers l''intérieur pendant la descente.', array['Descendre trop vite et perdre l''effet excentrique.', 'Laisser le genou partir vers l''intérieur pendant la descente.'], 'La descente doit durer au moins trois secondes : c''est là que tout se joue. Le genou reste aligné avec la pointe du pied. Une légère gêne est normale, une douleur vive impose d''arrêter et de consulter.', array['Allonge la descente à cinq secondes.'], array['Réduis la hauteur du banc et l''amplitude de descente.'], true, false, 3, 3, array['renforcement', 'genou', 'prevention', 'excentrique']),
  ('mobilite_001', 'Mobilité des chevilles et des hanches', 'Routine articulaire des membres inférieurs, à faire avant toute séance comportant des sauts.', 'mobilite', array['mobilité articulaire', 'prévention', 'échauffement'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire', 'avance'], 'global', 'Préparer chevilles et hanches aux contraintes du saut.', 8, 1, 12, array['tapis'], 'low', 1, 'Effectue 10 rotations de cheville dans chaque sens, par pied. Enchaîne 10 fentes dynamiques par jambe, puis 10 cercles de hanches par côté. 3 tours complets, sans temps mort entre les mouvements.', array['Effectue 10 rotations de cheville dans chaque sens, par pied.', 'Enchaîne 10 fentes dynamiques par jambe, puis 10 cercles de hanches par côté.', '3 tours complets, sans temps mort entre les mouvements.'], array['Effectue chaque mouvement lentement et en contrôle, l''amplitude prime sur la vitesse.', 'Une cheville mobile absorbe mieux les réceptions de saut.', 'Ne force jamais dans une amplitude douloureuse.'], 'Enchaîner trop vite et perdre tout le bénéfice articulaire. Négliger cette routine quand la séance est courte.', array['Enchaîner trop vite et perdre tout le bénéfice articulaire.', 'Négliger cette routine quand la séance est courte.'], 'Effectue chaque mouvement lentement et en contrôle, l''amplitude prime sur la vitesse. Une cheville mobile absorbe mieux les réceptions de saut. Ne force jamais dans une amplitude douloureuse.', array['Ajoute une tenue de cinq secondes en fin d''amplitude.'], array['Réduis à deux tours.'], true, false, 1, 1, array['mobilite', 'prevention', 'echauffement', 'maison']),
  ('mobilite_002', 'Mobilité des épaules', 'Préparation de l''articulation de l''épaule avant les séries de frappes et de services.', 'mobilite', array['mobilité de l''épaule', 'prévention', 'amplitude'], array['outside_hitter', 'opposite', 'middle_blocker', 'setter'], 'debutant', array['debutant', 'intermediaire', 'avance'], 'global', 'Préparer l''épaule aux contraintes répétées de la frappe.', 6, 1, 12, '{}', 'low', 1, 'Effectue 15 cercles de bras vers l''avant puis 15 vers l''arrière, amplitude complète. Enchaîne 10 passages de bras au-dessus de la tête, coudes tendus. 3 tours, en augmentant progressivement l''amplitude.', array['Effectue 15 cercles de bras vers l''avant puis 15 vers l''arrière, amplitude complète.', 'Enchaîne 10 passages de bras au-dessus de la tête, coudes tendus.', '3 tours, en augmentant progressivement l''amplitude.'], array['Commence avec de petits cercles et agrandis progressivement.', 'Les épaules restent basses, ne remonte pas les trapèzes.', 'Aucune séance de frappe ne devrait commencer sans cette routine.'], 'Démarrer directement à amplitude maximale. Remonter les épaules vers les oreilles pendant les cercles.', array['Démarrer directement à amplitude maximale.', 'Remonter les épaules vers les oreilles pendant les cercles.'], 'Commence avec de petits cercles et agrandis progressivement. Les épaules restent basses, ne remonte pas les trapèzes. Aucune séance de frappe ne devrait commencer sans cette routine.', array['Ajoute des rotations avec un élastique léger.'], array['Réduis l''amplitude et le nombre de répétitions.'], true, false, 1, 1, array['mobilite', 'epaule', 'prevention', 'maison']),
  ('mobilite_003', 'Mobilité thoracique en rotation', 'Assouplissement du haut du dos, qui conditionne l''amplitude de l''armé du bras.', 'mobilite', array['mobilité thoracique', 'rotation', 'posture'], array['outside_hitter', 'opposite', 'middle_blocker', 'setter'], 'intermediaire', array['intermediaire', 'avance'], 'global', 'Gagner en amplitude d''armé sans forcer sur l''épaule.', 6, 1, 12, array['tapis'], 'low', 2, 'À quatre pattes, place une main derrière la tête. Ouvre le coude vers le plafond en tournant le haut du dos, puis reviens lentement. 3 séries de 10 rotations par côté.', array['À quatre pattes, place une main derrière la tête.', 'Ouvre le coude vers le plafond en tournant le haut du dos, puis reviens lentement.', '3 séries de 10 rotations par côté.'], array['La rotation vient du haut du dos, pas du bas.', 'Le bassin reste strictement immobile pendant le mouvement.', 'Un dos plus mobile permet un armé plus ample et moins traumatisant pour l''épaule.'], 'Tourner tout le corps, bassin compris. Effectuer le mouvement trop vite.', array['Tourner tout le corps, bassin compris.', 'Effectuer le mouvement trop vite.'], 'La rotation vient du haut du dos, pas du bas. Le bassin reste strictement immobile pendant le mouvement. Un dos plus mobile permet un armé plus ample et moins traumatisant pour l''épaule.', array['Tiens l''ouverture trois secondes en fin d''amplitude.'], array['Effectue le mouvement assis sur une chaise.'], true, false, 1, 2, array['mobilite', 'dos', 'maison']),
  ('mobilite_004', 'Étirements dynamiques des jambes', 'Mise en action progressive des membres inférieurs par des mouvements amples et contrôlés.', 'mobilite', array['étirement dynamique', 'activation', 'amplitude'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire', 'avance'], 'global', 'Mettre les jambes en action avant l''effort.', 6, 1, 12, '{}', 'low', 2, 'Effectue 10 balanciers de jambe vers l''avant et l''arrière, par jambe. Enchaîne 10 balanciers latéraux par jambe, puis 10 talons-fesses en marchant. 2 tours complets.', array['Effectue 10 balanciers de jambe vers l''avant et l''arrière, par jambe.', 'Enchaîne 10 balanciers latéraux par jambe, puis 10 talons-fesses en marchant.', '2 tours complets.'], array['Augmente progressivement l''amplitude à chaque répétition.', 'Garde le buste droit, appuie-toi à un mur si nécessaire.', 'Les étirements dynamiques précèdent l''effort, les statiques le suivent.'], 'Aller à amplitude maximale dès la première répétition. Remplacer ces mouvements par des étirements statiques avant l''effort.', array['Aller à amplitude maximale dès la première répétition.', 'Remplacer ces mouvements par des étirements statiques avant l''effort.'], 'Augmente progressivement l''amplitude à chaque répétition. Garde le buste droit, appuie-toi à un mur si nécessaire. Les étirements dynamiques précèdent l''effort, les statiques le suivent.', array['Augmente à 15 répétitions par mouvement.'], array['Réduis l''amplitude et appuie-toi systématiquement.'], true, false, 2, 1, array['mobilite', 'echauffement', 'maison']),
  ('mobilite_005', 'Protocole de prévention du genou', 'Enchaînement ciblé sur la stabilité du genou, articulation la plus exposée chez le volleyeur.', 'mobilite', array['prévention du genou', 'stabilité', 'alignement'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire', 'avance'], 'global', 'Protéger le genou par un travail d''alignement systématique.', 10, 1, 12, array['tapis'], 'medium', 3, 'Enchaîne : 10 squats lents avec attention à l''alignement, 10 fentes contrôlées par jambe. Termine par 8 réceptions de saut contrôlées, en vérifiant la position du genou à chaque fois. 3 tours, avec 45 secondes de récupération.', array['Enchaîne : 10 squats lents avec attention à l''alignement, 10 fentes contrôlées par jambe.', 'Termine par 8 réceptions de saut contrôlées, en vérifiant la position du genou à chaque fois.', '3 tours, avec 45 secondes de récupération.'], array['Le genou doit toujours suivre la direction de la pointe du pied.', 'Vérifie visuellement ton alignement à chaque réception.', 'En cas de douleur persistante au genou, consulte avant de poursuivre.'], 'Laisser les genoux rentrer vers l''intérieur, principal facteur de blessure. Aller vite au détriment du contrôle.', array['Laisser les genoux rentrer vers l''intérieur, principal facteur de blessure.', 'Aller vite au détriment du contrôle.'], 'Le genou doit toujours suivre la direction de la pointe du pied. Vérifie visuellement ton alignement à chaque réception. En cas de douleur persistante au genou, consulte avant de poursuivre.', array['Effectue les réceptions sur une seule jambe.'], array['Supprime les réceptions de saut et garde squats et fentes.'], true, false, 3, 3, array['mobilite', 'genou', 'prevention']),
  ('mobilite_006', 'Proprioception de la cheville', 'Travail d''équilibre sur une jambe pour réduire le risque d''entorse, blessure la plus fréquente.', 'mobilite', array['proprioception', 'équilibre', 'prévention'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire'], 'global', 'Réduire le risque d''entorse par le travail proprioceptif.', 8, 1, 12, array['tapis'], 'low', 2, 'Tiens-toi en équilibre sur une jambe, genou légèrement fléchi, pendant 30 secondes. Répète les yeux fermés, puis en tournant lentement la tête. 3 séries par jambe, avec 30 secondes de récupération.', array['Tiens-toi en équilibre sur une jambe, genou légèrement fléchi, pendant 30 secondes.', 'Répète les yeux fermés, puis en tournant lentement la tête.', '3 séries par jambe, avec 30 secondes de récupération.'], array['Les ajustements permanents de la cheville sont exactement le travail recherché.', 'Garde le regard fixe pour la première série, puis complique progressivement.', 'Cet exercice est le plus efficace pour prévenir les entorses récidivantes.'], 'Poser le pied dès le premier déséquilibre au lieu de se rattraper. Verrouiller le genou de la jambe d''appui.', array['Poser le pied dès le premier déséquilibre au lieu de se rattraper.', 'Verrouiller le genou de la jambe d''appui.'], 'Les ajustements permanents de la cheville sont exactement le travail recherché. Garde le regard fixe pour la première série, puis complique progressivement. Cet exercice est le plus efficace pour prévenir les entorses récidivantes.', array['Effectue l''exercice sur un tapis souple ou un coussin.'], array['Garde une main en appui léger sur un mur.'], true, false, 2, 2, array['mobilite', 'cheville', 'prevention', 'maison']),
  ('mobilite_007', 'Activation de la coiffe des rotateurs', 'Réveil des stabilisateurs de l''épaule avant toute séance de service ou d''attaque.', 'mobilite', array['activation', 'coiffe des rotateurs', 'prévention'], array['outside_hitter', 'opposite', 'middle_blocker', 'setter'], 'intermediaire', array['intermediaire', 'avance'], 'global', 'Activer les stabilisateurs de l''épaule avant les frappes.', 6, 1, 12, array['elastique'], 'low', 2, 'Avec un élastique très léger, effectue 15 rotations externes lentes par bras. Enchaîne 15 élévations latérales à mi-hauteur, coudes légèrement fléchis. 2 tours, juste avant de commencer à frapper.', array['Avec un élastique très léger, effectue 15 rotations externes lentes par bras.', 'Enchaîne 15 élévations latérales à mi-hauteur, coudes légèrement fléchis.', '2 tours, juste avant de commencer à frapper.'], array['La résistance doit rester très faible : il s''agit d''activer, pas de renforcer.', 'Mouvements lents et contrôlés, sans à-coup.', 'À faire systématiquement avant la première frappe de la séance.'], 'Utiliser une résistance trop forte et fatiguer l''épaule avant la séance. Commencer à frapper sans aucune activation préalable.', array['Utiliser une résistance trop forte et fatiguer l''épaule avant la séance.', 'Commencer à frapper sans aucune activation préalable.'], 'La résistance doit rester très faible : il s''agit d''activer, pas de renforcer. Mouvements lents et contrôlés, sans à-coup. À faire systématiquement avant la première frappe de la séance.', array['Ajoute une série de rotations internes.'], array['Effectue les mouvements sans élastique.'], true, false, 1, 2, array['mobilite', 'epaule', 'prevention', 'echauffement']),
  ('mobilite_008', 'Étirements de retour au calme', 'Étirements statiques après la séance, pour accompagner le retour à l''état de repos.', 'mobilite', array['étirement statique', 'récupération', 'relâchement'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire', 'avance'], 'global', 'Accompagner le retour au calme après l''effort.', 10, 1, 12, array['tapis'], 'low', 1, 'Étire successivement quadriceps, ischio-jambiers, mollets, fessiers et épaules. Tiens chaque position 30 secondes, sans à-coup ni rebond. 1 tour complet, en respirant lentement.', array['Étire successivement quadriceps, ischio-jambiers, mollets, fessiers et épaules.', 'Tiens chaque position 30 secondes, sans à-coup ni rebond.', '1 tour complet, en respirant lentement.'], array['Étire jusqu''à la sensation de tension, jamais jusqu''à la douleur.', 'Respire profondément et relâche à chaque expiration.', 'Ces étirements se font après l''effort, jamais avant.'], 'Faire des rebonds pendant l''étirement. Bloquer sa respiration en position d''étirement.', array['Faire des rebonds pendant l''étirement.', 'Bloquer sa respiration en position d''étirement.'], 'Étire jusqu''à la sensation de tension, jamais jusqu''à la douleur. Respire profondément et relâche à chaque expiration. Ces étirements se font après l''effort, jamais avant.', array['Allonge chaque position à 45 secondes.'], array['Réduis à 20 secondes par position.'], true, false, 1, 1, array['mobilite', 'recuperation', 'retour au calme', 'maison']),
  ('mobilite_009', 'Auto-massage des membres inférieurs', 'Relâchement musculaire par pression manuelle ou rouleau, après les séances chargées en sauts.', 'mobilite', array['relâchement', 'récupération', 'circulation'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire', 'avance'], 'global', 'Favoriser le relâchement musculaire après les séances chargées.', 8, 1, 12, array['tapis'], 'low', 1, 'Masse successivement mollets, quadriceps et fessiers par pressions lentes. Passe environ 60 secondes par zone, en insistant sur les points sensibles sans forcer. 1 tour complet après les séances comportant beaucoup de sauts.', array['Masse successivement mollets, quadriceps et fessiers par pressions lentes.', 'Passe environ 60 secondes par zone, en insistant sur les points sensibles sans forcer.', '1 tour complet après les séances comportant beaucoup de sauts.'], array['Une pression modérée suffit, la douleur n''apporte rien de plus.', 'Respire calmement pendant le relâchement.', 'Sur une zone très douloureuse, passe à côté plutôt que d''insister.'], 'Appuyer très fort en pensant que c''est plus efficace. Masser une zone récemment blessée sans avis médical.', array['Appuyer très fort en pensant que c''est plus efficace.', 'Masser une zone récemment blessée sans avis médical.'], 'Une pression modérée suffit, la douleur n''apporte rien de plus. Respire calmement pendant le relâchement. Sur une zone très douloureuse, passe à côté plutôt que d''insister.', array['Ajoute le travail des bandes latérales de cuisse.'], array['Réduis à 30 secondes par zone.'], true, false, 1, 1, array['mobilite', 'recuperation', 'maison']),
  ('mobilite_010', 'Routine complète d''après-séance', 'Enchaînement structuré de retour au calme, combinant respiration, étirements et relâchement.', 'mobilite', array['récupération', 'respiration', 'routine'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire', 'avance'], 'global', 'Structurer un retour au calme complet après la séance.', 12, 1, 12, array['tapis'], 'low', 1, 'Commence par trois minutes de marche lente et de respiration profonde. Enchaîne cinq minutes d''étirements statiques des principaux groupes musculaires. Termine par quatre minutes d''auto-massage des zones les plus sollicitées.', array['Commence par trois minutes de marche lente et de respiration profonde.', 'Enchaîne cinq minutes d''étirements statiques des principaux groupes musculaires.', 'Termine par quatre minutes d''auto-massage des zones les plus sollicitées.'], array['Respecte l''ordre : d''abord baisser le rythme cardiaque, puis étirer.', 'Cette routine fait partie de la séance, ce n''est pas une option.', 'Profite de ce moment pour faire le bilan de ta séance.'], 'Partir dès le dernier ballon joué. Étirer à froid, une heure après la séance.', array['Partir dès le dernier ballon joué.', 'Étirer à froid, une heure après la séance.'], 'Respecte l''ordre : d''abord baisser le rythme cardiaque, puis étirer. Cette routine fait partie de la séance, ce n''est pas une option. Profite de ce moment pour faire le bilan de ta séance.', array['Ajoute deux minutes de respiration guidée en fin de routine.'], array['Réduis la routine à six minutes au total.'], true, false, 1, 1, array['mobilite', 'recuperation', 'routine', 'retour au calme']),
  ('lecture_001', 'Anticipation du type de service', 'Identification du service à venir à partir de la posture et du lancer du serveur adverse.', 'lecture_jeu', array['prise d''information', 'anticipation', 'réception'], array['libero', 'outside_hitter', 'opposite'], 'intermediaire', array['intermediaire', 'avance'], 'reception', 'Gagner du temps en identifiant le service avant la frappe.', 10, 3, 8, array['ballons', 'filet'], 'low', 3, 'Le serveur alterne librement service flottant, smashé et court. Le réceptionneur annonce le type de service dès le lancer, avant la frappe. 4 séries de 10 services, en comptant les annonces correctes.', array['Le serveur alterne librement service flottant, smashé et court.', 'Le réceptionneur annonce le type de service dès le lancer, avant la frappe.', '4 séries de 10 services, en comptant les annonces correctes.'], array['La hauteur du lancer trahit presque toujours le type de service.', 'Un lancer très en avant annonce un service sauté.', 'Regarde le serveur dès qu''il prend son ballon, pas au moment de la frappe.'], 'Attendre la frappe pour prendre l''information. Se fier uniquement à l''habitude du serveur.', array['Attendre la frappe pour prendre l''information.', 'Se fier uniquement à l''habitude du serveur.'], 'La hauteur du lancer trahit presque toujours le type de service. Un lancer très en avant annonce un service sauté. Regarde le serveur dès qu''il prend son ballon, pas au moment de la frappe.', array['Le serveur cherche volontairement à masquer son intention.'], array['Le serveur n''alterne que deux types de service.'], false, true, 1, 4, array['lecture', 'anticipation', 'service']),
  ('lecture_002', 'Identification du système offensif adverse', 'Reconnaissance des schémas d''attaque privilégiés par l''adversaire au fil d''un match.', 'lecture_jeu', array['observation', 'analyse', 'tactique'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'avance', array['avance'], 'competition', 'Identifier et exploiter les habitudes offensives adverses.', 15, 6, 12, array['ballons', 'filet'], 'low', 4, 'Pendant un set joué, chaque joueur note la distribution adverse par rotation. À la fin du set, l''équipe met en commun ses observations. Appliquez ensuite un ajustement collectif sur le set suivant.', array['Pendant un set joué, chaque joueur note la distribution adverse par rotation.', 'À la fin du set, l''équipe met en commun ses observations.', 'Appliquez ensuite un ajustement collectif sur le set suivant.'], array['Note ce qui se répète, pas ce qui t''a marqué émotionnellement.', 'Une tendance se confirme sur au moins trois occurrences.', 'L''observation ne sert que si elle débouche sur un ajustement concret.'], 'Retenir uniquement l''action spectaculaire du set. Observer sans jamais rien changer ensuite.', array['Retenir uniquement l''action spectaculaire du set.', 'Observer sans jamais rien changer ensuite.'], 'Note ce qui se répète, pas ce qui t''a marqué émotionnellement. Une tendance se confirme sur au moins trois occurrences. L''observation ne sert que si elle débouche sur un ajustement concret.', array['Chaque joueur observe une rotation adverse précise.'], array['Observez uniquement l''attaquant le plus servi.'], false, true, 2, 5, array['lecture', 'analyse', 'collectif', 'avance']),
  ('lecture_003', 'Décision sous contrainte de temps', 'Choix technique imposé dans un délai très court, pour entraîner la vitesse de décision.', 'lecture_jeu', array['décision', 'réactivité', 'adaptation'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire', 'avance'], 'regularite', 'Accélérer sa prise de décision technique.', 10, 3, 8, array['ballons', 'filet'], 'high', 4, 'Un partenaire annonce une consigne technique au moment où le ballon part vers le joueur. Le joueur doit exécuter exactement la consigne annoncée, sans hésitation. 4 séries de 10 ballons, en comptant les consignes respectées.', array['Un partenaire annonce une consigne technique au moment où le ballon part vers le joueur.', 'Le joueur doit exécuter exactement la consigne annoncée, sans hésitation.', '4 séries de 10 ballons, en comptant les consignes respectées.'], array['Décide immédiatement : une décision moyenne prise tôt vaut mieux qu''une bonne prise trop tard.', 'Ne change jamais d''avis en cours de geste.', 'L''erreur de décision est acceptable, l''hésitation ne l''est pas.'], 'Hésiter entre deux options et rater les deux. Changer de geste en cours d''exécution.', array['Hésiter entre deux options et rater les deux.', 'Changer de geste en cours d''exécution.'], 'Décide immédiatement : une décision moyenne prise tôt vaut mieux qu''une bonne prise trop tard. Ne change jamais d''avis en cours de geste. L''erreur de décision est acceptable, l''hésitation ne l''est pas.', array['L''annonce arrive plus tard, quand le ballon est déjà proche.'], array['L''annonce est donnée avant l''envoi du ballon.'], false, true, 3, 5, array['lecture', 'decision', 'reactivite']),
  ('lecture_004', 'Repérage des espaces libres', 'Identification à voix haute des zones non couvertes par la défense adverse, avant de jouer.', 'lecture_jeu', array['observation', 'placement adverse', 'décision'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire', 'avance'], 'attaque', 'Développer le réflexe d''observer le terrain adverse.', 10, 6, 12, array['ballons', 'filet'], 'medium', 4, 'Avant chaque attaque, l''attaquant annonce à voix haute la zone adverse qu''il juge libre. Il cherche ensuite à y placer son ballon. 4 séries de 8 attaques, en comparant annonce et réalisation.', array['Avant chaque attaque, l''attaquant annonce à voix haute la zone adverse qu''il juge libre.', 'Il cherche ensuite à y placer son ballon.', '4 séries de 8 attaques, en comparant annonce et réalisation.'], array['Prends l''information pendant ton élan, avant de sauter.', 'Un défenseur qui bouge tard laisse une zone libre exploitable.', 'Annoncer à voix haute force à vraiment regarder.'], 'Annoncer au hasard sans avoir observé la défense. Regarder uniquement le ballon pendant toute l''action.', array['Annoncer au hasard sans avoir observé la défense.', 'Regarder uniquement le ballon pendant toute l''action.'], 'Prends l''information pendant ton élan, avant de sauter. Un défenseur qui bouge tard laisse une zone libre exploitable. Annoncer à voix haute force à vraiment regarder.', array['La défense se replace juste avant la frappe.'], array['La défense laisse une zone libre évidente et fixe.'], false, true, 3, 4, array['lecture', 'espaces', 'attaque']),
  ('lecture_005', 'Reconnaissance de la rotation adverse', 'Identification rapide de la rotation en face pour anticiper les zones d''attaque probables.', 'lecture_jeu', array['lecture tactique', 'anticipation', 'organisation'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'avance', array['avance'], 'bloc', 'Anticiper l''organisation offensive adverse avant le point.', 12, 6, 12, array['ballons', 'filet'], 'low', 4, 'Avant chaque service, l''équipe identifie à voix haute la rotation adverse et la position du passeur. Elle en déduit les attaquants disponibles au filet et ajuste son bloc. Jouez un set complet en respectant ce protocole à chaque point.', array['Avant chaque service, l''équipe identifie à voix haute la rotation adverse et la position du passeur.', 'Elle en déduit les attaquants disponibles au filet et ajuste son bloc.', 'Jouez un set complet en respectant ce protocole à chaque point.'], array['La position du passeur détermine le nombre d''attaquants disponibles devant.', 'Un passeur en zone arrière signifie trois attaquants au filet.', 'L''annonce doit être faite par un joueur désigné, pas par tout le monde.'], 'Oublier de refaire l''analyse après chaque rotation. Laisser plusieurs joueurs annoncer en même temps.', array['Oublier de refaire l''analyse après chaque rotation.', 'Laisser plusieurs joueurs annoncer en même temps.'], 'La position du passeur détermine le nombre d''attaquants disponibles devant. Un passeur en zone arrière signifie trois attaquants au filet. L''annonce doit être faite par un joueur désigné, pas par tout le monde.', array['Ajoutez l''identification de l''attaquant le plus dangereux.'], array['Identifiez uniquement la position du passeur adverse.'], false, true, 2, 5, array['lecture', 'tactique', 'collectif', 'avance']),
  ('lecture_006', 'Réaction à signaux multiples', 'Traitement simultané de plusieurs informations pour choisir la bonne réponse motrice.', 'lecture_jeu', array['attention', 'réaction', 'traitement d''information'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire', 'avance'], 'vitesse', 'Trier l''information pertinente parmi plusieurs stimuli.', 8, 2, 8, array['plots'], 'high', 4, 'Un partenaire combine un signal visuel du bras et un signal verbal, parfois contradictoires. Le joueur suit uniquement le signal désigné comme prioritaire au début de la série. 4 séries de 10 signaux, en comptant les erreurs.', array['Un partenaire combine un signal visuel du bras et un signal verbal, parfois contradictoires.', 'Le joueur suit uniquement le signal désigné comme prioritaire au début de la série.', '4 séries de 10 signaux, en comptant les erreurs.'], array['Fixe ton attention sur le signal prioritaire et ignore volontairement l''autre.', 'La vitesse vient après la justesse : sois d''abord correct.', 'Les erreurs augmentent avec la fatigue, c''est précisément l''intérêt de l''exercice.'], 'Suivre le signal le plus fort plutôt que le prioritaire. Partir avant d''avoir traité l''information.', array['Suivre le signal le plus fort plutôt que le prioritaire.', 'Partir avant d''avoir traité l''information.'], 'Fixe ton attention sur le signal prioritaire et ignore volontairement l''autre. La vitesse vient après la justesse : sois d''abord correct. Les erreurs augmentent avec la fatigue, c''est précisément l''intérêt de l''exercice.', array['Inverse la priorité en cours de série.'], array['Utilise un seul type de signal.'], false, false, 3, 4, array['lecture', 'reaction', 'attention']),
  ('lecture_007', 'Choix tactique en situation réduite', 'Jeu à effectif réduit où chaque joueur doit justifier ses choix après le point.', 'lecture_jeu', array['décision', 'tactique', 'analyse'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'avance', array['avance'], 'competition', 'Rendre conscients les choix tactiques en jeu.', 15, 4, 8, array['ballons', 'filet'], 'high', 5, 'Jouez des points à trois contre trois sur un demi-terrain. Après chaque point perdu, le joueur concerné explique en une phrase son choix. Jouez 15 points, puis inversez les équipes.', array['Jouez des points à trois contre trois sur un demi-terrain.', 'Après chaque point perdu, le joueur concerné explique en une phrase son choix.', 'Jouez 15 points, puis inversez les équipes.'], array['Verbaliser son choix révèle si la décision était réfléchie ou automatique.', 'Un mauvais choix bien argumenté vaut mieux qu''un bon choix fait au hasard.', 'L''effectif réduit multiplie les décisions à prendre par joueur.'], 'Justifier a posteriori un geste fait sans réfléchir. Transformer l''exercice en recherche de coupable.', array['Justifier a posteriori un geste fait sans réfléchir.', 'Transformer l''exercice en recherche de coupable.'], 'Verbaliser son choix révèle si la décision était réfléchie ou automatique. Un mauvais choix bien argumenté vaut mieux qu''un bon choix fait au hasard. L''effectif réduit multiplie les décisions à prendre par joueur.', array['Passez à deux contre deux pour augmenter encore la charge décisionnelle.'], array['Ne commentez qu''un point sur trois.'], false, true, 4, 5, array['lecture', 'decision', 'jeu reduit', 'avance']),
  ('lecture_008', 'Observation ciblée d''un coéquipier', 'Analyse d''un partenaire en jeu pour développer sa capacité d''observation et l''aider à progresser.', 'lecture_jeu', array['observation', 'analyse technique', 'communication'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire', 'avance'], 'global', 'Développer l''œil technique et la qualité des retours.', 12, 4, 12, array['ballons', 'filet'], 'low', 3, 'Chaque joueur au repos observe un partenaire sur un seul critère technique défini à l''avance. Il lui fait un retour précis à la fin de la rotation. Alternez les rôles toutes les dix minutes.', array['Chaque joueur au repos observe un partenaire sur un seul critère technique défini à l''avance.', 'Il lui fait un retour précis à la fin de la rotation.', 'Alternez les rôles toutes les dix minutes.'], array['Un seul critère à la fois : observer tout revient à ne rien voir.', 'Le retour doit être factuel et précis, pas un jugement global.', 'Observer un partenaire aide aussi à comprendre son propre geste.'], 'Observer plusieurs critères et livrer un retour vague. Donner un avis général du type ça va ou ça ne va pas.', array['Observer plusieurs critères et livrer un retour vague.', 'Donner un avis général du type ça va ou ça ne va pas.'], 'Un seul critère à la fois : observer tout revient à ne rien voir. Le retour doit être factuel et précis, pas un jugement global. Observer un partenaire aide aussi à comprendre son propre geste.', array['Ajoutez un comptage chiffré du critère observé.'], array['Limitez l''observation à cinq actions seulement.'], false, true, 1, 4, array['lecture', 'observation', 'collectif']),
  ('lecture_009', 'Circulation de l''information en jeu', 'Protocole de communication obligatoire à chaque phase, du service jusqu''à la conclusion du point.', 'lecture_jeu', array['communication', 'organisation', 'collectif'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire', 'avance'], 'competition', 'Installer une communication systématique et hiérarchisée.', 15, 6, 12, array['ballons', 'filet'], 'medium', 4, 'À chaque point, trois informations doivent circuler : la rotation adverse, la direction du bloc, l''appel du ballon. Un point joué sans l''une des trois informations est annulé. Jouez un set complet selon cette règle.', array['À chaque point, trois informations doivent circuler : la rotation adverse, la direction du bloc, l''appel du ballon.', 'Un point joué sans l''une des trois informations est annulé.', 'Jouez un set complet selon cette règle.'], array['Chaque information a un émetteur désigné : évitez que tout le monde parle.', 'L''information doit arriver avant l''action, pas pendant.', 'Une équipe silencieuse perd des points qu''elle aurait pu jouer.'], 'Communiquer en début de set puis se taire dès que le rythme monte. Crier tous en même temps et rendre l''information inaudible.', array['Communiquer en début de set puis se taire dès que le rythme monte.', 'Crier tous en même temps et rendre l''information inaudible.'], 'Chaque information a un émetteur désigné : évitez que tout le monde parle. L''information doit arriver avant l''action, pas pendant. Une équipe silencieuse perd des points qu''elle aurait pu jouer.', array['Ajoutez une quatrième information à faire circuler.'], array['Réduisez à une seule information obligatoire.'], false, true, 3, 4, array['lecture', 'communication', 'collectif']),
  ('lecture_010', 'Jeu à contrainte décisionnelle', 'Points joués avec une règle changeante qui oblige à réévaluer ses choix en permanence.', 'lecture_jeu', array['adaptation', 'décision', 'situation de jeu'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'avance', array['avance'], 'competition', 'Développer l''adaptabilité décisionnelle en jeu.', 15, 6, 12, array['ballons', 'filet'], 'high', 5, 'Toutes les trois actions, l''entraîneur change une règle : zone interdite, attaque obligatoire, nombre de touches imposé. Les joueurs adaptent immédiatement leurs choix à la nouvelle contrainte. Jouez deux séries de dix minutes.', array['Toutes les trois actions, l''entraîneur change une règle : zone interdite, attaque obligatoire, nombre de touches imposé.', 'Les joueurs adaptent immédiatement leurs choix à la nouvelle contrainte.', 'Jouez deux séries de dix minutes.'], array['Écoute la nouvelle règle et reformule-la mentalement avant le point.', 'Adapter vite compte davantage que bien jouer sous l''ancienne règle.', 'Les contraintes révèlent les automatismes trop rigides.'], 'Continuer à jouer selon la règle précédente. Se figer en attendant que la situation redevienne familière.', array['Continuer à jouer selon la règle précédente.', 'Se figer en attendant que la situation redevienne familière.'], 'Écoute la nouvelle règle et reformule-la mentalement avant le point. Adapter vite compte davantage que bien jouer sous l''ancienne règle. Les contraintes révèlent les automatismes trop rigides.', array['Changez la règle toutes les deux actions.'], array['Changez la règle toutes les six actions.'], false, true, 4, 5, array['lecture', 'adaptation', 'jeu', 'avance']),
  ('echauffement_001', 'Mise en route articulaire', 'Réveil progressif de toutes les articulations sollicitées au volley, de la cheville à l''épaule.', 'echauffement', array['mobilisation', 'préparation', 'routine'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire', 'avance'], 'global', 'Préparer toutes les articulations avant l''effort.', 5, 1, 12, '{}', 'low', 1, 'Mobilise dans l''ordre : chevilles, genoux, hanches, tronc, épaules, poignets et nuque. Effectue 10 rotations par articulation, dans les deux sens. Enchaîne sans pause, en augmentant progressivement l''amplitude.', array['Mobilise dans l''ordre : chevilles, genoux, hanches, tronc, épaules, poignets et nuque.', 'Effectue 10 rotations par articulation, dans les deux sens.', 'Enchaîne sans pause, en augmentant progressivement l''amplitude.'], array['Commence toujours par le bas du corps et remonte progressivement.', 'L''amplitude augmente au fil des répétitions, elle ne commence pas au maximum.', 'Cinq minutes suffisent, mais elles ne se sautent jamais.'], 'Commencer par les épaules et négliger les chevilles. Sauter cette étape quand la séance commence en retard.', array['Commencer par les épaules et négliger les chevilles.', 'Sauter cette étape quand la séance commence en retard.'], 'Commence toujours par le bas du corps et remonte progressivement. L''amplitude augmente au fil des répétitions, elle ne commence pas au maximum. Cinq minutes suffisent, mais elles ne se sautent jamais.', array['Ajoute des mouvements combinés sur plusieurs articulations.'], array['Concentre-toi sur les chevilles, les hanches et les épaules uniquement.'], true, false, 1, 1, array['echauffement', 'articulaire', 'maison']),
  ('echauffement_002', 'Activation cardiovasculaire progressive', 'Montée en régime du rythme cardiaque par des déplacements d''intensité croissante.', 'echauffement', array['activation', 'endurance', 'déplacements'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire', 'avance'], 'global', 'Élever progressivement le rythme cardiaque avant la séance.', 6, 1, 12, '{}', 'medium', 2, 'Commence par deux minutes de course lente autour du terrain. Enchaîne deux minutes de déplacements spécifiques : pas chassés, talons-fesses, montées de genoux. Termine par deux minutes de course avec accélérations progressives.', array['Commence par deux minutes de course lente autour du terrain.', 'Enchaîne deux minutes de déplacements spécifiques : pas chassés, talons-fesses, montées de genoux.', 'Termine par deux minutes de course avec accélérations progressives.'], array['L''intensité monte par paliers, sans à-coup.', 'Tu dois pouvoir parler jusqu''à la dernière minute.', 'Termine légèrement essoufflé mais pas épuisé.'], 'Démarrer directement à haute intensité. Transformer l''échauffement en séance de condition physique.', array['Démarrer directement à haute intensité.', 'Transformer l''échauffement en séance de condition physique.'], 'L''intensité monte par paliers, sans à-coup. Tu dois pouvoir parler jusqu''à la dernière minute. Termine légèrement essoufflé mais pas épuisé.', array['Allonge la phase d''accélérations d''une minute.'], array['Réduis l''ensemble à quatre minutes.'], true, false, 3, 1, array['echauffement', 'cardio', 'maison']),
  ('echauffement_003', 'Prise de contact avec le ballon', 'Premiers échanges à intensité douce pour retrouver les sensations avant le travail technique.', 'echauffement', array['sensations', 'toucher de balle', 'progressivité'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'debutant', array['debutant', 'intermediaire', 'avance'], 'global', 'Retrouver ses sensations de balle avant le travail technique.', 8, 2, 12, array['ballons'], 'low', 2, 'En binôme à trois mètres, échangez en touche haute pendant deux minutes. Reculez à cinq mètres et échangez en manchette pendant deux minutes. Terminez par quatre minutes d''échanges libres, en augmentant progressivement la distance.', array['En binôme à trois mètres, échangez en touche haute pendant deux minutes.', 'Reculez à cinq mètres et échangez en manchette pendant deux minutes.', 'Terminez par quatre minutes d''échanges libres, en augmentant progressivement la distance.'], array['Cherche la qualité du contact, pas la puissance.', 'Replace-toi correctement sous chaque ballon, même à l''échauffement.', 'Augmente la distance progressivement plutôt que d''un coup.'], 'Frapper fort dès les premiers ballons. Échanger de façon relâchée, sans placement.', array['Frapper fort dès les premiers ballons.', 'Échanger de façon relâchée, sans placement.'], 'Cherche la qualité du contact, pas la puissance. Replace-toi correctement sous chaque ballon, même à l''échauffement. Augmente la distance progressivement plutôt que d''un coup.', array['Ajoutez des déplacements latéraux entre chaque touche.'], array['Restez à courte distance sur toute la durée.'], false, true, 2, 2, array['echauffement', 'ballon', 'sensations']),
  ('echauffement_004', 'Préparation de l''épaule avant les frappes', 'Montée en charge progressive du bras frappeur avant tout travail de service ou d''attaque.', 'echauffement', array['préparation de l''épaule', 'progressivité', 'prévention'], array['outside_hitter', 'opposite', 'middle_blocker', 'setter'], 'debutant', array['debutant', 'intermediaire', 'avance'], 'global', 'Préparer l''épaule avant les séries de frappes.', 6, 2, 12, array['ballons'], 'low', 2, 'Effectue 15 cercles de bras dans chaque sens, amplitude croissante. Enchaîne 10 frappes à cinquante pour cent d''intensité vers un partenaire, à cinq mètres. Termine par 10 frappes à soixante-quinze pour cent, à dix mètres.', array['Effectue 15 cercles de bras dans chaque sens, amplitude croissante.', 'Enchaîne 10 frappes à cinquante pour cent d''intensité vers un partenaire, à cinq mètres.', 'Termine par 10 frappes à soixante-quinze pour cent, à dix mètres.'], array['N''atteins jamais l''intensité maximale avant une vingtaine de frappes progressives.', 'Augmente la distance avant d''augmenter la puissance.', 'L''épaule est l''articulation la plus exposée du volleyeur : cette étape n''est pas facultative.'], 'Commencer par des services à pleine puissance. Négliger cette préparation quand la séance est courte.', array['Commencer par des services à pleine puissance.', 'Négliger cette préparation quand la séance est courte.'], 'N''atteins jamais l''intensité maximale avant une vingtaine de frappes progressives. Augmente la distance avant d''augmenter la puissance. L''épaule est l''articulation la plus exposée du volleyeur : cette étape n''est pas facultative.', array['Ajoute une série de dix frappes à quatre-vingt-dix pour cent.'], array['Reste à cinquante pour cent d''intensité sur toute la durée.'], false, true, 2, 2, array['echauffement', 'epaule', 'prevention']),
  ('echauffement_005', 'Échauffement complet d''avant-match', 'Protocole structuré couvrant articulations, cardio, ballon et gestes spécifiques avant une rencontre.', 'echauffement', array['routine', 'préparation', 'spécifique'], array['setter', 'outside_hitter', 'opposite', 'middle_blocker', 'libero'], 'intermediaire', array['intermediaire', 'avance'], 'competition', 'Arriver prêt physiquement et techniquement au coup d''envoi.', 20, 6, 12, array['ballons', 'filet'], 'medium', 3, 'Cinq minutes de mise en route articulaire et cardiovasculaire. Cinq minutes d''échanges au ballon, puis cinq minutes de services et réceptions progressives. Terminez par cinq minutes d''attaques et de blocs à intensité croissante.', array['Cinq minutes de mise en route articulaire et cardiovasculaire.', 'Cinq minutes d''échanges au ballon, puis cinq minutes de services et réceptions progressives.', 'Terminez par cinq minutes d''attaques et de blocs à intensité croissante.'], array['L''ordre est toujours le même : général d''abord, spécifique ensuite.', 'Terminez l''échauffement cinq minutes avant le coup d''envoi, pas juste avant.', 'Chaque joueur doit avoir frappé et réceptionné avant le premier point.'], 'Commencer par des attaques à pleine puissance. Terminer l''échauffement trop tôt et se refroidir avant le match.', array['Commencer par des attaques à pleine puissance.', 'Terminer l''échauffement trop tôt et se refroidir avant le match.'], 'L''ordre est toujours le même : général d''abord, spécifique ensuite. Terminez l''échauffement cinq minutes avant le coup d''envoi, pas juste avant. Chaque joueur doit avoir frappé et réceptionné avant le premier point.', array['Ajoutez cinq minutes de situations de jeu réelles.'], array['Réduisez chaque bloc à trois minutes.'], false, true, 3, 3, array['echauffement', 'match', 'routine'])
-- Le prédicat `where slug is not null` répète celui de l'index partiel
-- exercises_slug_key : sans lui, PostgreSQL ne peut pas rattacher le
-- `on conflict` à cet index et rejette l'insertion.
on conflict (slug) where slug is not null do update set
  name = excluded.name,
  description = excluded.description,
  category = excluded.category,
  skills = excluded.skills,
  positions = excluded.positions,
  level = excluded.level,
  levels = excluded.levels,
  objective = excluded.objective,
  objective_statement = excluded.objective_statement,
  duration_minutes = excluded.duration_minutes,
  players_min = excluded.players_min,
  players_max = excluded.players_max,
  equipment = excluded.equipment,
  intensity = excluded.intensity,
  difficulty = excluded.difficulty,
  instructions = excluded.instructions,
  instruction_steps = excluded.instruction_steps,
  coaching_points = excluded.coaching_points,
  common_mistakes = excluded.common_mistakes,
  common_mistakes_list = excluded.common_mistakes_list,
  tips = excluded.tips,
  progressions = excluded.progressions,
  regressions = excluded.regressions,
  solo_compatible = excluded.solo_compatible,
  ball_required = excluded.ball_required,
  physical_load = excluded.physical_load,
  technical_load = excluded.technical_load,
  tags = excluded.tags;
